import { achievementEventCounter, ACHIEVEMENT_COUNTER_KEY_PATTERN } from './AchievementCounters';
import {
  applyAchievementCounterDelta,
  withAchievementUnlocks,
  type AchievementLedger,
} from './AchievementLedger';
import type { AchievementRegistry } from './AchievementRegistry';
import { deriveAchievementStateValues, type AchievementProgressSource } from './AchievementState';
import {
  buildAchievementSyncState,
  deriveRoundCreditDelta,
  evaluateAchievements,
  resolveAchievementValues,
  type AchievementRoundCredit,
  type AchievementSyncState,
} from './AchievementTracker';

export interface AchievementPersistencePort {
  getLedger(): AchievementLedger;
  setLedger(ledger: AchievementLedger): void;
  getProgress(): AchievementProgressSource;
  /** Fires after any progress write; the service re-evaluates once per microtask. */
  subscribe(listener: () => void): () => void;
}

export interface AchievementSinkPort {
  sync(state: AchievementSyncState): void;
}

export interface AchievementServiceOptions {
  readonly syncDelayMs?: number;
  readonly setTimer?: (callback: () => void, delayMs: number) => unknown;
  readonly clearTimer?: (handle: unknown) => void;
  readonly queueMicrotask?: (callback: () => void) => void;
}

const DEFAULT_SYNC_DELAY_MS = 1_000;

/**
 * Keeps the persisted ledger and the platform in step. Facts arrive from exactly-once hooks
 * (round credit after the round is marked processed, explicit events); everything the save
 * already proves is re-derived, so the platform always receives the full state.
 */
export class AchievementService {
  private unsubscribe: (() => void) | null = null;
  private evaluationQueued = false;
  private syncTimer: unknown = null;
  private pendingSync: AchievementSyncState | null = null;
  private lastSentKey = '';
  private destroyed = false;
  private readonly syncDelayMs: number;
  private readonly setTimer: (callback: () => void, delayMs: number) => unknown;
  private readonly clearTimer: (handle: unknown) => void;
  private readonly queueTask: (callback: () => void) => void;

  constructor(
    private readonly registry: AchievementRegistry,
    private readonly persistence: AchievementPersistencePort,
    private readonly sink: AchievementSinkPort | null,
    options: AchievementServiceOptions = {},
  ) {
    this.syncDelayMs = options.syncDelayMs ?? DEFAULT_SYNC_DELAY_MS;
    this.setTimer = options.setTimer ?? ((callback, delayMs) => setTimeout(callback, delayMs));
    this.clearTimer = options.clearTimer ?? (handle => clearTimeout(handle as ReturnType<typeof setTimeout>));
    this.queueTask = options.queueMicrotask ?? (callback => queueMicrotask(callback));
  }

  start(): void {
    if (this.destroyed || this.unsubscribe) return;
    this.unsubscribe = this.persistence.subscribe(() => this.queueEvaluation());
    this.evaluate();
  }

  creditRound(credit: AchievementRoundCredit): void {
    if (this.destroyed) return;
    const ledger = this.persistence.getLedger();
    const next = applyAchievementCounterDelta(ledger, deriveRoundCreditDelta(credit));
    if (next !== ledger) this.persistence.setLedger(next);
    this.evaluate();
  }

  /** Content triggers without a round, e.g. a hidden lobby secret. */
  reportEvent(eventId: string): void {
    const counter = achievementEventCounter(eventId);
    if (this.destroyed || !ACHIEVEMENT_COUNTER_KEY_PATTERN.test(counter)) return;
    const ledger = this.persistence.getLedger();
    const next = applyAchievementCounterDelta(ledger, { add: { [counter]: 1 } });
    if (next !== ledger) this.persistence.setLedger(next);
    this.evaluate();
  }

  /** Sends a pending sync immediately so a scene shutdown never swallows a fresh unlock. */
  destroy(): void {
    if (this.destroyed) return;
    this.flushSync();
    this.destroyed = true;
    this.unsubscribe?.();
    this.unsubscribe = null;
  }

  private queueEvaluation(): void {
    if (this.evaluationQueued || this.destroyed) return;
    this.evaluationQueued = true;
    this.queueTask(() => {
      this.evaluationQueued = false;
      if (!this.destroyed) this.evaluate();
    });
  }

  private evaluate(): void {
    const ledger = this.persistence.getLedger();
    const values = resolveAchievementValues(ledger, deriveAchievementStateValues(this.persistence.getProgress()));
    const next = withAchievementUnlocks(ledger, evaluateAchievements(this.registry, values));
    if (next !== ledger) this.persistence.setLedger(next);
    this.scheduleSync(buildAchievementSyncState(this.registry, next, values));
  }

  private scheduleSync(state: AchievementSyncState): void {
    if (!this.sink) return;
    this.pendingSync = state;
    if (this.syncTimer !== null) return;
    this.syncTimer = this.setTimer(() => this.flushSync(), this.syncDelayMs);
  }

  private flushSync(): void {
    if (this.syncTimer !== null) this.clearTimer(this.syncTimer);
    this.syncTimer = null;
    const state = this.pendingSync;
    this.pendingSync = null;
    if (!state || !this.sink) return;
    const key = JSON.stringify(state);
    if (key === this.lastSentKey) return;
    this.lastSentKey = key;
    try { this.sink.sync(state); } catch (error) { console.warn('[achievements] platform sync failed', error); }
  }
}
