import rawAchievements from '../config/achievements.json';
import { ACHIEVEMENT_API_NAME_PATTERN } from './AchievementLedger';
import { ACHIEVEMENT_COUNTER_KEY_PATTERN } from './AchievementCounters';

export type AchievementLocale = 'de' | 'en';
export type AchievementGroup = 'campaign' | 'progress' | 'enemies' | 'specials' | 'pvp' | 'dawn';

export interface AchievementRequirement {
  /** Ledger counter (`kills.*`, `won.*`, …) or derived save value (`progress.*`). */
  readonly value: string;
  readonly min: number;
}

export interface AchievementDefinition {
  readonly apiName: string;
  readonly group: AchievementGroup;
  /** Steam "spoiler" (hidden) achievement. */
  readonly spoiler: boolean;
  readonly requires: readonly AchievementRequirement[];
  /** Steam stat that drives the progress bar of a single-threshold achievement. */
  readonly progressStat: string | null;
  readonly name: Readonly<Record<AchievementLocale, string>>;
  readonly description: Readonly<Record<AchievementLocale, string>>;
}

export interface AchievementStatDefinition {
  readonly apiName: string;
  readonly value: string;
}

export interface AchievementRegistry {
  readonly achievements: readonly AchievementDefinition[];
  readonly stats: readonly AchievementStatDefinition[];
}

/** Steam allows 100 achievements until an app passes its trust threshold. */
export const STEAM_NEW_APP_ACHIEVEMENT_LIMIT = 100;
export const ACHIEVEMENT_LOCALES: readonly AchievementLocale[] = ['de', 'en'];
const GROUPS: readonly AchievementGroup[] = ['campaign', 'progress', 'enemies', 'specials', 'pvp', 'dawn'];
/** `progress.*` keys are derived from the save; everything else is a ledger counter. */
const DERIVED_VALUE_PATTERN = /^progress\.(level|weaponMaxed|epicItem|necromancy|dawnVictories|dawnBestStreak|map\.\d{1,2}|bossMap\.\d{1,2})$/u;

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function fail(message: string): never {
  throw new Error(`[achievements] ${message}`);
}

function parseText(raw: unknown, field: string, apiName: string): Record<AchievementLocale, string> {
  if (!isRecord(raw)) fail(`${apiName}: ${field} missing`);
  const text = {} as Record<AchievementLocale, string>;
  for (const locale of ACHIEVEMENT_LOCALES) {
    const value = raw[locale];
    if (typeof value !== 'string' || value.trim().length === 0) fail(`${apiName}: ${field}.${locale} missing`);
    if (value.length > (field === 'name' ? 64 : 160)) fail(`${apiName}: ${field}.${locale} too long`);
    text[locale] = value;
  }
  return text;
}

export function isAchievementValueKey(value: string): boolean {
  if (value.startsWith('progress.')) return DERIVED_VALUE_PATTERN.test(value);
  return ACHIEVEMENT_COUNTER_KEY_PATTERN.test(value);
}

/** Structural validation; cross-references to enemies, maps and classes are covered by tests. */
export function parseAchievementRegistry(raw: unknown): AchievementRegistry {
  if (!isRecord(raw) || raw.version !== 1 || !Array.isArray(raw.achievements) || !Array.isArray(raw.stats)) {
    fail('registry must have version 1, achievements and stats');
  }
  const stats = raw.stats.map((entry): AchievementStatDefinition => {
    if (!isRecord(entry) || typeof entry.apiName !== 'string' || !ACHIEVEMENT_API_NAME_PATTERN.test(entry.apiName)
      || typeof entry.value !== 'string' || !isAchievementValueKey(entry.value)) fail(`invalid stat ${JSON.stringify(entry)}`);
    return { apiName: entry.apiName, value: entry.value };
  });
  const statNames = new Set(stats.map(stat => stat.apiName));
  if (statNames.size !== stats.length) fail('duplicate stat apiName');

  const achievements = raw.achievements.map((entry): AchievementDefinition => {
    if (!isRecord(entry) || typeof entry.apiName !== 'string' || !ACHIEVEMENT_API_NAME_PATTERN.test(entry.apiName)) {
      fail(`invalid achievement ${JSON.stringify(entry)}`);
    }
    const apiName = entry.apiName;
    if (!GROUPS.includes(entry.group as AchievementGroup)) fail(`${apiName}: unknown group`);
    if (entry.spoiler !== undefined && typeof entry.spoiler !== 'boolean') fail(`${apiName}: spoiler must be boolean`);
    if (!Array.isArray(entry.requires) || entry.requires.length === 0) fail(`${apiName}: requires missing`);
    const requires = entry.requires.map((requirement): AchievementRequirement => {
      if (!isRecord(requirement) || typeof requirement.value !== 'string' || !isAchievementValueKey(requirement.value)
        || typeof requirement.min !== 'number' || !Number.isSafeInteger(requirement.min) || requirement.min < 1) {
        fail(`${apiName}: invalid requirement ${JSON.stringify(requirement)}`);
      }
      return { value: requirement.value, min: requirement.min };
    });
    const progressStat = entry.progressStat ?? null;
    if (progressStat !== null) {
      const stat = stats.find(candidate => candidate.apiName === progressStat);
      if (!stat) fail(`${apiName}: unknown progressStat ${String(progressStat)}`);
      if (requires.length !== 1 || requires[0].value !== stat.value) fail(`${apiName}: progressStat must track its single requirement`);
    }
    return {
      apiName,
      group: entry.group as AchievementGroup,
      spoiler: entry.spoiler === true,
      requires,
      progressStat: progressStat as string | null,
      name: parseText(entry.name, 'name', apiName),
      description: parseText(entry.description, 'description', apiName),
    };
  });
  const names = new Set(achievements.map(achievement => achievement.apiName));
  if (names.size !== achievements.length) fail('duplicate achievement apiName');
  if ([...names].some(name => statNames.has(name))) fail('achievement and stat share an apiName');
  if (achievements.length > STEAM_NEW_APP_ACHIEVEMENT_LIMIT) fail(`more than ${STEAM_NEW_APP_ACHIEVEMENT_LIMIT} achievements`);
  return { achievements, stats };
}

export const ACHIEVEMENT_REGISTRY: AchievementRegistry = parseAchievementRegistry(rawAchievements);
