import * as Phaser from 'phaser';
import { KEY_CODES } from '../../controls/controlBindings';
import { isKeyCodeBoundToAction } from '../../controls/controlBindingStore';
import type { GamePhase } from '../../types';

/**
 * Entwickler-Hotkeys der Arena an genau einer Stelle.
 *
 * Fuer den Release: Schalter auf `false`. Danach installiert die Arena keine dieser Tasten mehr;
 * dieses Modul, der Port-Block `developer` in ArenaScene und die Diagnose-Overlays lassen sich
 * anschliessend einzeln entfernen, ohne Spielereingabe oder Esc-Stapel anzufassen.
 */
export const DEVELOPER_HOTKEYS_ENABLED = true;

export type ArenaFlowFieldDebugView = 'flowfield_bases' | 'flowfield_players';

export interface ArenaDeveloperOverlayPort {
  isOpen(): boolean;
  hide(): void;
  toggle(): void;
}

/** Alles, was die Entwickler-Hotkeys von der Scene brauchen; getrennt von den Spieler-Ports. */
export interface ArenaDeveloperPorts {
  getGamePhase(): GamePhase;
  isMatchTerminated(): boolean;
  isCoopDefenseMode(): boolean;
  isHotkeyInputBlocked(): boolean;
  isOptionsOverlayOpen(): boolean;
  isCoopDefenseUpgradesOpen(): boolean;
  readonly coopDefenseDebug: ArenaDeveloperOverlayPort;
  readonly weaponBalanceLab: ArenaDeveloperOverlayPort;
  readonly netDebug: ArenaDeveloperOverlayPort;
  readonly performance: ArenaDeveloperOverlayPort;
  readonly timeOfDay: ArenaDeveloperOverlayPort;
  showFlowFieldDebug(view: ArenaFlowFieldDebugView): void;
}

interface DeveloperHotkey {
  readonly keyCode: number;
  readonly purpose: string;
  readonly run: (ports: ArenaDeveloperPorts, event: KeyboardEvent) => void;
}

function inCoopLobbyMenu(ports: ArenaDeveloperPorts): boolean {
  return ports.getGamePhase() === 'LOBBY' && !ports.isMatchTerminated() && ports.isCoopDefenseMode()
    && !ports.isOptionsOverlayOpen() && !ports.isCoopDefenseUpgradesOpen();
}

/** Die vollstaendige Liste; Debug-Schaden (K) wird zusaetzlich von der Host-Simulation abgefragt. */
export const DEVELOPER_HOTKEYS: readonly DeveloperHotkey[] = [
  {
    keyCode: KEY_CODES.P,
    purpose: 'Netz-Diagnose, in jeder Phase',
    run: (ports) => ports.netDebug.toggle(),
  },
  {
    keyCode: KEY_CODES.T,
    purpose: 'Performance-Diagnose',
    run: (ports) => ports.performance.toggle(),
  },
  {
    keyCode: KEY_CODES.M,
    purpose: 'Tageszeit-Regler',
    run: (ports) => ports.timeOfDay.toggle(),
  },
  {
    keyCode: KEY_CODES.L,
    purpose: 'Coop-Cheat-Menue in der Lobby',
    run: (ports) => {
      if (!inCoopLobbyMenu(ports) || ports.weaponBalanceLab.isOpen()) return;
      ports.coopDefenseDebug.toggle();
    },
  },
  {
    keyCode: KEY_CODES.F8,
    purpose: 'Balance-Lab in der Coop-Lobby',
    run: (ports, event) => {
      if (!inCoopLobbyMenu(ports) || ports.coopDefenseDebug.isOpen()) return;
      event.preventDefault();
      ports.weaponBalanceLab.toggle();
    },
  },
  {
    keyCode: KEY_CODES.B,
    purpose: 'Flowfield der Basen',
    run: (ports) => ports.showFlowFieldDebug('flowfield_bases'),
  },
  {
    keyCode: KEY_CODES.N,
    purpose: 'Flowfield der Spieler',
    run: (ports) => ports.showFlowFieldDebug('flowfield_players'),
  },
];

const DEBUG_DAMAGE_KEY_CODE = KEY_CODES.K;

/**
 * Szenenlanger Owner der Entwickler-Hotkeys. Eine Taste, die der Spieler einer Aktion zugewiesen
 * hat, gehoert dem Spiel: Dann loest sie hier nichts aus.
 */
export class ArenaDeveloperHotkeys {
  private debugDamageKey: Phaser.Input.Keyboard.Key | null = null;
  private destroyed = false;

  constructor(
    private readonly keyboard: Phaser.Input.Keyboard.KeyboardPlugin,
    private readonly ports: ArenaDeveloperPorts,
  ) {
    keyboard.on(Phaser.Input.Keyboard.Events.ANY_KEY_DOWN, this.onKeyDown);
    // K bleibt abfragbar, darf aber kein DOM-Textfeld blockieren (Buchstabe in Spielernamen).
    this.debugDamageKey = keyboard.addKey(DEBUG_DAMAGE_KEY_CODE, false);
  }

  /** Esc-Stapel: schliesst das oberste offene Diagnose-Overlay. */
  closeTopOverlay(): boolean {
    for (const overlay of [
      this.ports.coopDefenseDebug,
      this.ports.weaponBalanceLab,
      this.ports.netDebug,
      this.ports.performance,
      this.ports.timeOfDay,
    ]) {
      if (!overlay.isOpen()) continue;
      overlay.hide();
      return true;
    }
    return false;
  }

  isDebugDamageJustDown(): boolean {
    if (this.destroyed || !this.debugDamageKey) return false;
    // Erst pruefen, dann lesen: JustDown verbraucht die Flanke, die sonst der Spieleraktion gehoert.
    if (isKeyCodeBoundToAction(DEBUG_DAMAGE_KEY_CODE)) return false;
    return Phaser.Input.Keyboard.JustDown(this.debugDamageKey);
  }

  destroy(): void {
    if (this.destroyed) return;
    this.destroyed = true;
    this.keyboard.off(Phaser.Input.Keyboard.Events.ANY_KEY_DOWN, this.onKeyDown);
    if (this.debugDamageKey) this.keyboard.removeKey(this.debugDamageKey, true, true);
    this.debugDamageKey = null;
  }

  private readonly onKeyDown = (event: KeyboardEvent): void => {
    if (this.destroyed || event.repeat) return;
    const hotkey = DEVELOPER_HOTKEYS.find((entry) => entry.keyCode === event.keyCode);
    if (!hotkey || isKeyCodeBoundToAction(hotkey.keyCode)) return;
    // Buchstaben sind Schreibzeichen: nicht ausloesen, waehrend ein Textfeld oder Menue sie braucht.
    if (this.ports.isHotkeyInputBlocked()) return;
    hotkey.run(this.ports, event);
  };
}
