/**
 * Brücke zur Desktop-Shell (`desktop/src/preload.cjs`), über die die Steam-Variante läuft.
 *
 * Der Vertrag ist versioniert: Änderungen erhöhen `shellVersion` auf beiden Seiten. Fehlt die
 * Brücke oder passt die Version nicht – Tests, Steam-Build im Browser –, gibt es keine Shell.
 *
 * `steam` ist die Steam-Anbindung des Shell-Hauptprozesses (`desktop/src/steam/steamService.mjs`).
 * SteamIDs und Lobby-IDs sind Dezimal-Strings (64 Bit). Nur `src/platform/steam/` liest sie.
 */
import type { PlatformShell } from '../PlatformServices';

const DESKTOP_SHELL_VERSION = 6;

/** Spielstand-Dateien der Shell (`desktop/src/saveStore.mjs`), beim Start einmal gelesen. */
export interface DesktopSaveBridge {
  /** Inhalt von `settings.json`; `null`, wenn es die Datei noch nicht gibt. */
  readonly settings: string | null;
  /** Inhalt von `save/progress.json`; `null`, wenn es die Datei noch nicht gibt. */
  readonly progress: string | null;
  /** Der Fortschritt war beschädigt und kam aus einer Sicherung. */
  readonly recovered: boolean;
  /** Asynchron; `null` entfernt das Dokument. */
  write(document: 'settings' | 'progress', text: string | null): void;
}

export type DesktopSteamStatus =
  | {
    readonly available: true;
    readonly appId: number;
    readonly steamId: string;
    readonly personaName: string;
    /** Echte Kanalgrenzen der Bindung (Steam-Config `MTU_DataSize` bzw. größte Nachricht). */
    readonly limits: { readonly reliableMessageBytes: number; readonly unreliableMessageBytes: number };
  }
  | { readonly available: false; readonly reason: 'no-steam' | 'native-missing' | 'disabled' };

export type DesktopSteamEvent =
  | { readonly kind: 'member-joined' | 'member-left' | 'owner-changed'; readonly lobbyId: string; readonly steamId: string }
  /** Einladung angenommen oder „Spiel beitreten“; `steamId` ist der einladende Freund, falls bekannt. */
  | { readonly kind: 'join-requested'; readonly lobbyId: string; readonly steamId: string | null }
  | { readonly kind: 'session-request'; readonly steamId: string }
  | { readonly kind: 'session-failed'; readonly steamId: string; readonly reason: string };

/** Messwerte je Gegenstelle, einmal je Sekunde (Sonden der Shell, `desktop/src/steam/probeDiagnostics.mjs`). */
export interface DesktopSteamPeerStats {
  readonly steamId: string;
  /** Letzte Sonden-Umlaufzeit Shell ↔ Shell; `null` ohne Antwort. */
  readonly rttMs: number | null;
  /** Beantwortete Sonden insgesamt: Steigt der Wert, liegt eine neue Messung vor. */
  readonly rttSamples: number;
  /** Sondenverlust im letzten abgeschlossenen Zehn-Sekunden-Fenster; `null` davor. */
  readonly lossPercent: number | null;
}

/** Eine Nachricht der Shell je Poll-Takt. */
export interface DesktopSteamUpdate {
  /** Letzte Folgenummer eines Sende-Batches, den die Shell an Steam übergeben hat. */
  readonly ack: number;
  /** Eingegangene Nachrichten im Batch-Format (`steamShellWire.ts`). */
  readonly batch: Uint8Array | null;
  /** Noch nicht versendete Bytes je Gegenstelle (Shell-Warteschlange plus Steam); ersetzt den letzten Stand. */
  readonly pending: readonly (readonly [steamId: string, bytes: number])[] | null;
  readonly events: readonly DesktopSteamEvent[];
  /** Ersetzt die letzten Messwerte; fehlt in Takten ohne neue Messung. */
  readonly stats?: readonly DesktopSteamPeerStats[] | null;
}

/** Ein Treffer der Lobbysuche: öffentliche Fragdachse-Lobbys mit freiem Platz. */
export interface DesktopLobbyListing {
  readonly lobbyId: string;
  readonly members: number;
  /** `null`, wenn Steam kein Limit meldet. */
  readonly memberLimit: number | null;
  /** Nur `fd_*`-Schlüssel. */
  readonly data: Readonly<Record<string, string>>;
}

export interface DesktopSteamBridge {
  status(): DesktopSteamStatus | null;
  /** Lobby aus `+connect_lobby` bzw. aus `setPendingLobby`; wird beim Lesen verbraucht. */
  takeLaunchLobby(): string | null;
  /** Merkt eine Lobby für den nächsten Start des Spiels vor (Beitritt per Neuladen). */
  setPendingLobby(lobbyId: string): void;
  /**
   * Host-Übergabe: Die Shell verlässt diese Lobby beim folgenden Neuladen nicht (auch nicht auf
   * `leaveLobby`), bis das Spiel sie mit `takeRetainedLobby` abholt; sonst nach 60 s.
   */
  retainLobby(lobbyId: string): void;
  /** Die gehaltene Lobby; wird beim Lesen verbraucht. */
  takeRetainedLobby(): string | null;
  createLobby(maxMembers: number, visibility: string): Promise<string>;
  joinLobby(lobbyId: string): Promise<void>;
  leaveLobby(lobbyId: string): void;
  lobbyOwner(lobbyId: string): string | null;
  lobbyMembers(lobbyId: string): string[];
  lobbyData(lobbyId: string, key: string): string | null;
  setLobbyData(lobbyId: string, key: string, value: string): boolean;
  /** Nur Owner: Lobby-Typ und Beitrittssperre zur Laufzeit. */
  configureLobby(lobbyId: string, visibility: 'private' | 'friends-only' | 'public', joinable: boolean): boolean;
  /** Öffentliche Lobbys, deren `fd_*`-Daten allen `filters` gleichen und die noch Platz haben, weltweit. */
  searchLobbies(filters: Readonly<Record<string, string>>, maxResults: number): Promise<DesktopLobbyListing[]>;
  /** Eigene Ping-Position im Valve-Relay-Netz als Text; `null`, solange sie noch gemessen wird. */
  pingLocation(): string | null;
  /** Geschätzter Ping in ms zu jeder Ping-Position; `null`, wo keine Schätzung möglich ist. */
  estimatePings(locations: readonly string[]): (number | null)[];
  openInviteDialog(lobbyId: string): void;
  /** Setzt Rich-Presence-Schlüssel; `null` löscht einen. Die Shell verwirft ungültige Einträge. */
  setRichPresence(entries: readonly (readonly [key: string, value: string | null])[]): void;
  /** Vollständiger Erfolgs-Stand; die Shell schaltet Fehlendes frei und erhöht Stats nur. */
  syncAchievements(state: { readonly unlocked: readonly string[]; readonly stats: Readonly<Record<string, number>> }): void;
  /** Übergibt einen Sende-Batch; `sequence` kommt als `ack` zurück. */
  send(sequence: number, batch: Uint8Array): void;
  decideSession(steamId: string, accept: boolean): void;
  closeSession(steamId: string): void;
  onUpdate(listener: (update: DesktopSteamUpdate) => void): () => void;
}

interface DesktopShellBridge {
  readonly shellVersion: number;
  /** `null`, wenn die Shell die Dateien nicht lesen konnte. */
  readonly saves: DesktopSaveBridge | null;
  quit(): void;
  isMinimized(): boolean;
  onMinimizedChange(listener: (minimized: boolean) => void): () => void;
  readonly steam: DesktopSteamBridge;
}

declare global {
  interface Window {
    /** Nur in der Desktop-Shell gesetzt, siehe `desktop/src/preload.cjs`. */
    readonly fragdachseDesktop?: DesktopShellBridge;
  }
}

function readBridge(): DesktopShellBridge | null {
  if (typeof window === 'undefined') return null;
  const bridge = window.fragdachseDesktop;
  return bridge?.shellVersion === DESKTOP_SHELL_VERSION ? bridge : null;
}

export function readDesktopSaves(): DesktopSaveBridge | null {
  return readBridge()?.saves ?? null;
}

export function readDesktopShell(): PlatformShell | null {
  const bridge = readBridge();
  if (!bridge) return null;
  return {
    quit: () => bridge.quit(),
    isMinimized: () => bridge.isMinimized(),
    onMinimizedChange: listener => bridge.onMinimizedChange(listener),
  };
}

export function readDesktopSteam(): DesktopSteamBridge | null {
  return readBridge()?.steam ?? null;
}
