import type * as Phaser from 'phaser';
import { getGraphicsQualityProfile, type GraphicsPreset } from '../../../../graphics/GraphicsQuality';
import { isLightingFeatureOn } from '../../../../graphics/LightingFeatures';
import { FIGURE_OUTLINE_GROWTH_TEXELS } from '../../FigureSilhouettes';
import { OCCLUDER_SHADE_FALLOFF_PX, SURFACE_REACH_DISTANCE_SHARE, SURFACE_REACH_DISTANCE_START_PX } from '../../../LightingConfig';
import { ROCK_BEHIND_SOFT_PX } from '../../../RockLightCoverage';
import { lightMapScaleV2 } from '../../LightHdrModel';
import type { DistanceFieldView } from '../../IndirectLightField';
import type { OccluderField } from '../../OccluderField';
import { registerShadowProvider, type ShadowProvider } from '../../ShadowProvider';
import { JumpFloodField, type JumpFloodQuality } from './JumpFloodField';

interface SdfQuality extends JumpFloodQuality {
  readonly steps: number;
}

const QUALITY: Readonly<Record<GraphicsPreset, SdfQuality>> = {
  ultra: { cellPx: 2, startJump: 128, refine: true, steps: 64 },
  high: { cellPx: 2, startJump: 64, refine: true, steps: 40 },
  medium: { cellPx: 4, startJump: 32, refine: true, steps: 24 },
  low: { cellPx: 8, startJump: 16, refine: false, steps: 12 },
};
/** Loop bound of the trace; the actual count is the uniform. */
const MAX_TRACE_STEPS = 64;
/** The ray stops this short of the light, so the figure holding it does not block it. */
const LAMP_CLEARANCE_PX = 16;
/** Reach of the carrier's own picture from its lamp, held weapon and closed outline included. */
const CARRIER_BODY_PX = 44;
/** Share of the field's distance range one step may use: its rim is the least exact part of a flood. */
const SAFE_STEP_SHARE = 0.75;
/** The first part of a lamp's reach into rock stays fully lit (GDD Nachtsicht N-4). */
const REACH_LIT_SHARE = 0.35;
/** Taps between a blocker's entry and the pixel that look for its far side; only pixels within the lit rim pay for them. */
const EXIT_TAPS = 6;
/** Far rock contour: dark from 1 px before it, soft for at least this many light-map pixels behind it. */
const ROCK_BEHIND_SOFT_LIGHTMAP_PX = 1.5;
/** Radius of the light source in px: base plus a share of its height, so high fire softens more than a torch. */
const SOURCE_RADIUS_BASE_PX = 4;
const SOURCE_RADIUS_PER_HEIGHT = 0.25;
/** Height band of a shadow's tip, as a share of the source radius: a wider source fades the end of a low object's shadow. */
const HEIGHT_SOFT_PER_SOURCE = 0.5;
/** A figure or trunk does not shade its own top; same height within this share of it counts as the same object. */
const SELF_RANGE_PER_HEIGHT = 0.9;
/** Narrowest penumbra, in field cells: right behind a blocker the edge would otherwise fall inside one cell and show the grid as steps. */
const MIN_PENUMBRA_CELLS = 0.75;
/** The edge without that floor, for the comparison in the review panel. */
const HARD_EDGE_PX = 0.01;
/** Coverage of the mask from which a spot shows a figure. Low, so a figure's edge stays lit rather than taking a dark fringe. */
const FIGURE_SHOWN_FROM = 0.35;
/**
 * Share of a texel a figure covers, across which the texel passes from ground to figure. With a single threshold a texel at
 * the figure's edge would switch between lit and shaded as soon as the figure moves a fraction of it.
 */
const FIGURE_EDGE_BAND = [0.1, 0.6] as const;
/** World px the blockers' outlines are grown by; the occluder field holds one texel per two px. */
/** Spots between a ground receiver and the lamp, over the contact reach, at which the mask is asked whether a figure stands there. */
const CONTACT_TAPS = 6;
const HARD_FIGURE_EDGE = [FIGURE_SHOWN_FROM, FIGURE_SHOWN_FROM] as const;
const FIGURE_GROWTH_PX = FIGURE_OUTLINE_GROWTH_TEXELS * 2;

const GLSL = `
uniform sampler2D uSdf;
// World x, y of the grid; 1 / world width, 1 / world height.
uniform vec4 uSdfFrame;
// Steps, cell size in px, largest step in px, softness behind a rock's far contour in px.
uniform vec4 uSdfTrace;
// Narrowest penumbra in px.
uniform float uSdfEdge;
// The pictures the figures show this frame: R coverage, G height / 510 px. Frame: world x, y; 1 / world width, 1 / world height.
uniform sampler2D uFigureMask;
uniform vec4 uFigureMaskFrame;
// 1 while the mask decides where a figure is seen; world px before a ground receiver in which only the true picture of a figure blocks.
uniform vec2 uFigureContact;
// Coverage from which a texel starts to count as the figure, and from which it does so fully.
uniform vec2 uFigureBand;
vec2 figureShownAt(vec2 world) {
  vec2 at = (world - uFigureMaskFrame.xy) * uFigureMaskFrame.zw;
  return texture2D(uFigureMask, vec2(at.x, 1.0 - at.y)).rg;
}
vec4 sdfAt(vec2 world) { return texture2D(uSdf, (world - uSdfFrame.xy) * uSdfFrame.zw); }
float shadowVisibility(vec2 world) {
  vec2 toReceiver = world - uLight.xy;
  float full = length(toReceiver);
  vec2 dir = full > 0.0 ? toReceiver / full : vec2(1.0, 0.0);
  if (uCone.w > 0.5) {
    float off = atan(dir.y, dir.x) - uCone.x;
    if (abs(atan(sin(off), cos(off))) >= uCone.y) return 0.0;
  }
  float cell = uSdfTrace.y, hit = cell * 0.25, minStep = cell * 0.5, edgeSoft = uSdfEdge;
  vec4 carrier = sdfAt(uLight.xy);
  // Rock inside the clearance counts for a lamp with a reach; the tracing below only starts behind the carrying figure.
  float enter = -1.0;
  bool enteredRock = false;
  if (uReach.x > 0.0 && carrier.r < ${LAMP_CLEARANCE_PX.toFixed(1)} + cell) {
    for (int k = 0; k < 5; k++) {
      float at = float(k) * ${(LAMP_CLEARANCE_PX / 5).toFixed(1)};
      if (at >= full) break;
      vec4 q = sdfAt(uLight.xy + dir * at);
      if (q.a > 0.75 && q.r < hit) { enter = at; enteredRock = true; break; }
    }
  }
  if (enter < 0.0 && full <= ${LAMP_CLEARANCE_PX.toFixed(1)}) return 1.0;
  vec4 receiver = sdfAt(world);
  bool onSurface = receiver.r < cell * 0.5;
  bool onFigure = onSurface && receiver.a > 0.25 && receiver.a <= 0.75;
  float selfHeight = onFigure ? receiver.g : -1.0, surfaceHeight = receiver.g;
  bool shownFigures = uFigureContact.x > 0.5;
  float edgeShare = 0.0, edgeHeight = 0.0, apart = 1.0;
  bool atContact = false;
  if (shownFigures) {
    // A figure's blocker is grown and closed; what counts as the figure itself is the picture it shows. The ground between the two
    // is ground, and lies in the figure's shadow like any other.
    vec2 shown = figureShownAt(world);
    if (shown.r >= uFigureBand.y) { onSurface = true; onFigure = true; selfHeight = shown.g * 510.0; surfaceHeight = selfHeight; }
    else {
      if (onFigure && receiver.a > 0.4) { onSurface = false; onFigure = false; selfHeight = -1.0; }
      // A texel the figure's edge runs through is traced as ground; what the figure itself would see is kept beside it and mixed in.
      if (shown.r > uFigureBand.x && !onSurface) { edgeShare = smoothstep(uFigureBand.x, uFigureBand.y, shown.r); edgeHeight = shown.g * 510.0; }
    }
  }
  float carrierHeight = carrier.r < cell * 0.5 && carrier.a > 0.25 && carrier.a <= 0.75 ? carrier.g : -1.0;
  // A surface under a higher light is lit from above instead of from the ground.
  float receiverHeight = onSurface ? min(surfaceHeight, uLight.w) : 0.0;
  float source = ${SOURCE_RADIUS_BASE_PX.toFixed(1)} + uLight.w * ${SOURCE_RADIUS_PER_HEIGHT.toFixed(2)};
  // Only ground receivers see a soft tip; a surface already sits at the height the band would fade across.
  float heightSoft = onSurface ? 2.0 : 2.0 + source * ${HEIGHT_SOFT_PER_SOURCE.toFixed(2)};
  float figures = 1.0, solids = 1.0, t = ${LAMP_CLEARANCE_PX.toFixed(1)}, previous = 0.0, lastStep = 0.0;
  for (int i = 0; i < ${MAX_TRACE_STEPS}; i++) {
    if (enter >= 0.0 || float(i) >= uSdfTrace.x) break;
    vec4 s = sdfAt(uLight.xy + dir * t);
    float d = s.r, left = full - t;
    // Where the ray came closest to this sample's blocker, if that lies between this sample and the previous one.
    float back = (d * d - previous * previous + lastStep * lastStep) / (2.0 * max(lastStep, 0.01));
    bool between = back > 0.0 && back < lastStep;
    // The sight line sinks towards the receiver, so a blocker's far contour decides whether it cuts the line.
    // That contour is known on the first sample past it; a sample inside lies at an arbitrary spot and would band the shadow's end.
    bool passedBlocker = lastStep > 0.0 && previous < hit && d >= hit;
    float sight = mix(uLight.w, receiverHeight, clamp((t - (passedBlocker ? min(d, lastStep) : between ? back : 0.0)) / full, 0.0, 1.0));
    // A blocker no taller than the surface the ray ends on can only be that surface.
    float blocks = s.g > receiverHeight + 0.5 ? smoothstep(-heightSoft, heightSoft, s.g - sight) : 0.0;
    bool isRock = s.a > 0.75, isFigure = s.a > 0.25 && !isRock, touching = d < hit;
    bool own = isFigure && (selfHeight >= 0.0 && left < selfHeight * ${SELF_RANGE_PER_HEIGHT.toFixed(2)} && abs(s.g - selfHeight) < 3.0
      || carrierHeight >= 0.0 && s.a > 0.55 && t < ${CARRIER_BODY_PX.toFixed(1)} && abs(s.g - carrierHeight) < 3.0);
    // Right before a ground receiver the field's figures do not count: their grown rim would shade the lamp's side. What a figure's
    // true picture blocks there is read from the mask after the trace, at fixed spots, so it does not depend on where samples fall.
    if (!own && shownFigures && isFigure && !onFigure && s.a > 0.4 && left < uFigureContact.y) { own = true; atContact = true; }
    float step = clamp(d, minStep, uSdfTrace.z);
    if (!own) {
      if (touching && !isFigure && blocks > 0.95) { enter = t; enteredRock = isRock; break; }
      // The share of the source the blocker leaves visible at the closest approach.
      float near = between ? sqrt(max(d * d - back * back, 0.0)) : d;
      float open = clamp(near / max(source * (left + (between ? back : 0.0)) / full, edgeSoft), 0.0, 1.0);
      float shade = s.b * blocks * (1.0 - open);
      if (isFigure) {
        figures = min(figures, 1.0 - shade);
        // The figure whose edge crosses this texel does not shade its own share of it.
        if (edgeShare <= 0.0 || !(left < edgeHeight * ${SELF_RANGE_PER_HEIGHT.toFixed(2)} && abs(s.g - edgeHeight) < 3.0)) apart = min(apart, 1.0 - shade);
      } else solids = min(solids, 1.0 - shade);
      if ((figures < 0.01 && (edgeShare <= 0.0 || apart < 0.01)) || (solids < 0.01 && !onSurface)) return 0.0;
    }
    if (touching) {
      // Inside something the ray passes over or through: its interior has no distance to work with.
      step = max(minStep, min(s.g * 0.2, blocks < 0.95 ? 8.0 : 24.0));
      if (blocks < 0.05 && uLight.w > receiverHeight) {
        // Still well above it: skip to where the sight line gets close to its top.
        float comesDown = full * (uLight.w - s.g - heightSoft) / (uLight.w - receiverHeight);
        step = max(step, min(comesDown - t, 64.0));
      }
    }
    if (t >= full) break;
    // The last sample lies on the receiver: a blocker right before it would otherwise never be passed.
    step = min(step, full - t);
    previous = d;
    lastStep = step;
    t += step;
  }
  if (enter < 0.0) {
    float seen = onSurface && !onFigure && t < full ? 0.0 : min(figures, solids);
    if (atContact && seen > 0.0) {
      float covered = 0.0;
      for (int k = 1; k <= ${CONTACT_TAPS}; k++) {
        float back = uFigureContact.y * float(k) / ${CONTACT_TAPS.toFixed(1)};
        if (back >= full) break;
        covered = max(covered, smoothstep(uFigureBand.x, max(uFigureBand.y, uFigureBand.x + 0.01), figureShownAt(world - dir * back).r));
      }
      seen *= 1.0 - covered;
    }
    return edgeShare > 0.0 ? mix(seen, min(apart, solids), edgeShare) : seen;
  }
  // Lit rim of the first solid blocker: the lamp's reach on rock (GDD Nachtsicht N-4), a narrow seam on everything else.
  float depth = full - enter, reach = ${OCCLUDER_SHADE_FALLOFF_PX.toFixed(1)}, fullyLit = 0.0;
  if (enteredRock && uReach.x > 0.0) {
    float nearFar = clamp((enter - ${SURFACE_REACH_DISTANCE_START_PX.toFixed(1)}) / max(1.0, uLight.z * ${SURFACE_REACH_DISTANCE_SHARE.toFixed(3)} - ${SURFACE_REACH_DISTANCE_START_PX.toFixed(1)}), 0.0, 1.0);
    reach = mix(uReach.x, uReach.y, nearFar * nearFar * (3.0 - 2.0 * nearFar));
    fullyLit = reach * ${REACH_LIT_SHARE.toFixed(2)};
  }
  if (depth >= reach) return 0.0;
  // Everything behind the blocker's far contour stays dark, ground and further blockers alike.
  float leaves = 1e6;
  for (int k = 1; k <= ${EXIT_TAPS}; k++) {
    float at = enter + depth * float(k) / ${EXIT_TAPS.toFixed(1)};
    vec4 q = sdfAt(uLight.xy + dir * at);
    if (q.r > cell * 0.5 || (enteredRock && q.a <= 0.75)) { leaves = max(at - q.r, enter); break; }
  }
  float shade = max(smoothstep(fullyLit, reach, depth), smoothstep(leaves - 1.0, leaves + uSdfTrace.w, full));
  return figures * (1.0 - shade);
}`;

class SdfShadowProvider implements ShadowProvider {
  readonly id = 'sdf';
  readonly glsl = GLSL;
  private readonly flood: JumpFloodField;
  private readonly trace = new Float32Array(4);
  private readonly contact = new Float32Array(2);

  constructor(private readonly scene: Phaser.Scene) {
    this.flood = new JumpFloodField(scene);
  }

  prepare(field: OccluderField): void {
    const profile = getGraphicsQualityProfile(this.scene), quality = QUALITY[profile.preset];
    this.flood.prepare(field, quality);
    this.trace[0] = quality.steps; this.trace[1] = quality.cellPx; this.trace[2] = this.flood.maxDistancePx * SAFE_STEP_SHARE;
    this.trace[3] = Math.max(ROCK_BEHIND_SOFT_PX[1], ROCK_BEHIND_SOFT_LIGHTMAP_PX / lightMapScaleV2(profile.preset, profile.lightMapScale));
  }

  textures(field: OccluderField): readonly Phaser.Textures.Texture[] {
    const texture = this.flood.texture;
    // Without a mask the unit still needs a texture; the shader then does not read it.
    return texture ? [texture, field.figureMask ?? texture] : [];
  }

  setUniforms(set: (name: string, value: unknown) => void, field: OccluderField): void {
    set('uSdf', 1); set('uSdfFrame', this.flood.frame); set('uSdfTrace', this.trace);
    this.contact[0] = field.figureMask ? 1 : 0; this.contact[1] = FIGURE_GROWTH_PX + this.trace[1] + 1;
    set('uFigureMask', 2); set('uFigureMaskFrame', field.figureMaskFrame); set('uFigureContact', this.contact);
    set('uFigureBand', isLightingFeatureOn('figureEdgeBlend') ? FIGURE_EDGE_BAND : HARD_FIGURE_EDGE);
    set('uSdfEdge', isLightingFeatureOn('softShadowEdge') ? this.trace[1] * MIN_PENUMBRA_CELLS : HARD_EDGE_PX);
  }

  distanceField(): DistanceFieldView | null {
    const texture = this.flood.texture;
    return texture ? { texture, frame: this.flood.frame, cellPx: this.trace[1] } : null;
  }

  destroy(): void { this.flood.destroy(); }
}

registerShadowProvider('sdf', scene => new SdfShadowProvider(scene));
