/**
 * Steam-Variante, läuft in der Desktop-Shell (`desktop/`). Wird nur aus `src/platform/` importiert.
 *
 * Mit Steam: Der Host ist Owner einer Steam-Lobby, Clients treten über Einladung, „Spiel beitreten“,
 * Spielsuche oder `+connect_lobby` bei; Daten laufen über `ISteamNetworkingMessages` (Valve-Relay),
 * siehe `ShellSteamNetBridge`. Ohne Steam (Client aus, `--no-steam`, Steam-Build im Browser)
 * eröffnet die Variante einen Host-Raum ohne Netzweg: Alles außer Mehrspieler funktioniert. PeerJS
 * bleibt in beiden Fällen draußen.
 *
 * Ein Beitritt zur Laufzeit lädt das Spiel neu, wie ein Einladungslink im Browser: Die Shell merkt
 * sich die Lobby, der Neustart tritt ihr über `pendingStart` bei. Läuft schon ein Steam-Raum, fragt
 * das Spiel vorher nach (`setIncomingJoinHandler`).
 *
 * Host-Übergabe: Geht der Host, hält die Shell die Lobby jedes Gasts über das Neuladen. Steam wählt
 * unter den Verbliebenen einen neuen Owner; der eröffnet den Raum in derselben Lobby neu, die
 * anderen treten ihm bei (`resumeSteamHandover`).
 */
import { ROOM_HANDOVER_JOIN_WINDOW_MS } from '../../config';
import { FULL_CONTENT_POLICY } from '../../config/distributionContentPolicy';
import { createOfflineHostSession } from '../../network/peer/OfflineHostSession';
import { createPeerNetworkError } from '../../network/peer/PeerNetworkError';
import {
  createSteamHostSession,
  joinSteamSession,
  resumeSteamHandover,
  STEAM_LOBBY_KEYS,
  writeSteamLobbyPresence,
  type SteamLobbyVisibility,
  type SteamPeerSession,
} from '../../network/steam';
import { takeRoomHandoverTicket } from '../../network/RoomHandover';
import type { RoomVisibility } from '../../types';
import { sanitizePlayerName } from '../../utils/playerName';
import type {
  PlatformAchievementState,
  PlatformIncomingJoin,
  PlatformPublicRoom,
  PlatformRoomPresence,
  PlatformServices,
  PlatformSessionStart,
} from '../PlatformServices';
import { resolveDesktopPreferences } from './desktopPreferencesStorage';
import { readDesktopShell, readDesktopSteam, type DesktopSteamBridge } from './desktopShell';
import { ShellSteamNetBridge } from './ShellSteamNetBridge';
import { steamRichPresenceEntries } from './steamRichPresence';
import { joinablePublicListings, PUBLIC_ROOM_SEARCH_LIMIT, publicRoomSearchFilters, toPublicRoom } from './steamPublicRooms';

/** Die Ping-Position steht erst, wenn Steam die Relays vermessen hat; danach ändert sie sich selten. */
const PING_LOCATION_RETRY_MS = 2_000;
const PING_LOCATION_REFRESH_MS = 60_000;

let steamNet: ShellSteamNetBridge | null | undefined;
let activeSteamSession: SteamPeerSession | null = null;
let incomingJoinHandler: ((join: PlatformIncomingJoin) => void) | null = null;
/** Zuletzt umgesetzte Sichtbarkeit des eigenen Raums (Host). */
let roomVisibility: RoomVisibility = 'friends';
let pingLocationTimer: ReturnType<typeof setTimeout> | null = null;

/** Was ein Gast für die Übergabe über das Neuladen mitnimmt (im Ticket). */
interface SteamHandoverData {
  lobbyId: string;
  previousOwner: string | null;
}

/** Die Bridge entsteht beim ersten Raum, nicht beim Modulladen (Tests, Browser ohne Shell). */
function steamNetBridge(): ShellSteamNetBridge | null {
  if (steamNet !== undefined) return steamNet;
  const shell = readDesktopSteam();
  const status = shell?.status();
  steamNet = shell && status?.available ? new ShellSteamNetBridge(shell, status) : null;
  if (shell && steamNet) installJoinRequests(shell, steamNet);
  return steamNet;
}

/**
 * Lädt neu; der Neustart tritt der Lobby bei. Den eigenen Raum verlässt `pagehide` (`main.ts`), sobald
 * die Seite wirklich geht – bis dahin laufen noch Frames, die eine geschlossene Session nicht fänden.
 */
function switchToLobby(shell: DesktopSteamBridge, lobbyId: string): void {
  console.info(`[Steam] Raum wird für Lobby ${lobbyId} gewechselt.`);
  shell.setPendingLobby(lobbyId);
  window.location.reload();
}

function installJoinRequests(shell: DesktopSteamBridge, net: ShellSteamNetBridge): void {
  net.lobby.onJoinRequested(lobbyId => {
    if (activeSteamSession?.lobbyId === lobbyId) return;
    console.info(`[Steam] Beitritt zu Lobby ${lobbyId} angefragt.`);
    let decided = false;
    const accept = (): void => {
      if (decided) return;
      decided = true;
      switchToLobby(shell, lobbyId);
    };
    // Ohne eigenen Steam-Raum (z. B. Raum ohne Netzwerk) geht nichts verloren.
    if (!activeSteamSession || !incomingJoinHandler) { accept(); return; }
    incomingJoinHandler({
      accept,
      decline: () => {
        if (decided) return;
        decided = true;
        console.info(`[Steam] Beitritt zu Lobby ${lobbyId} abgelehnt.`);
      },
    });
  });
}

/** ALLEIN ist eine private Lobby, die zusätzlich niemanden mehr hereinlässt (`configure`). */
function steamLobbyVisibility(visibility: RoomVisibility): SteamLobbyVisibility {
  if (visibility === 'public') return 'public';
  return visibility === 'closed' ? 'private' : 'friends-only';
}

/** Alle setzen ihre Rich Presence (N3); der Host führt zusätzlich die Lobby-Daten nach (N2). */
function updatePresence(presence: PlatformRoomPresence | null): void {
  if (!steamNetBridge()) return;
  const session = activeSteamSession;
  readDesktopSteam()?.setRichPresence(steamRichPresenceEntries(presence, session?.lobbyId ?? null));
  if (!steamNet || !session || !presence || !session.transport.isHost) return;
  writeSteamLobbyPresence(steamNet.lobby, session.lobbyId, {
    phase: presence.phase,
    players: presence.players,
    mode: presence.mode,
    map: presence.coopMapId,
    hostName: presence.hostName,
  });
}

/** Host: hält die eigene Ping-Position in den Lobby-Daten aktuell (Ping-Anzeige der Spielsuche). */
function schedulePingLocationPublish(delayMs: number): void {
  if (pingLocationTimer !== null) clearTimeout(pingLocationTimer);
  pingLocationTimer = setTimeout(() => {
    pingLocationTimer = null;
    const session = activeSteamSession;
    const steam = readDesktopSteam();
    if (!steamNet || !steam || !session?.transport.isHost) return;
    const location = steam.pingLocation();
    if (location && steamNet.lobby.getData(session.lobbyId, STEAM_LOBBY_KEYS.pingLocation) !== location) {
      steamNet.lobby.setData(session.lobbyId, STEAM_LOBBY_KEYS.pingLocation, location);
    }
    schedulePingLocationPublish(location ? PING_LOCATION_REFRESH_MS : PING_LOCATION_RETRY_MS);
  }, delayMs);
}

function startSession(session: SteamPeerSession): SteamPeerSession {
  activeSteamSession = session;
  if (session.transport.isHost) schedulePingLocationPublish(0);
  return session;
}

/** Ohne laufendes Steam bleibt der Stand im Spielstand und wird beim nächsten Start nachgeholt. */
function syncAchievements(state: PlatformAchievementState): void {
  const steam = readDesktopSteam();
  if (!steam?.status()?.available) return;
  steam.syncAchievements({ unlocked: [...state.unlocked], stats: { ...state.stats } });
}

function steamPersonaName(): string | null {
  const status = readDesktopSteam()?.status();
  if (!status?.available) return null;
  return sanitizePlayerName(status.personaName) || null;
}

function parseHandoverData(raw: string | null): SteamHandoverData | null {
  if (raw === null) return null;
  try {
    const value: unknown = JSON.parse(raw);
    if (!value || typeof value !== 'object') return null;
    const { lobbyId, previousOwner } = value as Record<string, unknown>;
    if (typeof lobbyId !== 'string' || !/^\d+$/.test(lobbyId)) return null;
    return { lobbyId, previousOwner: typeof previousOwner === 'string' ? previousOwner : null };
  } catch {
    return null;
  }
}

/**
 * Eine Einladung, „Spiel beitreten“ oder die Spielsuche gewinnt; sonst setzt ein Übergabe-Ticket
 * den Raum in der gehaltenen Lobby fort. Eine gehaltene Lobby, die nicht gebraucht wird, verlässt
 * die Shell sofort, damit sie nicht als Geist in der Freundesliste steht.
 */
function pendingStart(): PlatformSessionStart {
  const ticket = takeRoomHandoverTicket();
  const steam = steamNetBridge() ? readDesktopSteam() : null;
  if (!steam) return { kind: 'host' };
  const retained = steam.takeRetainedLobby();
  const launch = steam.takeLaunchLobby();
  const handover = ticket ? parseHandoverData(ticket.platform) : null;
  if (launch === null && ticket && handover && retained === handover.lobbyId) return { kind: 'handover', ticket };
  if (retained !== null) steam.leaveLobby(retained);
  return launch === null ? { kind: 'host' } : { kind: 'join', target: launch };
}

async function listPublicRooms(): Promise<PlatformPublicRoom[]> {
  const steam = readDesktopSteam();
  if (!steamNetBridge() || !steam) return [];
  const listings = joinablePublicListings(
    await steam.searchLobbies(publicRoomSearchFilters(), PUBLIC_ROOM_SEARCH_LIMIT),
    activeSteamSession?.lobbyId ?? null,
  );
  const pings = steam.estimatePings(listings.map(listing => listing.data[STEAM_LOBBY_KEYS.pingLocation] ?? ''));
  return listings.map((listing, index) => toPublicRoom(listing, pings[index] ?? null));
}

export const steamPlatformServices: PlatformServices = {
  sessions: {
    pendingStart,
    host: async (options, room) => {
      const net = steamNetBridge();
      if (!net) return createOfflineHostSession(options);
      try {
        const session = startSession(await createSteamHostSession(net, {
          room: options,
          visibility: steamLobbyVisibility(room.visibility),
          roomCode: room.roomCode,
        }));
        console.info(`[Steam] Raum ${session.roomCode} in Lobby ${session.lobbyId}`);
        return session;
      } catch (error) {
        // Steam läuft, aber ohne Verbindung zu den Steam-Servern gibt es keine Lobby.
        console.warn('[Steam] Lobby nicht angelegt – Raum ohne Netzwerk.', error);
        return createOfflineHostSession(options);
      }
    },
    join: async (lobbyId, options) => {
      const net = steamNetBridge();
      if (!net) throw createPeerNetworkError('connection-failed', new Error('Steam is not available'));
      const session = startSession(await joinSteamSession(net, lobbyId, { room: options }));
      console.info(`[Steam] Raum ${session.roomCode} in Lobby ${lobbyId} beigetreten`);
      return session;
    },
    prepareHandover: () => {
      const session = activeSteamSession;
      const steam = readDesktopSteam();
      if (!session || session.transport.isHost || !steam) return null;
      steam.retainLobby(session.lobbyId);
      const data: SteamHandoverData = { lobbyId: session.lobbyId, previousOwner: session.transport.hostSteamId };
      return JSON.stringify(data);
    },
    continueHandover: async (ticket, options, room) => {
      const net = steamNetBridge();
      const data = parseHandoverData(ticket.platform);
      if (!net || !data) throw createPeerNetworkError('host-not-found');
      const session = startSession(await resumeSteamHandover(net, data.lobbyId, {
        room: options,
        roomCode: ticket.roomCode,
        previousOwner: data.previousOwner,
        visibility: steamLobbyVisibility(room.visibility),
        // Die alte Gruppe ist schon Mitglied der Lobby; die Sperre trifft nur Neue.
        joinable: room.visibility !== 'closed',
        deadline: ticket.createdAt + ROOM_HANDOVER_JOIN_WINDOW_MS,
      }));
      console.info(`[Steam] Übergabe in Lobby ${data.lobbyId}: ${session.transport.isHost ? 'neuer Host' : 'Gast'}`);
      return session;
    },
  },
  rooms: {
    visibilities: ['closed', 'friends', 'public'],
    defaultVisibility: 'friends',
    applyVisibility: visibility => {
      roomVisibility = visibility;
      const session = activeSteamSession;
      if (!steamNet || !session || !session.transport.isHost) return;
      steamNet.lobby.configure(session.lobbyId, { visibility: steamLobbyVisibility(visibility), joinable: visibility !== 'closed' });
    },
    browser: {
      list: listPublicRooms,
      join: lobbyId => {
        const steam = readDesktopSteam();
        if (steam && steamNetBridge()) switchToLobby(steam, lobbyId);
      },
    },
  },
  invites: {
    // Öffnet den Einladungsdialog des Overlays; ein Raum auf ALLEIN lädt niemanden ein.
    invite: async roomCode => {
      const session = activeSteamSession;
      if (!steamNet || !session || session.roomCode !== roomCode || roomVisibility === 'closed') return false;
      steamNet.lobby.openInviteDialog(session.lobbyId);
      return true;
    },
    confirmation: 'dialog-opened',
    setIncomingJoinHandler: handler => { incomingJoinHandler = handler; },
  },
  presence: { update: updatePresence },
  achievements: { sync: syncAchievements },
  identity: {
    // Der Steam-Persona-Name ist der Vorschlag, solange kein eigener Name gespeichert ist (O3).
    defaultPlayerName: steamPersonaName,
  },
  content: FULL_CONTENT_POLICY,
  shell: readDesktopShell(),
  saves: resolveDesktopPreferences(),
  // Die Installation liefert alles von der Platte (`app://`, Steam-Plan L1/L12).
  assets: { local: true },
};
