import type { HomingRuntimeState, ProjectileHomingAssignment, ProjectileHomingConfig } from '../types';

/**
 * Homing fixed when a projectile is fired (the colossus's siege swarm). The shot flies straight for
 * `acquireDelayMs`, then turns at most `turnDegPerSec` toward its assigned target or point. It never
 * searches another one, and it stops steering for good once the target is gone or passed.
 */
export function assignedHomingConfig(assignment: ProjectileHomingAssignment): ProjectileHomingConfig {
  return {
    acquireDelayMs: assignment.acquireDelayMs,
    maxTurnDegreesPerSecond: assignment.turnDegPerSec,
    searchRadius: 0,
    retargetIntervalMs: 0,
    maxTurnDegreesPerStep: 0,
    targetTypes: [],
    requireLineOfSight: false,
    excludeOwner: true,
  };
}

/** Runtime state of a fresh homing; an assigned one starts locked on its target or point. */
export function initialHomingState(assignment: ProjectileHomingAssignment | undefined): HomingRuntimeState {
  if (!assignment) return { lockedTargetId: null };
  if (assignment.kind === 'point') return { lockedTargetId: null, fixed: true, fixedPoint: { x: assignment.x, y: assignment.y } };
  const lockedTargetType = assignment.type === 'player' ? 'players' : assignment.type === 'decoy' ? 'decoys' : 'bases';
  return { lockedTargetId: assignment.id, lockedTargetType, fixed: true };
}

/**
 * Flight distance of a shot launched at `angle` that curves onto a fixed point: the straight lead until
 * the homing starts, the turn at its limited rate, and the rest of the way. A point shot ends there.
 */
export function estimateAssignedHomingPathPx(fromX: number, fromY: number, angle: number, toX: number, toY: number,
  speedPxPerSec: number, assignment: ProjectileHomingAssignment): number {
  const lead = speedPxPerSec * assignment.acquireDelayMs / 1000;
  const leadX = fromX + Math.cos(angle) * lead, leadY = fromY + Math.sin(angle) * lead;
  const bearing = Math.atan2(toY - leadY, toX - leadX);
  const turn = Math.abs(Math.atan2(Math.sin(bearing - angle), Math.cos(bearing - angle)));
  const radius = speedPxPerSec / Math.max(1e-6, assignment.turnDegPerSec * Math.PI / 180);
  return lead + turn * radius + Math.max(0, Math.hypot(toX - leadX, toY - leadY) - radius * Math.sin(Math.min(turn, Math.PI / 2)));
}
