import * as Phaser from 'phaser';
import { GAME_HEIGHT, GAME_WIDTH } from '../config';
import { t } from '../i18n';
import { PERSISTENT_BASE_EDITOR_VIEW_SIZE } from '../persistentBase/PersistentBaseExpansionPreview';
import { ensureGlossyButtonTexture, ensureModalFrame, ensureModalPanelTexture, textStyle, TEXT } from './ForestModal';
import { BUTTON_CURSOR } from './gameCursor';
import { MATCH_RESULTS_BACKGROUND } from './MatchResultsAssets';
import { PERSISTENT_BASE_HEADER } from './PersistentBaseAssets';
import { activateUi } from './UiAudio';
import { attachHoverEffect } from './uiHover';
import { INTENT } from './uiTheme';
import { ensureUpgradeApply, ensureUpgradeFrame } from './upgradeForestTextures';
import { UPGRADE_MENU } from './UpgradeMenuLayout';

/**
 * The Bauhof's frame: everything the editor shows the same for every session. The editor's stage
 * and its loading shell both draw it from here, so the shell's frame lies exactly over the stage's
 * when the stage takes over.
 */
type Rect = { readonly x: number; readonly y: number; readonly width: number; readonly height: number };

/** The World view's panel; the view itself fills it with map terrain, else it sits in its middle. */
export const PERSISTENT_BASE_EDITOR_WORLD_PANEL = { x: 88, y: 262, ...PERSISTENT_BASE_EDITOR_VIEW_SIZE } as const;
/** Header row above both columns: stage and tools on the left, the situation map's title on the right. */
export const PERSISTENT_BASE_EDITOR_HEADER_Y = 222;
/** Overview of the whole map (Lagekarte); empty without map terrain. */
export const PERSISTENT_BASE_EDITOR_MINIMAP_PANEL = { x: 1130, y: 242, width: 708, height: 300 } as const;
/** The inventory's cards below the overview: four columns; rows scroll. */
export const PERSISTENT_BASE_EDITOR_INVENTORY = { x: 1130, y: 584, width: 708, height: 334 } as const;
/** The notice line below the header art; only a guest's session uses it (the host owns the base). */
export const PERSISTENT_BASE_EDITOR_NOTICE_Y = 170;

export function addPersistentBaseEditorLabel(scene: Phaser.Scene, x: number, y: number, value: string,
  role: Parameters<typeof textStyle>[0], origin: number, width: number | undefined,
  into: Phaser.GameObjects.Container | null): Phaser.GameObjects.Text {
  const label = scene.add.text(x, y, value, textStyle(role, { color: TEXT.primary })).setOrigin(origin, .5);
  if (width) label.setWordWrapWidth(width);
  into?.add(label); return label;
}

/** The four strips of a rectangle around the World view (`hole`). */
export function aroundPersistentBaseEditorView(hole: Rect, x: number, y: number, width: number, height: number): Rect[] {
  const bottom = hole.y + hole.height, right = hole.x + hole.width;
  return [
    { x, y, width, height: hole.y - y },
    { x, y: bottom, width, height: y + height - bottom },
    { x, y: hole.y, width: hole.x - x, height: hole.height },
    { x: right, y: hole.y, width: x + width - right, height: hole.height },
  ];
}

/**
 * Dim around the menu, glass and forest backdrop, timber frame, header art and title. The
 * backdrops leave the World view (`hole`) open. Art the lobby has not loaded yet joins once it arrives.
 */
export function addPersistentBaseEditorFrame(scene: Phaser.Scene, chrome: Phaser.GameObjects.Container,
  hole: Rect): { readonly dim: Phaser.GameObjects.GameObject[] } {
  const menu = UPGRADE_MENU;
  // Match Upgrades: the existing lobby remains visible outside the timber frame.
  const dim = aroundPersistentBaseEditorView(hole, 0, 0, GAME_WIDTH, GAME_HEIGHT)
    .map((crop) => scene.add.rectangle(crop.x, crop.y, crop.width, crop.height, menu.dimColor, menu.dimAlpha).setOrigin(0));
  chrome.add(dim);
  const backdrop = (layer: Phaser.GameObjects.Container, key: string, width: number, height: number, tint = 0xffffff) => {
    const x = (GAME_WIDTH - width) / 2, y = (GAME_HEIGHT - height) / 2;
    for (const crop of aroundPersistentBaseEditorView(hole, x, y, width, height)) {
      const image = scene.add.image(x, y, key).setOrigin(0).setDisplaySize(width, height).setTint(tint);
      image.setCrop((crop.x - x) * image.width / width, (crop.y - y) * image.height / height,
        crop.width * image.width / width, crop.height * image.height / height);
      layer.add(image);
    }
  };
  const glass = scene.add.container(0, 0), forest = scene.add.container(0, 0);
  chrome.add([glass, forest]);
  backdrop(glass, ensureModalPanelTexture(scene, '_base_panel', menu.width, menu.height), menu.width - 80, menu.height - 80);
  // The lobby owns deferred loading; opening this menu early must not enqueue a second load.
  whenTexture(scene, forest, MATCH_RESULTS_BACKGROUND.key, () => backdrop(forest, MATCH_RESULTS_BACKGROUND.key,
    menu.width - menu.forestInsetX, menu.height - menu.forestInsetY, menu.forestTint));
  chrome.add(scene.add.image(menu.centerX, menu.centerY, ensureModalFrame(scene, menu.width, menu.height))
    .setDisplaySize(menu.width, menu.height));
  const headerArt = PERSISTENT_BASE_HEADER;
  const header = scene.add.image(menu.centerX, menu.headerY, scene.textures.exists(headerArt.key) ? headerArt.key
    : ensureGlossyButtonTexture(scene, 'base-header', headerArt.width, headerArt.height, INTENT.neutral.fill))
    .setDisplaySize(headerArt.width, headerArt.height);
  chrome.add(header);
  if (header.texture.key !== headerArt.key) whenTexture(scene, header, headerArt.key,
    () => header.setTexture(headerArt.key).setDisplaySize(headerArt.width, headerArt.height));
  addPersistentBaseEditorLabel(scene, menu.centerX, menu.headerY + 4, t('ui.base.title').toLocaleUpperCase(), 'display', .5,
    undefined, chrome).setFontSize(44).setColor('#efe4bd').setStroke('#1e160f', 3);
  return { dim };
}

/**
 * The World view's panel: a dark mat around the view, its edge and the timber frame. `inside`
 * lies between the mat and the frame, so the frame's inner edge stays on top of it.
 */
export function addPersistentBaseEditorWorldFrame(scene: Phaser.Scene, chrome: Phaser.GameObjects.Container, view: Rect,
  inside: readonly Phaser.GameObjects.GameObject[] = []): void {
  const panel = PERSISTENT_BASE_EDITOR_WORLD_PANEL;
  // One frame for every map: the World sits in its middle, the rest of the panel is a dark mat.
  for (const mat of aroundPersistentBaseEditorView(view, panel.x, panel.y, panel.width, panel.height)) {
    if (mat.width > 0 && mat.height > 0) chrome.add(scene.add.rectangle(mat.x, mat.y, mat.width, mat.height, 0x0b120d, .94).setOrigin(0));
  }
  chrome.add(scene.add.rectangle(view.x, view.y, view.width, view.height).setOrigin(0).setStrokeStyle(1, 0x718160, .55));
  chrome.add([...inside]);
  const frameWidth = panel.width + 40, frameHeight = panel.height + 40;
  chrome.add(scene.add.image(panel.x + panel.width / 2, panel.y + panel.height / 2,
    ensureUpgradeFrame(scene, frameWidth, frameHeight)).setDisplaySize(frameWidth, frameHeight));
}

/** The situation map's panel behind the overview. */
export function addPersistentBaseEditorMinimapPanel(scene: Phaser.Scene, chrome: Phaser.GameObjects.Container): void {
  const panel = PERSISTENT_BASE_EDITOR_MINIMAP_PANEL;
  chrome.add(scene.add.rectangle(panel.x, panel.y, panel.width, panel.height, 0x101b14, .55)
    .setOrigin(0).setStrokeStyle(1, 0x718160, .5));
}

/** Cancel or Apply at the bottom of the menu; `enabled` is read on every press. */
export function addPersistentBaseEditorAction(scene: Phaser.Scene, chrome: Phaser.GameObjects.Container, kind: 'cancel' | 'apply',
  onClick: () => void, enabled: () => boolean = () => true): { readonly image: Phaser.GameObjects.Image; readonly label: Phaser.GameObjects.Text } {
  const { buttonWidth: w, buttonHeight: h, buttonY: y, buttonGap: gap, centerX } = UPGRADE_MENU;
  const x = centerX + (kind === 'apply' ? 1 : -1) * (gap + w) / 2;
  const texture = kind === 'apply' ? ensureUpgradeApply(scene, w, h) : ensureGlossyButtonTexture(scene, kind, w, h, INTENT.neutral.fill);
  const image = scene.add.image(x, y, texture).setInteractive({ cursor: BUTTON_CURSOR });
  const label = addPersistentBaseEditorLabel(scene, x, y, t(`ui.upgrades.${kind}`), 'label', .5, undefined, chrome).setFontSize(22);
  if (kind === 'apply') label.setColor('#f3ffca');
  image.on('pointerdown', () => { if (enabled()) activateUi(scene, onClick); });
  attachHoverEffect(scene, image, label);
  chrome.add(image); chrome.bringToTop(label);
  return { image, label };
}

/** Runs `apply` once the texture exists: now, or when the lobby's deferred loading adds it. */
function whenTexture(scene: Phaser.Scene, owner: Phaser.GameObjects.GameObject, key: string, apply: () => void): void {
  if (scene.textures.exists(key)) { apply(); return; }
  const event = Phaser.Textures.Events.ADD_KEY + key;
  scene.textures.once(event, apply);
  owner.once(Phaser.GameObjects.Events.DESTROY, () => scene.textures.off(event, apply));
}
