type EnemyAttackTargetKind = 'base' | 'player' | 'decoy' | 'ally' | 'train' | 'obstacle';

interface EnemyAttackCandidate {
  readonly kind: EnemyAttackTargetKind;
  readonly priority: 1 | 2 | 3 | 4;
  readonly distance: number;
  readonly targetX: number;
  readonly targetY: number;
  readonly targetId?: string;
  readonly targetRef?: EnemyAiTargetRef;
  readonly obstacle?: RockPhysicsProxy;
  readonly obstacleIndex?: number;
}

interface SustainedEnemyAttackState {
  readonly weaponId: string;
  readonly targetRef: EnemyAiTargetRef | null;
  readonly targetId: string | null;
  targetX: number;
  targetY: number;
  readonly fireUntil: number;
  lastShotAt: number;
}

interface PlayerTargetLockState {
  readonly targetRef: EnemyAiTargetRef;
  readonly lockedUntil: number;
}

interface MeleeWindupState {
  readonly attackWeapon: EnemyAttackWeapon;
  readonly target: EnemyAttackCandidate;
  readonly presentation: EnemyClawAttack;
  executed: boolean;
}

/** Sammelphase einer Salve mit `salvo.chargeMs`: der Gegner haelt an, bis bei `fireAt` ihr erster Schuss faellt. */
interface SalvoChargeState {
  readonly attackWeapon: EnemyAttackWeapon;
  readonly target: EnemyAttackCandidate;
  readonly fireAt: number;
}

/** Laufende Salve eines Gegners; pro Gegner kann nur eine Waffe gleichzeitig salvieren. */
interface EnemySalvoState {
  readonly weaponId: string;
  target: EnemyAttackCandidate;
  shotsFired: number;
  nextShotAt: number;
  /** Verfaellt die Salve ohne Nachschuss (Ziel weg, keine Sichtlinie), gilt sie als abgefeuert. */
  expiresAt: number;
}

/** Faction-resolved ground fire left by an enemy flame burst. */
export interface EnemyFlameGroundCell {
  readonly durationMs: number;
  readonly burnDurationMs: number;
  readonly burnDamagePerTick: number;
  /** Share of the base fire damage while this fire keeps a base burning. */
  readonly baseDamageMult: number;
  readonly visualStyle: import('../types').GroundFireVisualStyle;
  readonly damageTarget: import('../types').GroundFireDamageTarget;
  readonly sourceId: string;
}

export interface EnemyFlameGroundPort {
  ignite(enemy: EnemyEntity, x: number, y: number, cell: EnemyFlameGroundCell, now: number): void;
  /** Direct damage of a flame shot to the base it was aimed at. */
  scorchBase?(enemy: EnemyEntity, baseId: string, damage: number, sourceId: string, now: number): void;
}

/**
 * Owner of a body's salvo rhythm (the Demon Badger's heat). A spent salvo with `shotsFired` > 0 is
 * reported; a number locks every salvo weapon of the body for that pause, null keeps the weapon's own.
 */
export interface EnemySalvoHooks {
  salvoSpent(enemy: EnemyEntity, shotsFired: number, now: number): number | null;
}

/** Lock every salvo weapon of a body until `readyAt` (one rhythm across its target modes). */
export function lockEnemySalvoWeapons(enemy: EnemyEntity, readyAt: number): void {
  for (const attackWeapon of enemy.getAttackWeapons()) {
    if (attackWeapon.salvo) enemy.lockWeaponUntil(attackWeapon.weapon, readyAt);
  }
}

/** A burst's ground fire lands this far behind its target (inside a struck base wall). */
const FLAME_GROUND_OVERSHOOT_PX = 12;
/** A flame burst that paused longer than this ignites again before it fires. */
const IGNITION_GRACE_MS = 600;
/** Collateral scorch of one jet on one base at most this often (a flame weapon fires every ~100 ms). */
const COLLATERAL_SCORCH_INTERVAL_MS = 250;
/** Cells lit along the end of the burst, measured back from its reach. */
const FLAME_GROUND_CELL_OFFSETS = [0, 18] as const;

export class CoopDefenseEnemyAttackSystem implements EnemyCombatMovementSource {
  private readonly targetFacing = new WeakMap<EnemyEntity, { angle: number; at: number; held: boolean; from: number; budget: number }>();
  /** Overlapping centers do not define a stable bearing. Hysteresis avoids toggling at the boundary. */
  private aimAt(enemy: EnemyEntity, x: number, y: number, now: number): number {
    const previous = this.targetFacing.get(enemy);
    // Repeated read/fire in one host step must not spend the turn budget twice. A second call in
    // the same step may aim at another target (movement aim vs. selected weapon), so it turns from
    // the step's start angle with the step's budget instead of reusing the first target's angle.
    const sameStep = previous?.at === now;
    const dx = x - enemy.sprite.x, dy = y - enemy.sprite.y, distance = Math.hypot(dx, dy);
    const radius = enemy.getCollisionRadius();
    const held = distance < radius * (previous?.held ? 1.25 : 1);
    const current = sameStep ? previous.from : enemy.getAimAngle();
    const limit = sameStep ? previous.budget
      : previous ? Math.PI * 2 * Math.min(100, Math.max(0, now - previous.at)) / 1000 : Math.PI;
    let angle = current;
    if (!held && distance > .001) {
      const desired = Math.atan2(dy, dx);
      const diff = Math.atan2(Math.sin(desired - current), Math.cos(desired - current));
      angle += Math.max(-limit, Math.min(limit, diff));
    }
    this.targetFacing.set(enemy, { angle, at: now, held, from: current, budget: limit });
    return angle;
  }
  private intents: EnemyIntentSystem | null = null;
  setIntents(intents: EnemyIntentSystem | null): void { this.intents = intents; }
  private decoyTargets: DecoyTargetPort | null = null;
  setDecoyTargets(port: DecoyTargetPort | null): void { this.decoyTargets = port; }
  private flameGround: EnemyFlameGroundPort | null = null;
  /** Ground fire of igniting enemy flames (a base inside the cells catches fire through its void-fire owner). */
  setFlameGround(port: EnemyFlameGroundPort | null): void { this.flameGround = port; }
  /**
   * Hysterese der Mindest-Zieldistanz: eine bereits laufende Salve darf bis zu dieser Strecke
   * unterhalb ihrer Untergrenze weiterfeuern. Ohne den Puffer bricht ein Gegner seine Salve ab,
   * sobald sein Ziel einen Schritt zu nah kommt, und wechselt hektisch die Waffe.
   */
  private static readonly SALVO_MIN_DISTANCE_HYSTERESIS_PX = 60;
  /** A gathering salvo renews its walking pace each frame for at most this long. */
  private static readonly CHARGE_PACE_HOLD_MS = 120;
  /**
   * Verliert ein Gegner mitten in der Salve sein Ziel, laeuft sie nach diesem Vielfachen ihres
   * Schusstakts aus und startet ihre Pause – sonst bliebe ein halb verbrauchter Zaehler beliebig
   * lange stehen und die naechste Salve waere zu kurz.
   */
  private static readonly SALVO_GAP_TOLERANCE_FACTOR = 5;
  private static readonly MIN_SALVO_GAP_TOLERANCE_MS = 1_000;
  /** Prevents near-equal player distances from causing visible target oscillation. */
  private static readonly PLAYER_TARGET_LOCK_DURATION_MS = 2_000;

  private readonly sustainedAttacks = new Map<string, SustainedEnemyAttackState>();
  private readonly salvoStates = new Map<string, EnemySalvoState>();
  private readonly playerTargetLocks = new Map<string, PlayerTargetLockState>();
  private readonly meleeWindups = new Map<string, MeleeWindupState>();
  private readonly salvoCharges = new Map<string, SalvoChargeState>();
  /** Announced flame bursts: the jets ignite until `fireAt`, then the burst fires at its target. */
  private readonly ignitions = new Map<string, { attackWeapon: EnemyAttackWeapon; target: EnemyAttackCandidate; fireAt: number }>();
  /** Last flame of an igniting weapon per body; a longer pause makes the next burst ignite again. */
  private readonly lastIgnitedShotAt = new Map<string, number>();
  /** Collateral scorch per body and base is rate-limited like a burn tick. */
  private readonly scorchReadyAt = new Map<string, number>();
  private clawRevision = 0;
  private clawStateSink: ((enemy: EnemyEntity, state: EnemyClawState) => void) | null = null;
  setClawStateSink(sink: ((enemy: EnemyEntity, state: EnemyClawState) => void) | null): void { this.clawStateSink = sink; }

  private clearClawAttack(enemy: EnemyEntity): void {
    if (!this.meleeWindups.delete(enemy.id)) return;
    this.clawStateSink?.(enemy, { revision: ++this.clawRevision, attack: null });
  }

  destroy(): void {
    for (const enemy of this.enemyManager.getAllEnemies()) this.clearClawAttack(enemy);
    this.meleeWindups.clear(); this.salvoCharges.clear();
    this.salvoStates.clear(); this.sustainedAttacks.clear(); this.playerTargetLocks.clear(); this.lastAttackTargets.clear();
    this.clawStateSink = null;
  }

  removeEnemy(enemy: EnemyEntity): void {
    this.clearClawAttack(enemy);
    this.salvoCharges.delete(enemy.id);
    this.salvoStates.delete(enemy.id); this.sustainedAttacks.delete(enemy.id);
    this.playerTargetLocks.delete(enemy.id); this.lastAttackTargets.delete(enemy.id);
  }
  private readonly lastAttackTargets = new Map<string, EnemyAttackCandidate>();
  private actionBlockedChecker: ((enemyId: string) => boolean) | null = null;
  private salvoHooks: EnemySalvoHooks | null = null;

  private obstacleExcluded: ((obstacleIndex: number) => boolean) | null = null;

  constructor(
    private readonly enemyManager: EnemyManager,
    private readonly playerManager: PlayerManager,
    private readonly baseManager: BaseManager | null,
    private readonly combatSystem: CombatActorStatePort & CombatGeometryPort & CombatRelationshipQueryPort,
    private readonly weaponExecution: AutomatedWeaponExecution,
    private readonly getRockObjects: () => readonly (RockPhysicsProxy | null)[] | null,
    private readonly trainAwarenessSystem: CoopDefenseEnemyTrainAwarenessSystem | null = null,
    private readonly placementSystem: PlacementSystem | null = null,
    private readonly targetCatalog: EnemyAiTargetCatalog | null = null,
  ) {}

  getCurrentTarget(enemyId: string, now = Date.now()): EnemyAiTargetRef | null {
    return this.meleeWindups.get(enemyId)?.target.targetRef
      ?? this.salvoCharges.get(enemyId)?.target.targetRef
      ?? this.salvoStates.get(enemyId)?.target.targetRef
      ?? this.sustainedAttacks.get(enemyId)?.targetRef
      ?? ((this.playerTargetLocks.get(enemyId)?.lockedUntil ?? 0) >= now
        ? this.playerTargetLocks.get(enemyId)?.targetRef ?? null : null);
  }

  setActionBlockedChecker(checker: ((enemyId: string) => boolean) | null): void {
    this.actionBlockedChecker = checker;
  }

  setSalvoHooks(hooks: EnemySalvoHooks | null): void {
    this.salvoHooks = hooks;
  }

  /** Hindernisse, die Gegner nie gezielt angreifen (reaktive Map-Objekte wie Fässer). */
  setObstacleExclusion(excluded: ((obstacleIndex: number) => boolean) | null): void {
    this.obstacleExcluded = excluded;
  }

  /**
   * No scan, cooldown, lock or salvo mutation: locomotion reads this before moving the enemy. Without
   * `aimAngle` the body keeps facing its route and only takes the attack's pace.
   */
  getCombatMovement(enemy: EnemyEntity, now: number): { aimAngle?: number; holdPosition: boolean; committed?: boolean } | null {
    if (!enemy.sprite.active || enemy.faction !== 'hostile' || enemy.isBurrowed()
      || this.combatSystem.isStunned?.(enemy.id, now) || this.actionBlockedChecker?.(enemy.id)
      || this.enemyManager.isEnemyPanicking(enemy.id) || this.trainAwarenessSystem?.blocksRegularAttacks(enemy.id)) return null;

    const windup = this.meleeWindups.get(enemy.id);
    if (windup) return { aimAngle: isAllRoundStrike(windup.attackWeapon) ? undefined : windup.presentation.angle, holdPosition: true, committed: true };
    const charge = this.salvoCharges.get(enemy.id);
    if (charge && !charge.attackWeapon.aimsWithoutTurning) return { aimAngle: this.aimAt(enemy, charge.target.targetX, charge.target.targetY, now),
      holdPosition: charge.attackWeapon.attackMovementSpeedFactor <= 0, committed: true };
    const ignition = this.ignitions.get(enemy.id);
    if (ignition) return { aimAngle: this.aimAt(enemy, ignition.target.targetX, ignition.target.targetY, now),
      holdPosition: ignition.attackWeapon.attackMovementSpeedFactor <= 0, committed: true };
    // A volley aiming without turning leaves facing and route to the body (or to a melee target).
    let pace = charge?.attackWeapon;
    const salvo = this.salvoStates.get(enemy.id);
    const sustained = this.sustainedAttacks.get(enemy.id);
    const committedWeaponId = salvo && now < salvo.expiresAt ? salvo.weaponId
      : sustained && (now < sustained.fireUntil || sustained.lastShotAt < sustained.fireUntil) ? sustained.weaponId : null;
    for (const attackWeapon of enemy.getAttackWeapons()) {
      if (committedWeaponId && attackWeapon.weapon.config.id !== committedWeaponId) continue;
      if (attackWeapon.aimsWithoutTurning) {
        if (committedWeaponId === attackWeapon.weapon.config.id) pace = attackWeapon;
        continue;
      }
      // A salvo weapon in its pause cannot fire; aiming at its target would turn the body away from
      // what the next ready weapon (e.g. a melee bite on a base) actually attacks. A blocked body
      // faces what it has to break through first; the salvo needs no facing to start.
      if (attackWeapon.salvo && committedWeaponId !== attackWeapon.weapon.config.id
        && (!enemy.isWeaponReady(attackWeapon.weapon, now) || enemy.isPathBlocked())) continue;
      const fire = attackWeapon.weapon.config.fire.type;
      if (fire === 'tesla_dome') continue;
      // An all-round strike needs no facing and holds the body only once it can strike again.
      const allRound = isAllRoundStrike(attackWeapon);
      if (allRound && !enemy.isWeaponReady(attackWeapon.weapon, now)) continue;
      const range = attackWeapon.weapon.config.range;
      const frozen = committedWeaponId ? salvo?.target ?? this.lastAttackTargets.get(enemy.id) : undefined;
      const obscured = frozen && this.isAttackTargetObscured(enemy, frozen, range);
      const committedDecoy = salvo && (this.decoyTargets?.getTarget(enemy.id) || salvo.target.targetRef?.kind === 'decoy');
      const target = obscured ? frozen
        : committedDecoy ? (salvo.target.targetRef ? this.buildPlayerLikeTargetCandidate(enemy, salvo.target.targetRef, range) : null) ?? salvo.target
        : committedWeaponId === sustained?.weaponId && sustained?.targetRef
          ? this.buildPlayerLikeTargetCandidate(enemy, sustained.targetRef, range)
          : this.resolveWeaponTarget(enemy, attackWeapon, now, salvo?.shotsFired, false);
      if (!target || (!obscured && !this.isWithinWeaponMinDistance(enemy, attackWeapon, target))) continue;
      return {
        aimAngle: allRound ? undefined : this.aimAt(enemy, target.targetX, target.targetY, now),
        holdPosition: attackWeapon.attackMovementSpeedFactor <= 0,
      };
    }
    return pace ? { holdPosition: pace.attackMovementSpeedFactor <= 0 } : null;
  }

  hostUpdate(delta: number, now: number): void {
    const activeEnemyIds = new Set<string>();
    for (const enemy of this.enemyManager.getAllEnemies()) {
      if (!enemy.sprite.active || enemy.getHp?.() <= 0) { this.clearClawAttack(enemy); continue; }
      if (enemy.faction !== 'hostile') continue;
      activeEnemyIds.add(enemy.id);
      enemy.decayWeaponSpread(delta, now);
      this.expireStaleSalvo(enemy, now);
      // Mounted players leave the player target space. Do not keep their last position as a
      // smoke-obscured lock; the next scan must select the real construct/carrier reference.
      const currentTarget = this.getCurrentTarget(enemy.id, now);
      if (!this.meleeWindups.has(enemy.id) && currentTarget?.kind === 'player' && (this.combatSystem.isPlayerTargetable?.(currentTarget.id) === false
        || this.targetCatalog?.getPlayerReplacement(currentTarget.id))) {
        // An announced volley picks its next target on its own instead of fizzling.
        if (this.hasAnnouncedVolley(enemy.id)) { this.playerTargetLocks.delete(enemy.id); this.lastAttackTargets.delete(enemy.id); }
        else this.abortCombat(enemy, now);
      }

      if (this.combatSystem.isStunned?.(enemy.id, now) || this.actionBlockedChecker?.(enemy.id) || (enemy.getDashPhase?.() ?? 0) !== 0) {
        this.abortCombat(enemy, now);
        // Die Sperre gehoert ausschliesslich dem Angriffssystem. Exklusive Spezialbewegungen
        // (etwa die Jagd des Zeitbombendachses) wurden bereits vom EnemyManager gesetzt und
        // duerfen hier im spaeteren Host-Update nicht wieder auf null geschrieben werden.
        continue;
      }

      // Eingebuddelt gilt dieselbe Waffensperre wie beim Spieler.
      if (enemy.isBurrowed()) {
        this.abortCombat(enemy, now);
        continue;
      }

      if (this.enemyManager.isEnemyPanicking(enemy.id)) {
        this.abortCombat(enemy, now);
        continue;
      }

      if (this.trainAwarenessSystem?.blocksRegularAttacks(enemy.id)) {
        // An announced volley rides through a track crossing; only the other combat yields to it.
        if (this.hasAnnouncedVolley(enemy.id)) {
          this.clearClawAttack(enemy);
          if (this.salvoCharges.has(enemy.id)) this.updateSalvoCharge(enemy, now);
          else this.continueSalvo(enemy, now);
        } else this.abortCombat(enemy, now);
        continue;
      }

      // An announced salvo gathers and fires beside the body's melee: the boss keeps working on
      // what is in reach instead of standing idle while its ammunition gathers. The windup runs
      // after it, so the strike keeps its direction.
      const charging = this.salvoCharges.get(enemy.id)?.attackWeapon.weapon.config.id;
      if (charging) this.updateSalvoCharge(enemy, now);
      // Eine laufende Salve haelt ihren eigenen Takt. Ohne diesen Vorrang wuerde sie auf das
      // Zielscan-Raster des Gegners einrasten und langsamer feuern als konfiguriert.
      const firing = !charging && this.continueSalvo(enemy, now);

      if (this.meleeWindups.has(enemy.id)) {
        this.updateMeleeWindup(enemy, now);
        continue;
      }
      const gathering = this.salvoCharges.has(enemy.id) ? charging : undefined;
      // The gather just ended (first shot fired or the salvo spent): the next frame carries on.
      if (firing || (charging && !gathering)) continue;
      if (this.ignitions.has(enemy.id)) { this.updateIgnition(enemy, now); continue; }
      this.endIgnitedBurst(enemy, now);

      if (!enemy.canScanForAttack(now)) continue;

      enemy.scheduleNextAttackScan(now);
      const sustained = gathering ? { active: false as const } : this.getSustainedAttack(enemy, now);
      const attack = sustained.active ? sustained.attack : this.selectAttack(enemy, now, gathering);
      if (!attack) continue;
      // While gathering only a melee strike may start; the salvo itself is already on its way.
      if (gathering && !this.shouldStartMeleeWindup(attack)) continue;

      if (this.shouldStartMeleeWindup(attack)) {
        // Meanwhile the combat movement keeps turning the body towards this target.
        if (!this.facesSwingTarget(enemy, attack)) continue;
        this.startMeleeWindup(enemy, attack, now);
        continue;
      }

      if (!sustained.active && this.shouldStartSalvoCharge(enemy, attack)) {
        this.startSalvoCharge(enemy, attack, now);
        continue;
      }

      if (!sustained.active && this.shouldIgnite(enemy, attack, now)) {
        this.startIgnition(enemy, attack, now);
        continue;
      }

      this.fireAttack(enemy, attack, now, undefined, sustained.active);
    }

    this.cleanupInactiveEnemies(activeEnemyIds);
  }

  /**
   * Setzt den Gefechtszustand eines Gegners zurueck, der in diesem Frame nicht angreifen darf.
   * Eine unterbrochene Salve zaehlt dabei als verbraucht: ihre Pause wird sofort gestartet,
   * damit ein wiederholt blockierter Gegner nicht beliebig viele Salven ohne Cooldown feuert.
   */
  private abortCombat(enemy: EnemyEntity, now: number): void {
    if (this.ignitions.delete(enemy.id)) this.publishBurstEnd(enemy, now);
    else this.endIgnitedBurst(enemy, now, true);
    const charge = this.salvoCharges.get(enemy.id);
    if (charge) {
      this.salvoCharges.delete(enemy.id);
      this.spendSalvo(enemy, charge.attackWeapon, now, 0);
    }
    this.finishSalvo(enemy, now);
    this.sustainedAttacks.delete(enemy.id);
    this.playerTargetLocks.delete(enemy.id);
    this.lastAttackTargets.delete(enemy.id);
    this.clearClawAttack(enemy);
  }

  /** Beendet eine laufende Salve und sperrt ihre Waffe fuer die konfigurierte Pause. */
  private finishSalvo(enemy: EnemyEntity, now: number): void {
    const state = this.salvoStates.get(enemy.id);
    if (!state) return;
    this.salvoStates.delete(enemy.id);
    const attackWeapon = enemy.getAttackWeapons().find(candidate => candidate.weapon.config.id === state.weaponId);
    if (attackWeapon) this.spendSalvo(enemy, attackWeapon, now, state.shotsFired);
  }

  /**
   * Sperrt eine Salvenwaffe fuer ihre Pause; eine angekuendigte Salve meldet dabei ihr Ende. Gibt der
   * Salven-Owner des Koerpers eine Pause vor, sperrt sie alle seine Salvenwaffen.
   */
  private spendSalvo(enemy: EnemyEntity, attackWeapon: EnemyAttackWeapon, now: number, shotsFired: number): void {
    const salvo = attackWeapon.salvo;
    if (!salvo) return;
    const ownedPauseMs = shotsFired > 0 ? this.salvoHooks?.salvoSpent(enemy, shotsFired, now) ?? null : null;
    if (ownedPauseMs !== null) lockEnemySalvoWeapons(enemy, now + ownedPauseMs);
    else enemy.lockWeaponUntil(attackWeapon.weapon, now + salvo.cooldownMs);
    if (!salvo.chargeMs) return;
    const volley = enemy.getVolleyState();
    if (volley.revision === 0 || volley.endedAt > 0) return;
    enemy.applyVolleyState({ ...volley, revision: volley.revision + 1, endedAt: now, rechargedAt: now + salvo.cooldownMs, shotsFired });
  }

  private shouldStartSalvoCharge(enemy: EnemyEntity, attack: SelectedEnemyAttack): boolean {
    return (attack.attackWeapon.salvo?.chargeMs ?? 0) > 0 && !this.isSalvoInProgress(enemy.id, attack.attackWeapon.weapon.config.id);
  }

  /** A flame burst after a pause first ignites (mandibles spread and glow) so its reach stays fair. */
  private shouldIgnite(enemy: EnemyEntity, attack: SelectedEnemyAttack, now: number): boolean {
    const ignitionMs = attack.attackWeapon.ignitionMs ?? 0;
    return ignitionMs > 0 && now - (this.lastIgnitedShotAt.get(enemy.id) ?? Number.NEGATIVE_INFINITY) > IGNITION_GRACE_MS;
  }

  /** Announces the burst on the shared volley timeline; the body keeps its attack pace and turns to the target. */
  private startIgnition(enemy: EnemyEntity, attack: SelectedEnemyAttack, now: number): void {
    const fireAt = now + attack.attackWeapon.ignitionMs!;
    this.ignitions.set(enemy.id, { attackWeapon: attack.attackWeapon, target: { ...attack.target }, fireAt });
    const revision = enemy.getVolleyState().revision + 1;
    enemy.applyVolleyState({ revision, chargeStartAt: now, fireAt, endedAt: 0, rechargedAt: 0, shotsFired: 0 });
    this.updateIgnition(enemy, now);
  }

  /** Holds the announced burst until it fires at the then valid target; without one the burst ends unfired. */
  private updateIgnition(enemy: EnemyEntity, now: number): void {
    const ignition = this.ignitions.get(enemy.id)!;
    enemy.pauseAttackMovement(now, ignition.attackWeapon.attackMovementSpeedFactor, CoopDefenseEnemyAttackSystem.CHARGE_PACE_HOLD_MS);
    enemy.faceAngle(this.aimAt(enemy, ignition.target.targetX, ignition.target.targetY, now));
    if (now < ignition.fireAt) return;
    this.ignitions.delete(enemy.id);
    const target = this.resolveWeaponTarget(enemy, ignition.attackWeapon, now, 0);
    if (target) this.fireAttack(enemy, { attackWeapon: ignition.attackWeapon, target }, now);
    else this.publishBurstEnd(enemy, now);
  }

  /** A burst of an igniting weapon ends once its flames pause; clients let the mandibles settle. */
  private endIgnitedBurst(enemy: EnemyEntity, now: number, force = false): void {
    const lastShotAt = this.lastIgnitedShotAt.get(enemy.id);
    if (lastShotAt === undefined || (!force && now - lastShotAt <= IGNITION_GRACE_MS)) return;
    this.lastIgnitedShotAt.delete(enemy.id);
    this.publishBurstEnd(enemy, lastShotAt);
  }

  private publishBurstEnd(enemy: EnemyEntity, at: number): void {
    const volley = enemy.getVolleyState();
    if (volley.revision === 0 || volley.endedAt > 0) return;
    enemy.applyVolleyState({ ...volley, revision: volley.revision + 1, endedAt: Math.max(volley.fireAt, at), rechargedAt: Math.max(volley.fireAt, at) });
  }

  /** Kuendigt die Salve an: der Gegner haelt an und repliziert die Sammelphase bis zum ersten Schuss. */
  private startSalvoCharge(enemy: EnemyEntity, attack: SelectedEnemyAttack, now: number): void {
    const fireAt = now + attack.attackWeapon.salvo!.chargeMs!;
    this.salvoCharges.set(enemy.id, { attackWeapon: attack.attackWeapon, target: { ...attack.target }, fireAt });
    const revision = enemy.getVolleyState().revision + 1;
    enemy.applyVolleyState({ revision, chargeStartAt: now, fireAt, endedAt: 0, rechargedAt: 0, shotsFired: 0 });
    if (attack.target.targetRef) this.decoyTargets?.usedTarget(enemy.id, attack.target.targetRef);
    if (attack.attackWeapon.aimsWithoutTurning) return;
    enemy.stopMovement();
    enemy.faceAngle(this.aimAt(enemy, attack.target.targetX, attack.target.targetY, now));
  }

  /**
   * Haelt den Gegner bis `fireAt` und feuert dann den ersten Schuss auf das dann gueltige Ziel; den
   * Rest der Salve taktet `continueSalvo` wie ohne Sammelphase. Faellt kein erster Schuss (Ziel weg,
   * Angriff verweigert), gilt die angekuendigte Salve als verbraucht – sonst koennte er endlos sammeln.
   */
  private updateSalvoCharge(enemy: EnemyEntity, now: number): void {
    const charge = this.salvoCharges.get(enemy.id)!;
    // The body keeps advancing at the salvo's attack pace; a melee windup holds it instead.
    enemy.pauseAttackMovement(now, charge.attackWeapon.attackMovementSpeedFactor, CoopDefenseEnemyAttackSystem.CHARGE_PACE_HOLD_MS);
    if (!this.meleeWindups.has(enemy.id) && !charge.attackWeapon.aimsWithoutTurning) {
      enemy.faceAngle(this.aimAt(enemy, charge.target.targetX, charge.target.targetY, now));
    }
    if (now < charge.fireAt) return;
    this.salvoCharges.delete(enemy.id);
    const { attackWeapon } = charge, weapon = attackWeapon.weapon;
    const ready = enemy.isWeaponReady(weapon, now);
    const fresh = ready ? this.resolveWeaponTarget(enemy, attackWeapon, now, 0) : null;
    const held = ready && !fresh ? this.heldVolleyTarget(enemy, attackWeapon, charge.target) : null;
    const target = fresh ?? held;
    if (target) this.fireAttack(enemy, { attackWeapon, target }, now, undefined, !!held);
    if (!this.isSalvoInProgress(enemy.id, weapon.config.id) && enemy.isWeaponReady(weapon, now)) this.spendSalvo(enemy, attackWeapon, now, 0);
  }

  /**
   * Feuert den naechsten Schuss einer laufenden Salve, sobald ihr Takt es zulaesst. Der Rueckgabe-
   * wert meldet, dass die Salve den Gegner in diesem Frame beansprucht – waehrenddessen waehlt er
   * keine andere Waffe. Verliert er sein Ziel, laeuft die Salve ueber ihre Verfallszeit aus.
   */
  private continueSalvo(enemy: EnemyEntity, now: number): boolean {
    const state = this.salvoStates.get(enemy.id);
    if (!state) return false;

    const attackWeapon = enemy.getAttackWeapons().find(candidate => candidate.weapon.config.id === state.weaponId);
    if (!attackWeapon?.salvo) {
      this.salvoStates.delete(enemy.id);
      return false;
    }
    if (now < state.nextShotAt || !enemy.isWeaponReady(attackWeapon.weapon, now)) return true;

    // Ohne gueltiges Ziel gibt die Salve den Gegner frei, statt ihn zu blockieren: kommt ihm ein
    // Spieler unter die Mindestdistanz, soll er sofort auf den Hoellenwerfer wechseln duerfen.
    // Der Zaehler bleibt bis zur Verfallszeit stehen, damit sie nach kurzem Sichtverlust weiterlaeuft.
    const obscured = this.isAttackTargetObscured(enemy, state.target, attackWeapon.weapon.config.range);
    const committed = this.decoyTargets?.getTarget(enemy.id) || state.target.targetRef?.kind === 'decoy';
    const resolved = obscured ? state.target : committed
      ? (state.target.targetRef ? this.buildPlayerLikeTargetCandidate(enemy, state.target.targetRef, attackWeapon.weapon.config.range) : null) ?? state.target
      : this.resolveWeaponTarget(enemy, attackWeapon, now, state.shotsFired);
    const held = resolved ? null : this.heldVolleyTarget(enemy, attackWeapon, state.target);
    const target = resolved ?? held;
    if (!target) return false;

    this.fireAttack(enemy, { attackWeapon, target }, now, undefined, obscured || !!committed || !!held);
    return true;
  }

  private hasAnnouncedVolley(enemyId: string): boolean {
    if (this.salvoCharges.has(enemyId)) return true;
    const state = this.salvoStates.get(enemyId);
    return !!state && (this.enemyManager.getEnemy(enemyId)?.getAttackWeapons()
      .find(candidate => candidate.weapon.config.id === state.weaponId)?.salvo?.chargeMs ?? 0) > 0;
  }

  /**
   * An announced volley keeps a living target that cover hides from its line of fire: the shots fly
   * at it and break on whatever stands in between, instead of the volley fizzling. Smoke hides the
   * current position, so there the last seen one is kept. A gone, replaced or out-of-range target ends it.
   */
  private heldVolleyTarget(enemy: EnemyEntity, attackWeapon: EnemyAttackWeapon, target: EnemyAttackCandidate): EnemyAttackCandidate | null {
    const ref = target.targetRef, range = attackWeapon.weapon.config.range;
    if (!attackWeapon.salvo?.chargeMs || !ref || (ref.kind !== 'player' && ref.kind !== 'decoy')) return null;
    if (this.targetCatalog && !this.targetCatalog.isTargetValid(ref)) return null;
    if (ref.kind === 'player' && (this.combatSystem.isPlayerTargetable?.(String(ref.id)) === false
      || this.targetCatalog?.getPlayerReplacement(String(ref.id)))) return null;
    const current = this.targetCatalog?.resolve(ref)
      ?? (ref.kind === 'player' && !this.targetCatalog ? this.playerManager.getPlayer(String(ref.id)) : null);
    if (!current) return null;
    const seen = ('resolvePosition' in current ? current.resolvePosition?.(enemy.sprite.x, enemy.sprite.y) : null) ?? current;
    const position = this.enemyManager.canSeeThroughSmoke(enemy.id, seen.x, seen.y, range) ? seen : { x: target.targetX, y: target.targetY };
    const distance = Math.hypot(position.x - enemy.sprite.x, position.y - enemy.sprite.y);
    const held = { ...target, targetX: position.x, targetY: position.y, distance };
    return distance <= range && this.isWithinWeaponMinDistance(enemy, attackWeapon, held) ? held : null;
  }

  private expireStaleSalvo(enemy: EnemyEntity, now: number): void {
    const state = this.salvoStates.get(enemy.id);
    if (state && now >= state.expiresAt) this.finishSalvo(enemy, now);
  }

  private isSalvoInProgress(enemyId: string, weaponId: string): boolean {
    return this.salvoStates.get(enemyId)?.weaponId === weaponId;
  }

  private shouldStartMeleeWindup(attack: SelectedEnemyAttack): boolean {
    return attack.attackWeapon.weapon.config.fire.type === 'melee' && !!attack.attackWeapon.meleeTiming;
  }

  /**
   * A slowly turning body starts a frontal swing only once it can face its target before the strike
   * (it keeps turning through the windup); otherwise it would rear towards one side and strike
   * towards another.
   */
  private facesSwingTarget(enemy: EnemyEntity, attack: SelectedEnemyAttack): boolean {
    const config = attack.attackWeapon.weapon.config, rate = enemy.getTurnRateRadPerMs();
    if (config.fire.type !== 'melee' || isAllRoundStrike(attack.attackWeapon) || rate === null) return true;
    const dx = attack.target.targetX - enemy.sprite.x, dy = attack.target.targetY - enemy.sprite.y;
    if (Math.hypot(dx, dy) < enemy.getCollisionRadius()) return true;
    const off = Math.atan2(dy, dx) - enemy.getAimAngle();
    const windupMs = attack.attackWeapon.meleeTiming?.hitDelayMs ?? 0;
    const allowed = Math.max(config.fire.hitArcDegrees * Math.PI / 720, rate * windupMs * 0.8);
    return Math.abs(Math.atan2(Math.sin(off), Math.cos(off))) <= allowed;
  }

  private startMeleeWindup(enemy: EnemyEntity, attack: SelectedEnemyAttack, now: number): void {
    const timing = attack.attackWeapon.meleeTiming!;
    const config = attack.attackWeapon.weapon.config;
    if (config.fire.type !== 'melee') return;
    // The strike resolves along this fixed angle. A turn-limited aim could still point at the
    // previous movement target (e.g. a far ranged-weapon target) and swing into empty air.
    const dx = attack.target.targetX - enemy.sprite.x, dy = attack.target.targetY - enemy.sprite.y;
    const angle = Math.hypot(dx, dy) >= enemy.getCollisionRadius()
      ? Math.atan2(dy, dx) : this.aimAt(enemy, attack.target.targetX, attack.target.targetY, now);
    const revision = ++this.clawRevision;
    const presentation: EnemyClawAttack = {
      attackId: enemy.id + ':' + now + ':' + revision, weaponId: config.id, angle,
      startedAt: now, strikeAt: now + timing.hitDelayMs - timing.strikeMs,
      hitAt: now + timing.hitDelayMs, endsAt: now + timing.hitDelayMs + timing.recoveryMs,
      range: config.range, arcDegrees: config.fire.hitArcDegrees,
    };
    this.meleeWindups.set(enemy.id, { attackWeapon: attack.attackWeapon, target: { ...attack.target }, presentation, executed: false });
    this.clawStateSink?.(enemy, { revision, attack: presentation });
    if (attack.target.targetRef) this.decoyTargets?.usedTarget(enemy.id, attack.target.targetRef);
    enemy.stopMovement();
    if (!isAllRoundStrike(attack.attackWeapon)) enemy.faceAngle(angle);
  }

  private updateMeleeWindup(enemy: EnemyEntity, now: number): void {
    const state = this.meleeWindups.get(enemy.id);
    if (!state) return;
    enemy.stopMovement();
    if (!isAllRoundStrike(state.attackWeapon)) enemy.faceAngle(state.presentation.angle);
    if (!state.executed && now >= state.presentation.hitAt) {
      // Set before dispatch: damage callbacks may remove the attacker or end the Activity.
      state.executed = true;
      this.fireAttack(enemy, state, now, state.presentation.angle, true, state.presentation.attackId);
    }
    if (now >= state.presentation.endsAt) this.clearClawAttack(enemy);
  }

  private fireAttack(
    enemy: EnemyEntity,
    attack: SelectedEnemyAttack,
    now: number,
    forcedAngle?: number,
    committed = false,
    clawAttackId?: string,
  ): void {
    const { attackWeapon, target } = attack;
    const committedLivingAttack = committed && (target.targetRef?.kind === 'player' || target.targetRef?.kind === 'decoy' || target.kind === 'ally');
    if (this.intents && target.kind !== 'train' && !committedLivingAttack && !clawAttackId) {
      if (target.kind === 'obstacle' && (target.obstacleIndex === undefined
        || this.getRockObjects()?.[target.obstacleIndex] !== target.obstacle || !target.obstacle?.active)) {
        this.abortCombat(enemy, now); return;
      }
      const id = target.kind === 'obstacle' ? String(target.obstacleIndex)
        : target.targetRef?.id ?? target.targetId ?? '';
      const kind = target.kind === 'base' || target.kind === 'obstacle' ? target.kind : target.targetRef?.kind ?? target.kind;
      if (!this.intents.allowsAttack(enemy.id, kind, id, attackWeapon.targetMode)) {
        this.abortCombat(enemy, now); return;
      }
    }
    const weapon = attackWeapon.weapon;
    // A shot that aims without turning leaves straight for its target; the body keeps its facing.
    const free = forcedAngle === undefined && !clawAttackId && attackWeapon.aimsWithoutTurning;
    const angle = forcedAngle ?? (free ? Math.atan2(target.targetY - enemy.sprite.y, target.targetX - enemy.sprite.x)
      : this.aimAt(enemy, target.targetX, target.targetY, now));
    if (!free && !isAllRoundStrike(attackWeapon)) enemy.faceAngle(angle);

    const config = weapon.config, muzzle = attackWeapon.muzzleForwardPx;
    const shotAngle = clawAttackId ? angle : angle + enemy.rollWeaponSpreadOffset(weapon);
    const didFire = attackWeapon.muzzles?.length
      ? this.fireMuzzles(enemy, attackWeapon, target, angle, shotAngle - angle, now)
      : this.weaponExecution.fire(config, {
        x: enemy.sprite.x,
        y: enemy.sprite.y,
        angle: shotAngle,
        targetX: target.targetX,
        targetY: target.targetY,
        ownerId: enemy.id,
        ownerColor: COLORS.RED_2,
        visualMuzzleOrigin: muzzle > 0
          ? { x: enemy.sprite.x + Math.cos(angle) * muzzle, y: enemy.sprite.y + Math.sin(angle) * muzzle } : undefined,
        options: clawAttackId ? { clawAttackId } : undefined,
      });
    if (!didFire) return;
    if ((attackWeapon.ignitionMs ?? 0) > 0) this.lastIgnitedShotAt.set(enemy.id, now);
    this.scorchBase(enemy, attackWeapon, target, now);
    this.igniteFlameGround(enemy, attackWeapon, target, angle, now);
    if (target.targetRef) this.decoyTargets?.usedTarget(enemy.id, target.targetRef);

    if (!clawAttackId) enemy.pauseAttackMovement(now, attackWeapon.attackMovementSpeedFactor);
    enemy.recordWeaponUse(weapon, now);
    this.lastAttackTargets.set(enemy.id, { ...attack.target });
    this.advanceSalvo(enemy, attackWeapon, now);

    const existingSustainedAttack = this.sustainedAttacks.get(enemy.id);
    if (existingSustainedAttack) {
      existingSustainedAttack.lastShotAt = now;
    } else if (attackWeapon.minimumFireDurationMs > 0 && (target.targetRef || target.targetId)) {
      this.sustainedAttacks.set(enemy.id, {
        weaponId: weapon.config.id,
        targetRef: target.targetRef ?? null,
        targetId: target.targetId ?? null,
        targetX: target.targetX,
        targetY: target.targetY,
        fireUntil: now + attackWeapon.minimumFireDurationMs,
        lastShotAt: now,
      });
    }
  }

  /**
   * One flame from every muzzle tip of the body (the colossus's mandibles). Converging jets pass through
   * the target; each jet keeps its own flame chain and reaches the weapon range minus its tip's lead.
   * Only the first jet carries the shot sound.
   */
  private fireMuzzles(enemy: EnemyEntity, attackWeapon: EnemyAttackWeapon, target: EnemyAttackCandidate, facing: number,
    spread: number, now: number): boolean {
    const config = attackWeapon.weapon.config;
    let fired = false;
    attackWeapon.muzzles!.forEach((muzzle, index) => {
      const jet = resolveConvergingMuzzle(muzzle, enemy.sprite.x, enemy.sprite.y, facing, target.targetX, target.targetY,
        attackWeapon.convergeOnTarget === true);
      const angle = jet.angle + spread, travel = Math.max(1, config.range - muzzle.forwardPx);
      const shot = this.weaponExecution.fire(index === 0 ? config : { ...config, shotAudio: undefined }, {
        x: enemy.sprite.x, y: enemy.sprite.y, angle, targetX: target.targetX, targetY: target.targetY,
        ownerId: enemy.id, ownerColor: COLORS.RED_2,
        gameplayMuzzleOrigin: { x: jet.x, y: jet.y }, visualMuzzleOrigin: { x: jet.x, y: jet.y },
        options: { flameStreamKey: muzzleFlameStreamKey(enemy.id, index), flameTravelPx: travel },
      });
      fired = shot || fired;
      if (shot && attackWeapon.collateralScorch) this.scorchAlongJet(enemy, attackWeapon, jet.x, jet.y, angle, travel, now);
    });
    return fired;
  }

  /** A jet scorches every friendly base it reaches, whatever it aims at; once per body and base per tick. */
  private scorchAlongJet(enemy: EnemyEntity, attackWeapon: EnemyAttackWeapon, x: number, y: number, angle: number,
    travel: number, now: number): void {
    const config = attackWeapon.weapon.config, baseDamageMult = config.baseDamageMult ?? 1;
    if (!this.flameGround?.scorchBase || !(baseDamageMult > 0)) return;
    const endX = x + Math.cos(angle) * travel, endY = y + Math.sin(angle) * travel;
    const halfWidth = config.fire.type === 'flamethrower' ? config.fire.hitboxEndSize / 2 : 0;
    for (const base of this.baseManager?.getBasesByFaction('friendly') ?? []) {
      if (base.isInert?.() === true || base.getHp() <= 0) continue;
      const key = `${enemy.id}:${base.id}`;
      if (now < (this.scorchReadyAt.get(key) ?? 0)) continue;
      if (!sweptSegmentTouchesCells(base.getCellBodies().map(cell => cell.getBounds()), x, y, endX, endY, halfWidth)) continue;
      this.scorchReadyAt.set(key, now + COLLATERAL_SCORCH_INTERVAL_MS);
      this.flameGround.scorchBase(enemy, base.id, config.damage * baseDamageMult, `enemy.${enemy.kind}.flame`, now);
    }
  }

  /**
   * Enemy projectiles never hurt a friendly base by contact, so a flame shot aimed at a base in its
   * reach scorches it directly: its damage times the weapon's `baseDamageMult`. Each shot of each body
   * counts, so the pressure on a base grows with the number of spitters (the base burn does not stack).
   */
  private scorchBase(enemy: EnemyEntity, attackWeapon: EnemyAttackWeapon, target: EnemyAttackCandidate, now: number): void {
    const config = attackWeapon.weapon.config, baseDamageMult = config.baseDamageMult ?? 1;
    const baseId = target.kind === 'base' ? target.targetId ?? target.targetRef?.id : undefined;
    if (!this.flameGround?.scorchBase || config.fire.type !== 'flamethrower' || !baseId || !(baseDamageMult > 0)) return;
    this.flameGround.scorchBase(enemy, baseId, config.damage * baseDamageMult, `enemy.${enemy.kind}.spit_fire`, now);
  }

  /**
   * A flame weapon that authors `burningGround.createOnFlameExpiry` sets the ground on fire where its
   * burst ends: just behind the target, at most at its reach. The last flame of a salvo (or every
   * single shot) ignites, whether the flames hit or died out, so a struck base reliably catches fire.
   */
  private igniteFlameGround(enemy: EnemyEntity, attackWeapon: EnemyAttackWeapon, target: EnemyAttackCandidate,
    angle: number, now: number): void {
    const config = attackWeapon.weapon.config, fire = config.fire;
    if (!this.flameGround || fire.type !== 'flamethrower') return;
    const ground = fire.burningGround;
    if (!ground || ground.createOnFlameExpiry <= 0 || ground.durationMs <= 0) return;
    const salvo = attackWeapon.salvo, current = this.salvoStates.get(enemy.id);
    const shotsFired = current?.weaponId === config.id ? current.shotsFired + 1 : 1;
    if (salvo && shotsFired < salvo.count) return;
    const x = enemy.sprite.x, y = enemy.sprite.y;
    const reach = Math.min(config.range, Math.hypot(target.targetX - x, target.targetY - y) + FLAME_GROUND_OVERSHOOT_PX);
    const cos = Math.cos(angle), sin = Math.sin(angle);
    const fireGround = resolveEnemyFlameGround(enemy.faction, `enemy.${enemy.kind}.spit_fire`);
    for (const back of FLAME_GROUND_CELL_OFFSETS) {
      this.flameGround.ignite(enemy, x + cos * (reach - back), y + sin * (reach - back), {
        durationMs: ground.durationMs, burnDurationMs: fire.burnDurationMs, burnDamagePerTick: fire.burnDamagePerTick,
        baseDamageMult: ground.baseDamageMult ?? 1, ...fireGround,
      }, now);
    }
  }

  /**
   * Zaehlt einen Salvenschuss. Der Waffen-Cooldown taktet die Einzelschuesse; erst nach dem
   * letzten Schuss uebernimmt die Salvenpause.
   */
  private advanceSalvo(enemy: EnemyEntity, attackWeapon: EnemyAttackWeapon, now: number): void {
    const salvo = attackWeapon.salvo;
    if (!salvo) return;

    const weaponId = attackWeapon.weapon.config.id;
    const current = this.salvoStates.get(enemy.id);
    const shotsFired = (current?.weaponId === weaponId ? current.shotsFired : 0) + 1;
    this.salvoStates.set(enemy.id, {
      target: this.lastAttackTargets.get(enemy.id)!,
      weaponId,
      shotsFired,
      nextShotAt: now + salvo.intervalMs,
      expiresAt: now + Math.max(
        CoopDefenseEnemyAttackSystem.MIN_SALVO_GAP_TOLERANCE_MS,
        salvo.intervalMs * CoopDefenseEnemyAttackSystem.SALVO_GAP_TOLERANCE_FACTOR,
      ),
    });
    if (shotsFired >= salvo.count) this.finishSalvo(enemy, now);
  }

  /** Bestes Ziel einer einzelnen Waffe nach ihrem Zielmodus, inklusive Zug und Mindestdistanz. */
  private resolveWeaponTarget(
    enemy: EnemyEntity,
    attackWeapon: EnemyAttackWeapon,
    now: number,
    salvoShotIndex?: number,
    updateLock = true,
  ): EnemyAttackCandidate | null {
    const weapon = attackWeapon.weapon;
    // A weapon that cannot damage rocks (e.g. a flame) never takes a rock or an obstacle as its target.
    const hitsRocks = (weapon.config.rockDamageMult ?? 1) > 0;
    const reach = Math.min(weapon.config.range, attackWeapon.structureReachPx ?? Infinity);
    if (this.intents) {
      const intent = this.intents.get(enemy.id), ref = intent?.target;
      let target: EnemyAttackCandidate | null = null;
      const secondary = attackWeapon.targetMode === 'players' && intent?.reason === 'siege';
      if (secondary) {
        target = attackWeapon.salvo?.targetDistribution === 'round_robin'
          ? this.findDistributedPlayerTarget(enemy, weapon.config.range, attackWeapon.minTargetDistancePx, salvoShotIndex ?? 0)
          : this.findLivingTargetWithLock(enemy, weapon.config.range, now, updateLock);
      } else if (intent?.attackContext === 'breach' && attackWeapon.targetMode !== 'players') {
        const blocker = this.intents.getBreach(enemy.id)?.nextBlocker;
        if (blocker?.startsWith('base:')) target = this.findNearestBaseTarget(enemy, reach, blocker.slice(5));
        else if (blocker?.startsWith('rock:') && hitsRocks) target = this.findNearestObstacleTarget(enemy, reach, now, Number(blocker.slice(5)));
      } else if (ref && intent?.attackContext === 'primary') {
        if (ref.kind === 'base' && attackWeapon.targetMode !== 'players' && attackWeapon.targetMode !== 'rocks') {
          target = this.findNearestBaseTarget(enemy, reach, ref.id);
        } else if (ref.kind === 'armed-construct' && attackWeapon.targetMode !== 'players') {
          target = this.findNearestArmedConstructTarget(enemy, reach, Number(ref.id));
        } else if (ref.kind !== 'base' && ref.kind !== 'ally' && attackWeapon.targetMode !== 'structures' && attackWeapon.targetMode !== 'rocks') {
          target = this.buildPlayerLikeTargetCandidate(enemy, ref, weapon.config.range);
        }
      }
      // An all-round strike answers whatever stands in its reach, even while the body besieges a structure.
      if (attackWeapon.targetMode === 'all' && isAllRoundStrike(attackWeapon)) {
        const living = this.findLivingTargetWithLock(enemy, weapon.config.range, now, updateLock);
        if (this.isBetterCandidate(living, target)) target = living;
      }
      const train = (weapon.config.trainDamageMult ?? 1) > 0 ? this.findTrainTarget(enemy, weapon.config.range) : null;
      if (this.isBetterCandidate(train, target)) target = train;
      return target && this.isWithinWeaponMinDistance(enemy, attackWeapon, target) && this.isInSwingWithoutTurning(enemy, attackWeapon, target)
        ? target : null;
    }
    const decoy = this.decoyTargets?.getTarget(enemy.id);
    if (decoy) {
      const target = this.buildPlayerLikeTargetCandidate(enemy, decoy, weapon.config.range);
      return target && this.isWithinWeaponMinDistance(enemy, attackWeapon, target) && this.isInSwingWithoutTurning(enemy, attackWeapon, target)
        ? target : null;
    }
    const distributesTargets = attackWeapon.targetMode === 'players'
      && attackWeapon.salvo?.targetDistribution === 'round_robin';
    let target = distributesTargets
      ? this.findDistributedPlayerTarget(
        enemy,
        weapon.config.range,
        attackWeapon.minTargetDistancePx,
        salvoShotIndex ?? 0,
      )
      : attackWeapon.targetMode === 'players'
        ? this.findLivingTargetWithLock(enemy, weapon.config.range, now, updateLock)
      : attackWeapon.targetMode === 'rocks'
        ? (hitsRocks ? this.findNearestObstacleTarget(enemy, reach, now) : null)
        : attackWeapon.targetMode === 'structures'
          ? this.selectStructureTarget(enemy, reach, now, hitsRocks)
          : this.selectTarget(enemy, weapon.config.range, now, updateLock, hitsRocks, reach);
    const trainTarget = (weapon.config.trainDamageMult ?? 1) > 0
      ? this.findTrainTarget(enemy, weapon.config.range)
      : null;
    if (this.isBetterCandidate(trainTarget, target)) target = trainTarget;
    if (!target || !this.isWithinWeaponMinDistance(enemy, attackWeapon, target)) return null;
    return this.isInSwingWithoutTurning(enemy, attackWeapon, target) ? target : null;
  }

  /**
   * A swing that turns only for structures takes a living target (player, decoy, ally) only while it
   * already stands inside the arc, so a player beside or behind the body cannot turn it off its route.
   */
  private isInSwingWithoutTurning(enemy: EnemyEntity, attackWeapon: EnemyAttackWeapon, target: EnemyAttackCandidate): boolean {
    const fire = attackWeapon.weapon.config.fire;
    if (!attackWeapon.turnsOnlyForStructures || fire.type !== 'melee' || isAllRoundStrike(attackWeapon)) return true;
    const ref = target.targetRef?.kind;
    const living = target.kind === 'ally' || (ref ? ref === 'player' || ref === 'decoy' || ref === 'hostile-enemy'
      : target.kind === 'player' || target.kind === 'decoy');
    if (!living) return true;
    const dx = target.targetX - enemy.sprite.x, dy = target.targetY - enemy.sprite.y;
    if (Math.hypot(dx, dy) < enemy.getCollisionRadius()) return true;
    const off = Math.atan2(dy, dx) - enemy.getAimAngle();
    return Math.abs(Math.atan2(Math.sin(off), Math.cos(off))) <= fire.hitArcDegrees * Math.PI / 360;
  }

  private selectAttack(enemy: EnemyEntity, now: number, gatheringWeaponId?: string): SelectedEnemyAttack | null {
    // Die Konfigurationsreihenfolge ist zugleich die Waffenpriorität:
    // Die erste Waffe mit einem gültigen Ziel gewinnt.
    let higherPriorityWeaponBusy = false;
    for (const attackWeapon of enemy.getAttackWeapons()) {
      const weapon = attackWeapon.weapon;
      if (weapon.config.fire.type === 'tesla_dome' || weapon.config.id === gatheringWeaponId) continue;
      const target = this.resolveWeaponTarget(enemy, attackWeapon, now);
      if (!target) continue;
      // Existiert ein Ziel fuer eine hoeher priorisierte Waffe, wartet der
      // Gegner deren Cooldown ab, statt im Nahkampf auf Fernkampf zu wechseln.
      if (!enemy.isWeaponReady(weapon, now)) {
        higherPriorityWeaponBusy = true;
        continue;
      }
      // Ausnahme: Felsen freibeissen und Basen angreifen. Ein blockierter Gegner muss sich
      // befreien bzw. weiter an seiner strategischen Basis arbeiten duerfen.
      if (
        higherPriorityWeaponBusy
        && target.kind !== 'obstacle'
        && target.kind !== 'base'
        && !attackWeapon.usableDuringPriorityPause
      ) return null;
      return { attackWeapon, target };
    }

    return null;
  }

  /**
   * Mindest-Zieldistanz einer Waffe. Eine laufende Salve darf mit Hysterese unter die Grenze
   * feuern, damit ein herankommendes Ziel sie nicht mitten im Takt abbricht.
   */
  private isWithinWeaponMinDistance(
    enemy: EnemyEntity,
    attackWeapon: EnemyAttackWeapon,
    target: EnemyAttackCandidate,
  ): boolean {
    if (attackWeapon.minTargetDistancePx <= 0) return true;
    const hysteresis = attackWeapon.salvo?.targetDistribution === 'round_robin'
      ? 0
      : this.isSalvoInProgress(enemy.id, attackWeapon.weapon.config.id)
      ? CoopDefenseEnemyAttackSystem.SALVO_MIN_DISTANCE_HYSTERESIS_PX
      : 0;
    return target.distance >= attackWeapon.minTargetDistancePx - hysteresis;
  }

  /**
   * Zielauswahl fuer breit gestreute Salven. Die Kandidaten werden nach Distanz und ID sortiert,
   * damit Host-Wiederholungen stabil bleiben; der Schussindex rotiert anschliessend ueber die
   * verbleibenden, ausserhalb der Mindestdistanz liegenden Spieler.
   */
  private findDistributedPlayerTarget(
    enemy: EnemyEntity,
    range: number,
    minTargetDistancePx: number,
    salvoShotIndex: number,
  ): EnemyAttackCandidate | null {
    const candidates: EnemyAttackCandidate[] = [];
    if (this.targetCatalog) {
      this.targetCatalog.forEachTarget('player-like-threats', (target) => {
        const candidate = this.buildPlayerLikeTargetCandidate(enemy, { kind: target.kind, id: target.id }, range);
        if (!candidate || candidate.distance < minTargetDistancePx) return;
        candidates.push(candidate);
      });
    } else {
      for (const player of this.playerManager.getAllPlayers()) {
        const candidate = this.buildPlayerTargetCandidate(enemy, player.id, range);
        if (!candidate || candidate.distance < minTargetDistancePx) continue;
        candidates.push(candidate);
      }
    }
    candidates.sort((left, right) => left.distance - right.distance || this.targetKey(left).localeCompare(this.targetKey(right)));
    return candidates.length > 0 ? candidates[salvoShotIndex % candidates.length] : null;
  }

  private getSustainedAttack(
    enemy: EnemyEntity,
    now: number,
  ): { active: boolean; attack: SelectedEnemyAttack | null } {
    const state = this.sustainedAttacks.get(enemy.id);
    if (!state) return { active: false, attack: null };
    if (now >= state.fireUntil && state.lastShotAt >= state.fireUntil) {
      this.sustainedAttacks.delete(enemy.id);
      return { active: false, attack: null };
    }

    const attackWeapon = enemy.getAttackWeapons().find(candidate => candidate.weapon.config.id === state.weaponId);
    if (!attackWeapon) {
      this.sustainedAttacks.delete(enemy.id);
      return { active: false, attack: null };
    }
    if (!enemy.isWeaponReady(attackWeapon.weapon, now)) {
      return { active: true, attack: null };
    }

    const frozen = this.lastAttackTargets.get(enemy.id);
    if (frozen && this.isAttackTargetObscured(enemy, frozen, attackWeapon.weapon.config.range)) {
      return { active: true, attack: frozen ? { attackWeapon, target: { ...frozen, targetX: state.targetX, targetY: state.targetY } } : null };
    }
    const playerTarget = state.targetRef
      ? this.buildPlayerLikeTargetCandidate(enemy, state.targetRef, attackWeapon.weapon.config.range)
      : null;
    const ally = state.targetId ? this.enemyManager.getEnemy(state.targetId) : null;
    const allyTarget = !playerTarget && ally?.faction === 'allied'
      ? this.buildAllyTargetCandidate(enemy, ally, attackWeapon.weapon.config.range)
      : null;
    const sustainedTarget = playerTarget ?? allyTarget;
    if (!sustainedTarget) {
      this.sustainedAttacks.delete(enemy.id);
      this.playerTargetLocks.delete(enemy.id);
      return { active: false, attack: null };
    }

    state.targetX = sustainedTarget.targetX;
    state.targetY = sustainedTarget.targetY;

    return {
      active: true,
      attack: {
        attackWeapon,
        target: sustainedTarget,
      },
    };
  }

  /** Read the current position solely for visibility; never expose a hidden position to aiming. */
  private isAttackTargetObscured(enemy: EnemyEntity, target: EnemyAttackCandidate, range: number): boolean {
    let position = { x: target.targetX, y: target.targetY };
    if (target.targetRef) {
      if (this.targetCatalog && !this.targetCatalog.isTargetValid(target.targetRef)) return true;
      const current = this.targetCatalog?.resolve(target.targetRef);
      if (current) position = current.resolvePosition?.(enemy.sprite.x, enemy.sprite.y) ?? current;
      else if (target.targetRef.kind === 'player' && !this.targetCatalog) {
        const player = this.playerManager.getPlayer(String(target.targetRef.id));
        if (player) position = player;
      }
    } else if (target.kind === 'ally' && target.targetId) {
      const ally = this.enemyManager.getEnemy(target.targetId);
      if (ally) position = ally.sprite;
    }
    return !this.enemyManager.canSeeThroughSmoke(enemy.id, position.x, position.y, range);
  }

  private selectTarget(enemy: EnemyEntity, range: number, now: number, updateLock = true, hitsRocks = true,
    structureReach = range): EnemyAttackCandidate | null {
    let best = this.findNearestBaseTarget(enemy, structureReach);

    const armedConstruct = this.findNearestArmedConstructTarget(enemy, structureReach);
    if (this.isBetterCandidate(armedConstruct, best)) best = armedConstruct;

    const obstacle = hitsRocks ? this.findNearestObstacleTarget(enemy, structureReach, now) : null;
    if (this.isBetterCandidate(obstacle, best)) {
      best = obstacle;
    }

    const livingTarget = this.findLivingTargetWithLock(enemy, range, now, updateLock);
    if (this.isBetterCandidate(livingTarget, best)) {
      best = livingTarget;
    }

    return best;
  }

  /** Wie {@link selectTarget}, aber ohne Spieler und Verbuendete – reine Belagerungsziele. */
  private selectStructureTarget(enemy: EnemyEntity, range: number, now: number, hitsRocks = true): EnemyAttackCandidate | null {
    const best = this.findNearestBaseTarget(enemy, range);
    const obstacle = hitsRocks ? this.findNearestObstacleTarget(enemy, range, now) : null;
    return this.isBetterCandidate(obstacle, best) ? obstacle : best;
  }

  private findNearestBaseTarget(enemy: EnemyEntity, range: number, knownId?: string): EnemyAttackCandidate | null {
    let best: EnemyAttackCandidate | null = null;
    const strategicTarget = getCoopDefenseEnemyConfig(enemy.kind).movementTarget;

    // Gegnerbasen sind fuer Zombies kein Ziel; sie gehoeren derselben Fraktion.
    const knownBase = knownId === undefined ? undefined : this.baseManager?.getBase(knownId);
    const bases = knownId === undefined ? this.baseManager?.getBasesByFaction('friendly') ?? []
      : knownBase?.faction === 'friendly' ? [knownBase] : [];
    for (const base of bases) {
      if (this.intents && !this.intents.allowsAttack(enemy.id, 'base', base.id, 'all')) continue;
      if ((base.isInert?.() ?? false) || base.getHp() <= 0) continue;
      if (
        strategicTarget === 'players-and-armed-constructs'
        && (base.role !== 'outpost' || base.getTurrets().length === 0)
      ) continue;

      const surface = base.getNearestSurfacePoint(enemy.sprite.x, enemy.sprite.y);
      if (!surface) continue;
      const targetX = surface.x;
      const targetY = surface.y;
      const distance = surface.distance;
      if (distance > range || !this.enemyManager.canSeeThroughSmoke(enemy.id, targetX, targetY, range)) continue;
      if (!this.combatSystem.hasClearLineOfFire(enemy.sprite.x, enemy.sprite.y, targetX, targetY)) continue;

      const candidate: EnemyAttackCandidate = {
        kind: 'base',
        targetId: base.id,
        priority: strategicTarget === 'players-and-armed-constructs' ? 2 : 1,
        distance,
        targetX,
        targetY,
      };
      if (this.isBetterCandidate(candidate, best)) {
        best = candidate;
      }
    }

    return best;
  }

  private findNearestArmedConstructTarget(enemy: EnemyEntity, range: number, knownId?: number): EnemyAttackCandidate | null {
    const huntsArmedConstructions = getCoopDefenseEnemyConfig(enemy.kind).movementTarget === 'players-and-armed-constructs';
    const rockObjects = this.getRockObjects() ?? [];
    let best: EnemyAttackCandidate | null = null;
    const knownConstruction = knownId === undefined ? undefined : this.placementSystem?.getRuntimeRock(knownId);
    const constructions = knownId === undefined ? this.placementSystem?.getAllRuntimeRocks() ?? []
      : knownConstruction ? [knownConstruction] : [];
    for (const construction of constructions) {
      if (this.intents && !this.intents.allowsAttack(enemy.id, 'obstacle', String(construction.id), 'all')) continue;
      const occupiedTower = construction.kind === 'watchtower' && this.playerManager.getAllPlayers().some(
        p => this.combatSystem.isAlive(p.id) && this.combatSystem.getStructureOccupancyId?.(p.id) === construction.id);
      if (construction.hp <= 0 || (!occupiedTower && (!huntsArmedConstructions || !isOffensiveConstruction(construction)))) continue;
      const obstacle = rockObjects[construction.id];
      if (!obstacle?.active) continue;
      const point = occupiedTower ? this.placementSystem!.getRuntimeRockSurfacePoint(construction, enemy.sprite.x, enemy.sprite.y) : obstacle;
      const distance = Phaser.Math.Distance.Between(enemy.sprite.x, enemy.sprite.y, point.x, point.y);
      if (distance > range) continue;
      if (!this.enemyManager.canSeeThroughSmoke(enemy.id, point.x, point.y, range)) continue;
      if (!this.combatSystem.hasClearLineOfFire(
        enemy.sprite.x,
        enemy.sprite.y,
        point.x,
        point.y,
        { skipRockIndex: construction.id },
      )) continue;
      const candidate: EnemyAttackCandidate = {
        kind: 'obstacle',
        priority: 2,
        distance,
        targetX: point.x,
        targetY: point.y,
        obstacle,
        obstacleIndex: construction.id,
      };
      if (this.isBetterCandidate(candidate, best)) best = candidate;
    }
    return best;
  }

  private findNearestObstacleTarget(enemy: EnemyEntity, range: number, now: number, knownIndex?: number): EnemyAttackCandidate | null {
    if (!this.isObstacleAttackUnlocked(enemy)) return null;

    const rockObjects = this.getRockObjects() ?? [];
    if (knownIndex !== undefined) {
      const obstacle = rockObjects[knownIndex];
      return obstacle ? this.buildObstacleCandidate(enemy, obstacle, rockObjects, range, knownIndex) : null;
    }
    let best: EnemyAttackCandidate | null = null;
    for (let index = 0; index < rockObjects.length; index += 1) {
      const rock = rockObjects[index];
      if (!rock?.active) continue;

      const candidate = this.buildObstacleCandidate(enemy, rock, rockObjects, range, index);
      if (candidate && this.isBetterCandidate(candidate, best)) {
        best = candidate;
      }
    }

    return best;
  }

  private buildObstacleCandidate(
    enemy: EnemyEntity,
    obstacle: RockPhysicsProxy,
    rockObjects: readonly (RockPhysicsProxy | null)[],
    range: number,
    knownIndex?: number,
  ): EnemyAttackCandidate | null {
    if (!obstacle.active) return null;
    const index = knownIndex ?? rockObjects.indexOf(obstacle);
    if (index < 0 || this.obstacleExcluded?.(index)) return null;
    if (this.intents && !this.intents.allowsAttack(enemy.id, 'obstacle', String(index), 'all')) return null;

    const runtime = this.placementSystem?.getRuntimeRock(index);
    const point = runtime?.kind === 'watchtower'
      ? this.placementSystem!.getRuntimeRockSurfacePoint(runtime, enemy.sprite.x, enemy.sprite.y) : obstacle;
    const distance = Phaser.Math.Distance.Between(enemy.sprite.x, enemy.sprite.y, point.x, point.y);
    if (distance > range) return null;
    if (!this.enemyManager.canSeeThroughSmoke(enemy.id, point.x, point.y, range)) return null;
    if (!this.combatSystem.hasClearLineOfFire(enemy.sprite.x, enemy.sprite.y, point.x, point.y, { skipRockIndex: index })) return null;

    return {
      kind: 'obstacle',
      priority: 4,
      distance,
      targetX: point.x,
      targetY: point.y,
      obstacle,
      obstacleIndex: index,
    };
  }

  private findNearestPlayerTarget(enemy: EnemyEntity, range: number): EnemyAttackCandidate | null {
    let best: EnemyAttackCandidate | null = null;

    if (this.targetCatalog) {
      this.targetCatalog.forEachTarget('player-like-threats', (target) => {
        const candidate = this.buildPlayerLikeTargetCandidate(enemy, {
          kind: target.kind,
          id: target.id,
        }, range);
        if (candidate && this.isBetterCandidate(candidate, best)) best = candidate;
      });
      return best;
    }

    for (const player of this.playerManager.getAllPlayers()) {
      const candidate = this.buildPlayerTargetCandidate(enemy, player.id, range);
      if (candidate && this.isBetterCandidate(candidate, best)) best = candidate;
    }

    return best;
  }

  private findNearestLivingTarget(enemy: EnemyEntity, range: number): EnemyAttackCandidate | null {
    let best = this.findNearestPlayerTarget(enemy, range);
    for (const ally of this.enemyManager.getAlliedEnemies()) {
      const candidate = this.buildAllyTargetCandidate(enemy, ally, range);
      if (!candidate) continue;
      if (this.isBetterCandidate(candidate, best)) best = candidate;
    }
    return best;
  }

  private findLivingTargetWithLock(
    enemy: EnemyEntity,
    range: number,
    now: number,
    updateLock = true,
  ): EnemyAttackCandidate | null {
    const lockedTarget = this.getLockedPlayerTarget(enemy, range, now, updateLock);
    if (lockedTarget) return lockedTarget;

    const target = this.findNearestLivingTarget(enemy, range);
    if (target?.targetRef && updateLock) {
      this.playerTargetLocks.set(enemy.id, {
        targetRef: target.targetRef,
        lockedUntil: now + CoopDefenseEnemyAttackSystem.PLAYER_TARGET_LOCK_DURATION_MS,
      });
    }
    return target;
  }

  private getLockedPlayerTarget(
    enemy: EnemyEntity,
    range: number,
    now: number,
    updateLock = true,
  ): EnemyAttackCandidate | null {
    const lock = this.playerTargetLocks.get(enemy.id);
    if (!lock) return null;
    if (now >= lock.lockedUntil) {
      if (updateLock) this.playerTargetLocks.delete(enemy.id);
      return null;
    }

    const target = this.buildPlayerLikeTargetCandidate(enemy, lock.targetRef, range);
    if (!target && updateLock) this.playerTargetLocks.delete(enemy.id);
    return target;
  }

  private buildPlayerTargetCandidate(
    enemy: EnemyEntity,
    playerId: string,
    range: number,
  ): EnemyAttackCandidate | null {
    return this.buildPlayerLikeTargetCandidate(enemy, { kind: 'player', id: playerId }, range);
  }

  private buildPlayerLikeTargetCandidate(
    enemy: EnemyEntity,
    targetRef: EnemyAiTargetRef,
    range: number,
  ): EnemyAttackCandidate | null {
    if (targetRef.kind === 'player' && !this.targetCatalog) {
      const player = this.playerManager.getPlayer(targetRef.id);
      if (!player || !this.isValidPlayerTarget(enemy, targetRef.id, range)) return null;
      return {
        kind: 'player',
        priority: 2,
        distance: Phaser.Math.Distance.Between(enemy.sprite.x, enemy.sprite.y, player.x, player.y),
        targetX: player.x,
        targetY: player.y,
        targetId: player.id,
        targetRef,
      };
    }

    const target = this.targetCatalog?.resolve(targetRef);
    if (!target || target.kind === 'hostile-enemy') return null;
    const position = target.resolvePosition?.(enemy.sprite.x, enemy.sprite.y) ?? { x: target.x, y: target.y };
    const distance = Phaser.Math.Distance.Between(enemy.sprite.x, enemy.sprite.y, position.x, position.y);
    if (distance > range + (target.radius ?? PLAYER_SIZE * 0.5)) return null;
    if (!this.enemyManager.canSeeThroughSmoke(enemy.id, position.x, position.y, range)) return null;
    if (!this.combatSystem.hasClearLineOfFire(enemy.sprite.x, enemy.sprite.y, position.x, position.y,
      { skipRockIndex: target.skipRockIndex })) return null;
    if (target.kind === 'armed-construct') {
      const obstacle = this.getRockObjects()?.[Number(target.id)];
      if (!obstacle?.active) return null;
      return { kind: 'obstacle', priority: 2, distance, targetX: position.x, targetY: position.y, obstacle, obstacleIndex: Number(target.id), targetRef };
    }
    if (target.kind === 'armed-base' || target.kind === 'armed-outpost') {
      return { kind: 'base', priority: 2, distance, targetX: position.x, targetY: position.y, targetRef };
    }
    return {
      kind: target.kind,
      priority: 2,
      distance,
      targetX: position.x,
      targetY: position.y,
      targetId: target.kind === 'player' ? target.id : undefined,
      targetRef,
    };
  }

  private buildAllyTargetCandidate(
    enemy: EnemyEntity,
    ally: EnemyEntity,
    range: number,
  ): EnemyAttackCandidate | null {
    if (!ally.sprite.active || !this.combatSystem.isAlive(ally.id)) return null;
    if (!this.combatSystem.canDamageTarget(enemy.id, ally.id)) return null;

    const distance = Phaser.Math.Distance.Between(enemy.sprite.x, enemy.sprite.y, ally.sprite.x, ally.sprite.y);
    if (distance > range || !this.enemyManager.canSeeThroughSmoke(enemy.id, ally.sprite.x, ally.sprite.y, range) || !this.combatSystem.hasClearLineOfFire(enemy.sprite.x, enemy.sprite.y, ally.sprite.x, ally.sprite.y)) {
      return null;
    }

    return {
      kind: 'ally',
      priority: 2,
      distance,
      targetX: ally.sprite.x,
      targetY: ally.sprite.y,
      targetId: ally.id,
    };
  }

  private isValidPlayerTarget(enemy: EnemyEntity, playerId: string, range: number): boolean {
    const player = this.playerManager.getPlayer(playerId);
    if (!player?.active) return false;
    if (!this.combatSystem.isAlive(player.id) || this.combatSystem.isPlayerTargetable?.(player.id) === false) return false;
    if (this.combatSystem.isBurrowed(player.id)) return false;
    if (this.targetCatalog?.isTargetValid({ kind: 'player', id: playerId }) === false) return false;
    if (!this.combatSystem.canDamageTarget(enemy.id, player.id)) return false;

    const distance = Phaser.Math.Distance.Between(enemy.sprite.x, enemy.sprite.y, player.x, player.y);
    if (distance > range + PLAYER_SIZE * 0.5) return false;
    return this.enemyManager.canSeeThroughSmoke(enemy.id, player.x, player.y, range) && this.combatSystem.hasClearLineOfFire(enemy.sprite.x, enemy.sprite.y, player.x, player.y);
  }

  private findTrainTarget(enemy: EnemyEntity, range: number): EnemyAttackCandidate | null {
    const target = this.trainAwarenessSystem?.getTrainAttackTarget(enemy);
    if (!target || target.distance > range) return null;
    // Bewusst die Sichtlinie: der Zug ist hier das Ziel und würde sich in der Schusslinie
    // selbst verdecken.
    if (!this.enemyManager.canSeeThroughSmoke(enemy.id, target.x, target.y, range)) return null;
    if (!this.combatSystem.hasLineOfSight(enemy.sprite.x, enemy.sprite.y, target.x, target.y)) return null;
    return {
      kind: 'train',
      priority: 3,
      distance: target.distance,
      targetX: target.x,
      targetY: target.y,
    };
  }

  private isObstacleAttackUnlocked(enemy: EnemyEntity): boolean {
    return this.intents?.getBreach(enemy.id)?.status === 'ready';
  }

  private cleanupInactiveEnemies(activeEnemyIds: ReadonlySet<string>): void {
    this.deleteInactiveEntries(this.lastAttackTargets, activeEnemyIds);
    this.deleteInactiveEntries(this.sustainedAttacks, activeEnemyIds);
    this.deleteInactiveEntries(this.salvoStates, activeEnemyIds);
    this.deleteInactiveEntries(this.playerTargetLocks, activeEnemyIds);
    this.deleteInactiveEntries(this.meleeWindups, activeEnemyIds);
    this.deleteInactiveEntries(this.ignitions, activeEnemyIds);
    this.deleteInactiveEntries(this.lastIgnitedShotAt, activeEnemyIds);
    for (const key of this.scorchReadyAt.keys()) if (!activeEnemyIds.has(key.slice(0, key.indexOf(':')))) this.scorchReadyAt.delete(key);
  }

  private deleteInactiveEntries<T>(entries: Map<string, T>, activeEnemyIds: ReadonlySet<string>): void {
    for (const enemyId of entries.keys()) {
      if (!activeEnemyIds.has(enemyId)) entries.delete(enemyId);
    }
  }

  private isBetterCandidate(candidate: EnemyAttackCandidate | null, current: EnemyAttackCandidate | null): boolean {
    if (!candidate) return false;
    if (!current) return true;
    if (candidate.priority !== current.priority) {
      return candidate.priority < current.priority;
    }
    return candidate.distance < current.distance;
  }

  private targetKey(candidate: EnemyAttackCandidate): string {
    return candidate.targetRef
      ? `${candidate.targetRef.kind}:${candidate.targetRef.id}`
      : (candidate.targetId ?? candidate.kind);
  }
}

interface SelectedEnemyAttack {
  readonly attackWeapon: EnemyAttackWeapon;
  readonly target: EnemyAttackCandidate;
}

/** A melee strike all around the body: it needs no facing at all. */
function isAllRoundStrike(attackWeapon: EnemyAttackWeapon): boolean {
  const fire = attackWeapon.weapon.config.fire;
  return fire.type === 'melee' && fire.hitArcDegrees >= 300;
}
