/**
 * Empfangsseite eines Links, unabhängig vom Transport: Fragmente zusammensetzen, optional
 * dekomprimieren und Nachrichten je Kanal mit der richtigen Semantik ausliefern.
 *
 * - `rel`: strikt in Eingangsreihenfolge, auch wenn einzelne Nachrichten asynchron
 *   dekomprimiert werden müssen; der Rückstand ist begrenzt.
 * - `fast`: nur der neueste vollständige Stand zählt; ein noch laufendes Dekodieren
 *   verdrängt ältere wartende Nutzlasten.
 *
 * WebRTC (`PeerLink`) und Steam (`SteamLink`) teilen diese Pipeline, damit beide exakt
 * dieselbe Reihenfolge- und Fragmentsemantik haben.
 */
import { PeerPacketAssembler, decodePeerPayload, PEER_MESSAGE_LIMIT_BYTES,
  type EncodedPeerPayload } from './PeerPacketCodec';
import type { PeerChannelKind } from './protocol';

export interface PeerReceiveSink {
  /** Vollständige Nachricht als Text; das Parsen gehört dem Link. */
  deliver(payload: string, channel: PeerChannelKind): void;
  /** Der Reliable-Rückstand überschreitet das Budget; der Link muss schließen. */
  overloaded(): void;
}

export class PeerReceivePipeline {
  private readonly reliablePackets = new PeerPacketAssembler(true);
  private readonly fastPackets = new PeerPacketAssembler(false);
  private reliableReceiveTail: Promise<void> = Promise.resolve();
  private reliableReceiveBytes = 0;
  private fastDecoding = false;
  private pendingFastDecode: EncodedPeerPayload | null = null;
  private closed = false;

  constructor(private readonly sink: PeerReceiveSink) {}

  /** Ein Datenkanal-Ereignis: Text (unfragmentiert) oder ein Binärfragment. */
  receive(data: unknown, channel: PeerChannelKind): void {
    if (this.closed) return;
    const payload = typeof data === 'string' ? data
      : (channel === 'rel' ? this.reliablePackets : this.fastPackets).accept(data);
    if (payload === null) return;
    if (typeof payload === 'string' && (channel === 'fast' || this.reliableReceiveBytes === 0)) {
      this.sink.deliver(payload, channel); return;
    }
    if (channel === 'fast') {
      this.pendingFastDecode = payload as EncodedPeerPayload;
      void this.decodeFast();
      return;
    }
    const bytes = typeof payload === 'string' ? payload.length * 2 : payload.rawBytes;
    this.reliableReceiveBytes += bytes;
    if (this.reliableReceiveBytes > PEER_MESSAGE_LIMIT_BYTES * 2) {
      this.sink.overloaded(); return;
    }
    this.reliableReceiveTail = this.reliableReceiveTail.then(async () => {
      if (this.closed) return;
      try {
        const text = typeof payload === 'string' ? payload : await decodePeerPayload(payload);
        if (!this.closed) this.sink.deliver(text, channel);
      } catch (error) { console.warn('[PeerLink] Ungültige Reliable-Nachricht.', error); }
      finally { this.reliableReceiveBytes -= bytes; }
    });
  }

  /** Endgültig: verwirft Teilnachrichten und laufende Dekodierungen. */
  close(): void {
    this.closed = true;
    this.reliablePackets.clear(); this.fastPackets.clear();
    this.pendingFastDecode = null;
  }

  private async decodeFast(): Promise<void> {
    if (this.fastDecoding) return;
    this.fastDecoding = true;
    try {
      while (this.pendingFastDecode && !this.closed) {
        const payload = this.pendingFastDecode;
        this.pendingFastDecode = null;
        try {
          const text = await decodePeerPayload(payload);
          if (!this.closed) this.sink.deliver(text, 'fast');
        } catch { /* Corrupt/lost fast message: a subsequent complete snapshot heals it. */ }
      }
    } finally { this.fastDecoding = false; }
  }
}
