import type { GameMode } from '../types';
import { COOP_DEFENSE_MODE } from '../gameModes';
import { DEFAULT_COOP_PROGRAM, type CoopProgram } from '../dawn/contracts/CoopProgram';
import { COOP_DEFENSE_MAP_CONFIGS, DEFAULT_COOP_DEFENSE_MAP_ID } from './coopDefenseMaps';
import demoContentSource from './distributionDemoContent.json';

/**
 * Inhaltsumfang einer Distributionsvariante (Steam-Plan, Regel 4).
 *
 * Die Demo ist eine Whitelist: Was nicht ausdrücklich in `distributionDemoContent.json` steht,
 * gibt es nur in der Vollversion. Neue Modi, Programme und Karten sind dadurch automatisch
 * Steam-only. Welche Policy gilt, entscheidet allein `src/platform/` über `PlatformServices.content`;
 * Lobby-Auswahl, Host-Übernahme und Kampagnenfortschritt lesen nur diesen Vertrag.
 */
export type CoopProgramKind = CoopProgram['kind'];

export interface DistributionContentWhitelist {
  readonly gameModes: readonly GameMode[];
  readonly coopPrograms: readonly CoopProgramKind[];
  /** Coop-Defense-Karten-IDs; die Kampagnenreihenfolge bleibt Sache der Map-Registry. */
  readonly coopDefenseMapIds: readonly string[];
}

export interface DistributionContentPolicy {
  /** `null` bedeutet uneingeschränkt (Vollversion). */
  readonly whitelist: DistributionContentWhitelist | null;
  allowsGameMode(mode: GameMode): boolean;
  allowsCoopProgram(kind: CoopProgramKind): boolean;
  allowsCoopDefenseMap(mapId: string): boolean;
}

const KNOWN_GAME_MODES: Record<GameMode, true> = {
  deathmatch: true, team_deathmatch: true, capture_the_beer: true, coop_defense: true,
};
const KNOWN_COOP_PROGRAMS: Record<CoopProgramKind, true> = { campaign: true, dawn: true };

function readIdList<T extends string>(raw: unknown, field: string, isKnown: (id: string) => boolean): readonly T[] {
  if (!Array.isArray(raw)) throw new Error(`[distributionContentPolicy] ${field}: Array erwartet.`);
  const ids = raw.map(id => {
    if (typeof id !== 'string' || !isKnown(id)) throw new Error(`[distributionContentPolicy] ${field}: unbekannte ID ${String(id)}.`);
    return id as T;
  });
  if (new Set(ids).size !== ids.length) throw new Error(`[distributionContentPolicy] ${field}: doppelte ID.`);
  return Object.freeze(ids);
}

/**
 * Validiert eine authored Whitelist. Unbekannte IDs werden abgelehnt; die Werte, auf die die
 * Lobby bei unzulässigem Zustand zurückfällt (Coop-Modus, Standardkarte, Kampagne), müssen
 * erlaubt sein, damit jede Rückfallauswahl selbst gültig bleibt.
 */
export function parseDistributionContentWhitelist(raw: unknown): DistributionContentWhitelist {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error('[distributionContentPolicy] Objekt erwartet.');
  const source = raw as Record<string, unknown>;
  const mapIds = new Set(COOP_DEFENSE_MAP_CONFIGS.map(map => map.mapId));
  const whitelist: DistributionContentWhitelist = Object.freeze({
    gameModes: readIdList<GameMode>(source.gameModes, 'gameModes', id => Object.keys(KNOWN_GAME_MODES).includes(id)),
    coopPrograms: readIdList<CoopProgramKind>(source.coopPrograms, 'coopPrograms', id => Object.keys(KNOWN_COOP_PROGRAMS).includes(id)),
    coopDefenseMapIds: readIdList<string>(source.coopDefenseMapIds, 'coopDefenseMapIds', id => mapIds.has(id)),
  });
  if (!whitelist.gameModes.includes(COOP_DEFENSE_MODE)
    || !whitelist.coopPrograms.includes(DEFAULT_COOP_PROGRAM.kind)
    || !whitelist.coopDefenseMapIds.includes(DEFAULT_COOP_DEFENSE_MAP_ID)) {
    throw new Error('[distributionContentPolicy] Die Lobby-Rückfallauswahl muss erlaubt sein.');
  }
  return whitelist;
}

export function createDistributionContentPolicy(whitelist: DistributionContentWhitelist | null): DistributionContentPolicy {
  if (!whitelist) {
    return Object.freeze({
      whitelist: null,
      allowsGameMode: () => true,
      allowsCoopProgram: () => true,
      allowsCoopDefenseMap: () => true,
    });
  }
  return Object.freeze({
    whitelist,
    allowsGameMode: (mode: GameMode) => whitelist.gameModes.includes(mode),
    allowsCoopProgram: (kind: CoopProgramKind) => whitelist.coopPrograms.includes(kind),
    allowsCoopDefenseMap: (mapId: string) => whitelist.coopDefenseMapIds.includes(mapId),
  });
}

/** Vollversion (Steam): alles erlaubt, auch künftige Inhalte. */
export const FULL_CONTENT_POLICY = createDistributionContentPolicy(null);

/** Browser-Demo: ausschließlich die authored Whitelist. */
export const DEMO_CONTENT_POLICY = createDistributionContentPolicy(parseDistributionContentWhitelist(demoContentSource));
