import * as Phaser from 'phaser';
import type { FormationCoverageBinding } from '../../arena/rocks/RockFormationLighting';
import { lightAddBlendMode } from '../../graphics/CustomBlendModes';
import type { GraphicsPreset } from '../../graphics/GraphicsQuality';
import { runWithScopedBlend } from '../../graphics/PhaserScopedBlend';
import type { DynamicLightOccluderSource } from '../DynamicLightOccluders';
import type { LightOccluderIndex } from '../LightOccluderIndex';
import { EnemyMeshGpu } from '../EnemyMeshGpu';
import { ownSunShader } from '../sunlight/SunRenderTarget';
import { IndirectLightField } from './IndirectLightField';
import type { LightMapBinding } from './LightMapBinding';
import { OccluderField, type FigureMaskRect, type OccluderCaster } from './OccluderField';
import type { ShadowProvider } from './ShadowProvider';

/** Shadowed lights per frame; the rest fall back to plain stamps. Final numbers follow the shadow winner. */
const SHADOWED_LIGHT_BUDGET: Readonly<Record<GraphicsPreset, number>> = { ultra: 64, high: 24, medium: 12, low: 4 };

export interface ShadowedLightView {
  readonly x: number;
  readonly y: number;
  readonly radiusPx: number;
  readonly heightPx: number;
  readonly color: number;
  readonly intensity: number;
  readonly shape: 'radial' | 'cone';
  readonly angle: number;
  readonly coneAngle: number;
  readonly falloffExponent: number;
  readonly surfaceReachNearPx: number;
  readonly surfaceReachFarPx: number;
  /** Radius of the light's own glowing body in px: nothing standing inside it can darken it. */
  readonly bodyPx: number;
  /** 1 full shadow, 0 none: a light that gains or loses its place in the budget fades instead of popping. */
  readonly shadowBlend: number;
}

/** Below this a light adds nothing the eye can tell from black; its rim then skips the trace. */
const MIN_VISIBLE_LIGHT = 0.003;

const BATCH_CAPACITY = 256;
const INSTANCE_WORDS = 19;
const ATTRIBUTES = [
  { name: 'inMap', size: 3 }, { name: 'inLight', size: 4 }, { name: 'inColor', size: 4 },
  { name: 'inCone', size: 4 }, { name: 'inReach', size: 4 },
];

export const SHADOWED_LIGHT_VERTEX = `
precision highp float;
attribute vec2 inPosition;
attribute vec3 inMap;
attribute vec4 inLight,inColor,inCone,inReach;
uniform mat4 uProjectionMatrix;
uniform mat3 uViewMatrix;
varying vec2 outTexCoord;
varying vec4 uLight,uColor,uCone,uReach;
void main() {
 vec2 at=inMap.xy+(inPosition*2.0-1.0)*inMap.z;
 vec3 view=uViewMatrix*vec3(at,1.0);
 gl_Position=uProjectionMatrix*vec4(view.xy,0.0,1.0);
 outTexCoord=vec2(inPosition.x,1.0-inPosition.y);
 uLight=inLight;uColor=inColor;uCone=inCone;uReach=inReach;
}`;

interface LightBatch {
  readonly target: Phaser.GameObjects.RenderTexture;
  readonly entry: Phaser.GameObjects.Shader;
  readonly data: Float32Array;
  count: number;
}

export function shadowedLightFragment(providerGlsl: string): string {
  return `
#pragma phaserTemplate(shaderName)
precision highp float;
varying vec2 outTexCoord;
// World x, y, radius, height of the light.
varying vec4 uLight;
// Colour and intensity.
varying vec4 uColor;
// Direction, half angle, falloff exponent, 1 for a cone.
varying vec4 uCone;
// Rock front lit by a lamp: reach near, reach far; radius of the light's glowing body, strength of the shadow.
varying vec4 uReach;
uniform sampler2D uOccluderField;
uniform vec4 uOccluderFrame;
/** R blocker, G height / 510 px, B surface kind (1 = rock front rule). */
vec4 occluderAt(vec2 world) {
  vec2 uv = (world - uOccluderFrame.xy) / uOccluderFrame.zw;
  return texture2D(uOccluderField, vec2(uv.x, 1.0 - uv.y));
}
${providerGlsl}
void main() {
  vec2 p = vec2(outTexCoord.x - 0.5, 0.5 - outTexCoord.y) * 2.0;
  float d = length(p);
  if (d >= 1.0) discard;
  float shape;
  if (uCone.w > 0.5) {
    float a = atan(p.y, p.x) - uCone.x;
    a = abs(atan(sin(a), cos(a)));
    shape = pow(1.0 - d, uCone.z) * clamp((uCone.y - a) / (0.3 * uCone.y), 0.0, 1.0);
  } else shape = (1.0 - d) * (1.0 - d);
  if (uColor.a * shape < ${MIN_VISIBLE_LIGHT.toFixed(4)}) discard;
  float visible = shadowVisibility(uLight.xy + p * uLight.z);
  if (uReach.z > 0.0) visible = mix(1.0, visible, smoothstep(uReach.z * 0.75, uReach.z * 1.25, d * uLight.z));
  visible = mix(1.0, visible, uReach.w);
  gl_FragColor = vec4(uColor.rgb * uColor.a * shape * visible, 0.0);
}`;
}

export function shadowedLightShaderName(providerId: string): string { return `ShadowedLight_${providerId}`; }

/** Batches shadowed lights per target; all instances share the frame's occluder and distance fields. */
export class ShadowedLightPass {
  private readonly field: OccluderField;
  private readonly batches: LightBatch[] = [];
  private readonly gpu: EnemyMeshGpu;
  private readonly blend: number;
  private used = 0;
  /** Field and provider textures shared by every light in this frame. */
  private textures: Phaser.Textures.Texture[] = [];
  private readonly viewMatrix = new Float32Array(9);
  private readonly glTextures: Phaser.Renderer.WebGL.Wrappers.WebGLTextureWrapper[] = [];
  private indirect: IndirectLightField | null = null;

  constructor(private readonly scene: Phaser.Scene, private readonly provider: ShadowProvider) {
    this.field = new OccluderField(scene);
    this.blend = lightAddBlendMode(scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer);
    this.gpu = new EnemyMeshGpu(scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer,
      shadowedLightShaderName(provider.id), SHADOWED_LIGHT_VERTEX, shadowedLightFragment(provider.glsl), new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]), 2,
      new Uint16Array([0, 1, 2, 0, 2, 3]), ATTRIBUTES, BATCH_CAPACITY);
  }

  /** Once per frame, before the first `draw`. `reachPx`: how far outside the view the farthest light of this frame's draws stands. */
  prepare(viewX: number, viewY: number, viewWidth: number, viewHeight: number, reachPx: number, occluders: LightOccluderIndex | null,
    dynamicOccluders: DynamicLightOccluderSource | null, coverage: FormationCoverageBinding | null, casters: readonly OccluderCaster[],
    figureMask: FigureMaskRect | null, animatedFigures: boolean, figureCoverage: boolean): void {
    this.used = 0;
    for (const batch of this.batches) batch.count = 0;
    this.field.update(viewX, viewY, viewWidth, viewHeight, reachPx, { occluders, dynamicOccluders, coverage, casters, figureMask, animatedFigures, figureCoverage });
    this.provider.prepare?.(this.field);
    const field = this.field.texture, extra = this.provider.textures?.(this.field) ?? [];
    if (!field) return;
    if (this.textures[0] !== field || this.textures.length !== extra.length + 1 || extra.some((texture, i) => this.textures[i + 1] !== texture)) {
      this.textures = [field, ...extra];
    }
  }

  /** Null switches the indirect light off for this frame. */
  prepareIndirect(binding: LightMapBinding | null): void {
    if (binding) this.indirect ??= new IndirectLightField(this.scene);
    this.indirect?.prepare(binding ? this.provider.distanceField?.() ?? null : null, binding, work => this.field.afterDrawn(work));
  }

  /** After the direct lights; `frame` is the world rectangle of `target`. */
  drawIndirect(target: Phaser.GameObjects.RenderTexture, frame: Float32Array): void {
    this.indirect?.draw(target, frame);
  }

  canDraw(preset: GraphicsPreset): boolean {
    return this.field.texture !== null && this.used < SHADOWED_LIGHT_BUDGET[preset];
  }

  /** `mapX`/`mapY` and `mapRadius` are in light-map texels. */
  draw(target: Phaser.GameObjects.RenderTexture, light: ShadowedLightView, mapX: number, mapY: number, mapRadius: number): void {
    let batch = this.batches.find(value => value.target === target && value.count < BATCH_CAPACITY);
    if (!batch) { batch = this.createBatch(target); this.batches.push(batch); }
    if (batch.count === 0) target.draw(batch.entry);
    const at = batch.count++ * INSTANCE_WORDS, data = batch.data;
    this.used += 1;
    data[at] = mapX; data[at + 1] = mapY; data[at + 2] = mapRadius;
    data[at + 3] = light.x; data[at + 4] = light.y; data[at + 5] = light.radiusPx; data[at + 6] = light.heightPx;
    data[at + 7] = ((light.color >> 16) & 255) / 255; data[at + 8] = ((light.color >> 8) & 255) / 255;
    data[at + 9] = (light.color & 255) / 255; data[at + 10] = light.intensity;
    data[at + 11] = light.angle; data[at + 12] = light.coneAngle * 0.5;
    data[at + 13] = light.falloffExponent; data[at + 14] = light.shape === 'cone' ? 1 : 0;
    data[at + 15] = light.surfaceReachNearPx; data[at + 16] = light.surfaceReachFarPx;
    data[at + 17] = light.bodyPx; data[at + 18] = light.shadowBlend;
  }

  destroy(): void {
    for (const batch of this.batches) batch.entry.destroy();
    this.batches.length = 0;
    this.gpu.destroy();
    this.indirect?.destroy(); this.indirect = null;
    this.field.destroy();
    this.provider.destroy?.();
  }

  private createBatch(target: Phaser.GameObjects.RenderTexture): LightBatch {
    const name = 'ShadowedLightEntry', owner = this;
    const entry = new Phaser.GameObjects.Shader(this.scene, {
      name, shaderName: name, fragmentSource: 'precision mediump float;void main(){gl_FragColor=vec4(0.0);}',
    }, 0, 0, target.width, target.height);
    ownSunShader(entry, name, true);
    entry.setOrigin(0);
    const batch = { target, entry, count: 0, data: new Float32Array(BATCH_CAPACITY * INSTANCE_WORDS) };
    entry.renderNode.run = function (context, object, parent): void {
      runWithScopedBlend(this, () => owner.renderBatch(context, batch), context, owner.blend, object, parent);
    };
    return batch;
  }

  private renderBatch(context: Phaser.Renderer.WebGL.DrawingContext, batch: LightBatch): void {
    const renderer = this.scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer;
    const camera = context.camera!.getViewMatrix(!context.useCanvas), matrix = this.viewMatrix;
    matrix.set([camera.a, camera.b, 0, camera.c, camera.d, 0, camera.tx, camera.ty, 1]);
    renderer.setProjectionMatrixFromDrawingContext(context);
    this.glTextures.length = this.textures.length;
    for (let i = 0; i < this.textures.length; i++) this.glTextures[i] = this.textures[i].get().source.glTexture!;
    this.gpu.draw(context, batch.data.subarray(0, batch.count * INSTANCE_WORDS), batch.count, this.glTextures, set => {
      set('uProjectionMatrix', renderer.projectionMatrix.val); set('uViewMatrix', matrix);
      set('uOccluderField', 0); set('uOccluderFrame', this.field.frame);
      this.provider.setUniforms?.(set, this.field);
    });
  }
}
