import { CELL_SIZE } from '../config';
import { getCoopDefenseEnemyConfig } from '../config/coopDefenseEnemies';
import type { InfernoColossusChunksConfig, InfernoColossusConfig, InfernoColossusImpactConfig } from '../config/infernoColossus';
import type { EnemyEntity } from '../entities/EnemyEntity';
import type { EnemyMovementOverride, EnemySpecialMovementSource } from '../entities/EnemyManager';
import type { SyncedMortarStrike } from '../types';
import { beginEnemyFlightTracking, enemyFlightVelocity, stepEnemyFlight, type EnemyFlightTracker } from './enemyFlight';
import {
  assignSwarmTargets, chooseColossusAction, colossusRandom, findColossusLandingPoint, incendiaryFlightMs, incendiaryLandingPoints,
  pickSalvoTarget, type SwarmCandidate, type SwarmShot,
} from './infernoColossusRules';
import type { InfernoColossusAction, InfernoColossusActionKind } from './InfernoColossusState';

/** The target the body hunts, as its intent resolves it. */
export interface ColossusHuntedTarget {
  readonly x: number;
  readonly y: number;
  /** Seen through smoke and cover rules; a hidden target is neither thrown at nor flown to. */
  readonly visible: boolean;
  /** The body has no walkable route to it. */
  readonly unreachable: boolean;
}

export interface InfernoColossusPorts {
  readonly enemies: { getAllEnemies(): readonly EnemyEntity[] };
  readonly isStunned: (enemyId: string, now: number) => boolean;
  /** The train-awareness owner currently moves the body off the track. */
  readonly isEvadingTrain?: (enemyId: string) => boolean;
  readonly hunted: (enemy: EnemyEntity) => ColossusHuntedTarget | null;
  /** A player, decoy, base surface or construction inside `radiusPx` of the body. */
  readonly hasThreatWithin: (enemy: EnemyEntity, radiusPx: number) => boolean;
  readonly swarmCandidates: (enemy: EnemyEntity, rangePx: number) => readonly SwarmCandidate[];
  readonly isFreeGround: (x: number, y: number, radius: number) => boolean;
  readonly findSafeGround: (x: number, y: number, radius: number, maxCells: number) => { x: number; y: number } | null;
  readonly clampToWorld: (x: number, y: number) => { x: number; y: number };
  /** Area hit around a point with the body's faction rules; structures take their multipliers. */
  readonly areaBurst: (enemy: EnemyEntity, x: number, y: number, burst: InfernoColossusImpactConfig,
    chunks: InfernoColossusChunksConfig | null, sourceId: string, effectStyle: 'colossus_quake' | 'colossus_awakening', now: number) => void;
  readonly chunks: (enemy: EnemyEntity, x: number, y: number, chunks: InfernoColossusChunksConfig, sourceKey: string, now: number) => void;
  /**
   * Brandsatz shells, announced with their final points when the windup starts (`armedAt`). Launched at
   * `launchAt`, they land at `impactAt` on their point even if the body dies meanwhile; a windup dropped
   * before its launch never lands.
   */
  readonly prepareIncendiary: (enemy: EnemyEntity, shells: readonly { readonly x: number; readonly y: number; readonly impactAt: number }[],
    sourceX: number, sourceY: number, armedAt: number, launchAt: number, config: InfernoColossusConfig['incendiary']) => IncendiaryWindup | null;
  readonly fireSwarm: (enemy: EnemyEntity, shots: readonly SwarmShot[], config: InfernoColossusConfig['siege'], now: number) => void;
  /** One aimed beetle of the salvo from the body's muzzle at `target`, scattered by `spreadRad`. */
  readonly fireBeetle: (enemy: EnemyEntity, target: SwarmCandidate, spreadRad: number, config: InfernoColossusConfig['beetleSalvo'],
    now: number) => void;
  readonly setAirborne: (enemyId: string, airborne: boolean) => void;
}

type CooldownKind = Exclude<InfernoColossusActionKind, 'transition'>;

/** Announced Brandsatz shells of a running windup; `launch` commits them unchanged. */
export interface IncendiaryWindup {
  readonly snapshots: readonly SyncedMortarStrike[];
  launch(): void;
}

interface FlightRun {
  readonly tracker: EnemyFlightTracker;
  nominalAirMs: number;
  airborne: boolean;
  chunkX: number;
  chunkY: number;
}

interface ColossusState {
  readonly enemy: EnemyEntity;
  revision: number;
  phase: number;
  action: InfernoColossusAction | null;
  /** The action's damaging moment already ran (burst, throw, landing). */
  committed: boolean;
  /** Siege waves or salvo beetles fired so far. */
  wavesFired: number;
  heading: number;
  flight: FlightRun | null;
  incendiary: IncendiaryWindup | null;
  gapUntil: number;
  /** The body walks from here on; before it, it stands where it appeared. */
  walkAt: number;
  readyAt: Record<CooldownKind, number>;
}

/** Phase-two actions wait until the transition sets their first time. */
const NEVER = Number.POSITIVE_INFINITY;
/** Windups a stun breaks before their hit; the transition and a flight in the air go on. */
const STUN_BREAKS: ReadonlySet<InfernoColossusActionKind> = new Set(['glutstoss', 'incendiary', 'siege', 'beetleSalvo']);

/**
 * Host owner of the Flammenkoloss's phases and big actions. One action runs at a time and is
 * published as a replicated InfernoColossusState; between actions the body hunts with its
 * flamethrower (AttackSystem). Phase 2 starts once at the authored HP share with a standing
 * transition; it unlocks the siege and the storm flight. The beetle salvo (both phases) is the one
 * action that holds neither the body nor its flame. An allied (necromancy) colossus has no
 * phases and no big actions.
 */
export class CoopDefenseInfernoColossusSystem implements EnemySpecialMovementSource {
  private readonly states = new Map<string, ColossusState>();
  private readonly reachedPhases = new Set<number>();
  private lastNow = 0;

  constructor(private readonly ports: InfernoColossusPorts) {}

  hostUpdate(now: number): void {
    this.lastNow = now;
    const live = new Set<string>();
    for (const enemy of this.ports.enemies.getAllEnemies()) {
      const config = this.configOf(enemy);
      if (!config || !enemy.sprite.active || enemy.getHp() <= 0) continue;
      live.add(enemy.id);
      const state = this.stateOf(enemy, config, now);
      this.step(state, config, now);
    }
    for (const [id, state] of this.states) {
      if (live.has(id)) continue;
      if (state.flight?.airborne) this.ports.setAirborne(id, false);
      this.states.delete(id);
    }
  }

  /** Persistent host fact for map triggers. */
  hasReachedPhase(phase: number): boolean { return this.reachedPhases.has(phase); }

  /** Standing actions hold the body; the flight carries it along its line. */
  getMovementOverride(enemy: EnemyEntity, now: number): EnemyMovementOverride | null {
    const state = this.states.get(enemy.id);
    if (state?.enemy === enemy && now < state.walkAt && !this.ports.isEvadingTrain?.(enemy.id)) {
      return { vx: 0, vy: 0, aimAngle: state.heading };
    }
    const action = state?.enemy === enemy ? state.action : null;
    if (!state || !action || action.kind === 'beetleSalvo' || now >= action.endsAt || this.ports.isEvadingTrain?.(enemy.id)) return null;
    if (action.kind === 'flight' && state.flight?.airborne) {
      const line = { originX: action.originX, originY: action.originY, targetX: action.x, targetY: action.y,
        takeoffAt: action.releaseAt, landAt: action.commitAt };
      return { ...enemyFlightVelocity(line, enemy.sprite.x, enemy.sprite.y, state.flight.nominalAirMs), aimAngle: state.heading };
    }
    return { vx: 0, vy: 0, aimAngle: state.heading };
  }

  /** No flame and no bite while a big action runs (the beetle salvo is no big action). */
  blocksRegularAttacks(enemyId: string): boolean {
    const action = this.states.get(enemyId)?.action;
    return !!action && action.kind !== 'beetleSalvo' && this.lastNow < action.endsAt;
  }

  /** A flying or rearing body does not dodge. */
  blocksDodge(enemyId: string): boolean { return this.blocksRegularAttacks(enemyId); }

  getDevStatus(enemyId: string): { phase: number; action: InfernoColossusActionKind | null } | null {
    const state = this.states.get(enemyId);
    return state ? { phase: state.phase, action: state.action?.kind ?? null } : null;
  }

  /** Dev scenarios: start an action now, skipping its cooldown and trigger (never the phase rule). */
  forceAction(enemyId: string, kind: InfernoColossusActionKind, now: number): boolean {
    const state = this.states.get(enemyId);
    const config = state && this.configOf(state.enemy);
    if (!state || !config || state.action) return false;
    if (kind === 'transition') {
      if (state.phase >= 2) return false;
      this.startTransition(state, config, now);
      return true;
    }
    if ((kind === 'siege' || kind === 'flight') && state.phase < 2) return false;
    return this.start(state, config, kind, now, true);
  }

  clear(): void {
    for (const [id, state] of this.states) if (state.flight?.airborne) this.ports.setAirborne(id, false);
    this.states.clear();
    this.reachedPhases.clear();
  }

  private configOf(enemy: EnemyEntity): InfernoColossusConfig | undefined {
    return enemy.faction === 'hostile' ? getCoopDefenseEnemyConfig(enemy.kind).infernoColossus : undefined;
  }

  private stateOf(enemy: EnemyEntity, config: InfernoColossusConfig, now: number): ColossusState {
    const existing = this.states.get(enemy.id);
    if (existing && existing.enemy === enemy) return existing;
    const first = now + config.initialDelayMs;
    const published = enemy.getInfernoColossusState();
    const state: ColossusState = {
      enemy, revision: published.revision, phase: Math.max(1, enemy.getBossPhase()), action: null, committed: false,
      wavesFired: 0, heading: enemy.getAimAngle(), flight: null, incendiary: null, gapUntil: first, walkAt: now + config.spawnHoldMs,
      readyAt: { glutstoss: first, incendiary: first, siege: NEVER, flight: NEVER, beetleSalvo: first },
    };
    this.states.set(enemy.id, state);
    return state;
  }

  private step(state: ColossusState, config: InfernoColossusConfig, now: number): void {
    const enemy = state.enemy;
    const phaseTwoDue = state.phase < 2 && enemy.getHp() <= enemy.getMaxHp() * config.phaseTwoHpRatio;
    if (phaseTwoDue && !(state.action?.kind === 'flight' && state.flight?.airborne)) {
      if (state.action) this.cancel(state, now);
      this.startTransition(state, config, now);
    }
    if (state.action && STUN_BREAKS.has(state.action.kind) && !state.committed && this.ports.isStunned(enemy.id, now)) {
      this.cancel(state, now);
      state.gapUntil = now + config.actionGapMs;
      return;
    }
    if (state.action) {
      this.advance(state, config, now);
      return;
    }
    if (now < state.gapUntil || this.ports.isStunned(enemy.id, now) || enemy.isBurrowed()
      || this.ports.isEvadingTrain?.(enemy.id)) return;
    const hunted = this.ports.hunted(enemy);
    const visible = hunted?.visible ? hunted : null;
    const kind = chooseColossusAction({
      phase: state.phase, now, readyAt: state.readyAt,
      threatInGlutstossRadius: now >= state.readyAt.glutstoss && this.ports.hasThreatWithin(enemy, config.glutstoss.triggerRadiusPx),
      huntedDistancePx: visible ? Math.hypot(visible.x - enemy.sprite.x, visible.y - enemy.sprite.y) : null,
      routeUnreachable: hunted?.unreachable ?? false,
      siegeHasTarget: state.phase >= 2 && now >= state.readyAt.siege
        && this.ports.swarmCandidates(enemy, config.siege.rangePx).length > 0,
      salvoHasTarget: now >= state.readyAt.beetleSalvo && pickSalvoTarget(this.ports.swarmCandidates(enemy, config.beetleSalvo.rangePx), 0) !== null,
    }, config);
    if (kind) this.start(state, config, kind, now, false);
  }

  private startTransition(state: ColossusState, config: InfernoColossusConfig, now: number): void {
    const enemy = state.enemy, transition = config.phaseTwo;
    state.phase = 2;
    enemy.setBossPhase(2);
    enemy.setMoveSpeedMultiplier(transition.moveSpeedMultiplier);
    this.reachedPhases.add(2);
    const at = Math.round(now);
    this.publishAction(state, {
      kind: 'transition', startedAt: at, markAt: at + transition.zoneAtMs, releaseAt: at + transition.burstAtMs,
      commitAt: at + transition.burstAtMs, endsAt: at + transition.transitionMs, x: enemy.sprite.x, y: enemy.sprite.y,
      originX: enemy.sprite.x, originY: enemy.sprite.y, radius: transition.burst.radiusPx,
    });
    const after = at + transition.transitionMs;
    state.readyAt.siege = after + config.siege.phaseTwoDelayMs;
    state.readyAt.flight = after + config.stormFlight.phaseTwoDelayMs;
  }

  /** Starts an action at the body; false when it has no valid target or landing. */
  private start(state: ColossusState, config: InfernoColossusConfig, kind: CooldownKind, now: number, forced: boolean): boolean {
    const enemy = state.enemy, at = Math.round(now), x = enemy.sprite.x, y = enemy.sprite.y;
    const base = { startedAt: at, markAt: at, originX: x, originY: y };
    const hunted = this.ports.hunted(enemy);
    switch (kind) {
      case 'glutstoss': {
        const g = config.glutstoss, commitAt = at + g.chargeMs;
        state.readyAt.glutstoss = at + g.cooldownMs;
        this.publishAction(state, { ...base, kind, releaseAt: commitAt, commitAt, endsAt: commitAt + g.recoverMs, x, y, radius: g.burst.radiusPx });
        return true;
      }
      case 'incendiary': {
        if (!hunted && !forced) return false;
        const c = config.incendiary, target = hunted ?? this.pointAhead(enemy, (c.minRangePx + c.maxRangePx) / 2);
        state.heading = Math.atan2(target.y - y, target.x - x);
        const releaseAt = at + c.windupMs;
        state.readyAt.incendiary = at + c.cooldownMs;
        this.publishAction(state, { ...base, kind, releaseAt, commitAt: releaseAt, endsAt: releaseAt + c.recoverMs,
          x: target.x, y: target.y, radius: c.impact.radiusPx });
        // Every shell is announced now at its final point: a zone never moves once its warning runs.
        state.incendiary = this.prepareIncendiary(state, c, target, at, releaseAt);
        return true;
      }
      case 'siege': {
        const s = config.siege;
        state.readyAt.siege = at + s.cooldownMs;
        state.wavesFired = 0;
        const first = at + s.waveAtMs[0], last = at + s.waveAtMs[s.waveAtMs.length - 1];
        this.publishAction(state, { ...base, kind, releaseAt: first, commitAt: last, endsAt: at + s.durationMs, x, y, radius: 0 });
        return true;
      }
      case 'beetleSalvo': {
        const b = config.beetleSalvo, first = at + b.windupMs, last = first + (b.count - 1) * b.intervalMs;
        state.readyAt.beetleSalvo = at + b.cooldownMs;
        state.wavesFired = 0;
        this.publishAction(state, { ...base, kind, releaseAt: first, commitAt: last, endsAt: last + b.recoverMs, x, y, radius: 0 });
        return true;
      }
      case 'flight': {
        const f = config.stormFlight;
        const aim = hunted ?? (forced ? this.pointAhead(enemy, (f.minRangePx + f.maxRangePx) / 3) : null);
        if (!aim) return false;
        const radius = enemy.getCollisionRadius();
        const goal = this.ports.clampToWorld(aim.x, aim.y);
        const landing = findColossusLandingPoint(goal.x, goal.y, CELL_SIZE, f.landingSearchCells,
          (px, py) => this.ports.isFreeGround(px, py, radius));
        if (!landing) { state.readyAt.flight = at + Math.min(f.cooldownMs, 2000); return false; }
        const distance = Math.hypot(landing.x - x, landing.y - y);
        if (distance < radius) return false;
        const releaseAt = at + f.takeoffMs, airMs = Math.round(distance / f.speedPxPerSec * 1000);
        state.heading = Math.atan2(landing.y - y, landing.x - x);
        state.readyAt.flight = at + f.cooldownMs;
        state.flight = { tracker: { lastX: x, lastY: y, lastMovedAt: at, retimedAt: at }, nominalAirMs: airMs,
          airborne: false, chunkX: x, chunkY: y };
        this.publishAction(state, { ...base, kind, releaseAt, commitAt: releaseAt + airMs, endsAt: releaseAt + airMs + f.recoverMs,
          x: landing.x, y: landing.y, radius: f.landing.radiusPx });
        return true;
      }
    }
  }

  private advance(state: ColossusState, config: InfernoColossusConfig, now: number): void {
    const action = state.action!, enemy = state.enemy;
    switch (action.kind) {
      case 'transition':
        if (!state.committed && now >= action.commitAt) {
          state.committed = true;
          this.ports.areaBurst(enemy, enemy.sprite.x, enemy.sprite.y, config.phaseTwo.burst, config.phaseTwo.fireChunks,
            `enemy.${enemy.kind}.phase_shockwave`, 'colossus_awakening', now);
        }
        break;
      case 'glutstoss':
        if (!state.committed && now >= action.commitAt) {
          state.committed = true;
          this.ports.areaBurst(enemy, action.x, action.y, config.glutstoss.burst, config.glutstoss.fireChunks,
            `enemy.${enemy.kind}.glutstoss`, 'colossus_quake', now);
        }
        break;
      case 'incendiary':
        if (!state.committed && now >= action.releaseAt) {
          state.committed = true;
          state.incendiary?.launch();
          state.incendiary = null;
        }
        break;
      case 'siege': {
        const siege = config.siege;
        while (state.wavesFired < siege.waveAtMs.length && now >= action.startedAt + siege.waveAtMs[state.wavesFired]) {
          const candidates = this.ports.swarmCandidates(enemy, siege.rangePx);
          const shots = assignSwarmTargets(enemy.sprite.x, enemy.sprite.y, state.wavesFired, siege.perWave, candidates,
            { perPlayer: siege.perPlayerCap, perStructure: siege.perStructureCap },
            (action.startedAt ^ (state.wavesFired * 0x9e3779b1)) >>> 0, this.ports.clampToWorld);
          this.ports.fireSwarm(enemy, shots, siege, now);
          state.wavesFired++;
        }
        break;
      }
      case 'beetleSalvo': {
        const b = config.beetleSalvo;
        while (state.wavesFired < b.count && now >= action.releaseAt + state.wavesFired * b.intervalMs) {
          const index = state.wavesFired++;
          // Every beetle aims at the players' positions of its own moment, one after the other.
          const target = pickSalvoTarget(this.ports.swarmCandidates(enemy, b.rangePx), index);
          if (!target) continue;
          const random = colossusRandom((action.startedAt ^ (index * 0x9e3779b1)) >>> 0);
          this.ports.fireBeetle(enemy, target, (random() * 2 - 1) * b.spreadDeg * Math.PI / 180, b, now);
        }
        if (state.wavesFired >= b.count) state.committed = true;
        break;
      }
      case 'flight':
        this.advanceFlight(state, config, action, now);
        if (state.action !== action) return;
        break;
    }
    if (now >= action.endsAt) this.finish(state, config, now);
  }

  private advanceFlight(state: ColossusState, config: InfernoColossusConfig, action: InfernoColossusAction, now: number): void {
    const enemy = state.enemy, flight = state.flight, f = config.stormFlight;
    if (!flight || state.committed || now < action.releaseAt) return;
    if (!flight.airborne) {
      flight.airborne = true;
      this.ports.setAirborne(enemy.id, true);
      beginEnemyFlightTracking(flight.tracker, enemy.sprite.x, enemy.sprite.y, now);
    }
    const line = { originX: action.originX, originY: action.originY, targetX: action.x, targetY: action.y,
      takeoffAt: action.releaseAt, landAt: action.commitAt };
    const step = stepEnemyFlight(line, flight.tracker, enemy.sprite.x, enemy.sprite.y, now, flight.nominalAirMs, false);
    if (Math.hypot(enemy.sprite.x - flight.chunkX, enemy.sprite.y - flight.chunkY) >= f.chunkEveryPx) {
      flight.chunkX = enemy.sprite.x; flight.chunkY = enemy.sprite.y;
      this.ports.chunks(enemy, enemy.sprite.x, enemy.sprite.y, f.trailChunks, `colossus-flight:${enemy.id}:${Math.round(now)}`, now);
    }
    if (step.kind === 'air') {
      if (step.retime) this.publishAction(state, { ...action, releaseAt: Math.round(step.retime.takeoffAt),
        commitAt: Math.round(step.retime.landAt), endsAt: Math.round(step.retime.landAt) + f.recoverMs,
        startedAt: Math.min(action.startedAt, Math.round(step.retime.takeoffAt)),
        markAt: Math.min(action.markAt, Math.round(step.retime.takeoffAt)) }, true);
      return;
    }
    flight.airborne = false;
    this.ports.setAirborne(enemy.id, false);
    state.committed = true;
    const at = Math.round(now);
    if (step.kind === 'arrived') {
      this.ports.areaBurst(enemy, enemy.sprite.x, enemy.sprite.y, f.landing, f.landingChunks, `enemy.${enemy.kind}.storm_landing`, 'colossus_quake', now);
      if (Math.abs(at - action.commitAt) > 16) this.publishAction(state, { ...action, commitAt: Math.max(action.releaseAt, at),
        endsAt: Math.max(action.releaseAt, at) + f.recoverMs }, true);
      return;
    }
    // Aborted (wedged or overdue): no landing blast, the zone goes out and the body settles on free ground.
    const radius = enemy.getCollisionRadius();
    if (!this.ports.isFreeGround(enemy.sprite.x, enemy.sprite.y, radius)) {
      const safe = this.ports.findSafeGround(enemy.sprite.x, enemy.sprite.y, radius, f.landingSearchCells + 2);
      if (safe) enemy.setPosition(safe.x, safe.y);
    }
    this.publishAction(state, { ...action, commitAt: Math.max(action.releaseAt, at), endsAt: Math.max(action.releaseAt, at) + f.recoverMs,
      radius: 0 }, true);
  }

  /** The body stands through the windup, so its abdomen at the start is the launch point at release. */
  private prepareIncendiary(state: ColossusState, c: InfernoColossusConfig['incendiary'], target: { readonly x: number; readonly y: number },
    armedAt: number, launchAt: number): IncendiaryWindup | null {
    const enemy = state.enemy;
    const sourceX = enemy.sprite.x - Math.cos(state.heading) * c.sourceBackPx;
    const sourceY = enemy.sprite.y - Math.sin(state.heading) * c.sourceBackPx;
    const count = state.phase >= 2 ? c.phaseTwoCount : 1;
    const shells = incendiaryLandingPoints(sourceX, sourceY, target.x, target.y, count, c.fanSpreadPx).map(point => {
      const clamped = this.ports.clampToWorld(point.x, point.y);
      const distance = Math.hypot(clamped.x - sourceX, clamped.y - sourceY);
      return { x: clamped.x, y: clamped.y, impactAt: launchAt + incendiaryFlightMs(distance, c) };
    });
    return this.ports.prepareIncendiary(enemy, shells, sourceX, sourceY, armedAt, launchAt, c);
  }

  /** Announced, not yet launched Brandsatz shells (replicated with the mortar strikes). */
  getPendingStrikes(): SyncedMortarStrike[] {
    return [...this.states.values()].flatMap(state => state.incendiary?.snapshots.map(strike => ({ ...strike })) ?? []);
  }

  /** Ends the running action without its hit (a phase change, a stun before the commit). */
  private cancel(state: ColossusState, now: number): void {
    const action = state.action;
    if (!action) return;
    if (state.flight?.airborne) this.ports.setAirborne(state.enemy.id, false);
    state.flight = null;
    state.incendiary = null;
    const at = Math.round(now);
    this.publishAction(state, { ...action, commitAt: Math.max(action.releaseAt, Math.min(action.commitAt, at)),
      releaseAt: Math.min(action.releaseAt, at), endsAt: at, radius: 0, markAt: Math.min(action.markAt, at),
      startedAt: Math.min(action.startedAt, at) }, true);
    state.action = null;
  }

  private finish(state: ColossusState, config: InfernoColossusConfig, now: number): void {
    const light = state.action?.kind === 'beetleSalvo';
    state.action = null;
    state.flight = null;
    state.incendiary = null;
    state.committed = false;
    // The light salvo leaves no pause behind: a big action may follow at once.
    state.gapUntil = light ? now : now + config.actionGapMs;
  }

  private pointAhead(enemy: EnemyEntity, distancePx: number): { x: number; y: number } {
    const angle = enemy.getAimAngle();
    return this.ports.clampToWorld(enemy.sprite.x + Math.cos(angle) * distancePx, enemy.sprite.y + Math.sin(angle) * distancePx);
  }

  /** Publishes a new action (or a change of the running one, keeping its progress). */
  private publishAction(state: ColossusState, action: InfernoColossusAction, keepProgress = false): void {
    if (!keepProgress) { state.committed = false; state.wavesFired = 0; if (action.kind !== 'flight') state.flight = null; }
    if (action.kind === 'glutstoss' || action.kind === 'transition') state.heading = state.enemy.getAimAngle();
    state.action = action;
    state.revision = Math.max(state.revision, state.enemy.getInfernoColossusState().revision) + 1;
    state.enemy.applyInfernoColossusState({ revision: state.revision, action });
  }
}
