import * as Phaser from 'phaser';
import { DEPTH_LIGHTING } from '../../config';
import { lightAddBlendMode } from '../../graphics/CustomBlendModes';
import { createColorRenderTexture } from '../../graphics/createColorRenderTexture';
import { runWithScopedBlend } from '../../graphics/PhaserScopedBlend';
import { EnemyMeshGpu } from '../EnemyMeshGpu';
import { ownSunShader, sunShaderName, SunRenderTarget } from '../sunlight/SunRenderTarget';
import { fastLightRate } from './FastLightField';
import { enableHdrShaderTarget, enableHdrTarget } from './LightHdrComposite';

export const LIGHT_VECTOR_HOLD_SHADER = 'LightVectorHold';
/** World pixels per texel: the direction of light turns slowly across the ground. */
const TEXEL_PX = 4;
/**
 * Time over which the direction settles. A bolt flying past turns its direction around within a few frames, and a held
 * trigger would do so with every shot; averaged over this time the shadows of a line of fire point steadily away from it.
 */
export const LIGHT_VECTOR_SETTLE_MS = 90;
/** Frames without a light until what is held has faded away. */
const QUIET_FRAMES = 36;
const CAPACITY = 256;
const ATTRIBUTES = [{ name: 'inCentre', size: 4 }, { name: 'inLight', size: 4 }, { name: 'inCone', size: 2 }];
const INSTANCE_WORDS = 10;

const VERTEX = `
precision highp float;
attribute vec2 inPosition;
// Texel x, y and radius in the field, radius in world px.
attribute vec4 inCentre;
// Weight, height above the ground in px, falloff exponent, 1 for a cone.
attribute vec4 inLight;
// Direction and half angle of a cone.
attribute vec2 inCone;
uniform mat4 uProjectionMatrix;
uniform mat3 uViewMatrix;
varying vec2 local;
varying vec4 light;
varying vec3 cone;
void main() {
 local=inPosition*2.0-1.0;
 vec3 view=uViewMatrix*vec3(inCentre.xy+local*inCentre.z,1.0);
 gl_Position=uProjectionMatrix*vec4(view.xy,0.0,1.0);
 light=inLight;
 cone=vec3(inCone,inCentre.w);
}`;

/** Each light adds its strength times the direction towards it; lights from opposite sides cancel, a light overhead points up. */
const FRAGMENT = `
precision highp float;
varying vec2 local;
varying vec4 light;
varying vec3 cone;
void main() {
 float d=length(local);
 if(d>=1.0)discard;
 float w;
 if(light.w>.5){
  float a=atan(local.y,local.x)-cone.x;
  a=abs(atan(sin(a),cos(a)));
  w=pow(1.0-d,light.z)*clamp((cone.y-a)/(.3*cone.y),0.0,1.0);
 } else w=(1.0-d)*(1.0-d);
 gl_FragColor=vec4(normalize(vec3(-local*cone.z,max(light.y,2.0)))*w*light.x,0.0);
}`;

export const LIGHT_VECTOR_HOLD_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uCurrent,uHeld;
uniform vec2 uTexel,uShift;
uniform float uRate;
void main(){
 vec2 uv=gl_FragCoord.xy*uTexel,from=uv+uShift;
 vec3 now=texture2D(uCurrent,uv).rgb;
 // Ground the camera has just reached has no history.
 bool known=from.x>=0.0&&from.y>=0.0&&from.x<=1.0&&from.y<=1.0;
 gl_FragColor=vec4(known?mix(texture2D(uHeld,from).rgb,now,uRate):now,1.0);
}`;

export interface LightVectorView {
  readonly texture: Phaser.Textures.Texture;
  /** World x, y, width, height the texture covers. */
  readonly frame: Float32Array;
}

/**
 * Where the light on the ground comes from: per texel the sum of every light's strength times the direction towards it,
 * settled over a short time. The ground reads one vector instead of ranking single lights, so no light takes a spot over
 * from another, any number of projectiles count, and moving lights turn the shadows calmly.
 */
export class LightVectorField {
  private readonly width: number;
  private readonly height: number;
  private readonly texelsPerMapTexel: number;
  private readonly renderer: Phaser.Renderer.WebGL.WebGLRenderer;
  private readonly gpu: EnemyMeshGpu;
  private readonly display: Phaser.GameObjects.Shader;
  private readonly blend: number;
  private readonly data = new Float32Array(CAPACITY * INSTANCE_WORDS);
  private readonly frames = [new Float32Array(4), new Float32Array(4)];
  private readonly views: LightVectorView[] = [];
  private readonly texel = new Float32Array(2);
  private readonly shift = new Float32Array(2);
  private current: Phaser.GameObjects.RenderTexture | null = null;
  private held: [SunRenderTarget, SunRenderTarget] | null = null;
  private holdTarget: SunRenderTarget | null = null;
  private unavailable = false;
  private ready = false;
  private count = 0;
  private drawCount = 0;
  private front = 0;
  private rate = 1;
  private quiet = QUIET_FRAMES;
  private lastFrame = -2;
  private readable: LightVectorView | null = null;
  private readonly runHold = (): void => { this.holdTarget?.draw(this.width, this.height); };

  /** `mapWidth`, `mapHeight` in light-map texels; `mapTexelsPerPx` is the light map's scale. */
  constructor(private readonly scene: Phaser.Scene, mapWidth: number, mapHeight: number, mapTexelsPerPx: number) {
    this.texelsPerMapTexel = 1 / (TEXEL_PX * mapTexelsPerPx);
    this.width = Math.max(2, Math.ceil(mapWidth * this.texelsPerMapTexel));
    this.height = Math.max(2, Math.ceil(mapHeight * this.texelsPerMapTexel));
    this.texel[0] = 1 / this.width; this.texel[1] = 1 / this.height;
    const renderer = this.renderer = scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer;
    this.blend = lightAddBlendMode(renderer);
    this.gpu = new EnemyMeshGpu(renderer, sunShaderName('LightVectorStamp'), VERTEX, FRAGMENT, new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]), 2,
      new Uint16Array([0, 1, 2, 0, 2, 3]), ATTRIBUTES, CAPACITY);
    const name = sunShaderName('LightVectorEntry'), owner = this;
    const display = new Phaser.GameObjects.Shader(scene, { name, shaderName: name, fragmentSource: 'precision mediump float;void main(){gl_FragColor=vec4(0.0);}' }, 0, 0, 1, 1);
    ownSunShader(display, name);
    display.renderNode.run = function (context, object, parent): void {
      runWithScopedBlend(this, () => owner.draw(context), context, owner.blend, object, parent);
    };
    this.display = display.setOrigin(0);
  }

  /** The settled vectors of an earlier frame, the latest that are finished when the ground draws; null while nothing shines. */
  get vectors(): LightVectorView | null { return this.readable; }

  /** Starts this frame's lights; false while the field cannot draw. */
  begin(enabled = true): boolean {
    this.count = 0;
    this.ready = enabled && !this.unavailable && this.gpu.prepare();
    return this.ready;
  }

  /** Position and radius in light-map texels; `weight` is the light's luminance at its centre. */
  add(mapX: number, mapY: number, mapRadius: number, radiusPx: number, weight: number, heightPx: number,
    falloffExponent: number, cone: boolean, angle: number, halfAngle: number): void {
    if (!this.ready || this.count >= CAPACITY || weight <= 0) return;
    const at = this.count++ * INSTANCE_WORDS, data = this.data, scale = this.texelsPerMapTexel;
    data[at] = mapX * scale; data[at + 1] = mapY * scale; data[at + 2] = mapRadius * scale; data[at + 3] = radiusPx;
    data[at + 4] = weight; data[at + 5] = heightPx; data[at + 6] = falloffExponent; data[at + 7] = cone ? 1 : 0;
    data[at + 8] = angle; data[at + 9] = halfAngle;
  }

  /** Draws this frame's lights and settles them into what is held. The rectangle is the light map's, in world px. */
  finish(worldX: number, worldY: number, worldWidth: number, worldHeight: number, deltaMs: number): void {
    const frame = this.scene.game.loop.frame, resumed = frame - this.lastFrame > 1;
    this.lastFrame = frame;
    this.quiet = this.count > 0 ? 0 : Math.min(QUIET_FRAMES, this.quiet + 1);
    if (!this.ready || resumed && this.count === 0 || this.quiet >= QUIET_FRAMES) {
      this.readable = null; this.holdTarget = null; this.quiet = QUIET_FRAMES; return;
    }
    const current = this.ensureCurrent();
    if (!current || !this.ensureHeld()) { this.unavailable = true; this.readable = null; return; }
    const held = this.held!, from = held[this.front], to = held[1 - this.front];
    const last = this.frames[this.front], next = this.frames[1 - this.front];
    // History is only worth anything from the frame before; after a pause it would blend in lights long gone.
    const fresh = resumed || this.readable === null && this.holdTarget === null;
    this.readable = fresh ? null : this.views[this.front];
    next[0] = worldX; next[1] = worldY; next[2] = worldWidth; next[3] = worldHeight;
    this.shift[0] = fresh ? 0 : (worldX - last[0]) / worldWidth;
    this.shift[1] = fresh ? 0 : -(worldY - last[1]) / worldHeight;
    this.rate = fresh ? 1 : fastLightRate(deltaMs, LIGHT_VECTOR_SETTLE_MS);
    // The add mode leaves alpha alone, and a float target must stay opaque.
    current.clear().fill(0, 1);
    this.drawCount = this.count;
    if (this.count > 0) {
      this.display.setPosition(0, 0).setSize(current.width, current.height);
      current.draw(this.display);
    }
    to.shader.setTextures([current.texture, from.shader.texture!]);
    this.holdTarget = to;
    (current.texture as Phaser.Textures.DynamicTexture).callback(this.runHold);
    this.front = 1 - this.front;
  }

  destroy(): void {
    this.current?.destroy(); this.current = null;
    for (const target of this.held ?? []) target.destroy();
    this.held = null; this.holdTarget = null; this.readable = null;
    this.display.destroy();
    this.gpu.destroy();
  }

  private draw(context: Phaser.Renderer.WebGL.DrawingContext): void {
    if (!this.drawCount) return;
    const camera = context.camera!.getViewMatrix(!context.useCanvas);
    this.renderer.setProjectionMatrixFromDrawingContext(context);
    this.gpu.draw(context, this.data.subarray(0, this.drawCount * INSTANCE_WORDS), this.drawCount, [], set => {
      set('uProjectionMatrix', this.renderer.projectionMatrix.val);
      set('uViewMatrix', [camera.a, camera.b, 0, camera.c, camera.d, 0, camera.tx, camera.ty, 1]);
    });
  }

  private ensureCurrent(): Phaser.GameObjects.RenderTexture | null {
    if (this.current) return this.current;
    const target = createColorRenderTexture(this.scene, this.width, this.height);
    // Beside the fast lights' field: drawn before the light map, read by the ground in the frame after.
    target.setOrigin(0).setScrollFactor(0).setDepth(DEPTH_LIGHTING - 0.025).setRenderMode('redraw');
    target.texture.setFilter(Phaser.Textures.FilterMode.LINEAR);
    if (!enableHdrTarget(this.renderer, target.texture as Phaser.Textures.DynamicTexture)) { target.destroy(); return null; }
    return this.current = target;
  }

  private ensureHeld(): boolean {
    if (this.held) return true;
    const make = (): SunRenderTarget => {
      const target = new SunRenderTarget(this.scene, 'LightVectorHold', LIGHT_VECTOR_HOLD_FRAGMENT, set => {
        set('uCurrent', 0); set('uHeld', 1); set('uTexel', this.texel); set('uShift', this.shift); set('uRate', this.rate);
      }, ['__WHITE', '__WHITE'], LIGHT_VECTOR_HOLD_SHADER);
      target.draw(this.width, this.height);
      return target;
    };
    const first = make(), second = make();
    if (!enableHdrShaderTarget(this.scene, first) || !enableHdrShaderTarget(this.scene, second)) { first.destroy(); second.destroy(); return false; }
    this.held = [first, second];
    this.views[0] = { texture: first.shader.texture!, frame: this.frames[0] };
    this.views[1] = { texture: second.shader.texture!, frame: this.frames[1] };
    return true;
  }
}
