import * as Phaser from 'phaser';
import { DEPTH_LIGHTING } from '../../config';
import type { LightMapBinding } from '../lighting2/LightMapBinding';
import { ownSunShader } from '../sunlight/SunRenderTarget';
import { VOID_FOG_HUE } from './fogShaders';

export const FOG_LIGHT_SCATTER_SHADER = 'GroundFog_lightScatter';
const SHARP_SHARE = 0.4;
/** How strongly fog answers light; the shoulder keeps a blast from turning the fog white. */
const SCATTER_GAIN = 2.5;
const SCATTER_STRENGTH = 0.85;
/** Light excess that starts to show in the air, and from where it shows fully. */
const FAINT_LIGHT = 0.04;
const CLEAR_LIGHT = 0.32;
const WISP_CONTRAST = 1.35;
/** Void haze catches light that plain fog ignores, from further away, and answers in its own violet. */
const VOID_FAINT_LIGHT = 0.008;
const VOID_CLEAR_LIGHT = 0.14;
const VOID_GAIN = 2.1;
/** Void haze glows faintly of its own at night, so a danger zone reads even with no light near it. */
const VOID_SELF_GLOW = 0.15;

export const FOG_LIGHT_SCATTER_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
varying vec2 outTexCoord;
uniform sampler2D uMaterial,uTrails,uSurfaces,uLightMap,uAmbientLayer,uWideLight,uFarLight;
uniform float uHasTrails,uHasRockCoverage,uAmbientLayerOn,uAmbientLayerWeight,uHasSoftLight,uVoidInMaterial;
uniform vec3 uAmbient;
// World rectangle of the fog's material and of the light map.
uniform vec4 uFogView,uLightFrame;
vec2 lightUv(vec2 world) {
 vec2 uv=(world-uLightFrame.xy)/uLightFrame.zw;
 return vec2(uv.x,1.0-uv.y);
}
vec3 lightAbove(vec2 world) {
 vec2 uv=lightUv(world);
 vec3 floorLight=uAmbient;
 if(uAmbientLayerOn>.5)floorLight+=texture2D(uAmbientLayer,uv).rgb*uAmbientLayerWeight;
 return max(texture2D(uLightMap,uv).rgb-floorLight,vec3(0.0));
}
void main() {
 float trace=uHasTrails>.5?texture2D(uTrails,outTexCoord).r:0.0;
 vec4 material=texture2D(uMaterial,outTexCoord);
 float fog=material.a*(1.0-trace);
 // Shaped fog keeps the void's share in its red channel.
 float voidShare=uVoidInMaterial>.5?clamp(material.r/max(.0001,material.a),0.0,1.0):0.0;
 if(uHasRockCoverage>.5)fog*=1.0-smoothstep(.25,.75,texture2D(uSurfaces,outTexCoord).r);
 if(fog<.004)discard;
 vec2 world=uFogView.xy+vec2(outTexCoord.x,1.0-outTexCoord.y)*uFogView.zw;
 // Sharp enough to carry the light's cone and shadows, wide enough to read as lit air rather than a lit floor.
 vec3 light=lightAbove(world)*${SHARP_SHARE.toFixed(2)};
 // Already blurred: sparse taps over the sharp map draw a beam's edge several times, and turning them leaves a pattern.
 vec3 wide=uHasSoftLight>.5?mix(texture2D(uWideLight,lightUv(world)).rgb,texture2D(uFarLight,lightUv(world)).rgb,voidShare):lightAbove(world);
 light+=wide*${(1 - SHARP_SHARE).toFixed(2)};
 float peak=max(light.r,max(light.g,light.b));
 // Faint spill stays out of the air, so the night around a light keeps its darkness.
 vec3 lit=peak>0.0?light/peak*(1.0-exp(-peak*${SCATTER_GAIN.toFixed(2)}))*smoothstep(mix(${FAINT_LIGHT.toFixed(2)},${VOID_FAINT_LIGHT.toFixed(3)},voidShare),mix(${CLEAR_LIGHT.toFixed(2)},${VOID_CLEAR_LIGHT.toFixed(2)},voidShare),peak):vec3(0.0);
 if(voidShare>0.0)lit=mix(lit,dot(lit,vec3(.2126,.7152,.0722))*vec3(${VOID_FOG_HUE})*${VOID_GAIN.toFixed(2)},voidShare)+vec3(${VOID_FOG_HUE})*${VOID_SELF_GLOW.toFixed(2)}*voidShare;
 // Thin fog catches disproportionately little, which also brings out the wisps inside a beam.
 // Bright air around a dim scene already carries the fog's own colour; added light there only washes the picture out.
 float daylight=max(uAmbient.r,max(uAmbient.g,uAmbient.b));
 gl_FragColor=vec4(lit*pow(fog,${WISP_CONTRAST.toFixed(2)})*${SCATTER_STRENGTH.toFixed(2)}*(1.0-.8*smoothstep(.12,.55,daylight)),1.0);
}
`;

/** Light caught in the fog: drawn over the lit World from the fog's own density and the shadowed light map. */
export class FogLightScatter {
  private readonly quad: Phaser.GameObjects.Shader;
  private readonly view = new Float32Array(4);
  private binding: LightMapBinding | null = null;
  private hasTrails = false;
  private hasRockCoverage = false;
  private voidInMaterial = false;
  private shownFrame = -1;

  constructor(private readonly scene: Phaser.Scene) {
    const quad = new Phaser.GameObjects.Shader(scene, {
      name: FOG_LIGHT_SCATTER_SHADER, shaderName: FOG_LIGHT_SCATTER_SHADER, fragmentSource: FOG_LIGHT_SCATTER_FRAGMENT,
      setupUniforms: (set: (name: string, value: unknown) => void) => {
        const binding = this.binding;
        set('uMaterial', 0); set('uTrails', 1); set('uSurfaces', 2); set('uLightMap', 3); set('uAmbientLayer', 4); set('uWideLight', 5); set('uFarLight', 6);
        set('uHasSoftLight', binding?.softLight ? 1 : 0);
        set('uVoidInMaterial', this.voidInMaterial ? 1 : 0);
        set('uHasTrails', this.hasTrails ? 1 : 0); set('uHasRockCoverage', this.hasRockCoverage ? 1 : 0);
        set('uAmbientLayerOn', binding?.ambientLayer ? 1 : 0); set('uAmbientLayerWeight', binding?.ambientLayerWeight ?? 0);
        set('uAmbient', binding?.ambient ?? [0, 0, 0]);
        set('uFogView', this.view); set('uLightFrame', binding?.frame ?? this.view);
      },
    }, 0, 0, 2, 2, Array(7).fill('__DEFAULT'));
    ownSunShader(quad, FOG_LIGHT_SCATTER_SHADER, true);
    // The textures are borrowed for one frame. A teardown between two frames can free them while the quad is still listed.
    const node = quad.renderNode, run = node.run, owner = this;
    node.run = function (context, object, parent): void {
      if (owner.shownFrame === scene.game.loop.frame) run.call(this, context, object, parent);
    };
    this.quad = scene.add.existing(quad).setOrigin(0).setDepth(DEPTH_LIGHTING + 0.002).setBlendMode(Phaser.BlendModes.SCREEN).setVisible(false);
  }

  /** `material`, `trails`, `surfaces` are the fog display's own inputs of this frame. */
  show(binding: LightMapBinding, voidInMaterial: boolean, x: number, y: number, width: number, height: number, material: Phaser.Textures.Texture,
    trails: Phaser.Textures.Texture | null, surfaces: Phaser.Textures.Texture | null): void {
    const fallback = material;
    this.binding = binding;
    this.voidInMaterial = voidInMaterial;
    this.shownFrame = this.scene.game.loop.frame;
    this.hasTrails = trails !== null; this.hasRockCoverage = surfaces !== null;
    this.view[0] = x; this.view[1] = y; this.view[2] = width; this.view[3] = height;
    this.quad.setTextures([material, trails ?? fallback, surfaces ?? fallback, binding.texture, binding.ambientLayer ?? binding.texture,
      binding.softLight?.wide ?? binding.texture, binding.softLight?.far ?? binding.texture]);
    this.quad.setPosition(x, y).setDisplaySize(width, height).setVisible(true);
  }

  hide(): void { this.quad.setVisible(false); this.binding = null; }
  destroy(): void { this.quad.destroy(); this.binding = null; }
}
