/**
 * Host-Übergabe über ein Neuladen hinweg.
 *
 * Verlässt der Host den Raum, bleibt die Gruppe zusammen: Jeder Gast schreibt ein Ticket in den
 * sessionStorage (er übersteht das Neuladen im Browser wie in der Desktop-App) und lädt neu. Der
 * neue Start liest es genau einmal (`PlatformSessions.pendingStart`) und setzt den Raum beim
 * Nachfolger fort. Es wird kein Spielzustand migriert: Nur die Raumeinstellungen reisen mit, eine
 * laufende Runde endet ohne Wertung.
 *
 * Ebenso einmalig trägt ein Raum-Hinweis die Erklärung für das Banner nach dem Neuladen.
 */
import { ROOM_HANDOVER_TICKET_TTL_MS } from '../config';
import { parseCoopProgram, type CoopProgram } from '../dawn/contracts/CoopProgram';
import type { GameMode, RoomVisibility } from '../types';
import type { PeerFailureKind } from './peer/PeerNetworkError';
import { isValidRoomCode } from './peer/roomCode';
import { isRoomVisibility } from './RoomVisibility';

const TICKET_STORAGE_KEY = 'fragdachse:room-handover';
const NOTICE_STORAGE_KEY = 'fragdachse:room-notice';
const GAME_MODES: readonly GameMode[] = ['deathmatch', 'team_deathmatch', 'capture_the_beer', 'coop_defense'];

/** Lobby-Einstellungen des alten Raums; der Nachfolger übernimmt, was er selbst anbieten darf. */
export interface RoomHandoverSettings {
  readonly mode: GameMode;
  readonly coopMapId: string;
  readonly coopProgram: CoopProgram;
  readonly timeOfDayMinutes: number;
  readonly visibility: RoomVisibility;
}

export interface RoomHandoverTicket {
  readonly v: 1;
  /** Zeitpunkt des Host-Verlusts (Epoch-ms); Fristen der Übergabe zählen ab hier. */
  readonly createdAt: number;
  /** Raumcode, unter dem der Raum beim Nachfolger weiterläuft. */
  readonly roomCode: string;
  readonly previousRoomCode: string;
  /** Der Host hat diesen Spieler als Nachfolger bestimmt (Steam entscheidet selbst über die Owner-Wahl). */
  readonly successor: boolean;
  readonly previousHostName: string | null;
  readonly successorName: string | null;
  readonly settings: RoomHandoverSettings | null;
  /** Undurchsichtige Daten der Plattform, z. B. die gehaltene Steam-Lobby. */
  readonly platform: string | null;
}

export type RoomNoticeKind =
  /** Der Host ging, die Gruppe ist beim Nachfolger. */
  | 'handover'
  /** Der Host ging, die Übergabe kam nicht zustande: eigener Raum. */
  | 'handover-failed'
  /** Ein Beitritt scheiterte: eigener Raum. */
  | 'join-failed'
  | 'kicked'
  /** Der Raum endete ohne Nachfolge (z. B. der eigene Raum fiel aus): eigener Raum. */
  | 'room-lost';

export interface RoomNotice {
  readonly kind: RoomNoticeKind;
  readonly previousHostName?: string | null;
  readonly successorName?: string | null;
  readonly failure?: PeerFailureKind | null;
}

function readStorage(key: string): string | null {
  try {
    return window.sessionStorage.getItem(key);
  } catch {
    return null;
  }
}

function writeStorage(key: string, value: string | null): void {
  try {
    if (value === null) window.sessionStorage.removeItem(key);
    else window.sessionStorage.setItem(key, value);
  } catch {
    // Ohne Speicher landet jeder nach dem Neuladen im eigenen Raum – kein Absturz.
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function optionalName(value: unknown): string | null {
  return typeof value === 'string' && value.length > 0 ? value.slice(0, 64) : null;
}

export function parseRoomHandoverSettings(raw: unknown): RoomHandoverSettings | null {
  if (!isRecord(raw)) return null;
  const mode = GAME_MODES.find(candidate => candidate === raw.mode);
  const coopProgram = parseCoopProgram(raw.coopProgram);
  if (!mode || !coopProgram || typeof raw.coopMapId !== 'string' || raw.coopMapId.length === 0
    || typeof raw.timeOfDayMinutes !== 'number' || !Number.isFinite(raw.timeOfDayMinutes)
    || !isRoomVisibility(raw.visibility)) return null;
  return {
    mode,
    coopMapId: raw.coopMapId,
    coopProgram,
    timeOfDayMinutes: raw.timeOfDayMinutes,
    visibility: raw.visibility,
  };
}

export function parseRoomHandoverTicket(raw: unknown): RoomHandoverTicket | null {
  if (!isRecord(raw) || raw.v !== 1) return null;
  if (typeof raw.createdAt !== 'number' || !Number.isFinite(raw.createdAt)) return null;
  if (typeof raw.roomCode !== 'string' || !isValidRoomCode(raw.roomCode)) return null;
  if (typeof raw.previousRoomCode !== 'string' || typeof raw.successor !== 'boolean') return null;
  return {
    v: 1,
    createdAt: raw.createdAt,
    roomCode: raw.roomCode.toUpperCase(),
    previousRoomCode: raw.previousRoomCode,
    successor: raw.successor,
    previousHostName: optionalName(raw.previousHostName),
    successorName: optionalName(raw.successorName),
    settings: parseRoomHandoverSettings(raw.settings),
    platform: typeof raw.platform === 'string' ? raw.platform : null,
  };
}

export function writeRoomHandoverTicket(ticket: RoomHandoverTicket): void {
  writeStorage(TICKET_STORAGE_KEY, JSON.stringify(ticket));
}

/** Liest das Ticket genau einmal; ein abgelaufenes oder beschädigtes gilt als keines. */
export function takeRoomHandoverTicket(now = Date.now()): RoomHandoverTicket | null {
  const raw = readStorage(TICKET_STORAGE_KEY);
  if (raw === null) return null;
  writeStorage(TICKET_STORAGE_KEY, null);
  let ticket: RoomHandoverTicket | null;
  try {
    ticket = parseRoomHandoverTicket(JSON.parse(raw));
  } catch {
    return null;
  }
  if (!ticket || now < ticket.createdAt - 5_000 || now - ticket.createdAt > ROOM_HANDOVER_TICKET_TTL_MS) return null;
  return ticket;
}

export function writeRoomNotice(notice: RoomNotice): void {
  writeStorage(NOTICE_STORAGE_KEY, JSON.stringify(notice));
}

const NOTICE_KINDS: readonly RoomNoticeKind[] = ['handover', 'handover-failed', 'join-failed', 'kicked', 'room-lost'];

/** Liest den Hinweis für das Banner nach dem Neuladen genau einmal. */
export function takeRoomNotice(): RoomNotice | null {
  const raw = readStorage(NOTICE_STORAGE_KEY);
  if (raw === null) return null;
  writeStorage(NOTICE_STORAGE_KEY, null);
  try {
    const value: unknown = JSON.parse(raw);
    if (!isRecord(value)) return null;
    const kind = NOTICE_KINDS.find(candidate => candidate === value.kind);
    if (!kind) return null;
    return {
      kind,
      previousHostName: optionalName(value.previousHostName),
      successorName: optionalName(value.successorName),
      failure: typeof value.failure === 'string' ? value.failure as PeerFailureKind : null,
    };
  } catch {
    return null;
  }
}

export interface RetryUntilOptions {
  /** Epoch-ms; nach dieser Zeit wird kein neuer Versuch mehr gestartet. */
  readonly deadline: number;
  readonly isRetryable: (error: unknown) => boolean;
  readonly firstDelayMs?: number;
  readonly maxDelayMs?: number;
  readonly now?: () => number;
  readonly sleep?: (ms: number) => Promise<void>;
}

/** Wiederholt `attempt` mit wachsendem Abstand, bis es gelingt, ein Fehler endgültig ist oder die Frist abläuft. */
export async function retryUntil<T>(attempt: () => Promise<T>, options: RetryUntilOptions): Promise<T> {
  const now = options.now ?? Date.now;
  const sleep = options.sleep ?? (ms => new Promise<void>(resolve => setTimeout(resolve, ms)));
  const maxDelayMs = options.maxDelayMs ?? 2_000;
  let delayMs = options.firstDelayMs ?? 500;
  for (;;) {
    try {
      return await attempt();
    } catch (error) {
      if (!options.isRetryable(error)) throw error;
      const remaining = options.deadline - now();
      if (remaining <= 0) throw error;
      await sleep(Math.min(delayMs, remaining));
      if (options.deadline - now() <= 0) throw error;
      delayMs = Math.min(delayMs * 2, maxDelayMs);
    }
  }
}
