import type * as Phaser from 'phaser';
import { CELL_SIZE } from '../../config';
import { resolveCoopDefenseMapMissionProgress, type CoopDefenseMapConfig } from '../../config/coopDefenseMaps';
import { ArenaVisualFactory } from '../../arena/ArenaVisualFactory';
import { ArenaCellBucketIndex } from '../../arena/chunks/ArenaCellBucketIndex';
import { ARENA_RENDER_CHUNK_SIZE, type ChunkWorldFrame } from '../../arena/chunks/ArenaChunkGrid';
import { CHUNK_SAMPLING_GUTTER_PX } from '../../arena/chunks/ChunkedRenderSurface';
import { soilReachesRegion } from '../../arena/chunks/GroundSurfaceStreamer';
import { DirtSurfaceLayer } from '../../arena/DirtSurfaceLayer';
import { readGroundMaterialSamples } from '../../arena/GroundMaterialSamples';
import { ROCK_OVERLAY_CHUNK_SIZE } from '../../arena/RockOverlayRegions';
import { getTerrainSnapshotRegions, TERRAIN_SNAPSHOT_STAGING_SIZE } from '../../arena/TerrainColorSnapshotBuilder';
import type { TerrainSnapshotMaterialSource } from '../../arena/TerrainSnapshotMaterial';
import { compactSnapshotSamples } from '../../arena/TerrainSnapshotSampling';
import { TERRAIN_MATERIAL_WORKERS, TerrainSnapshotWorkerClient } from '../../arena/TerrainSnapshotWorkerClient';
import { TrackGravelLayer } from '../../arena/TrackGravelLayer';
import { createWaterMaskJob, waterMaskKey } from '../../arena/WaterMaskJob';
import { createWaterMaskWorker, type WaterMaskWorkerClient } from '../../arena/WaterMaskWorkerClient';
import { snapshotTileKey, soilTileKey, WorldPrebake } from '../../arena/prebake/WorldPrebake';
import type { ArenaLayout, GameMode } from '../../types';
import { resolveRoundWorldMetrics } from '../../world/RoundWorldLayout';

/** Soil tiles around the expected start, nearest first (132² RGBA each, ~68 KiB). */
const SOIL_TILE_BUDGET = 960;
/** Terrain-snapshot tiles, kept as their sample texels (1 MiB each at the 1024 px staging size). */
const SNAPSHOT_TILE_BUDGET = 64;
/** The start view at zoom 1 plus the residency prefetch fits inside this radius, also when the camera
 * starts at a base rather than the mission's start area. */
const SOIL_RADIUS_PX = 2560;
/** Tiles each worker holds: the next one is computed while the main thread files the last. */
const TILES_PER_WORKER = 2;

/** What the lobby announces for the next round, with the layout the round start will reuse. */
export interface DeploymentPrebakeRequest {
  readonly gameMode: GameMode;
  readonly mapConfig: CoopDefenseMapConfig | null;
  readonly layout: ArenaLayout;
}

interface TileJob {
  readonly key: string;
  readonly kind: 'soil' | 'snapshot';
  readonly source: TerrainSnapshotMaterialSource;
  readonly side: number;
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

interface TileLane { readonly client: TerrainSnapshotWorkerClient; readonly jobs: TileJob[] }

/**
 * Computes the CPU part of a deployment's World build in the lobby (Steam plan L14): water masks, the
 * soil tiles around the expected start and the terrain-snapshot material, with the very worker jobs
 * the World build runs. Owned by `ArenaDeploymentTerrain`, one run per announced layout.
 */
export class DeploymentPrebaker {
  constructor(private readonly scene: Phaser.Scene) {}

  start(request: DeploymentPrebakeRequest): WorldPrebake {
    const metrics = resolveRoundWorldMetrics(request.gameMode, request.mapConfig);
    const frame: ChunkWorldFrame = { offsetX: metrics.offsetX, offsetY: metrics.offsetY, width: metrics.widthPx, height: metrics.heightPx };
    const prebake = new WorldPrebake(frame);
    // Headless runtimes and tests have no module workers; the World computes everything itself.
    if (typeof Worker === 'undefined') return prebake;
    const run = new PrebakeRun(prebake, frame, request, this.scene);
    prebake.addPump(() => run.pump());
    prebake.addDisposer(() => run.dispose());
    run.pump();
    return prebake;
  }
}

class PrebakeRun {
  private water: WaterMaskWorkerClient | null = null;
  private waterPending = 0;
  private readonly queue: TileJob[];
  private next = 0;
  private readonly lanes: TileLane[] = [];

  constructor(private readonly prebake: WorldPrebake, private readonly frame: ChunkWorldFrame,
    request: DeploymentPrebakeRequest, scene: Phaser.Scene) {
    const { layout } = request;
    const water = layout.water ?? [], dirt = layout.dirt ?? [];
    const waterJob = createWaterMaskJob(water, frame.width, frame.height, ARENA_RENDER_CHUNK_SIZE);
    if (waterJob.origins.length) {
      this.water = createWaterMaskWorker(waterJob);
      this.waterPending = this.water ? waterJob.origins.length : 0;
    }
    const materials = readGroundMaterialSamples(scene);
    const tracks = ArenaVisualFactory.getTrackColumnSpecs(layout.tracks ?? [], frame);
    // The sources the ground streamer builds for this layout: soil with dirt or water, ballast with tracks.
    const soil = dirt.length || water.length ? DirtSurfaceLayer.source(layout.seed, dirt, frame, materials, water, tracks) : null;
    const track = tracks.length ? TrackGravelLayer.source(layout.seed, tracks, frame, materials) : null;
    this.queue = [
      ...(soil ? this.soilJobs(soil, dirt, water, focusOf(request, frame)) : []),
      ...this.snapshotJobs([soil, track].filter((source): source is TerrainSnapshotMaterialSource => source !== null)),
    ];
  }

  /** Files arrived results, then hands the next jobs to idle workers unless a World build began. */
  pump(): void {
    this.collectWater();
    for (const lane of this.lanes) {
      for (let buffer = lane.client.take(); buffer; buffer = lane.client.take()) this.file(lane.jobs.shift()!, buffer);
    }
    if (this.prebake.sealed) { this.releaseIdleLanes(); return; }
    while (this.next < this.queue.length) {
      const lane = this.idleLane();
      if (!lane) break;
      const job = this.queue[this.next++];
      lane.jobs.push(job);
      lane.client.request(job.source, job.side, job.x, job.y, job.width, job.height,
        new ArrayBuffer(job.side * job.side * 4), job.kind === 'soil');
    }
    if (this.next >= this.queue.length) this.releaseIdleLanes();
    if (!this.water && this.next >= this.queue.length && !this.lanes.length) this.prebake.markComplete();
  }

  dispose(): void {
    this.water?.destroy(); this.water = null;
    for (const lane of this.lanes) lane.client.destroy();
    this.lanes.length = 0;
  }

  private collectWater(): void {
    if (!this.water) return;
    try {
      for (const { x, y, size, data } of this.water.take()) {
        this.prebake.waterMasks.set(waterMaskKey(x, y, ARENA_RENDER_CHUNK_SIZE), { size, data: new Uint8ClampedArray(data) });
        this.waterPending--;
      }
    } catch (error) {
      // The World bakes whatever is missing itself.
      console.warn('[DeploymentPrebake] Water masks failed; the World bakes them.', error);
      this.waterPending = 0;
    }
    if (this.waterPending <= 0) { this.water.destroy(); this.water = null; }
  }

  private file(job: TileJob, buffer: ArrayBuffer): void {
    if (job.kind === 'soil') this.prebake.soilTiles.set(job.key, new Uint8ClampedArray(buffer));
    else this.prebake.snapshotTiles.set(job.key, compactSnapshotSamples(new Uint8Array(buffer), job.side));
  }

  private idleLane(): TileLane | null {
    const idle = this.lanes.find(lane => lane.client.canRequest());
    if (idle || this.lanes.length >= TERRAIN_MATERIAL_WORKERS) return idle ?? null;
    const lane = { client: new TerrainSnapshotWorkerClient(undefined, TILES_PER_WORKER), jobs: [] };
    this.lanes.push(lane);
    return lane;
  }

  /** Workers with nothing left to do end; a lane that still computes ends after its results arrive. */
  private releaseIdleLanes(): void {
    for (let i = this.lanes.length - 1; i >= 0; i--) {
      if (this.lanes[i].jobs.length) continue;
      this.lanes[i].client.destroy();
      this.lanes.splice(i, 1);
    }
  }

  /** The ground streamer's soil tiles of the 128 px regions around `focus`, nearest first. */
  private soilJobs(source: TerrainSnapshotMaterialSource, dirt: ArenaLayout['dirt'], water: ArenaLayout['water'],
    focus: { x: number; y: number }): TileJob[] {
    const dirtIndex = new ArenaCellBucketIndex(this.frame.width), waterIndex = new ArenaCellBucketIndex(this.frame.width);
    dirtIndex.sync(dirt ?? []); waterIndex.sync(water ?? []);
    const scratch: number[] = [], region = ROCK_OVERLAY_CHUNK_SIZE, gutter = CHUNK_SAMPLING_GUTTER_PX;
    const extentX = Math.ceil(this.frame.width / ARENA_RENDER_CHUNK_SIZE) * ARENA_RENDER_CHUNK_SIZE;
    const extentY = Math.ceil(this.frame.height / ARENA_RENDER_CHUNK_SIZE) * ARENA_RENDER_CHUNK_SIZE;
    const candidates: { localX: number; localY: number; distance: number }[] = [];
    for (let localY = 0; localY < extentY; localY += region) for (let localX = 0; localX < extentX; localX += region) {
      const distance = Math.hypot(localX + region / 2 - focus.x, localY + region / 2 - focus.y);
      if (distance <= SOIL_RADIUS_PX) candidates.push({ localX, localY, distance });
    }
    candidates.sort((a, b) => a.distance - b.distance);
    const jobs: TileJob[] = [];
    for (const { localX, localY } of candidates) {
      if (jobs.length >= SOIL_TILE_BUDGET) break;
      // Prepared exactly where the ground streamer asks: the region plus its sampling gutter.
      const x = this.frame.offsetX + localX - gutter, y = this.frame.offsetY + localY - gutter, side = region + gutter * 2;
      if (!soilReachesRegion(dirtIndex, waterIndex, localX - gutter, localY - gutter, side, scratch)) continue;
      jobs.push({ key: soilTileKey(x, y, side), kind: 'soil', source, side, x, y, width: side, height: side });
    }
    return jobs;
  }

  /** Every staging tile of the terrain snapshot, in the snapshot's own region order. */
  private snapshotJobs(sources: readonly TerrainSnapshotMaterialSource[]): TileJob[] {
    const side = TERRAIN_SNAPSHOT_STAGING_SIZE, jobs: TileJob[] = [];
    for (const region of getTerrainSnapshotRegions(this.frame.width, this.frame.height, this.frame.offsetX, this.frame.offsetY)) {
      for (const source of sources) {
        for (let y = 0; y < region.height; y += side) for (let x = 0; x < region.width; x += side) {
          if (jobs.length >= SNAPSHOT_TILE_BUDGET) return jobs;
          const width = Math.min(side, region.width - x), height = Math.min(side, region.height - y);
          const worldX = region.worldX + x, worldY = region.worldY + y;
          jobs.push({ key: snapshotTileKey(source, worldX, worldY, width, height, side), kind: 'snapshot', source, side,
            x: worldX, y: worldY, width, height });
        }
      }
    }
    return jobs;
  }
}

/** Where the start view is expected, frame-local: the mission's start area, else the map centre. */
function focusOf(request: DeploymentPrebakeRequest, frame: ChunkWorldFrame): { x: number; y: number } {
  const start = request.mapConfig ? resolveCoopDefenseMapMissionProgress(request.mapConfig)?.startArea : undefined;
  return start
    ? { x: (start.gridX + .5) * CELL_SIZE, y: (start.gridY + .5) * CELL_SIZE }
    : { x: frame.width / 2, y: frame.height / 2 };
}
