import type * as Phaser from 'phaser';
import { runtimeAssetUrl } from '../assets/RuntimeAssetUrls';

/** The height layer stores this range in 8 bits. */
export const GROUND_HEIGHT_RANGE_PX = 24;
/** Open ground lies at this height, so that soil can sink below it. */
export const GROUND_HEIGHT_LEVEL_PX = 4;

/** Height image beside a colour atlas page, same layout. Written by scripts/asset-pipeline/ground_height_atlas.py. */
export const GROUND_HEIGHT_PAGES: Readonly<Record<string, { readonly key: string; readonly file: string }>> = {
  atlas_groundcover_1: { key: 'ground_height_cover', file: 'assets/atlases/groundcover-1-height.png' },
  atlas_decals_0: { key: 'ground_height_decals', file: 'assets/atlases/decals-0-height.png' },
  'woodland-ground-litter': { key: 'ground_height_litter', file: 'assets/atlases/ground-litter-atlas-height.png' },
  'woodland-shore-stones': { key: 'ground_height_shore', file: 'assets/atlases/shore-stones-atlas-height.png' },
};

/** Height of an object as a share of its stamped size, at least the given px: a stick is as high as it is thick, however long it is. Everything else is flat. */
const HEIGHT_SHARES: readonly (readonly [string, number, number?])[] = [
  ['forest_fern', 0.29], ['forest_plant', 0.27], ['forest_grass', 0.22], ['forest_flowers', 0.2], ['forest_small', 0.2],
  ['forest_stone', 0.5], ['forest_twig', 0.12, 6], ['forest_leaf', 0.07, 1.5], ['ground_cover_', 0.18],
  ['Kiesel', 0.45], ['busch', 0.5], ['flower', 0.4], ['grass', 0.4], ['pilz', 0.5],
  ['decal03', 0.3], ['decal04', 0.3], ['decal05', 0.5], ['decal06', 0.2], ['decal07', 0.4],
  ['dirt_brown_clod', 0.3], ['dirt_brown_crumb', 0.2], ['dirt_brown_pebble', 0.35], ['dirt_rock_earth_chip', 0.3],
  ['twigs', 0.1, 6], ['leaf-litter', 0.06, 2], ['needle-litter', 0.06, 2.5], ['pebbles', 0.2, 5], ['bank', 0.22, 6], ['shoal', 0.16, 5], ['scree', 0.1, 3],
];
export const MAX_OBJECT_HEIGHT_PX = 18;

export function groundObjectHeightPx(textureId: string, sizePx: number): number {
  for (const [prefix, share, least = 0] of HEIGHT_SHARES) if (textureId.startsWith(prefix)) return Math.min(MAX_OBJECT_HEIGHT_PX, Math.max(least, sizePx * share));
  return 0;
}

export function preloadGroundHeight(load: Phaser.Loader.LoaderPlugin): void {
  // Keep height pages available for a later High/Ultra quality upgrade in the same World.
  for (const page of Object.values(GROUND_HEIGHT_PAGES)) load.image(page.key, runtimeAssetUrl(`./${page.file}`));
}
