import type * as Phaser from 'phaser';
import { FOG_LIGHT_SCATTER_FRAGMENT, FOG_LIGHT_SCATTER_SHADER } from '../groundFog/FogLightScatter';
import { GROUND_HEIGHT_BASE_FRAGMENT, GROUND_HEIGHT_BASE_SHADER } from '../../arena/GroundHeightBaker';
import { FAST_LIGHT_ADD_FRAGMENT, FAST_LIGHT_ADD_SHADER, FAST_LIGHT_HOLD_FRAGMENT, FAST_LIGHT_HOLD_SHADER } from './FastLightField';
import { GROUND_LIGHT_FRAGMENT, GROUND_LIGHT_SHADER, GROUND_SUN_FIELD_FRAGMENT, GROUND_SUN_FIELD_SHADER } from './GroundLightPass';
import { CASCADE_FRAGMENT, CASCADE_SHADER, FLUENCE_FRAGMENT, FLUENCE_SHADER, INDIRECT_ADD_FRAGMENT, INDIRECT_ADD_SHADER } from './IndirectLightField';
import { LIGHT_HDR_BRIGHT_FRAGMENT, LIGHT_HDR_BRIGHT_SHADER, LIGHT_HDR_COMPOSITE_FRAGMENT, LIGHT_HDR_COMPOSITE_SHADER, LIGHT_HDR_GLOW_FRAGMENT, LIGHT_HDR_GLOW_SHADER, LIGHT_HDR_SCATTER_FRAGMENT, LIGHT_HDR_SCATTER_SHADER } from './LightHdrComposite';
import { FIRE_LIGHT_ADD_FRAGMENT, FIRE_LIGHT_ADD_SHADER, FIRE_LIGHT_HOLD_FRAGMENT, FIRE_LIGHT_HOLD_SHADER, FIRE_LIGHT_SPREAD_FRAGMENT, FIRE_LIGHT_SPREAD_SHADER } from './FireLightField';
import { LIGHT_VECTOR_HOLD_FRAGMENT, LIGHT_VECTOR_HOLD_SHADER } from './LightVectorField';
import { OCCLUDER_ROCKS_FRAGMENT, OCCLUDER_ROCKS_SHADER } from './OccluderField';
import { SHADOWED_LIGHT_VERTEX, shadowedLightFragment, shadowedLightShaderName } from './ShadowedLightPass';
import { createSelectedShadowProvider } from './ShadowProvider';
import './shadows';
import { JUMP_FLOOD_FRAGMENT, JUMP_FLOOD_SHADER } from './shadows/sdf/JumpFloodField';

/** Lighting programs linked during World loading in every distribution. */
export function lightingV2ShaderPrograms(scene: Phaser.Scene): [string, string, string?][] {
  const programs: [string, string, string?][] = [
    [LIGHT_HDR_COMPOSITE_SHADER, LIGHT_HDR_COMPOSITE_FRAGMENT], [LIGHT_HDR_SCATTER_SHADER, LIGHT_HDR_SCATTER_FRAGMENT],
    [FAST_LIGHT_HOLD_SHADER, FAST_LIGHT_HOLD_FRAGMENT], [FAST_LIGHT_ADD_SHADER, FAST_LIGHT_ADD_FRAGMENT], [LIGHT_VECTOR_HOLD_SHADER, LIGHT_VECTOR_HOLD_FRAGMENT],
    [FIRE_LIGHT_HOLD_SHADER, FIRE_LIGHT_HOLD_FRAGMENT], [FIRE_LIGHT_SPREAD_SHADER, FIRE_LIGHT_SPREAD_FRAGMENT], [FIRE_LIGHT_ADD_SHADER, FIRE_LIGHT_ADD_FRAGMENT],
    [LIGHT_HDR_BRIGHT_SHADER, LIGHT_HDR_BRIGHT_FRAGMENT], [LIGHT_HDR_GLOW_SHADER, LIGHT_HDR_GLOW_FRAGMENT],
    [OCCLUDER_ROCKS_SHADER, OCCLUDER_ROCKS_FRAGMENT], [JUMP_FLOOD_SHADER, JUMP_FLOOD_FRAGMENT],
    [FOG_LIGHT_SCATTER_SHADER, FOG_LIGHT_SCATTER_FRAGMENT], [GROUND_LIGHT_SHADER, GROUND_LIGHT_FRAGMENT], [GROUND_SUN_FIELD_SHADER, GROUND_SUN_FIELD_FRAGMENT], [GROUND_HEIGHT_BASE_SHADER, GROUND_HEIGHT_BASE_FRAGMENT],
    [CASCADE_SHADER, CASCADE_FRAGMENT], [FLUENCE_SHADER, FLUENCE_FRAGMENT], [INDIRECT_ADD_SHADER, INDIRECT_ADD_FRAGMENT],
  ];
  const provider = createSelectedShadowProvider(scene);
  if (provider) {
    programs.push([shadowedLightShaderName(provider.id), shadowedLightFragment(provider.glsl), SHADOWED_LIGHT_VERTEX]);
    provider.destroy?.();
  }
  return programs;
}
