/**
 * Einstellungen und Fortschritt der Steam-Variante als Dateien der Desktop-Shell (Steam-Plan 4.4, L6).
 *
 * `src/utils/localPreferences.ts` bleibt die einzige Persistenzgrenze: Sie liest und schreibt
 * weiter über die `Storage`-Schnittstelle; Validierung, Migration und Cache ändern sich nicht.
 * Diese Implementierung lenkt nur ihre beiden Dokumente um:
 * - Einstellungen → `settings.json` (pro PC, ohne Cloud)
 * - Fortschritt → `save/progress.json` im Exportformat. So lässt sich der Stand und jede
 *   Sicherung aus `save/backups/` über den vorhandenen Import zurückholen.
 * Alles andere (Balance-Lab, Debug) bleibt im Browser-Speicher. Gelesen wird synchron aus dem
 * beim Start geladenen Stand, geschrieben asynchron über die Shell.
 */
import {
  LOCAL_PROGRESS_EXPORT_FORMAT,
  LOCAL_PROGRESS_EXPORT_VERSION,
  LOCAL_PROGRESS_STORAGE_KEY,
  LOCAL_SETTINGS_STORAGE_KEY,
} from '../../utils/localPreferences';
import { readDesktopSaves, type DesktopSaveBridge } from './desktopShell';

type SaveDocument = 'settings' | 'progress';

const DOCUMENT_BY_KEY: ReadonlyMap<string, SaveDocument> = new Map([
  [LOCAL_SETTINGS_STORAGE_KEY, 'settings'],
  [LOCAL_PROGRESS_STORAGE_KEY, 'progress'],
]);

export interface DesktopPreferences {
  readonly storage: Storage;
  /** Die Shell hat einen beschädigten Fortschritt aus einer Sicherung geholt. */
  readonly recoveredFromBackup: boolean;
}

/** Der Fortschritt als Datei: dieselbe Hülle wie der Export, der Inhalt unverändert. */
export function wrapProgressForFile(progressJson: string, exportedAt: Date): string {
  return `{"format":${JSON.stringify(LOCAL_PROGRESS_EXPORT_FORMAT)},`
    + `"formatVersion":${LOCAL_PROGRESS_EXPORT_VERSION},`
    + `"exportedAt":${JSON.stringify(exportedAt.toISOString())},`
    + `"progress":${progressJson}}`;
}

/** Fremde oder ältere Inhalte gehen unverändert an den Decoder, der über ihre Gültigkeit entscheidet. */
export function unwrapProgressFromFile(text: string): string {
  try {
    const parsed: unknown = JSON.parse(text);
    if (parsed && typeof parsed === 'object' && 'progress' in parsed
      && (parsed as { format?: unknown }).format === LOCAL_PROGRESS_EXPORT_FORMAT) {
      return JSON.stringify((parsed as { progress: unknown }).progress);
    }
  } catch {
    // Die Shell legt Nicht-JSON schon beim Laden beiseite; hier entscheidet der Decoder.
  }
  return text;
}

function safeGet(storage: Storage | null, key: string): string | null {
  try { return storage?.getItem(key) ?? null; } catch { return null; }
}

export function createDesktopPreferences(
  saves: DesktopSaveBridge,
  fallback: Storage | null,
  now: () => Date = () => new Date(),
): DesktopPreferences {
  const documents = new Map<SaveDocument, string | null>([
    ['settings', saves.settings],
    ['progress', saves.progress === null ? null : unwrapProgressFromFile(saves.progress)],
  ]);
  const write = (document: SaveDocument, value: string | null): void => {
    documents.set(document, value);
    saves.write(document, value === null || document === 'settings' ? value : wrapProgressForFile(value, now()));
  };
  const fallbackKeys = (): string[] => {
    const keys: string[] = [];
    try {
      for (let index = 0; index < (fallback?.length ?? 0); index++) {
        const key = fallback?.key(index);
        if (key !== null && key !== undefined && !DOCUMENT_BY_KEY.has(key)) keys.push(key);
      }
    } catch {
      // Ohne Browser-Speicher gibt es nur die beiden Dokumente.
    }
    return keys;
  };
  const keys = (): string[] => [
    ...[...DOCUMENT_BY_KEY].filter(([, document]) => documents.get(document) !== null).map(([key]) => key),
    ...fallbackKeys(),
  ];

  const storage: Storage = {
    get length() { return keys().length; },
    key: index => keys()[index] ?? null,
    getItem: key => {
      const document = DOCUMENT_BY_KEY.get(key);
      return document ? documents.get(document) ?? null : safeGet(fallback, key);
    },
    setItem: (key, value) => {
      const document = DOCUMENT_BY_KEY.get(key);
      if (document) write(document, String(value));
      else fallback?.setItem(key, value);
    },
    removeItem: key => {
      const document = DOCUMENT_BY_KEY.get(key);
      if (document) write(document, null);
      else fallback?.removeItem(key);
    },
    clear: () => {
      for (const document of DOCUMENT_BY_KEY.values()) write(document, null);
      fallback?.clear();
    },
  };

  // Frühere Desktop-Builds speicherten im Browser-Speicher des festen Origins: einmal übernehmen.
  for (const [key, document] of DOCUMENT_BY_KEY) {
    if (documents.get(document) !== null) continue;
    const legacy = safeGet(fallback, key);
    if (legacy === null) continue;
    write(document, legacy);
  }

  return {
    storage,
    recoveredFromBackup: saves.recovered,
  };
}

let resolved: DesktopPreferences | null | undefined;

/** Einmal je Seitenleben; `null` ohne Shell (Tests, Steam-Build im Browser) oder ohne lesbare Dateien. */
export function resolveDesktopPreferences(): DesktopPreferences | null {
  if (resolved !== undefined) return resolved;
  const saves = readDesktopSaves();
  let fallback: Storage | null = null;
  try { fallback = typeof window === 'undefined' ? null : window.localStorage; } catch { fallback = null; }
  resolved = saves ? createDesktopPreferences(saves, fallback) : null;
  return resolved;
}
