import { COOP_DEFENSE_CLASS_IDS, DEFAULT_COOP_DEFENSE_CLASS_ID } from '../config/coopDefenseClasses';
import { getCoopDefenseLevelForXp } from '../utils/coopDefenseXp';
import {
  getFullyUpgradedCoopDefenseWeaponIds,
  resolveCoopDefenseUpgradeEntitlements,
} from '../utils/coopDefenseUpgrades';
import type { CoopDefenseProgressPreferences } from '../utils/localPreferences';

export const NECROMANCY_BRANCH_ID = 'necromancy';
export const EPIC_ITEM_RARITY = 'yellow';
/** Real campaign ids only; synthetic cheat boss entries never match. */
const CAMPAIGN_MAP_ID_PATTERN = /^\d{1,2}$/u;

export type AchievementProgressSource = Pick<CoopDefenseProgressPreferences,
  'totalXp' | 'completedMapIds' | 'completedBossMapIds' | 'dawn' | 'items' | 'classesUnlocked'
  | 'defaultProfile' | 'profilesByClass'>;

/**
 * Achievement values that the save already proves. Re-evaluating them on every start is what
 * unlocks achievements retroactively for existing saves.
 */
export function deriveAchievementStateValues(progress: AchievementProgressSource): Record<string, number> {
  const values: Record<string, number> = {
    'progress.level': getCoopDefenseLevelForXp(progress.totalXp),
    'progress.dawnVictories': progress.dawn.stats.victories,
    'progress.dawnBestStreak': progress.dawn.stats.bestStreak,
    'progress.necromancy': progress.dawn.unlockedBranchIds.includes(NECROMANCY_BRANCH_ID) ? 1 : 0,
    'progress.epicItem': progress.items.some(item => item.rarity === EPIC_ITEM_RARITY) ? 1 : 0,
    'progress.weaponMaxed': hasFullyUpgradedWeapon(progress) ? 1 : 0,
  };
  for (const mapId of progress.completedMapIds) {
    if (CAMPAIGN_MAP_ID_PATTERN.test(mapId)) values[`progress.map.${mapId}`] = 1;
  }
  for (const mapId of progress.completedBossMapIds) {
    if (CAMPAIGN_MAP_ID_PATTERN.test(mapId)) values[`progress.bossMap.${mapId}`] = 1;
  }
  return values;
}

function hasFullyUpgradedWeapon(progress: AchievementProgressSource): boolean {
  const entitlements = resolveCoopDefenseUpgradeEntitlements(progress.dawn.unlockedBranchIds);
  if (!progress.classesUnlocked) {
    return getFullyUpgradedCoopDefenseWeaponIds(progress.defaultProfile, DEFAULT_COOP_DEFENSE_CLASS_ID, entitlements).length > 0;
  }
  return COOP_DEFENSE_CLASS_IDS.some(classId => (
    getFullyUpgradedCoopDefenseWeaponIds(progress.profilesByClass[classId], classId, entitlements).length > 0
  ));
}
