import type * as Phaser from 'phaser';
import { getPipelineAssetForTexture, type PipelineClip } from '../config/pipelineAssets';
import type { EnemyVolleyState } from '../systems/EnemyVolleyState';
import type { InfernoColossusAction } from '../systems/InfernoColossusState';

type Clip = Pick<PipelineClip, 'frames' | 'markers' | 'frameRate'>;
type ClipSource = (name: string) => Clip | undefined;

const frameMs = (clip: Clip): number => 1000 / Math.max(1, clip.frameRate ?? 24);

/**
 * Frame of `clip` placed so its `marker` frame shows at `markerAt` (the body strikes, throws or
 * ignites exactly then). Before the lead-in and after the clip it yields null; with `loopFrom`
 * the frames from that index on repeat until `until`.
 */
export function markerAlignedFrame(clip: Clip | undefined, marker: string, fallbackShare: number, markerAt: number,
  now: number, loopFrom?: number, until = Number.POSITIVE_INFINITY): number | null {
  if (!clip?.frames.length) return null;
  const last = clip.frames.length - 1, ms = frameMs(clip);
  const markerIndex = Math.min(last, Math.max(0, clip.markers?.[marker] ?? Math.round(last * fallbackShare)));
  let index = markerIndex + Math.floor((now - markerAt) / ms);
  if (index < 0) return null;
  if (index > last) {
    if (loopFrom === undefined || now >= until) return null;
    const span = last - loopFrom + 1;
    index = loopFrom + (index - loopFrom) % Math.max(1, span);
  }
  return clip.frames[index]!;
}

/** A looping clip from `startedAt` on, null outside [startedAt, until). */
function loopFrame(clip: Clip | undefined, startedAt: number, now: number, until: number): number | null {
  if (!clip?.frames.length || now < startedAt || now >= until) return null;
  return clip.frames[Math.floor((now - startedAt) / frameMs(clip)) % clip.frames.length]!;
}

/**
 * Texture frame of the colossus's big action at `now`, or null when ordinary clips apply. Every clip
 * sits on the replicated timeline: the transition bursts open at the shockwave, the Glutstoss slams
 * at its blast, the Brandsatz leaves the abdomen at its throw, the siege loops while it stands,
 * the flight takes off, flies and lands on its timestamps. Sheets without a clip show none.
 */
export function infernoColossusActionFrame(action: InfernoColossusAction | null, now: number, clip: ClipSource): number | null {
  if (!action || now >= action.endsAt) return null;
  switch (action.kind) {
    case 'transition': return markerAlignedFrame(clip('transition'), 'burst', 0.7, action.commitAt, now);
    case 'glutstoss': return markerAlignedFrame(clip('glutstoss'), 'impact', 0.6, action.commitAt, now);
    case 'incendiary': return markerAlignedFrame(clip('bombard'), 'release', 0.5, action.releaseAt, now);
    case 'siege': return loopFrame(clip('siege'), action.startedAt, now, action.endsAt);
    case 'beetleSalvo': return null; // the body keeps walking and flaming; only its light shows the salvo
    case 'flight': {
      if (now < action.releaseAt) {
        const takeoff = clip('takeoff');
        return takeoff?.frames.length ? markerAlignedFrame(takeoff, 'lift', 1, action.releaseAt, now) : null;
      }
      if (now < action.commitAt) return loopFrame(clip('fly'), action.releaseAt, now, action.commitAt);
      return markerAlignedFrame(clip('land'), 'touch', 0, action.commitAt, now);
    }
  }
}

/**
 * Frame of the flame burst: the mandibles spread toward the ignition (`ignite` marker at the first
 * flame), then the frames after it loop while the burst lasts. A walking body keeps its legs moving:
 * before the ignition the ordinary move clip runs (null), after it the flame walk (`walk`, the tripod
 * under the burning pose) loops from the ignition on.
 */
export function flameBurstFrame(volley: EnemyVolleyState, now: number, clip: Clip | undefined, walk?: Clip,
  walking = false): number | null {
  if (volley.revision === 0 || !clip?.frames.length) return null;
  const until = volley.endedAt > 0 ? volley.endedAt : Number.POSITIVE_INFINITY;
  if (now >= until) return null;
  if (walking && walk?.frames.length) {
    if (now < volley.fireAt) return null;
    return walk.frames[Math.floor((now - volley.fireAt) / frameMs(walk)) % walk.frames.length]!;
  }
  const ignite = Math.min(clip.frames.length - 1, Math.max(0, clip.markers?.ignite ?? Math.round((clip.frames.length - 1) * 0.5)));
  return markerAlignedFrame(clip, 'ignite', 0.5, volley.fireAt, now, ignite, until);
}

/**
 * True while the phase change still plays on the sheet of `texture` (the closed phase-1 sheet carries
 * the transition): from the action's start until its clip's last frame after the burst. The body
 * presents its phase sheet only afterwards, whose rest is the clip's last pose.
 */
export function infernoColossusTransitionHolds(texture: string, action: InfernoColossusAction | null, now: number): boolean {
  if (action?.kind !== 'transition' || now >= action.endsAt) return false;
  const clip = getPipelineAssetForTexture(texture)?.clips.find(candidate => candidate.name === 'transition');
  if (!clip?.frames.length) return false;
  const last = clip.frames.length - 1;
  const burst = Math.min(last, Math.max(0, clip.markers?.burst ?? Math.round(last * 0.7)));
  return now < action.commitAt + (last - burst + 1) * frameMs(clip);
}

/** Plays the action (priority) or the flame burst; false when ordinary clips apply. */
export function syncEnemyInfernoColossusAnimation(sprite: Phaser.GameObjects.Sprite, texture: string,
  action: InfernoColossusAction | null, volley: EnemyVolleyState, now: number, blocked: boolean, walking = false): boolean {
  if (blocked) return false;
  const clips = getPipelineAssetForTexture(texture)?.clips;
  const clip: ClipSource = name => clips?.find(candidate => candidate.name === name);
  const frame = infernoColossusActionFrame(action, now, clip)
    ?? flameBurstFrame(volley, now, clip('flame'), clip('flamewalk'), walking);
  if (frame === null) return false;
  if (sprite.anims.isPlaying) sprite.anims.stop();
  sprite.setFrame(frame);
  return true;
}
