import * as Phaser from 'phaser';

/**
 * Steam-Plan L5: geladene Bilder außerhalb des Main-Threads dekodieren.
 *
 * Phaser 4.2.1 macht aus jedem Bild ein `HTMLImageElement`; dekodiert wird erst beim Textur-Upload,
 * synchron auf dem Main-Thread. `createImageBitmap` dekodiert im Hintergrund, der Upload kopiert
 * dann nur noch Pixel (große Atlanten: rund ein Zehntel der Main-Thread-Zeit).
 *
 * Vertrag:
 * - WebGL ignoriert für ImageBitmaps `UNPACK_FLIP_Y` und `UNPACK_PREMULTIPLY_ALPHA`. Ein Bitmap trägt
 *   deshalb schon Ausrichtung und Alpha-Form seines Uploads (`ImageBitmapDecode`). Gemessen in
 *   Electron 45: Rohdaten und PNG bitgleich zum Bildelement, WebP mit Teiltransparenz einzelne
 *   Kanäle ±1 (Rundung beim Vormultiplizieren).
 * - Nach dem Upload zeigen TextureSource und Textur-Wrapper wieder auf ein gewöhnliches, aufrechtes
 *   `HTMLImageElement` aus demselben Blob. CPU-Leser (`getSourceImage()`), Neu-Uploads und
 *   Kontextwiederherstellung sehen also dasselbe Bild wie vorher; das Bitmap wird geschlossen.
 * - Unverändertes Phaser-Laden (die übergebenen Standardklassen ohne eigenes `onProcessComplete`)
 *   nutzt den Weg automatisch. Eigene Uploads melden sich mit `decodeImageFileAsBitmap` an; alles
 *   andere bleibt beim Bildelement.
 */
export interface ImageBitmapDecode {
  readonly options: ImageBitmapOptions;
  /** Gespiegelt und vormultipliziert für Phasers TextureSource-Upload mit `flipY`. */
  readonly textureSource: boolean;
}

/** Phasers Bild-Upload: vormultipliziertes Alpha, `UNPACK_FLIP_Y`. */
export const TEXTURE_SOURCE_DECODE: ImageBitmapDecode = Object.freeze({
  options: Object.freeze({ premultiplyAlpha: 'premultiply', imageOrientation: 'flipY', colorSpaceConversion: 'default' }),
  textureSource: true,
});
/** Rohdaten: aufrecht, Alpha unverändert (Datentexturen ohne PMA/Flip, CPU-Auswertung). */
export const RAW_PIXELS_DECODE: ImageBitmapDecode = Object.freeze({
  options: Object.freeze({ premultiplyAlpha: 'none', imageOrientation: 'from-image', colorSpaceConversion: 'default' }),
  textureSource: false,
});

type ImageFileLike = {
  data: unknown;
  state: number;
  crossOrigin?: string;
  xhrLoader: XMLHttpRequest | null;
  onProcess(): void;
  onProcessComplete(): void;
};
type TextureSourceLike = {
  source: unknown; image: unknown; flipY: boolean; glTexture: { pixels: unknown } | null;
  init(game: Phaser.Game): void;
};
type Decoded = { readonly element: HTMLImageElement; readonly decode: ImageBitmapDecode };

const requested = new WeakMap<object, ImageBitmapDecode>();
const decoded = new WeakMap<object, Decoded>();
const installed = new WeakSet<object>();

/** Lässt eine angepasste ImageFile im Hintergrund dekodieren; `data` ist dann ein ImageBitmap. */
export function decodeImageFileAsBitmap(file: object, decode: ImageBitmapDecode): void {
  requested.set(file, decode);
}

/** Das gleichwertige aufrechte Bildelement eines dekodierten Bitmaps, sonst das Bild selbst. */
export function decodedImageElement<T>(image: T): T | HTMLImageElement {
  return (typeof image === 'object' && image !== null && decoded.get(image)?.element) || image;
}

/** Schließt ein von hier dekodiertes Bitmap nach seinem Upload. Andere Bilder bleiben unberührt. */
export function releaseDecodedImage(image: unknown): void {
  if (typeof image === 'object' && image !== null && decoded.delete(image)) (image as ImageBitmap).close();
}

/**
 * Für eigene Uploads außerhalb des Loaders (z. B. Kraken-Atlasseiten): dekodiert ein Bild im Hintergrund.
 * `image` geht an `addImage`/`addAtlas` und wird dort wie ein Loader-Bild hochgeladen und danach gegen
 * `element` getauscht. Ohne `createImageBitmap` oder bei dessen Fehler ist `image` das Bildelement selbst.
 * Ein nie hochgeladenes Bitmap gibt `releaseDecodedImage` frei.
 */
export async function decodeBlobForTextureSource(blob: Blob, crossOrigin?: string):
  Promise<{ readonly image: ImageBitmap | HTMLImageElement; readonly element: HTMLImageElement }> {
  if (typeof createImageBitmap !== 'function') { const element = await loadElement(blob, crossOrigin); return { image: element, element }; }
  const [bitmap, element] = await Promise.allSettled([createImageBitmap(blob, TEXTURE_SOURCE_DECODE.options), loadElement(blob, crossOrigin)]);
  if (element.status === 'rejected') {
    if (bitmap.status === 'fulfilled') bitmap.value.close();
    throw element.reason;
  }
  if (bitmap.status === 'rejected') return { image: element.value, element: element.value };
  decoded.set(bitmap.value, { element: element.value, decode: TEXTURE_SOURCE_DECODE });
  return { image: bitmap.value, element: element.value };
}

function loadElement(blob: Blob, crossOrigin: string | undefined): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const element = new Image();
    if (crossOrigin) element.crossOrigin = crossOrigin;
    const url = URL.createObjectURL(blob);
    element.onload = () => { URL.revokeObjectURL(url); resolve(element); };
    element.onerror = () => { URL.revokeObjectURL(url); reject(new Error('Image element failed')); };
    element.src = url;
  });
}

/**
 * @param imageFile `Phaser.Loader.FileTypes.ImageFile`
 * @param standardFiles Klassen, deren unverändertes Laden Phasers TextureSource-Upload verwendet
 * @param textureSource `Phaser.Textures.TextureSource.prototype`
 */
export function installPhaserImageBitmapLoading(
  imageFile: { prototype: object },
  standardFiles: readonly unknown[],
  textureSource: object,
): void {
  if (installed.has(imageFile.prototype) || typeof createImageBitmap !== 'function') return;
  installed.add(imageFile.prototype);
  const file = imageFile.prototype as ImageFileLike;
  const standard = new Set(standardFiles);
  const standardComplete = file.onProcessComplete;
  const process = file.onProcess;

  file.onProcess = function (this: ImageFileLike): void {
    const blob = this.xhrLoader?.response;
    const decode = requested.get(this) ?? (standard.has(this.constructor)
      && this.onProcessComplete === standardComplete ? TEXTURE_SOURCE_DECODE : undefined);
    if (!decode || !(blob instanceof Blob)) { process.call(this); return; }
    this.state = Phaser.Loader.FILE_PROCESSING;
    void Promise.allSettled([createImageBitmap(blob, decode.options), loadElement(blob, this.crossOrigin)])
      .then(([bitmap, element]) => {
        if (bitmap.status === 'fulfilled' && element.status === 'fulfilled') {
          decoded.set(bitmap.value, { element: element.value, decode });
          this.data = bitmap.value;
          this.onProcessComplete();
          return;
        }
        if (bitmap.status === 'fulfilled') bitmap.value.close();
        // Phasers eigener Weg dekodiert erneut und meldet einen echten Fehler über seinen Fehlerpfad.
        process.call(this);
      });
  };

  const source = textureSource as TextureSourceLike;
  const init = source.init;
  source.init = function (this: TextureSourceLike, game: Phaser.Game): void {
    const bitmap = this.image;
    const entry = typeof bitmap === 'object' && bitmap !== null ? decoded.get(bitmap) : undefined;
    // Nur ein für TextureSources dekodiertes Bitmap passt zu diesem Upload; sonst wie bisher.
    if (entry && !(entry.decode.textureSource && this.flipY)) this.source = this.image = entry.element;
    init.call(this, game);
    if (!entry || this.image !== bitmap) return;
    this.source = this.image = entry.element;
    const wrapper = this.glTexture;
    if (wrapper && wrapper.pixels === bitmap) wrapper.pixels = entry.element;
    releaseDecodedImage(bitmap);
  };
}
