import * as Phaser from 'phaser';
import { DEPTH, VOID_FIRE_COLOR, VOID_PALETTE } from '../../config';
import { getPipelineAsset, pipelineAnimationKey } from '../../config/pipelineAssets';
import type { ProjectileCustomVisual, ProjectileCustomVisualFactory } from '../../projectile/ProjectileVisualOverrides';
import { BULLET_GLOW_TEXTURE } from '../BulletRenderer';
import { emissiveAlpha } from '../EmissiveScale';

const ASSET = getPipelineAsset('inferno-ember-beetle');
const FLY_CLIP = ASSET.clips.find(clip => clip.name === 'fly');
/** Weapon of the colossus's siege swarm (see `infernoColossus.siege.weaponId`). */
const EMBER_BEETLE_WEAPON_ID = 'INFERNO_COLOSSUS_EMBER_BEETLE';
/** Above the catalog's 18 px: the beetle shape has to read while 48 of them swarm. */
const BEETLE_SIZE = 28;
/** The ember core glows on the abdomen, small enough that the beetle's outline stays visible. */
const CORE_GLOW_SIZE = 12;
const CORE_BACK_PX = 4;
const TAIL_LENGTH = 30;
const TAIL_WIDTH = 8;
const TAIL_BACK_PX = 9;
const SHEEN_ALPHA = 0.42;

function ensureBeetleSheet(scene: Phaser.Scene): boolean {
  if (scene.textures.exists(ASSET.sheetTextureKey)) {
    if (FLY_CLIP && !scene.anims.exists(pipelineAnimationKey(ASSET, FLY_CLIP))) {
      scene.anims.create({ key: pipelineAnimationKey(ASSET, FLY_CLIP), frameRate: FLY_CLIP.frameRate, repeat: -1,
        frames: scene.anims.generateFrameNumbers(ASSET.sheetTextureKey, { frames: [...FLY_CLIP.frames] }) });
    }
    return true;
  }
  scene.load.spritesheet(ASSET.sheetTextureKey, ASSET.sheetPath, { ...ASSET.layout, endFrame: ASSET.layout.frameCount - 1 });
  if (!scene.load.isLoading()) scene.load.start();
  return false;
}

/**
 * One Glutkäfer of the siege swarm: the beetle flaps its burning wings and faces its flight
 * (forward = north). The body sits under the light map like every projectile; a faint violet copy
 * of it, its ember core and a short void-haze tail are emissive above it, so the dark chitin reads
 * as a glowing beetle by day and night without a light per shot.
 */
class EmberBeetleFlightView implements ProjectileCustomVisual {
  private readonly sprite: Phaser.GameObjects.Sprite;
  private readonly sheen: Phaser.GameObjects.Image;
  private readonly core: Phaser.GameObjects.Image | null;
  private readonly tail: Phaser.GameObjects.Image | null;
  private rotation = 0;
  constructor(private readonly scene: Phaser.Scene, x: number, y: number, private readonly seed: number) {
    this.sprite = scene.add.sprite(x, y, ASSET.sheetTextureKey, ASSET.idleFrame)
      .setOrigin(...ASSET.pivot).setDisplaySize(BEETLE_SIZE, BEETLE_SIZE).setDepth(DEPTH.PROJECTILES);
    if (FLY_CLIP && scene.anims.exists(pipelineAnimationKey(ASSET, FLY_CLIP))) {
      // Each beetle starts at its own wingbeat, or the swarm flaps in lockstep.
      this.sprite.play({ key: pipelineAnimationKey(ASSET, FLY_CLIP), startFrame: Math.floor(seed * FLY_CLIP.frames.length) });
    }
    this.sheen = scene.add.image(x, y, ASSET.sheetTextureKey, this.sprite.frame.name).setOrigin(...ASSET.pivot)
      .setDisplaySize(BEETLE_SIZE, BEETLE_SIZE).setTint(VOID_FIRE_COLOR).setBlendMode(Phaser.BlendModes.ADD).setDepth(DEPTH.CANOPY - 0.32);
    const glow = scene.textures.exists(BULLET_GLOW_TEXTURE);
    this.tail = glow ? scene.add.image(x, y, BULLET_GLOW_TEXTURE).setOrigin(0, 0.5).setDisplaySize(TAIL_LENGTH, TAIL_WIDTH)
      .setTint(VOID_FIRE_COLOR).setBlendMode(Phaser.BlendModes.ADD).setDepth(DEPTH.CANOPY - 0.31) : null;
    this.core = glow ? scene.add.image(x, y, BULLET_GLOW_TEXTURE).setDisplaySize(CORE_GLOW_SIZE, CORE_GLOW_SIZE)
      .setTint(VOID_PALETTE.bright).setBlendMode(Phaser.BlendModes.ADD).setDepth(DEPTH.CANOPY - 0.3) : null;
  }
  update(x: number, y: number, _size: number, vx: number, vy: number): void {
    if (Math.hypot(vx, vy) > 1) this.rotation = Math.atan2(vy, vx);
    this.sprite.setPosition(x, y).setRotation(this.rotation + Math.PI / 2);
    if (this.sheen.frame.name !== this.sprite.frame.name) this.sheen.setFrame(this.sprite.frame.name, false, false);
    this.sheen.setPosition(x, y).setRotation(this.rotation + Math.PI / 2).setAlpha(emissiveAlpha(SHEEN_ALPHA));
    const flicker = 0.5 + 0.5 * Math.sin(this.scene.time.now / 70 + this.seed * Math.PI * 2);
    const backX = -Math.cos(this.rotation), backY = -Math.sin(this.rotation);
    this.core?.setPosition(x + backX * CORE_BACK_PX, y + backY * CORE_BACK_PX).setAlpha(emissiveAlpha(0.5 + 0.25 * flicker));
    // The haze trails from the abdomen against the flight direction.
    this.tail?.setPosition(x + backX * TAIL_BACK_PX, y + backY * TAIL_BACK_PX).setRotation(this.rotation + Math.PI)
      .setAlpha(emissiveAlpha(0.4 + 0.1 * flicker));
  }
  destroy(): void { this.sprite.destroy(); this.sheen.destroy(); this.core?.destroy(); this.tail?.destroy(); }
}

/**
 * Claims the siege swarm's shots by their replicated weapon source on host and client. They bring
 * their own glow instead of a muzzle flash and a light per shot; until the small sheet is loaded the
 * generic energy-ball renderer keeps drawing them.
 */
export function createEmberBeetleFlightFactory(scene: Phaser.Scene): {
  readonly factory: ProjectileCustomVisualFactory;
  readonly ownsSpawnFx: (weaponSourceId: string) => boolean;
} {
  ensureBeetleSheet(scene);
  return {
    factory: projectile => projectile.weaponSourceId === EMBER_BEETLE_WEAPON_ID && ensureBeetleSheet(scene)
      ? new EmberBeetleFlightView(scene, projectile.x, projectile.y, (projectile.id * 0.6180339887) % 1) : null,
    ownsSpawnFx: weaponSourceId => weaponSourceId === EMBER_BEETLE_WEAPON_ID && scene.textures.exists(ASSET.sheetTextureKey),
  };
}
