import * as Phaser from 'phaser';
import { DEPTH_LIGHTING } from '../../config';
import type { FormationCoverageBinding } from '../../arena/rocks/RockFormationLighting';
import { maxBlendMode } from '../../graphics/CustomBlendModes';
import type { DynamicLightOccluderSource } from '../DynamicLightOccluders';
import { EnemyEyeBatch } from '../EnemyEyeBatch';
import type { LightOccluderIndex } from '../LightOccluderIndex';
import { OCCLUDER_GROUP_ROCK } from '../LightOccluderIndex';
import { ROCK_CONTOUR, ROCK_COVERAGE_GLSL } from '../RockLightCoverage';
import { ownSunShader } from '../sunlight/SunRenderTarget';
import { FigureSilhouettes } from './FigureSilhouettes';
import type { FigureMaskRect } from './FigureMask';
import { encodeOccluder, OCCLUDER_HEIGHT_PX, OCCLUDER_KIND_FIGURE, OCCLUDER_KIND_FIGURE_DISC, OCCLUDER_KIND_LAMP_CARRIER, OCCLUDER_KIND_OTHER, OCCLUDER_KIND_ROCK } from './OccluderHeights';

/** One world pixel in this many field texels; soft light needs no finer mask. */
const TEXELS_PER_PX = 0.5;
const FIGURE_CORE_SHARE = 0.7;
/**
 * Lights reach into the view from outside it, up to the largest shadowed radius. The field only grows that far
 * while a shadowed light stands out there: every texel of the margin is flooded each frame.
 */
const MARGIN_STEPS_PX = [192, 352, 512] as const;
/** A margin no longer needed stays this long, so lights at the edge of a step do not rebuild the targets back and forth. */
const MARGIN_SHRINK_AFTER_MS = 4000;
/** The static layer follows the camera in coarse steps; a step redraws it. */
const STATIC_STEP_PX = 256;
const CASTER_CAPACITY = 512;
const TEX_DISC = '__occluder_disc';
const TEX_WHITE = '__occluder_white';
export const OCCLUDER_ROCKS_SHADER = 'OccluderRocks';
const MAX_HEIGHT_NORMALIZED = (OCCLUDER_HEIGHT_PX.rock / 510).toFixed(4);

export const OCCLUDER_ROCKS_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
varying vec2 outTexCoord;
${ROCK_COVERAGE_GLSL}
uniform vec4 uWorld;
uniform float uFlipY;
void main() {
  vec2 uv = vec2(outTexCoord.x, uFlipY > 0.5 ? 1.0 - outTexCoord.y : outTexCoord.y);
  float rock = smoothstep(${(ROCK_CONTOUR - 0.05).toFixed(2)}, ${(ROCK_CONTOUR + 0.05).toFixed(2)}, rockCoverage(uWorld.xy + uv * uWorld.zw));
  gl_FragColor = vec4(rock, rock * ${MAX_HEIGHT_NORMALIZED}, rock, 1.0);
}`;

/** A figure or other moving blocker of this frame. */
export interface OccluderCaster {
  x: number;
  y: number;
  /** Only for a figure without a usable sprite, which is then drawn as a disc. */
  radius: number;
  heightPx: number;
  strength: number;
  sprite: Phaser.GameObjects.Sprite | null;
  /** Players: their own body must not block the lamp they hold. */
  lampCarrier?: boolean;
}

export interface OccluderFieldInputs {
  readonly occluders: LightOccluderIndex | null;
  readonly dynamicOccluders: DynamicLightOccluderSource | null;
  readonly coverage: FormationCoverageBinding | null;
  readonly casters: readonly OccluderCaster[];
  /** Where to draw the figures' shown pictures for the shadow pass; null leaves the mask out. */
  readonly figureMask: FigureMaskRect | null;
  /** The blockers follow the picture shown this frame instead of the resting pose alone. */
  readonly animatedFigures: boolean;
  /** The mask holds how much of each texel a figure covers instead of one sample at its centre. */
  readonly figureCoverage: boolean;
}

export type { FigureMaskRect } from './FigureMask';

/** Shared GPU mask of everything that blocks point lights: R blocker, G height / 510 px, B surface kind. */
export class OccluderField {
  /** World x, y, width, height of `texture`. */
  readonly frame = new Float32Array(4);
  private readonly staticWorld = new Float32Array(4);
  private readonly rocks: Phaser.GameObjects.Shader;
  private readonly casterBatch: EnemyEyeBatch;
  private readonly silhouettes: FigureSilhouettes;
  private readonly maxBlend: number;
  private field: Phaser.GameObjects.RenderTexture | null = null;
  private statics: Phaser.GameObjects.RenderTexture | null = null;
  private staticImage: Phaser.GameObjects.Image | null = null;
  private staticOriginX = NaN;
  private staticOriginY = NaN;
  private staticRevision = -1;
  private staticCoverage: FormationCoverageBinding | null = null;
  private marginPx: number = MARGIN_STEPS_PX[0];
  private mask: Phaser.GameObjects.RenderTexture | null = null;
  private maskDrawn = false;
  /** World x, y of the figure mask; 1 / world width, 1 / world height. */
  readonly figureMaskFrame = new Float32Array(4);
  private marginNeededAt = 0;

  constructor(private readonly scene: Phaser.Scene) {
    this.ensureTextures();
    this.maxBlend = maxBlendMode(scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer);
    this.rocks = new Phaser.GameObjects.Shader(scene, {
      name: OCCLUDER_ROCKS_SHADER, shaderName: OCCLUDER_ROCKS_SHADER, fragmentSource: OCCLUDER_ROCKS_FRAGMENT,
      setupUniforms: (set: (name: string, value: unknown) => void) => {
        set('uRockField', 0); set('uRockLookup', 1); set('uRockFrame', this.staticCoverage?.frame ?? [0, 0, 0, 0]);
        set('uWorld', this.staticWorld); set('uFlipY', 1);
      },
    }, 0, 0, 2, 2, ['__WHITE', '__WHITE']);
    ownSunShader(this.rocks, OCCLUDER_ROCKS_SHADER, true);
    this.rocks.setOrigin(0);
    this.casterBatch = new EnemyEyeBatch(scene, TEX_DISC, CASTER_CAPACITY);
    this.casterBatch.layer.setBlendMode(this.maxBlend);
    this.silhouettes = new FigureSilhouettes(scene, this.maxBlend);
  }

  get texture(): Phaser.Textures.Texture | null { return this.field?.texture ?? null; }

  /** The pictures the figures show this frame (R coverage, G height / 510 px), or null while no mask is drawn. */
  get figureMask(): Phaser.Textures.Texture | null { return this.maskDrawn ? this.mask!.texture : null; }

  /** Runs `work` right behind this frame's drawing of the field, which happens later in the display list. */
  afterDrawn(work: () => void): void {
    (this.field?.texture as Phaser.Textures.DynamicTexture | undefined)?.callback(work);
  }

  /** `reachPx` is how far outside the view this frame's farthest shadowed light stands. */
  update(viewX: number, viewY: number, viewWidth: number, viewHeight: number, reachPx: number, inputs: OccluderFieldInputs): void {
    const margin = this.resolveMargin(reachPx);
    const originX = snapDown(viewX - margin, 1 / TEXELS_PER_PX), originY = snapDown(viewY - margin, 1 / TEXELS_PER_PX);
    const worldWidth = viewWidth + margin * 2, worldHeight = viewHeight + margin * 2;
    const field = this.ensureTargets(worldWidth, worldHeight);
    this.frame[0] = originX; this.frame[1] = originY; this.frame[2] = field.width / TEXELS_PER_PX; this.frame[3] = field.height / TEXELS_PER_PX;
    this.refreshStatics(originX, originY, inputs);

    field.clear();
    const image = this.staticImage!;
    image.setPosition((this.staticOriginX - originX) * TEXELS_PER_PX, (this.staticOriginY - originY) * TEXELS_PER_PX);
    field.draw(image);
    inputs.dynamicOccluders?.queryCircle(originX + this.frame[2] * 0.5, originY + this.frame[3] * 0.5, Math.hypot(this.frame[2], this.frame[3]) * 0.5,
      (left, top, right, bottom) => this.stampRect(field, originX, originY, left, top, right, bottom, encodeOccluder(OCCLUDER_HEIGHT_PX.train, OCCLUDER_KIND_OTHER)));
    const mask = this.prepareMask(inputs.figureMask);
    this.drawCasters(field, originX, originY, inputs.casters, inputs.animatedFigures);
    const rect = inputs.figureMask;
    if (mask && rect && inputs.casters.length) {
      const scale = rect.texWidth / rect.width;
      this.silhouettes.drawMask(mask, scale / TEXELS_PER_PX, (originX - rect.x) * scale, (originY - rect.y) * scale, inputs.figureCoverage);
    }
  }

  private prepareMask(rect: FigureMaskRect | null): Phaser.GameObjects.RenderTexture | null {
    this.maskDrawn = false;
    if (!rect) return null;
    let mask = this.mask;
    if (!mask || mask.width !== rect.texWidth || mask.height !== rect.texHeight) {
      mask?.destroy();
      mask = this.mask = this.scene.add.renderTexture(0, 0, rect.texWidth, rect.texHeight)
        .setOrigin(0).setScrollFactor(0).setDepth(DEPTH_LIGHTING - 0.035).setRenderMode('redraw');
      mask.texture.setFilter(Phaser.Textures.FilterMode.LINEAR);
    }
    this.figureMaskFrame[0] = rect.x; this.figureMaskFrame[1] = rect.y; this.figureMaskFrame[2] = 1 / rect.width; this.figureMaskFrame[3] = 1 / rect.height;
    mask.clear();
    this.maskDrawn = true;
    return mask;
  }

  destroy(): void {
    this.rocks.destroy();
    this.casterBatch.destroy();
    this.silhouettes.destroy();
    this.destroyTargets();
  }

  private resolveMargin(reachPx: number): number {
    const needed = MARGIN_STEPS_PX.find(step => step >= reachPx) ?? MARGIN_STEPS_PX[MARGIN_STEPS_PX.length - 1];
    const now = this.scene.game.loop.time;
    if (needed >= this.marginPx) { this.marginPx = needed; this.marginNeededAt = now; }
    else if (now - this.marginNeededAt > MARGIN_SHRINK_AFTER_MS) { this.marginPx = needed; this.marginNeededAt = now; }
    return this.marginPx;
  }

  private refreshStatics(originX: number, originY: number, inputs: OccluderFieldInputs): void {
    const statics = this.statics!;
    const stepX = snapDown(originX, STATIC_STEP_PX), stepY = snapDown(originY, STATIC_STEP_PX);
    const revision = inputs.occluders?.getRevision() ?? 0;
    if (stepX === this.staticOriginX && stepY === this.staticOriginY && revision === this.staticRevision && inputs.coverage === this.staticCoverage) return;
    this.staticOriginX = stepX; this.staticOriginY = stepY; this.staticRevision = revision;
    const width = statics.width / TEXELS_PER_PX, height = statics.height / TEXELS_PER_PX;
    statics.clear();
    if (inputs.coverage !== this.staticCoverage) {
      this.staticCoverage = inputs.coverage;
      if (inputs.coverage) this.rocks.setTextures([inputs.coverage.field, inputs.coverage.lookup]);
    }
    if (inputs.coverage) {
      this.staticWorld[0] = stepX; this.staticWorld[1] = stepY; this.staticWorld[2] = width; this.staticWorld[3] = height;
      this.rocks.setPosition(0, 0).setSize(statics.width, statics.height);
      statics.draw(this.rocks);
    }
    const coverage = inputs.coverage;
    inputs.occluders?.queryCircle(stepX + width * 0.5, stepY + height * 0.5, Math.hypot(width, height) * 0.5,
      (left, top, right, bottom, _edges, group) => {
        if (group === OCCLUDER_GROUP_ROCK && coverage?.covers?.(left, top, right, bottom)) return;
        const rock = group === OCCLUDER_GROUP_ROCK;
        this.stampRect(statics, stepX, stepY, left, top, right, bottom,
          encodeOccluder(rock ? OCCLUDER_HEIGHT_PX.rock : OCCLUDER_HEIGHT_PX.base, rock ? OCCLUDER_KIND_ROCK : OCCLUDER_KIND_OTHER));
      },
      (x, y, radius) => {
        statics.stamp(TEX_DISC, undefined, (x - stepX) * TEXELS_PER_PX, (y - stepY) * TEXELS_PER_PX, {
          scale: radius * 2 * TEXELS_PER_PX / DISC_SIZE, tint: encodeOccluder(OCCLUDER_HEIGHT_PX.trunk, OCCLUDER_KIND_OTHER), blendMode: this.maxBlend,
        });
      });
  }

  private stampRect(target: Phaser.GameObjects.RenderTexture, originX: number, originY: number,
    left: number, top: number, right: number, bottom: number, tint: number): void {
    target.stamp(TEX_WHITE, undefined, (left - originX) * TEXELS_PER_PX, (top - originY) * TEXELS_PER_PX, {
      originX: 0, originY: 0, scaleX: (right - left) * TEXELS_PER_PX / WHITE_SIZE, scaleY: (bottom - top) * TEXELS_PER_PX / WHITE_SIZE, tint, blendMode: this.maxBlend,
    });
  }

  private drawCasters(field: Phaser.GameObjects.RenderTexture, originX: number, originY: number, casters: readonly OccluderCaster[], animated: boolean): void {
    if (!casters.length) { this.silhouettes.begin(); return; }
    const batch = this.casterBatch, silhouettes = this.silhouettes;
    batch.begin(casters.length);
    silhouettes.begin();
    for (const caster of casters) {
      const code = encodeOccluder(caster.heightPx, caster.lampCarrier ? OCCLUDER_KIND_LAMP_CARRIER : OCCLUDER_KIND_FIGURE, caster.strength);
      // With an outline only the body's core is a disc: it closes what the picture leaves open, without rounding the contour.
      const outlined = silhouettes.add(caster.sprite, originX, originY, TEXELS_PER_PX, code);
      const diameter = caster.radius * 2 * TEXELS_PER_PX * (outlined ? FIGURE_CORE_SHARE : 1);
      const disc = outlined || caster.lampCarrier ? code : encodeOccluder(caster.heightPx, OCCLUDER_KIND_FIGURE_DISC, caster.strength);
      batch.write((caster.x - originX) * TEXELS_PER_PX, (caster.y - originY) * TEXELS_PER_PX, diameter, diameter, 0, disc, 1);
    }
    field.draw(batch.layer);
    silhouettes.drawInto(field, animated);
  }

  private ensureTargets(worldWidth: number, worldHeight: number): Phaser.GameObjects.RenderTexture {
    const width = Math.ceil(worldWidth * TEXELS_PER_PX), height = Math.ceil(worldHeight * TEXELS_PER_PX);
    if (this.field && this.field.width === width && this.field.height === height) return this.field;
    this.destroyTargets();
    const pad = Math.ceil(STATIC_STEP_PX * TEXELS_PER_PX);
    const statics = this.scene.add.renderTexture(0, 0, width + pad, height + pad)
      .setOrigin(0).setScrollFactor(0).setDepth(DEPTH_LIGHTING - 0.04).setRenderMode('redraw');
    statics.texture.setFilter(Phaser.Textures.FilterMode.NEAREST);
    const field = this.scene.add.renderTexture(0, 0, width, height)
      .setOrigin(0).setScrollFactor(0).setDepth(DEPTH_LIGHTING - 0.03).setRenderMode('redraw');
    field.texture.setFilter(Phaser.Textures.FilterMode.LINEAR);
    this.statics = statics;
    this.field = field;
    this.staticImage = new Phaser.GameObjects.Image(this.scene, 0, 0, statics.texture.key).setOrigin(0);
    this.staticOriginX = NaN;
    return field;
  }

  private destroyTargets(): void {
    this.staticImage?.destroy(); this.staticImage = null;
    this.statics?.destroy(); this.statics = null;
    this.field?.destroy(); this.field = null;
    this.mask?.destroy(); this.mask = null; this.maskDrawn = false;
  }

  private ensureTextures(): void {
    const textures = this.scene.textures;
    if (!textures.exists(TEX_WHITE)) {
      const white = textures.createCanvas(TEX_WHITE, WHITE_SIZE, WHITE_SIZE)!;
      white.context.fillStyle = '#ffffff'; white.context.fillRect(0, 0, WHITE_SIZE, WHITE_SIZE); white.refresh();
    }
    if (!textures.exists(TEX_DISC)) {
      const disc = textures.createCanvas(TEX_DISC, DISC_SIZE, DISC_SIZE)!;
      disc.context.fillStyle = '#ffffff'; disc.context.beginPath();
      disc.context.arc(DISC_SIZE / 2, DISC_SIZE / 2, DISC_SIZE / 2 - 1, 0, Math.PI * 2); disc.context.fill(); disc.refresh();
    }
  }
}

const WHITE_SIZE = 4;
const DISC_SIZE = 64;

function snapDown(value: number, step: number): number {
  return Math.floor(value / step) * step;
}
