/**
 * Sichtbarkeit eines Raums: Wer ihm beitreten darf. Der Host wählt sie, `NetworkBridge` repliziert
 * sie, die Plattform setzt sie um (Steam: Lobby-Typ, Web: nur die Aufnahme im Raum).
 */
import type { RoomVisibility } from '../types';

export const ROOM_VISIBILITIES: readonly RoomVisibility[] = ['closed', 'friends', 'public'];

export function isRoomVisibility(value: unknown): value is RoomVisibility {
  return value === 'closed' || value === 'friends' || value === 'public';
}

/** Die angebotene Stufe, die einer gewünschten am nächsten kommt (öffentlich → Freunde → allein). */
export function resolveOfferedRoomVisibility(
  wanted: RoomVisibility,
  offered: readonly RoomVisibility[],
): RoomVisibility {
  if (offered.includes(wanted)) return wanted;
  if (wanted === 'public' && offered.includes('friends')) return 'friends';
  return offered[0] ?? 'friends';
}
