/**
 * Replicated, host-decided big action of the Flammenkoloss. The host publishes every action and
 * every change of it (a stretched flight, an aborted landing) with a growing `revision`; clients only
 * draw it: body clips, the flight line, the red zones and the effects at `commitAt`.
 *
 * One timeline serves every action:
 * - `startedAt`: the body begins the action (it stands, or crouches for take-off).
 * - `markAt`: the red zone around (`x`, `y`) with `radius` shows from here (radius 0 = no zone).
 * - `releaseAt`: take-off (flight), throw (Brandsatz), first wave (siege), first beetle (beetleSalvo); the burst time otherwise.
 * - `commitAt`: the moment that hits – burst, landing, last wave, last beetle.
 * - `endsAt`: recovery done; the body hunts again.
 * `originX`/`originY` is where the body stood when the action started (the flight's take-off point).
 * The wire codec sends the kind as its index: new kinds are appended. The beetleSalvo is the one action
 * that does not hold the body: it keeps walking and flaming while it runs.
 */
export const INFERNO_COLOSSUS_ACTION_KINDS = ['transition', 'glutstoss', 'incendiary', 'siege', 'flight', 'beetleSalvo'] as const;
export type InfernoColossusActionKind = typeof INFERNO_COLOSSUS_ACTION_KINDS[number];

export interface InfernoColossusAction {
  readonly kind: InfernoColossusActionKind;
  readonly startedAt: number;
  readonly markAt: number;
  readonly releaseAt: number;
  readonly commitAt: number;
  readonly endsAt: number;
  readonly x: number;
  readonly y: number;
  readonly originX: number;
  readonly originY: number;
  readonly radius: number;
}

export interface InfernoColossusState {
  readonly revision: number;
  readonly action: InfernoColossusAction | null;
}

export const EMPTY_INFERNO_COLOSSUS_STATE: InfernoColossusState = Object.freeze({ revision: 0, action: null });

export type InfernoColossusActionPhase = 'windup' | 'release' | 'recover' | 'done';

/** Where an action stands at `now`: before release, between release and commit, after commit, or over. */
export function infernoColossusActionPhaseAt(action: InfernoColossusAction, now: number): InfernoColossusActionPhase {
  if (now >= action.endsAt) return 'done';
  if (now >= action.commitAt) return 'recover';
  return now >= action.releaseAt ? 'release' : 'windup';
}

/** Body position on the flight line at `now` (take-off point before `releaseAt`, landing after `commitAt`). */
export function infernoColossusFlightPoint(action: InfernoColossusAction, now: number): { x: number; y: number; t: number } {
  const span = Math.max(1, action.commitAt - action.releaseAt);
  const t = Math.max(0, Math.min(1, (now - action.releaseAt) / span));
  return { x: action.originX + (action.x - action.originX) * t, y: action.originY + (action.y - action.originY) * t, t };
}

const finite = (value: unknown): value is number => typeof value === 'number' && Number.isFinite(value);

/** Structural validation for decoded or remote state; invalid optional state is ignored. */
export function isInfernoColossusState(value: unknown): value is InfernoColossusState {
  if (!value || typeof value !== 'object') return false;
  const state = value as InfernoColossusState;
  if (!Number.isSafeInteger(state.revision) || state.revision < 0) return false;
  const action = state.action;
  if (action === null) return true;
  if (!action || typeof action !== 'object' || !INFERNO_COLOSSUS_ACTION_KINDS.includes(action.kind)) return false;
  const { startedAt, markAt, releaseAt, commitAt, endsAt } = action;
  if (![startedAt, markAt, releaseAt, commitAt, endsAt, action.x, action.y, action.originX, action.originY, action.radius]
    .every(finite) || action.radius < 0) return false;
  return startedAt <= markAt && markAt <= commitAt && startedAt <= releaseAt && releaseAt <= commitAt && commitAt <= endsAt;
}
