import type { PeerFailureKind } from '../network/peer/PeerSignaling';
import { getLocale, translate } from './index';
import type { Locale } from './types';

const PEER_FAILURE_KEYS: Record<PeerFailureKind, string> = {
  'broker-unreachable': 'ui.network.failure.broker-unreachable',
  'host-not-found': 'ui.network.failure.host-not-found',
  'foreign-lobby': 'ui.network.failure.foreign-lobby',
  'room-code-taken': 'ui.network.failure.room-code-taken',
  'invalid-room-code': 'ui.network.failure.invalid-room-code',
  'browser-unsupported': 'ui.network.failure.browser-unsupported',
  'connection-failed': 'ui.network.failure.connection-failed',
  'transport-overloaded': 'ui.network.failure.transport-overloaded',
  'relay-rejected': 'ui.network.failure.relay-rejected',
  'protocol-mismatch': 'ui.network.failure.protocol-mismatch',
  'host-left': 'ui.network.failure.host-left',
  'room-full': 'ui.network.failure.room-full',
  'room-closed': 'ui.network.failure.room-closed',
  'resume-expired': 'ui.network.failure.resume-expired',
};

/** All translation keys used for network failures; the record keeps them exhaustive per kind. */
export const PEER_FAILURE_TRANSLATION_KEYS: readonly string[] = Object.values(PEER_FAILURE_KEYS);

/**
 * Turns the language-neutral failure kind of the network substrate into player text.
 * The substrate itself never depends on i18n.
 */
export function describePeerFailure(kind: PeerFailureKind, locale: Locale = getLocale()): string {
  return translate(locale, PEER_FAILURE_KEYS[kind]);
}
