import type * as Phaser from 'phaser';
import { CELL_SIZE, DEPTH } from '../config';
import { dawnDecalTextureKey } from '../assets/DawnAssets';
import type { WorldDefinition } from '../config/authoring/WorldDefinition';
import { resolveCoopDefenseWorldMetrics } from '../world/WorldMetrics';

const ASH_FIELD_ALPHA = 0.85;
/** Scorch blots of one field: offset (share of the zone radius), size (share of the zone diameter), turn. */
const ASH_FIELD_BLOTS = [
  { dx: 0, dy: 0, size: 1.05, turn: 0.4, decal: 'scorch-01' },
  { dx: -0.42, dy: 0.3, size: 0.62, turn: 2.1, decal: 'scorch-03' },
  { dx: 0.45, dy: -0.28, size: 0.58, turn: 4.0, decal: 'scorch-03' },
  { dx: 0.18, dy: 0.5, size: 0.5, turn: 5.3, decal: 'scorch-01' },
] as const;

/**
 * Static burnt ground of authored ash zones (the meteor field of the Flammenkoloss): overlapping
 * scorch blots across the zone, World-owned and laid once. Missing art is skipped silently.
 */
export class AshFieldDecalRenderer {
  private readonly decals: Phaser.GameObjects.Image[] = [];

  constructor(scene: Phaser.Scene, world: WorldDefinition) {
    const metrics = resolveCoopDefenseWorldMetrics(world.metrics.widthCells, world.metrics.heightCells);
    for (const zone of world.spawnZones ?? []) {
      if (zone.ground !== 'ash') continue;
      const x = metrics.offsetX + (zone.gridX + zone.widthCells / 2) * CELL_SIZE;
      const y = metrics.offsetY + (zone.gridY + zone.heightCells / 2) * CELL_SIZE;
      const radius = Math.min(zone.widthCells, zone.heightCells) * CELL_SIZE / 2;
      for (const blot of ASH_FIELD_BLOTS) {
        const key = dawnDecalTextureKey(blot.decal);
        if (!scene.textures.exists(key)) continue;
        const size = radius * 2 * blot.size;
        // Painted just below the bases like the Dawn site scorch; never emits light.
        this.decals.push(scene.add.image(x + blot.dx * radius, y + blot.dy * radius, key)
          .setDisplaySize(size, size).setRotation(blot.turn).setAlpha(ASH_FIELD_ALPHA).setDepth(DEPTH.BASES - 0.05));
      }
    }
  }

  get count(): number { return this.decals.length; }

  destroy(): void {
    for (const decal of this.decals) decal.destroy();
    this.decals.length = 0;
  }
}
