/**
 * Transportneutrale Fehlerklassen der Netzwerk-Substratschicht. Bewusst ohne PeerJS-Bezug:
 * PeerRoom und jeder Transport (WebRTC wie Steam) melden Fehler über diese Klassen.
 */

export type PeerFailureKind =
  | 'broker-unreachable'
  | 'host-not-found'
  /** Steam: Die Lobby einer Einladung ist kein (vollständiger) Fragdachse-Raum, z. B. ein anderes Spiel unter 480. */
  | 'foreign-lobby'
  | 'room-code-taken'
  | 'invalid-room-code'
  | 'browser-unsupported'
  | 'connection-failed'
  | 'transport-overloaded'
  | 'relay-rejected'
  | 'protocol-mismatch'
  | 'host-left'
  | 'room-full'
  /** Der Host nimmt keine neuen Spieler auf (Sichtbarkeit ALLEIN). */
  | 'room-closed'
  | 'resume-expired';

export class PeerNetworkError extends Error {
  constructor(readonly kind: PeerFailureKind, message: string, readonly cause?: unknown) {
    super(message);
    this.name = 'PeerNetworkError';
  }
}

/**
 * Die Substratschicht kennt keine Spielersprache: `message` ist eine sprachneutrale
 * Diagnose fuer Logs. Spielersichtbare Texte erzeugt die UI-Schicht aus `kind`
 * (`describePeerFailure` in `src/i18n/networkFailurePresentation.ts`).
 */
export function createPeerNetworkError(kind: PeerFailureKind, cause?: unknown): PeerNetworkError {
  return new PeerNetworkError(kind, `Peer network failure: ${kind}`, cause);
}
