import type { ChunkWorldFrame } from '../chunks/ArenaChunkGrid';
import type { TerrainSnapshotMaterialSource } from '../TerrainSnapshotMaterial';

/** A water mask as `WaterSurfaceRenderer` keeps it, keyed by chunk (`cx,cy`). */
export interface PrebakedWaterMask { readonly size: number; readonly data: Uint8ClampedArray }

/**
 * Identity of a material source beyond the layout: dirt soil and base gravel are both `soil` sources
 * of the same World, with different seeds and cells.
 */
export function materialSourceSignature(source: TerrainSnapshotMaterialSource): string {
  return source.kind === 'track'
    ? `track|${source.seed}|${source.columns.length}`
    : `soil|${source.seed}|${source.dirt.length}|${source.water?.length ?? 0}|${source.tracks?.length ?? 0}`;
}

/** One terrain-snapshot material tile, identical for the lobby prebake and the World's staging. */
export function snapshotTileKey(source: TerrainSnapshotMaterialSource, x: number, y: number,
  width: number, height: number, side: number): string {
  return `${materialSourceSignature(source)}|${x}|${y}|${width}|${height}|${side}`;
}

/** One native soil tile, keyed like `DirtSurfaceLayer` keeps it. */
export function soilTileKey(x: number, y: number, size: number): string {
  return `${x}:${y}:${size}`;
}

/**
 * CPU results the lobby computed for the announced deployment, from the very layout the round start
 * reuses (Steam plan L14). The same worker jobs as the World build, so a taken result is the result
 * the World would compute itself.
 *
 * Owner: the deployment preparation of the Scene. A World built from the same prepared layout gets
 * this object; each consumer takes (removes) an entry only while its own frame matches, and computes
 * everything else as before. `seal()` stops new jobs once a World build starts; `dispose()` ends the
 * remaining jobs and frees all results.
 */
export class WorldPrebake {
  readonly waterMasks = new Map<string, PrebakedWaterMask>();
  /** Sample texels only (`compactSnapshotSamples`), a quarter of a tile. */
  readonly snapshotTiles = new Map<string, Uint8Array>();
  readonly soilTiles = new Map<string, Uint8ClampedArray>();
  private sealedState = false;
  private completeState = false;
  private disposedState = false;
  private readonly pumps: (() => void)[] = [];
  private readonly disposers: (() => void)[] = [];

  constructor(readonly frame: ChunkWorldFrame) {}

  get sealed(): boolean { return this.sealedState; }
  /** Every planned job finished; the producer marks it (diagnostics and the load probe). */
  get complete(): boolean { return this.completeState; }
  markComplete(): void { this.completeState = true; }
  get disposed(): boolean { return this.disposedState; }

  /** The World's frame equals the one the results were computed for. */
  matchesFrame(frame: ChunkWorldFrame): boolean {
    return !this.disposedState && frame.offsetX === this.frame.offsetX && frame.offsetY === this.frame.offsetY
      && frame.width === this.frame.width && frame.height === this.frame.height;
  }

  /** Producer side: results that already arrived move into the maps before a consumer looks. */
  addPump(pump: () => void): void { this.pumps.push(pump); }
  addDisposer(dispose: () => void): void { this.disposers.push(dispose); }

  pump(): void {
    if (this.disposedState) return;
    for (const pump of this.pumps) pump();
  }

  takeWaterMask(key: string): PrebakedWaterMask | null { return this.take(this.waterMasks, key); }
  takeSnapshotTile(key: string): Uint8Array | null { return this.take(this.snapshotTiles, key); }
  takeSoilTile(key: string): Uint8ClampedArray | null { return this.take(this.soilTiles, key); }

  /** A World build started from this prepared layout: running jobs finish, no new ones start. */
  seal(): void { this.sealedState = true; }

  dispose(): void {
    if (this.disposedState) return;
    this.disposedState = true;
    this.sealedState = true;
    for (const dispose of this.disposers.splice(0)) dispose();
    this.pumps.length = 0;
    this.waterMasks.clear(); this.snapshotTiles.clear(); this.soilTiles.clear();
  }

  private take<T>(map: Map<string, T>, key: string): T | null {
    if (this.disposedState) return null;
    this.pump();
    const value = map.get(key);
    if (value === undefined) return null;
    map.delete(key);
    return value;
  }
}
