/**
 * Tastenkappen der Steuerungsübersicht (Tutorial-Tafel, Options-Kurzübersicht) in der aktuellen
 * Spielerbelegung.
 */
import type { HelpControlEntry } from '../config/helpControls';
import { getLocale, translate, type Locale } from '../i18n';
import { getControlKeyLabel } from './controlBindingStore';

/** Tastenkappen zeigen die Taste in Versalien, wie die übrigen Kappen der Forest-Menüs. */
function capLabel(label: string, locale: Locale): string {
  return label.toLocaleUpperCase(locale);
}

/**
 * Beschriftung der Tastenkappe einer Zeile in der aktuellen Belegung. Einzelzeichen stehen mit
 * Leerzeichen nebeneinander („W A S D“), längere Namen mit Schrägstrich.
 */
export function formatHelpControlKey(entry: HelpControlEntry, locale: Locale = getLocale()): string {
  const input = entry.input;
  if (input.kind === 'fixed') return capLabel(translate(locale, input.labelKey), locale);
  if (input.kind === 'actions') {
    const labels = input.actions.map((action) => capLabel(getControlKeyLabel(action, locale), locale));
    return labels.join(labels.every((label) => label.length === 1) ? ' ' : ' / ');
  }
  const key = capLabel(getControlKeyLabel(input.action, locale), locale);
  return input.hold ? translate(locale, 'ui.help.hold', { key }) : key;
}

/** Kappenbreite ohne Rand; zu lange Belegungsnamen werden auf diese Breite herunterskaliert. */
export function fitKeycapLabel<T extends { width?: number; setScale(scale: number): unknown }>(text: T, maxWidth: number): T {
  const width = text.width ?? 0;
  text.setScale(width > maxWidth ? maxWidth / width : 1);
  return text;
}
