/**
 * Ein Host↔Client-Link über das Steam-Netzwerk zu genau einer SteamID.
 *
 * `rel`  → zuverlässiger, geordneter Steam-Kanal;
 * `fast` → unzuverlässiger Steam-Kanal ohne Verzögerung (Verlust und Umordnung erlaubt).
 *
 * Fragmentierung, Kompression, Backpressure und Empfangsreihenfolge kommen unverändert aus
 * `PeerSendQueue`, `PeerPacketCodec` und `PeerReceivePipeline`; die Fragmentgröße ist die
 * Kanalgrenze der Bridge. Auf der Leitung liegen dieselben Bytes wie über WebRTC: kleine
 * Nachrichten als UTF-8-JSON-Text, große als Codec-Fragmente.
 */
import { PEER_DIAGNOSTICS_RECENT_SENDS } from '../../config';
import { createPeerNetworkError, type PeerNetworkError } from '../peer/PeerNetworkError';
import { encodePeerBytes, PEER_COMPRESSION_THRESHOLD_BYTES, supportsPeerCompression } from '../peer/PeerPacketCodec';
import { PeerReceivePipeline } from '../peer/PeerReceivePipeline';
import { PeerSendQueue, type PeerSendChannel } from '../peer/PeerSendQueue';
import { encodePeerMessage, parsePeerMessage, type PeerChannelKind, type PeerMessage } from '../peer/protocol';
import {
  createPeerPayloadDiagnostics,
  type DiagnosableLink,
  type RecentSendSample,
  type TransportLinkStats,
} from '../peer/TransportDiagnostics';
import type { PeerLinkLike, PeerPayloadDiagnostics } from '../peer/transport';
import type { SteamId, SteamNetBridge, SteamSendChannel } from './SteamNetBridge';

/** JSON-Text beginnt immer mit `{`; Codec-Fragmente beginnen mit ihrer Magic-Zahl. */
const JSON_TEXT_FIRST_BYTE = 0x7b;
const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder('utf-8', { fatal: true });

export interface SteamLinkHandlers {
  onMessage: (message: PeerMessage, channel: PeerChannelKind) => void;
  /** Der Link ist geschlossen (lokal oder durch die Gegenseite). Genau einmal. */
  onClose: () => void;
}

function toSteamChannel(channel: PeerChannelKind): SteamSendChannel {
  return channel === 'rel' ? 'reliable' : 'unreliable';
}

/** Bildet ein Steam-Sendeergebnis auf die Signale ab, die `PeerSendQueue` versteht. */
class SteamSendChannelAdapter implements PeerSendChannel {
  readyState: 'open' | 'closed' = 'open';
  readonly bufferedAmount = 0;

  constructor(
    private readonly net: SteamNetBridge,
    private readonly remote: SteamId,
    private readonly channel: SteamSendChannel,
  ) {}

  send(data: string | ArrayBuffer): void {
    const bytes = typeof data === 'string' ? textEncoder.encode(data) : new Uint8Array(data);
    const result = this.net.send(this.remote, this.channel, bytes);
    if (result === 'ok') return;
    if (result === 'too-large') throw new TypeError('Steam message too large for channel');
    if (result === 'buffer-full') {
      const error = new Error('Steam send buffer full');
      error.name = 'OperationError';
      throw error;
    }
    this.readyState = 'closed';
    throw new Error('Steam session unavailable');
  }
}

export class SteamLink implements PeerLinkLike, DiagnosableLink {
  playerId = '';
  closeError?: PeerNetworkError;
  readonly createdAtMs = Date.now();
  openedAtMs = 0;

  private closed = false;
  private compressionAllowed = false;
  private droppedFastMessages = 0;
  private payloadDiagnosticsSink: ((info: PeerPayloadDiagnostics) => void) | null = null;
  private readonly recentSendSamples: RecentSendSample[] = [];
  private readonly reliableChannelAdapter: SteamSendChannelAdapter;
  private readonly fastChannelAdapter: SteamSendChannelAdapter;
  private readonly reliableSends: PeerSendQueue;
  private readonly fastSends: PeerSendQueue;
  private readonly received = new PeerReceivePipeline({
    deliver: (payload, channel) => this.parseAndDeliver(payload, channel),
    overloaded: () => {
      this.closeError = createPeerNetworkError('transport-overloaded');
      this.fail('Empfangspuffer überlastet', this.closeError);
    },
  });

  constructor(
    private readonly net: SteamNetBridge,
    readonly remoteSteamId: SteamId,
    private readonly handlers: SteamLinkHandlers,
  ) {
    this.reliableChannelAdapter = new SteamSendChannelAdapter(net, remoteSteamId, 'reliable');
    this.fastChannelAdapter = new SteamSendChannelAdapter(net, remoteSteamId, 'unreliable');
    this.reliableSends = this.createSendQueue(false);
    this.fastSends = this.createSendQueue(true);
  }

  get remotePeerId(): string {
    return this.remoteSteamId;
  }

  get isOpen(): boolean {
    return !this.closed;
  }

  // ── DiagnosableLink: Steam hat keine WebRTC-Objekte; Ping und Verlust kommen von der Bindung. ──
  readonly peerConnection = undefined;
  readonly reliableChannel = undefined;
  readonly unreliableChannel = null;
  get droppedFastCount(): number { return this.droppedFastMessages; }
  get recentSends(): readonly RecentSendSample[] { return this.recentSendSamples; }
  get reliableQueuedBytes(): number { return this.reliableSends.queuedBytes; }
  get fastQueuedBytes(): number { return this.fastSends.queuedBytes; }
  transportStats(): TransportLinkStats | null { return this.net.linkStats?.(this.remoteSteamId) ?? null; }

  setPayloadDiagnosticsSink(sink: ((info: PeerPayloadDiagnostics) => void) | null): void {
    this.payloadDiagnosticsSink = sink;
  }

  /** Steam braucht keinen Kanalaufbau: Die Sitzung entsteht mit der ersten Nachricht. */
  markOpen(): void {
    if (!this.closed && this.openedAtMs === 0) this.openedAtMs = Date.now();
  }

  send(message: PeerMessage, channel: PeerChannelKind): void {
    if (this.closed) return;
    if ((message.t === 'hello' || message.t === 'welcome') && supportsPeerCompression()) {
      message = { ...message, z: 1 };
    }
    try {
      const payload = encodePeerMessage(message);
      const bytes = encodePeerBytes(payload);
      (channel === 'fast' ? this.fastSends : this.reliableSends).enqueue({
        message,
        textLength: payload.length,
        payload: bytes,
        text: bytes.rawBytes < PEER_COMPRESSION_THRESHOLD_BYTES ? payload : undefined,
        sent: (wireBytes, item) => {
          this.recordSent(item.message, channel, wireBytes);
          this.payloadDiagnosticsSink?.(createPeerPayloadDiagnostics(item.message, channel, item.textLength, wireBytes));
        },
      });
    } catch (error) {
      this.closeError = createPeerNetworkError('transport-overloaded', error);
      this.fail('Nachricht nicht kodierbar', this.closeError);
    }
  }

  /** Eingang einer Steam-Nachricht dieser Gegenstelle. */
  receive(bytes: Uint8Array, channel: SteamSendChannel): void {
    if (this.closed || bytes.length === 0) return;
    const kind: PeerChannelKind = channel === 'reliable' ? 'rel' : 'fast';
    if (bytes[0] !== JSON_TEXT_FIRST_BYTE) {
      this.received.receive(bytes, kind);
      return;
    }
    let text: string;
    try { text = textDecoder.decode(bytes); } catch { return; }
    this.received.receive(text, kind);
  }

  /** Lokales Schließen (Raum, Kick, Heartbeat). Beendet auch die Steam-Sitzung. */
  close(): void {
    if (this.closed) return;
    this.shutdown();
    this.net.closeSession(this.remoteSteamId);
    this.handlers.onClose();
  }

  /** Schließt nur diesen Link; die Steam-Sitzung trägt sofort einen Nachfolge-Link. */
  retire(): void {
    if (this.closed) return;
    this.shutdown();
    this.handlers.onClose();
  }

  /** Die Gegenseite ist weg (Lobby verlassen, Sitzung gescheitert, Sendekanal tot). */
  fail(cause: string, error?: unknown): void {
    if (this.closed) return;
    const details = `[SteamLink] Verbindung geschlossen (steamId=${this.remoteSteamId}): ${cause}; `
      + `offen seit ${this.openedAtMs > 0 ? Date.now() - this.openedAtMs : 0} ms.`;
    if (error === undefined) console.warn(details);
    else console.warn(details, error);
    this.shutdown();
    this.net.closeSession(this.remoteSteamId);
    this.handlers.onClose();
  }

  /**
   * Schließt ohne `onClose`: Der Transport hat bereits einen terminalen Fehler gemeldet
   * (Host verloren). Ein Linkabbruch würde sonst einen sinnlosen Resume-Versuch starten.
   */
  abandon(error: PeerNetworkError): void {
    if (this.closed) return;
    this.closeError = error;
    this.shutdown();
    this.net.closeSession(this.remoteSteamId);
  }

  private shutdown(): void {
    this.closed = true;
    this.reliableChannelAdapter.readyState = 'closed';
    this.fastChannelAdapter.readyState = 'closed';
    this.reliableSends.close();
    this.fastSends.close();
    this.received.close();
  }

  private parseAndDeliver(payload: string, channel: PeerChannelKind): void {
    if (this.closed) return;
    const message = parsePeerMessage(payload);
    if (!message) return;
    if (message.t === 'hello' || message.t === 'welcome') this.compressionAllowed = message.z === 1;
    this.handlers.onMessage(message, channel);
  }

  private createSendQueue(fast: boolean): PeerSendQueue {
    const limit = fast ? this.net.limits.unreliableMessageBytes : this.net.limits.reliableMessageBytes;
    return new PeerSendQueue({
      fast,
      channel: () => fast ? this.fastChannelAdapter : this.reliableChannelAdapter,
      maxMessageSize: () => limit,
      compress: () => this.compressionAllowed,
      dropped: () => { this.droppedFastMessages++; },
      failed: (reason, error) => {
        if (reason === 'overload') this.closeError = createPeerNetworkError('transport-overloaded', error);
        const cause = reason === 'overload' ? 'Sendewarteschlange überlastet' : 'Steam-Sitzung nicht verfügbar';
        this.fail(`${cause} (${toSteamChannel(fast ? 'fast' : 'rel')})`, this.closeError ?? error);
      },
    });
  }

  private recordSent(message: PeerMessage, channel: PeerChannelKind, wireBytes: number): void {
    const samples = this.recentSendSamples;
    samples.push({ atMs: Date.now(), channel, message, wireBytes });
    if (samples.length > PEER_DIAGNOSTICS_RECENT_SENDS) samples.shift();
  }
}
