const EYE_SHARED_LIGHT_PX = 20;
const FAST_RELIEF_MIN_WEIGHT = 0.01;
/** The single stand-in for a stream of shots reaches further than one shot. */
const FAST_RELIEF_REACH = 1.5;
/** Two muzzle flashes at once mean a held trigger, whose flashes would strobe; a single shot stays in the map as a sharp flash. */
const HELD_TRIGGER_FLASHES = 2;
