import * as Phaser from 'phaser';
import { DEPTH_LIGHTING } from '../../config';
import { getClarityCameraRegistry } from '../../scenes/arena/ClarityCameraRegistry';
import { lightAddBlendMode, maxBlendMode } from '../../graphics/CustomBlendModes';
import { createColorRenderTexture } from '../../graphics/createColorRenderTexture';
import { runWithScopedBlend } from '../../graphics/PhaserScopedBlend';
import { EnemyMeshGpu } from '../EnemyMeshGpu';
import { ownSunShader, sunShaderName, SunRenderTarget } from '../sunlight/SunRenderTarget';
import { fastLightRate } from './FastLightField';
import { enableHdrShaderTarget } from './LightHdrComposite';

export const FIRE_LIGHT_HOLD_SHADER = 'FireLightHold', FIRE_LIGHT_SPREAD_SHADER = 'FireLightSpread', FIRE_LIGHT_ADD_SHADER = 'FireLightAdd';
/** World px per texel of the heat: half a burning cell. */
const TEXEL_PX = 8;
/** Fire outside the light map still glows into it, as far as the wide glow reaches. */
const MARGIN_PX = 288;
/** Radius of one cell's heat in px. Wider than the cell, so neighbours close to one surface without a grid showing. */
const CELL_HEAT_RADIUS_PX = 26;
/** A fire flares up fast and dies down slowly; a cell that goes out leaves its glow for a moment. */
const RISE_MS = 90;
const FALL_MS = 420;
/** Frames without fire until what is held has faded below a visible step. */
const QUIET_FRAMES = 150;
/**
 * Reach of the three glows in px, each spread from the one before at half its size: the near one hugs the fire, the far one
 * lights the ground around it, the wide one grows with the size of the burning area. One wide disc straight from the heat
 * would show every small fire again at each of its taps.
 */
const NEAR_GLOW_PX = 48;
const FAR_GLOW_PX = 120;
const WIDE_GLOW_PX = 260;
const SPREAD_TAPS = 12;
/**
 * Light in the map's units. Ground is dark and only shows as lit well above 1, so the glow beside a fire is strong. On the
 * flames themselves the light is held near 1 instead: they are drawn additively under the map, and a strong light would
 * push them past full brightness into flat yellow.
 */
const FLAME_LIGHT = 1.05;
const NEAR_LIGHT = 2.0;
const FAR_LIGHT = 1.8;
const WIDE_LIGHT = 2.4;
/**
 * The fire's own glow, added over the lit World and the ground fog, which lies above the flames: hot knots that wander
 * through the burning area, and a breath of colour right around it.
 */
const KNOT_GLOW = 0.34;
const NEAR_GLOW = 0.06;
const CAPACITY = 4096;
const ATTRIBUTES = [{ name: 'inCell', size: 4 }];
const INSTANCE_WORDS = 4;
/** Words per cell in a `FireCellFrame`: world x, y, heat 0..1, style 0 normal, 1 void, 2 allied. */
export const FIRE_CELL_WORDS = 4;

/**
 * Light of the three fire styles: what burns, and what its glow throws on the surroundings. The first is pale: it multiplies
 * the flames' own colour, and a saturated light would darken them.
 */
const CORE_COLORS = [1.0, 0.86, 0.62, 0.84, 0.62, 1.0, 0.74, 1.0, 0.88] as const;
const GLOW_COLORS = [1.0, 0.5, 0.17, 0.62, 0.34, 1.0, 0.36, 1.0, 0.72] as const;
/** Violet and green carry less brightness than orange at the same strength; their light is lifted to read as equally hot. */
const STYLE_GAIN = [1, 1.3, 1.15] as const;

/** This frame's burning cells of one owner; `revision` changes whenever `data` or `count` do. */
export interface FireCellFrame {
  readonly data: Float32Array;
  readonly count: number;
  readonly revision: number;
}

const VERTEX = `
precision highp float;
attribute vec2 inPosition;
// World x, y, heat, style.
attribute vec4 inCell;
uniform mat4 uProjectionMatrix;
uniform mat3 uViewMatrix;
// World x, y of the first texel, texels per world px, radius of a cell's heat in texels.
uniform vec4 uWindow;
varying vec2 local;
varying vec4 heat;
void main() {
 local=inPosition*2.0-1.0;
 vec3 view=uViewMatrix*vec3((inCell.xy-uWindow.xy)*uWindow.z+local*uWindow.w,1.0);
 gl_Position=uProjectionMatrix*vec4(view.xy,0.0,1.0);
 heat=vec4(inCell.w<.5?1.0:0.0,inCell.w>=.5&&inCell.w<1.5?1.0:0.0,inCell.w>=1.5?1.0:0.0,1.0)*inCell.z;
}`;

/** One burning cell as a soft dome; the draw keeps the hottest value, so a filled area is even instead of adding up. */
const FRAGMENT = `
precision highp float;
varying vec2 local;
varying vec4 heat;
void main() {
 float d=dot(local,local);
 if(d>=1.0)discard;
 gl_FragColor=heat*(1.0-d)*(1.0-d);
}`;

export const FIRE_LIGHT_HOLD_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uCurrent,uHeld;
uniform vec2 uTexel,uShift,uRate;
void main(){
 vec2 uv=gl_FragCoord.xy*uTexel,from=uv+uShift;
 vec3 now=texture2D(uCurrent,uv).rgb;
 bool known=from.x>=0.0&&from.y>=0.0&&from.x<=1.0&&from.y<=1.0;
 vec3 held=known?texture2D(uHeld,from).rgb:now;
 gl_FragColor=vec4(mix(held,now,mix(vec3(uRate.y),vec3(uRate.x),step(held,now))),1.0);
}`;

/** A disc over the source at this target's size: the heat spread into the glow around it. */
export const FIRE_LIGHT_SPREAD_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uSource;
uniform vec2 uTexel,uReach;
void main(){
 vec2 uv=gl_FragCoord.xy*uTexel;
 vec3 sum=texture2D(uSource,uv).rgb;
 float total=1.0;
 for(int i=0;i<${SPREAD_TAPS};i++){
  float ring=sqrt((float(i)+.5)/${SPREAD_TAPS.toFixed(1)}),angle=float(i)*2.39996,weight=1.0-ring*.55;
  sum+=texture2D(uSource,uv+vec2(cos(angle),sin(angle))*ring*uReach).rgb*weight;
  total+=weight;
 }
 gl_FragColor=vec4(sum/total,1.0);
}`;

export const FIRE_LIGHT_ADD_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
varying vec2 outTexCoord;
uniform sampler2D uHeat,uNear,uFar,uWide;
// World rectangle of the light map; world x, y and 1 / world size of the heat.
uniform vec4 uMapWorld,uHeatFrame;
uniform vec3 uCore[3];
uniform vec3 uGlow[3];
// As light: on the flames, beside them, around them; strength of the whole field. As glow: knots, beside them, unused; strength.
uniform vec4 uLight;
// Light of the wide glow.
uniform float uWideLight;
// 0 writes light into the map, 1 the fire's own glow over the World.
uniform float uGlowMode;
// Light the map already holds everywhere: the flames are only lifted to their level, not above it by that much again.
uniform float uAmbientLevel;
uniform float uTime;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){
 vec2 i=floor(p),f=fract(p);
 f=f*f*(3.0-2.0*f);
 return mix(mix(hash(i),hash(i+vec2(1.0,0.0)),f.x),mix(hash(i+vec2(0.0,1.0)),hash(i+vec2(1.0,1.0)),f.x),f.y);
}
vec3 tint(vec3 heat,vec3 colors[3]){return heat.r*colors[0]+heat.g*colors[1]+heat.b*colors[2];}
void main(){
 vec2 world=uMapWorld.xy+vec2(outTexCoord.x,1.0-outTexCoord.y)*uMapWorld.zw;
 vec2 at=(world-uHeatFrame.xy)*uHeatFrame.zw;
 vec2 uv=vec2(at.x,1.0-at.y);
 vec3 wide=texture2D(uWide,uv).rgb,far=texture2D(uFar,uv).rgb,near=texture2D(uNear,uv).rgb;
 if(wide.r+wide.g+wide.b+far.r+far.g+far.b+near.r+near.g+near.b<.003)discard;
 vec3 heat=texture2D(uHeat,uv).rgb;
 // Fire moves at three paces: tongues that lick within a hand's width, a body that breathes over a few cells, and a slow
 // swell of the whole blaze. Each lies in space as well as in time, so two spots never brighten together.
 float tongue=noise(world*.055+uTime*vec2(1.3,-1.9))*.6+noise(world*.12+uTime*vec2(-2.1,1.4))*.4;
 float lick=noise(world*.045+uTime*vec2(1.9,-2.6))*noise(world*.09+uTime*vec2(-2.4,1.7));
 float breathe=noise(world*.012+uTime*vec2(.42,.3));
 float swell=noise(vec2(uTime*.55,world.x*.0015+world.y*.0011));
 // The rim of what burns is not the rim of its cells: tongues reach out of it and draw back.
 vec3 burn=smoothstep(vec3(.3),vec3(.8),heat+(tongue-.5)*.6);
 float burning=max(burn.r,max(burn.g,burn.b));
 if(uGlowMode>.5){
  gl_FragColor=vec4((tint(burn*burn,uGlow)*uLight.x*(.1+2.2*lick)+tint(near,uGlow)*uLight.y*(.5+breathe))*uLight.w,1.0);
  return;
 }
 vec3 glow=tint(near,uGlow)*uLight.y*(.8+.4*breathe)+tint(far,uGlow)*uLight.z*(.88+.24*swell)+tint(wide,uGlow)*uWideLight*(.92+.16*swell);
 vec3 flame=tint(burn,uCore)*max(uLight.x*(.86+.28*breathe)-uAmbientLevel,0.0);
 gl_FragColor=vec4(mix(glow*uLight.w,flame,burning*.9),0.0);
}`;

/**
 * Light of burning ground. Every burning cell is one small dome of heat in a World-locked field; held over time and spread
 * twice, it is added to the light map as what burns, what lies beside it and what surrounds it. The light therefore covers
 * exactly what burns: one cell as a small flame, loose pools each for themselves, a wide field as one blaze whose glow
 * reaches further the larger it is. No ranking, no cap, and nothing the CPU does per cell and frame.
 */
export class FireLightField {
  private readonly width: number;
  private readonly height: number;
  private readonly renderer: Phaser.Renderer.WebGL.WebGLRenderer;
  private readonly gpu: EnemyMeshGpu;
  private readonly entry: Phaser.GameObjects.Shader;
  private readonly stampBlend: number;
  private readonly addBlend: number;
  private frames: ReadonlyMap<object, FireCellFrame> = new Map();
  private readonly window = new Float32Array(4);
  private readonly heatFrame = new Float32Array(4);
  private readonly mapWorld = new Float32Array(4);
  private readonly light = new Float32Array(4);
  private readonly texel = new Float32Array(2);
  private readonly shift = new Float32Array(2);
  private readonly rate = new Float32Array(2);
  private readonly nearTexel = new Float32Array(2);
  private readonly farTexel = new Float32Array(2);
  private readonly nearReach = new Float32Array(2);
  private readonly farReach = new Float32Array(2);
  private readonly wideTexel = new Float32Array(2);
  private readonly wideReach = new Float32Array(2);
  private current: Phaser.GameObjects.RenderTexture | null = null;
  private held: [SunRenderTarget, SunRenderTarget] | null = null;
  private near: SunRenderTarget | null = null;
  private far: SunRenderTarget | null = null;
  private wide: SunRenderTarget | null = null;
  private addQuad: Phaser.GameObjects.Shader | null = null;
  private glowQuad: Phaser.GameObjects.Shader | null = null;
  private readonly glow = new Float32Array(4);
  private readonly baseX: number;
  private readonly baseY: number;
  private holdTarget: SunRenderTarget | null = null;
  private unavailable = false;
  private front = 0;
  private quiet = QUIET_FRAMES;
  private drawnSignature = '';
  private originX = NaN;
  private originY = NaN;
  private lastFrame = -2;
  private timeS = 0;
  private ambientLevel = 0;
  private readonly runChain = (): void => {
    this.holdTarget?.draw(this.width, this.height);
    this.near?.draw(Math.ceil(this.width / 2), Math.ceil(this.height / 2));
    this.far?.draw(Math.ceil(this.width / 4), Math.ceil(this.height / 4));
    this.wide?.draw(Math.ceil(this.width / 8), Math.ceil(this.height / 8));
  };

  /** `mapTexelsPerPx` is the light map's scale. */
  constructor(private readonly scene: Phaser.Scene, private readonly lightMap: Phaser.GameObjects.RenderTexture, mapTexelsPerPx: number) {
    const mapWidth = lightMap.width, mapHeight = lightMap.height;
    this.baseX = lightMap.x; this.baseY = lightMap.y;
    this.width = Math.max(4, Math.ceil((mapWidth / mapTexelsPerPx + MARGIN_PX * 2) / TEXEL_PX) + 1);
    this.height = Math.max(4, Math.ceil((mapHeight / mapTexelsPerPx + MARGIN_PX * 2) / TEXEL_PX) + 1);
    this.texel[0] = 1 / this.width; this.texel[1] = 1 / this.height;
    const halfW = Math.ceil(this.width / 2), halfH = Math.ceil(this.height / 2), quarterW = Math.ceil(this.width / 4), quarterH = Math.ceil(this.height / 4);
    this.nearTexel[0] = 1 / halfW; this.nearTexel[1] = 1 / halfH; this.farTexel[0] = 1 / quarterW; this.farTexel[1] = 1 / quarterH;
    this.nearReach[0] = NEAR_GLOW_PX / (this.width * TEXEL_PX); this.nearReach[1] = NEAR_GLOW_PX / (this.height * TEXEL_PX);
    this.farReach[0] = FAR_GLOW_PX / (this.width * TEXEL_PX); this.farReach[1] = FAR_GLOW_PX / (this.height * TEXEL_PX);
    this.wideTexel[0] = 1 / Math.ceil(this.width / 8); this.wideTexel[1] = 1 / Math.ceil(this.height / 8);
    this.wideReach[0] = WIDE_GLOW_PX / (this.width * TEXEL_PX); this.wideReach[1] = WIDE_GLOW_PX / (this.height * TEXEL_PX);
    this.window[2] = 1 / TEXEL_PX; this.window[3] = CELL_HEAT_RADIUS_PX / TEXEL_PX;
    this.heatFrame[2] = 1 / (this.width * TEXEL_PX); this.heatFrame[3] = 1 / (this.height * TEXEL_PX);
    const renderer = this.renderer = scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer;
    this.stampBlend = maxBlendMode(renderer);
    this.addBlend = lightAddBlendMode(renderer);
    this.gpu = new EnemyMeshGpu(renderer, sunShaderName('FireLightCell'), VERTEX, FRAGMENT, new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]), 2,
      new Uint16Array([0, 1, 2, 0, 2, 3]), ATTRIBUTES, CAPACITY);
    const name = sunShaderName('FireLightEntry'), owner = this;
    const entry = new Phaser.GameObjects.Shader(scene, { name, shaderName: name, fragmentSource: 'precision mediump float;void main(){gl_FragColor=vec4(0.0);}' }, 0, 0, 1, 1);
    ownSunShader(entry, name);
    entry.renderNode.run = function (context, object, parent): void {
      runWithScopedBlend(this, () => owner.drawCells(context), context, owner.stampBlend, object, parent);
    };
    this.entry = entry.setOrigin(0);
  }

  /** Fire is still dying down, so the light map has to be drawn although nothing burns any more. */
  get busy(): boolean { return this.quiet < QUIET_FRAMES; }

  /** The fire's own glow lies over the World; without a frame's `finish` it is hidden. */
  hide(): void { this.glowQuad?.setVisible(false); }

  /**
   * Draws the heat, lets it rise and fall, and adds its light to the map. The rectangle is the map's in world px; `strength`
   * scales the whole field with the time of day, `ambientLevel` is the brightness the map holds without any light.
   */
  finish(cells: ReadonlyMap<object, FireCellFrame>, worldX: number, worldY: number, worldWidth: number, worldHeight: number, deltaMs: number, strength: number,
    ambientLevel: number, offsetX: number, offsetY: number): void {
    const map = this.lightMap, frame = this.scene.game.loop.frame, resumed = frame - this.lastFrame > 1;
    this.lastFrame = frame;
    this.frames = cells;
    const burning = cells.size > 0;
    this.quiet = burning ? 0 : Math.min(QUIET_FRAMES, this.quiet + 1);
    if (this.unavailable || strength <= 0 || !this.busy || !this.gpu.prepare()) { this.hide(); return; }
    const current = this.ensureCurrent();
    if (!current || !this.ensureChain()) { this.unavailable = true; return; }

    const originX = Math.floor((worldX - MARGIN_PX) / TEXEL_PX) * TEXEL_PX, originY = Math.floor((worldY - MARGIN_PX) / TEXEL_PX) * TEXEL_PX;
    const fresh = resumed || Number.isNaN(this.originX);
    this.shift[0] = fresh ? 0 : (originX - this.originX) / (this.width * TEXEL_PX);
    this.shift[1] = fresh ? 0 : -(originY - this.originY) / (this.height * TEXEL_PX);
    const moved = originX !== this.originX || originY !== this.originY;
    this.originX = originX; this.originY = originY;
    this.window[0] = originX; this.window[1] = originY;
    this.heatFrame[0] = originX; this.heatFrame[1] = originY;

    // The cells are only drawn again when they or the window changed; between that the target keeps its picture.
    let signature = `${originX}:${originY}`;
    for (const cells of this.frames.values()) signature += `:${cells.revision}:${cells.count}`;
    if (signature !== this.drawnSignature || moved) {
      this.drawnSignature = signature;
      current.clear().fill(0, 1);
      if (burning) {
        this.entry.setPosition(0, 0).setSize(current.width, current.height);
        current.draw(this.entry);
      }
    }
    this.rate[0] = fresh ? 1 : fastLightRate(deltaMs, RISE_MS); this.rate[1] = fresh ? 1 : fastLightRate(deltaMs, FALL_MS);
    const held = this.held!, from = held[this.front], to = held[1 - this.front];
    to.shader.setTextures([current.texture, from.shader.texture!]);
    this.near!.shader.setTextures([to.shader.texture!]);
    this.holdTarget = to;
    (current.texture as Phaser.Textures.DynamicTexture).callback(this.runChain);
    this.front = 1 - this.front;

    this.timeS = (this.timeS + Math.min(deltaMs, 100) / 1000) % 3600;
    this.ambientLevel = ambientLevel;
    this.mapWorld[0] = worldX; this.mapWorld[1] = worldY; this.mapWorld[2] = worldWidth; this.mapWorld[3] = worldHeight;
    this.light[0] = FLAME_LIGHT; this.light[1] = NEAR_LIGHT; this.light[2] = FAR_LIGHT; this.light[3] = strength;
    const quad = this.addQuad ??= this.createAddQuad();
    quad.setTextures([to.shader.texture!, this.near!.shader.texture!, this.far!.shader.texture!, this.wide!.shader.texture!]);
    quad.setSize(map.width, map.height);
    map.draw(quad);

    this.glow[0] = KNOT_GLOW; this.glow[1] = NEAR_GLOW; this.glow[2] = 0; this.glow[3] = strength;
    const glow = this.glowQuad ??= this.createGlowQuad();
    glow.setTextures([to.shader.texture!, this.near!.shader.texture!, this.far!.shader.texture!, this.wide!.shader.texture!]);
    glow.setPosition(this.baseX + offsetX, this.baseY + offsetY).setVisible(true);
  }

  destroy(): void {
    this.current?.destroy(); this.current = null;
    for (const target of this.held ?? []) target.destroy();
    this.held = null; this.holdTarget = null;
    this.near?.destroy(); this.near = null;
    this.far?.destroy(); this.far = null;
    this.wide?.destroy(); this.wide = null;
    this.addQuad?.destroy(); this.addQuad = null;
    this.glowQuad?.destroy(); this.glowQuad = null;
    this.entry.destroy();
    this.gpu.destroy();
  }

  private drawCells(context: Phaser.Renderer.WebGL.DrawingContext): void {
    const camera = context.camera!.getViewMatrix(!context.useCanvas);
    this.renderer.setProjectionMatrixFromDrawingContext(context);
    const view = [camera.a, camera.b, 0, camera.c, camera.d, 0, camera.tx, camera.ty, 1];
    for (const cells of this.frames.values()) {
      for (let first = 0; first < cells.count; first += CAPACITY) {
        const count = Math.min(CAPACITY, cells.count - first);
        this.gpu.draw(context, cells.data.subarray(first * FIRE_CELL_WORDS, (first + count) * INSTANCE_WORDS), count, [], set => {
          set('uProjectionMatrix', this.renderer.projectionMatrix.val);
          set('uViewMatrix', view); set('uWindow', this.window);
        });
      }
    }
  }

  private ensureCurrent(): Phaser.GameObjects.RenderTexture | null {
    if (this.current) return this.current;
    const target = createColorRenderTexture(this.scene, this.width, this.height);
    // Before the light map, which takes the spread heat as light.
    target.setOrigin(0).setScrollFactor(0).setDepth(DEPTH_LIGHTING - 0.022).setRenderMode('redraw');
    target.texture.setFilter(Phaser.Textures.FilterMode.LINEAR);
    return this.current = target;
  }

  private ensureChain(): boolean {
    if (this.held) return true;
    const hold = (): SunRenderTarget => {
      const target = new SunRenderTarget(this.scene, 'FireLightHold', FIRE_LIGHT_HOLD_FRAGMENT, set => {
        set('uCurrent', 0); set('uHeld', 1); set('uTexel', this.texel); set('uShift', this.shift); set('uRate', this.rate);
      }, ['__WHITE', '__WHITE'], FIRE_LIGHT_HOLD_SHADER);
      target.draw(this.width, this.height);
      return target;
    };
    const first = hold(), second = hold();
    // What is held fades in ever smaller steps; in eight bits it would stop short of dark.
    if (!enableHdrShaderTarget(this.scene, first) || !enableHdrShaderTarget(this.scene, second)) { first.destroy(); second.destroy(); return false; }
    const spread = (texel: Float32Array, reach: Float32Array): SunRenderTarget =>
      new SunRenderTarget(this.scene, 'FireLightSpread', FIRE_LIGHT_SPREAD_FRAGMENT, set => { set('uSource', 0); set('uTexel', texel); set('uReach', reach); }, ['__WHITE'], FIRE_LIGHT_SPREAD_SHADER);
    this.near = spread(this.nearTexel, this.nearReach);
    this.far = spread(this.farTexel, this.farReach);
    this.near.draw(Math.ceil(this.width / 2), Math.ceil(this.height / 2));
    this.far.draw(Math.ceil(this.width / 4), Math.ceil(this.height / 4));
    this.far.shader.setTextures([this.near.shader.texture!]);
    this.wide = spread(this.wideTexel, this.wideReach);
    this.wide.draw(Math.ceil(this.width / 8), Math.ceil(this.height / 8));
    this.wide.shader.setTextures([this.far.shader.texture!]);
    this.held = [first, second];
    return true;
  }

  private createQuad(core: Float32Array, light: Float32Array, glowMode: number, width: number, height: number): Phaser.GameObjects.Shader {
    const quad = new Phaser.GameObjects.Shader(this.scene, {
      name: FIRE_LIGHT_ADD_SHADER, shaderName: FIRE_LIGHT_ADD_SHADER, fragmentSource: FIRE_LIGHT_ADD_FRAGMENT,
      setupUniforms: (set: (name: string, value: unknown) => void) => {
        set('uHeat', 0); set('uNear', 1); set('uFar', 2); set('uWide', 3); set('uWideLight', WIDE_LIGHT); set('uMapWorld', this.mapWorld); set('uHeatFrame', this.heatFrame);
        set('uCore[0]', core); set('uGlow[0]', GLOW_LIGHTS); set('uLight', light); set('uGlowMode', glowMode); set('uAmbientLevel', this.ambientLevel); set('uTime', this.timeS);
      },
    }, 0, 0, width, height, ['__WHITE', '__WHITE', '__WHITE', '__WHITE']);
    ownSunShader(quad, FIRE_LIGHT_ADD_SHADER, true);
    return quad.setOrigin(0);
  }

  /** The same field once more, over the lit World: saturated, so the flames keep their colour where the light lifts them. */
  private createGlowQuad(): Phaser.GameObjects.Shader {
    const map = this.lightMap, quad = this.createQuad(GLOW_LIGHTS, this.glow, 1, map.displayWidth, map.displayHeight);
    quad.setTextureCoordinatesFromFrame(map.frame);
    quad.setScrollFactor(0).setDepth(DEPTH_LIGHTING + 0.002).setBlendMode(Phaser.BlendModes.ADD).setName('fire-glow');
    this.scene.add.existing(quad);
    getClarityCameraRegistry(this.scene)?.demote(quad);
    return quad;
  }

  private createAddQuad(): Phaser.GameObjects.Shader {
    const quad = this.createQuad(CORE_LIGHTS, this.light, 0, 2, 2);
    const blend = this.addBlend, node = quad.renderNode, run = node.run;
    node.run = function (context, object, parent): void { runWithScopedBlend(this, run, context, blend, object, parent); };
    return quad;
  }
}

const CORE_LIGHTS = new Float32Array(CORE_COLORS.map((value, i) => value * STYLE_GAIN[Math.floor(i / 3)]));
