import * as Phaser from 'phaser';
import { loadingTimeline } from '../diagnostics/LoadingTimeline';
import { ROCK_OVERLAY_CHUNK_SIZE } from './RockOverlayRegions';
import type { ChunkWorldFrame } from './chunks/ArenaChunkGrid';
import type { ChunkBakeRegion } from './chunks/ChunkedRenderSurface';
import type { GroundSnapshotRegion } from './chunks/GroundSurfaceStreamer';
import type { TerrainSnapshotMaterialSource } from './TerrainSnapshotMaterial';
import { TERRAIN_MATERIAL_WORKERS, TerrainSnapshotWorkerClient } from './TerrainSnapshotWorkerClient';
import { expandSnapshotSamples } from './TerrainSnapshotSampling';
import { snapshotTileKey, type WorldPrebake } from './prebake/WorldPrebake';

let nextId = 0;

/** Build-owned material staging. Workers supply exact linear-filter support texels;
 * the camera keeps the original filtering and premultiplied blend. Tiles of one
 * region never overlap, so they draw in any order; regions and layers stay in call order.
 * Headless/workerless ports retain the native bake fallback. Scratch images are
 * borrowed only until the next generator yield; false means asynchronous waiting. */
export class TerrainSnapshotStaging {
  private texture: Phaser.Textures.CanvasTexture | null = null;
  private image: Phaser.GameObjects.Image | null = null;
  /** Created on demand: a region with a single tile keeps a single worker. */
  private readonly workers: TerrainSnapshotWorkerClient[] = [];
  private readonly buffers: ArrayBuffer[] = [];

  constructor(private readonly scene: Phaser.Scene, private readonly size: number,
    private readonly maxWorkers = TERRAIN_MATERIAL_WORKERS,
    /** Tiles the lobby prepared from the same layout (Steam plan L14), kept as their sample texels. */
    private readonly prebake: WorldPrebake | null = null) {}

  private idleWorker(): TerrainSnapshotWorkerClient | null {
    const idle = this.workers.find(worker => worker.canRequest());
    if (idle || this.workers.length >= this.maxWorkers) return idle ?? null;
    const worker = new TerrainSnapshotWorkerClient();
    this.workers.push(worker);
    return worker;
  }

  *draw(
    target: Phaser.GameObjects.RenderTexture,
    region: GroundSnapshotRegion,
    frame: ChunkWorldFrame,
    write: (part: ChunkBakeRegion) => ImageData | null,
    source?: TerrainSnapshotMaterialSource,
  ): Generator<void | false, void> {
    if (!this.texture) {
      this.texture = this.scene.textures.createCanvas(`__terrain_snapshot_stage_${nextId++}`, this.size, this.size);
      if (!this.texture) throw new Error('[TerrainColorSnapshot] Could not allocate material staging.');
      this.texture.setFilter(Phaser.Textures.FilterMode.LINEAR);
      this.image = new Phaser.GameObjects.Image(this.scene, 0, 0, this.texture.key).setOrigin(0);
    }
    const texture = this.texture;
    if (source && typeof Worker !== 'undefined') {
      const tiles: { x: number; y: number }[] = [];
      const prepared = this.prebake?.matchesFrame(frame) ? this.prebake : null;
      for (let y = 0; y < region.height; y += this.size) for (let x = 0; x < region.width; x += this.size) {
        const width = Math.min(this.size, region.width - x), height = Math.min(this.size, region.height - y);
        const samples = prepared?.takeSnapshotTile(snapshotTileKey(source, region.worldX + x, region.worldY + y, width, height, this.size));
        if (!samples) { tiles.push({ x, y }); continue; }
        // A prepared tile is the worker's own result; only its sample texels were kept.
        const started = loadingTimeline.start();
        const buffer = this.buffers.pop() ?? new ArrayBuffer(this.size * this.size * 4), pixels = new Uint8ClampedArray(buffer);
        expandSnapshotSamples(samples, this.size, pixels);
        this.drawTile(target, region.worldX + x, region.worldY + y, pixels);
        this.buffers.push(buffer);
        loadingTimeline.end('terrain-snapshot/prebaked-tile', started);
        yield;
      }
      // Oldest first: every worker holds at most one tile, so the claim order is deterministic.
      const inFlight: { x: number; y: number; worker: TerrainSnapshotWorkerClient }[] = [];
      let next = 0;
      while (next < tiles.length || inFlight.length) {
        for (let worker = next < tiles.length ? this.idleWorker() : null; worker; worker = next < tiles.length ? this.idleWorker() : null) {
          const { x, y } = tiles[next++];
          worker.request(source, this.size, region.worldX + x, region.worldY + y,
            Math.min(this.size, region.width - x), Math.min(this.size, region.height - y),
            this.buffers.pop() ?? new ArrayBuffer(this.size * this.size * 4));
          inFlight.push({ x, y, worker });
        }
        // Only an abandoned earlier draw could leave every worker holding an unclaimed tile.
        if (!inFlight.length) throw new Error('[TerrainColorSnapshot] Invalid worker request lifetime.');
        const oldest = inFlight[0], buffer = oldest.worker.take();
        if (!buffer) { yield false; continue; }
        inFlight.shift();
        const started = loadingTimeline.start();
        this.drawTile(target, region.worldX + oldest.x, region.worldY + oldest.y, new Uint8ClampedArray(buffer));
        this.buffers.push(buffer);
        loadingTimeline.end('terrain-snapshot/material-upload-draw', started);
        yield;
      }
      return;
    }
    const size = ROCK_OVERLAY_CHUNK_SIZE;
    // Batch native tiles into a bounded upload. Tile boundaries remain aligned to
    // the snapshot sampling grid; linear filtering never crosses an old tile edge.
    for (let by = 0; by < region.height; by += this.size) for (let bx = 0; bx < region.width; bx += this.size) {
      texture.context.clearRect(0, 0, this.size, this.size);
      let populated = false;
      const height = Math.min(this.size, region.height - by), width = Math.min(this.size, region.width - bx);
      for (let y = 0; y < height; y += size) for (let x = 0; x < width; x += size) {
        const worldX = region.worldX + bx + x, worldY = region.worldY + by + y;
        const localX = worldX - frame.offsetX, localY = worldY - frame.offsetY;
        const started = loadingTimeline.start();
        const pixels = write({ chunk: { cx: 0, cy: 0, localX, localY }, localX, localY,
          worldX, worldY, size, gutterPx: 0 });
        if (pixels) {
          // The original scratch clipped the larger, gutter-capable source to size.
          texture.context.putImageData(pixels, x, y, 0, 0, size, size);
          populated = true;
        }
        loadingTimeline.end('terrain-snapshot/material-cpu', started);
        yield;
      }
      if (populated) {
        const started = loadingTimeline.start();
        texture.refresh();
        this.image!.setPosition(region.worldX + bx, region.worldY + by);
        target.draw(this.image!);
        // Flush before a later batch reuses this canvas, including across frames.
        target.render();
        loadingTimeline.end('terrain-snapshot/material-upload-draw', started);
      }
      yield;
    }
  }

  private drawTile(target: Phaser.GameObjects.RenderTexture, worldX: number, worldY: number, pixels: Uint8ClampedArray): void {
    const texture = this.texture!;
    texture.context.putImageData(new ImageData(pixels, this.size, this.size), 0, 0);
    texture.refresh();
    this.image!.setPosition(worldX, worldY);
    target.draw(this.image!);
    target.render();
  }

  destroy(): void {
    for (const worker of this.workers) worker.destroy();
    this.workers.length = 0; this.buffers.length = 0;
    this.image?.destroy();
    if (this.texture) this.scene.textures.remove(this.texture.key);
    this.image = null;
    this.texture = null;
  }
}
