/** Axis-aligned cell bounds of a base body (Arcade static bodies expose left/right/top/bottom). */
export interface BaseCellBounds {
  readonly left: number;
  readonly right: number;
  readonly top: number;
  readonly bottom: number;
}

/** Closest distance from (x, y) to any of the cells (0 inside one). */
export function distanceToCells(cells: Iterable<BaseCellBounds>, x: number, y: number): number {
  let distance = Infinity;
  for (const b of cells) {
    const dx = Math.max(b.left - x, 0, x - b.right), dy = Math.max(b.top - y, 0, y - b.bottom);
    distance = Math.min(distance, Math.sqrt(dx * dx + dy * dy));
  }
  return distance;
}

/**
 * Whether a segment from (ax, ay) to (bx, by), swept with `radius`, touches one of the cells: the
 * closest distance between the cell rectangle and points sampled along the segment.
 */
export function sweptSegmentTouchesCells(cells: Iterable<BaseCellBounds>, ax: number, ay: number, bx: number, by: number,
  radius: number, samples = 8): boolean {
  const radiusSq = radius * radius;
  for (const b of cells) {
    for (let i = 0; i <= samples; i++) {
      const x = ax + (bx - ax) * i / samples, y = ay + (by - ay) * i / samples;
      const dx = Math.max(b.left - x, 0, x - b.right), dy = Math.max(b.top - y, 0, y - b.bottom);
      if (dx * dx + dy * dy <= radiusSq) return true;
    }
  }
  return false;
}
