/**
 * Building blocks of the new light that can be judged one by one. Shipped builds run them all;
 * only the dev server and the performance lab can switch one off.
 */
export const LIGHTING_FEATURES = ['fogLight', 'surfaceShaping', 'figureRelief', 'groundRelief', 'groundLightVectors', 'groundNearSoft', 'softShadowEdge', 'figureShadowContact', 'figureShadowAnimated', 'figureEdgeBlend', 'lightMapWorldGrid', 'fireLightField', 'vividLight', 'ownGlowYield', 'indirectLight'] as const;
export type LightingFeature = typeof LIGHTING_FEATURES[number];

export const LIGHTING_FEATURE_LABELS: Readonly<Record<LightingFeature, string>> = {
  fogLight: 'Licht im Nebel',
  surfaceShaping: 'Felsen und Bauten formen (alle Lichter)',
  figureRelief: 'Relief an Figuren und Türmen',
  groundRelief: 'Boden: Form und Schatten',
  groundLightVectors: 'Boden: gemeinsame Lichtrichtung (aus: stärkstes Licht gewinnt)',
  groundNearSoft: 'Boden: nahes Licht wirft weichere Schatten',
  softShadowEdge: 'Schatten: glatte Kante direkt hinter Figuren',
  figureShadowContact: 'Schatten: schließt direkt an die Figur an (aus: heller Saum)',
  figureShadowAnimated: 'Schatten: folgt der Laufanimation (aus: Ruhepose)',
  figureEdgeBlend: 'Schatten: weicher Übergang an der Figurenkante (aus: harte Schwelle)',
  lightMapWorldGrid: 'Lichtkarte: festes Weltraster (aus: gleitet mit der Kamera)',
  fireLightField: 'Bodenfeuer: Lichtfeld und Eigenglühen (aus: ein Licht je Block)',
  vividLight: 'Farbe: kräftiges Licht, Überlagerung bleibt farbig (aus: blass, kippt ins Weiße)',
  ownGlowYield: 'Figurenschein weicht fremdem Licht',
  indirectLight: 'Streulicht (nur Ultra)',
};

const switchable = import.meta.env.DEV || __PERFORMANCE_LAB__;
const off = new Set<LightingFeature>();
const listeners = new Set<() => void>();

export function isLightingFeature(value: unknown): value is LightingFeature {
  return LIGHTING_FEATURES.includes(value as LightingFeature);
}

export function isLightingFeatureOn(feature: LightingFeature): boolean {
  return !off.has(feature);
}

export function setLightingFeature(feature: LightingFeature, on: boolean): void {
  if (!switchable || on === isLightingFeatureOn(feature)) return;
  if (on) off.delete(feature); else off.add(feature);
  for (const listener of listeners) listener();
}

/** Switches off exactly the listed features and on all others. */
export function setLightingFeaturesOff(features: readonly LightingFeature[]): void {
  for (const feature of LIGHTING_FEATURES) setLightingFeature(feature, !features.includes(feature));
}

export function getLightingFeaturesOff(): readonly LightingFeature[] {
  return LIGHTING_FEATURES.filter(feature => off.has(feature));
}

/** Strength of the bounce; the dev panel can change it to judge the effect. */
export const INDIRECT_LIGHT_GAIN = 3.5;
let indirectGain = INDIRECT_LIGHT_GAIN;

export function getIndirectLightGain(): number { return indirectGain; }

export function setIndirectLightGain(gain: number): void {
  if (!switchable || gain === indirectGain) return;
  indirectGain = gain;
  for (const listener of listeners) listener();
}

/** Where the form of plants and stones comes from; all three are baked side by side, to be judged in the game. */
export const GROUND_DETAILS = ['outline', 'brightness', 'depth'] as const;
export type GroundDetail = typeof GROUND_DETAILS[number];
export const GROUND_DETAIL_LABELS: Readonly<Record<GroundDetail, string>> = { outline: 'Umriss', brightness: 'Umriss und Helligkeit', depth: 'Höhenbild je Pflanze' };
let groundDetail: GroundDetail = 'depth';

export function getGroundDetail(): GroundDetail { return groundDetail; }

export function setGroundDetail(detail: GroundDetail): void {
  if (!switchable || detail === groundDetail) return;
  groundDetail = detail;
  for (const listener of listeners) listener();
}

export function onLightingFeaturesChange(listener: () => void): () => void {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}
