import * as Phaser from 'phaser';
import { DEPTH_LIGHTING } from '../../config';
import { lightAddBlendMode } from '../../graphics/CustomBlendModes';
import { createColorRenderTexture } from '../../graphics/createColorRenderTexture';
import { runWithScopedBlend } from '../../graphics/PhaserScopedBlend';
import { ownSunShader, SunRenderTarget } from '../sunlight/SunRenderTarget';
import { enableHdrShaderTarget, enableHdrTarget } from './LightHdrComposite';

export const FAST_LIGHT_HOLD_SHADER = 'FastLightHold', FAST_LIGHT_ADD_SHADER = 'FastLightAdd';
/** Share of the light map's resolution; these lights are soft discs. */
export const FAST_LIGHT_FIELD_SCALE = 0.5;
/** A new light shows almost at once; what it leaves behind fades slowly enough to reach the next shot of a held trigger. */
export const FAST_LIGHT_RISE_MS = 16;
export const FAST_LIGHT_FALL_MS = 130;
/** Frames after the last light until what is held has faded below a visible step. */
const QUIET_FRAMES = 40;

export const FAST_LIGHT_HOLD_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uCurrent,uHeld;
uniform vec2 uTexel,uShift,uRate;
void main(){
 vec2 uv=gl_FragCoord.xy*uTexel;
 vec2 from=uv+uShift;
 bool known=from.x>=0.0&&from.y>=0.0&&from.x<=1.0&&from.y<=1.0;
 vec3 now=texture2D(uCurrent,uv).rgb,held=known?texture2D(uHeld,from).rgb:vec3(0.0);
 gl_FragColor=vec4(mix(held,now,mix(vec3(uRate.y),vec3(uRate.x),step(held,now))),1.0);
}`;

export const FAST_LIGHT_ADD_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
varying vec2 outTexCoord;
uniform sampler2D uHeld;
void main(){ gl_FragColor=vec4(texture2D(uHeld,outTexCoord).rgb,0.0); }`;

/** Share of the way to a new value after `deltaMs`, independent of the frame rate. */
export function fastLightRate(deltaMs: number, timeMs: number): number {
  return 1 - Math.exp(-deltaMs / timeMs);
}

/**
 * Lights that pass a spot within a few frames. Drawn one by one they and their shadows strobe with every
 * shot; here they add up over time, so a held trigger reads as one steady glow whose shadows blend into each other.
 */
export class FastLightField {
  private readonly width: number;
  private readonly height: number;
  private readonly addBlend: number;
  private current: Phaser.GameObjects.RenderTexture | null = null;
  private held: [SunRenderTarget, SunRenderTarget] | null = null;
  private addQuad: Phaser.GameObjects.Shader | null = null;
  private holdTarget: SunRenderTarget | null = null;
  private front = 0;
  private count = 0;
  private cleared = false;
  private quiet = QUIET_FRAMES;
  private lastWorldX = NaN;
  private lastWorldY = NaN;
  private readonly texel = new Float32Array(2);
  private readonly shift = new Float32Array(2);
  private readonly rate = new Float32Array(2);
  private readonly runHold = (): void => { this.holdTarget?.draw(this.width, this.height); };

  /** `mapWidth` and `mapHeight` are in light-map texels. */
  constructor(private readonly scene: Phaser.Scene, mapWidth: number, mapHeight: number, private readonly radialTexture: string, private readonly radialHalfSize: number) {
    this.width = Math.max(2, Math.ceil(mapWidth * FAST_LIGHT_FIELD_SCALE));
    this.height = Math.max(2, Math.ceil(mapHeight * FAST_LIGHT_FIELD_SCALE));
    this.addBlend = lightAddBlendMode(scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer);
    this.texel[0] = 1 / this.width; this.texel[1] = 1 / this.height;
  }

  /** Light is still fading, so the map has to be drawn although nothing new shines. */
  get busy(): boolean { return this.quiet < QUIET_FRAMES; }

  /** Where this frame's lights go; null when no float target is available and the caller has to draw them itself. */
  get target(): Phaser.GameObjects.RenderTexture | null {
    const current = this.ensureCurrent();
    if (current) this.prepare(current);
    return current;
  }

  /** Position and radius in light-map texels. */
  add(x: number, y: number, radius: number, color: number, intensity: number): boolean {
    const current = this.target;
    if (!current) return false;
    current.stamp(this.radialTexture, undefined, x * FAST_LIGHT_FIELD_SCALE, y * FAST_LIGHT_FIELD_SCALE, {
      alpha: intensity, tint: color, scale: radius * FAST_LIGHT_FIELD_SCALE / this.radialHalfSize, blendMode: this.addBlend,
    });
    this.count += 1;
    return true;
  }

  /** A light somebody else drew into `target` this frame. */
  noteLight(): void { this.count += 1; }

  /** Folds this frame's lights into what is held and adds the result to the light map. `worldX`, `worldY` and `worldWidth`, `worldHeight` describe the map. */
  finish(map: Phaser.GameObjects.RenderTexture, worldX: number, worldY: number, worldWidth: number, worldHeight: number, deltaMs: number): void {
    const hadLight = this.count > 0;
    this.quiet = hadLight ? 0 : this.quiet + 1;
    this.count = 0;
    if (!hadLight && !this.busy) { this.cleared = false; this.lastWorldX = worldX; this.lastWorldY = worldY; return; }
    const current = this.ensureCurrent();
    if (!current || !this.ensureHeld()) return;
    this.prepare(current);
    this.cleared = false;
    this.shift[0] = Number.isNaN(this.lastWorldX) ? 0 : (worldX - this.lastWorldX) / worldWidth;
    this.shift[1] = Number.isNaN(this.lastWorldY) ? 0 : -(worldY - this.lastWorldY) / worldHeight;
    this.lastWorldX = worldX; this.lastWorldY = worldY;
    this.rate[0] = fastLightRate(deltaMs, FAST_LIGHT_RISE_MS); this.rate[1] = fastLightRate(deltaMs, FAST_LIGHT_FALL_MS);
    const held = this.held!, from = held[this.front], to = held[1 - this.front];
    to.shader.setTextures([current.texture, from.shader.texture!]);
    this.holdTarget = to;
    (current.texture as Phaser.Textures.DynamicTexture).callback(this.runHold);
    this.front = 1 - this.front;
    const quad = this.addQuad ??= this.createAddQuad(to);
    quad.setTextures([to.shader.texture!]);
    quad.setSize(map.width, map.height);
    map.draw(quad);
  }

  destroy(): void {
    this.current?.destroy(); this.current = null;
    for (const target of this.held ?? []) target.destroy();
    this.held = null; this.holdTarget = null;
    this.addQuad?.destroy(); this.addQuad = null;
  }

  private prepare(current: Phaser.GameObjects.RenderTexture): void {
    if (this.cleared) return;
    // The add mode leaves alpha alone, and a float target must stay opaque.
    current.clear().fill(0, 1);
    this.cleared = true;
  }

  private ensureCurrent(): Phaser.GameObjects.RenderTexture | null {
    if (this.current) return this.current;
    const target = createColorRenderTexture(this.scene, this.width, this.height);
    // After the occluder field, whose distance field the shadowed lights read, and before the light map.
    target.setOrigin(0).setScrollFactor(0).setDepth(DEPTH_LIGHTING - 0.02).setRenderMode('redraw');
    target.texture.setFilter(Phaser.Textures.FilterMode.LINEAR);
    if (!enableHdrTarget(this.scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer, target.texture as Phaser.Textures.DynamicTexture)) { target.destroy(); return null; }
    return this.current = target;
  }

  private ensureHeld(): boolean {
    if (this.held) return true;
    const make = (): SunRenderTarget => {
      const target = new SunRenderTarget(this.scene, 'FastLightHold', FAST_LIGHT_HOLD_FRAGMENT, set => {
        set('uCurrent', 0); set('uHeld', 1); set('uTexel', this.texel); set('uShift', this.shift); set('uRate', this.rate);
      }, ['__WHITE', '__WHITE'], FAST_LIGHT_HOLD_SHADER);
      target.draw(this.width, this.height);
      return target;
    };
    const first = make(), second = make();
    if (!enableHdrShaderTarget(this.scene, first) || !enableHdrShaderTarget(this.scene, second)) { first.destroy(); second.destroy(); return false; }
    this.held = [first, second];
    return true;
  }

  private createAddQuad(source: SunRenderTarget): Phaser.GameObjects.Shader {
    const quad = new Phaser.GameObjects.Shader(this.scene, {
      name: FAST_LIGHT_ADD_SHADER, shaderName: FAST_LIGHT_ADD_SHADER, fragmentSource: FAST_LIGHT_ADD_FRAGMENT,
      setupUniforms: (set: (name: string, value: unknown) => void) => { set('uHeld', 0); },
    }, 0, 0, 2, 2, [source.shader.texture!]);
    ownSunShader(quad, FAST_LIGHT_ADD_SHADER, true);
    quad.setOrigin(0);
    const blend = this.addBlend, node = quad.renderNode, run = node.run;
    node.run = function (context, object, parent): void { runWithScopedBlend(this, run, context, blend, object, parent); };
    return quad;
  }
}
