import * as Phaser from 'phaser';
import { COLOSSUS_EMISSION_FRAGMENT_SHADER, COLOSSUS_EMISSION_VERTEX_SHADER } from './infernoColossusEmissionShader';

/** Bodies drawn per frame; a fight never fields more colossi than this. */
export const COLOSSUS_EMISSION_CAPACITY = 8;
const VERTICES = 6;
const FLOATS_PER_VERTEX = 19;
const QUAD_CORNERS: readonly (readonly [number, number])[] = [[0, 0], [1, 0], [0, 1], [0, 1], [1, 0], [1, 1]];

/** One body's light this frame: its sprite placement, sheet frame, zone levels and state. */
export interface ColossusEmissionQuad {
  readonly x: number;
  readonly y: number;
  readonly rotation: number;
  readonly width: number;
  readonly height: number;
  readonly originX: number;
  readonly originY: number;
  readonly flipX: boolean;
  readonly flipY: boolean;
  readonly u0: number;
  readonly v0: number;
  readonly u1: number;
  readonly v1: number;
  readonly seed: number;
  readonly allied: boolean;
  /** Zone levels in [0, 1]: veined chitin, mandibles, lantern, wings. */
  readonly veins: number;
  readonly mandibles: number;
  readonly lantern: number;
  readonly wings: number;
  /** Mandible heat in [0, 1] (white-hot edges, the heat front's reach). */
  readonly heat: number;
  /** Heartbeat phase in beats and its gain. */
  readonly beat: number;
  readonly beatGain: number;
  /** Overall strength (alpha incl. day/night damping). */
  readonly strength: number;
  /** How far the sheet's painted glow may sink where the light sleeps, in [0, 1]. */
  readonly sink: number;
}

/** Per-frame vertex data of all colossus light quads. Pure data: no Phaser, no GL. */
export class ColossusEmissionBatchData {
  readonly data = new Float32Array(COLOSSUS_EMISSION_CAPACITY * VERTICES * FLOATS_PER_VERTEX);
  count = 0;
  version = 0;

  begin(): void { this.count = 0; this.version++; }

  push(quad: ColossusEmissionQuad): void {
    if (this.count >= COLOSSUS_EMISSION_CAPACITY) return;
    const cos = Math.cos(quad.rotation), sin = Math.sin(quad.rotation);
    let offset = this.count * VERTICES * FLOATS_PER_VERTEX;
    for (const [cx, cy] of QUAD_CORNERS) {
      const lx = (cx - quad.originX) * quad.width, ly = (cy - quad.originY) * quad.height;
      const ux = quad.flipX ? 1 - cx : cx, uy = quad.flipY ? 1 - cy : cy;
      const d = this.data;
      d[offset++] = quad.x + lx * cos - ly * sin; d[offset++] = quad.y + lx * sin + ly * cos;
      d[offset++] = quad.u0 + (quad.u1 - quad.u0) * ux; d[offset++] = quad.v0 + (quad.v1 - quad.v0) * uy;
      d[offset++] = ux - 0.5; d[offset++] = uy - 0.5; d[offset++] = quad.seed; d[offset++] = quad.allied ? 1 : 0;
      d[offset++] = quad.veins; d[offset++] = quad.mandibles; d[offset++] = quad.lantern; d[offset++] = quad.wings;
      d[offset++] = quad.heat; d[offset++] = quad.beat; d[offset++] = quad.beatGain; d[offset++] = quad.strength;
      d[offset++] = Math.abs(quad.u1 - quad.u0); d[offset++] = Math.abs(quad.v1 - quad.v0); d[offset++] = quad.sink;
    }
    this.count++;
  }
}

export interface ColossusEmissionPalette {
  /** Glow, hot and deep colours (0xRRGGBB). */
  readonly glow: number;
  readonly hot: number;
  readonly deep: number;
}

export interface ColossusEmissionGpuLayer {
  readonly image: Phaser.GameObjects.Image;
  isReady(): boolean;
}

const rgb = (color: number): number[] => [((color >> 16) & 0xff) / 255, ((color >> 8) & 0xff) / 255, (color & 0xff) / 255];

/**
 * One display-list entry and one draw call for the light of all colossi on one emission sheet, just
 * above the light map. Premultiplied NORMAL: the shader adds light and lets the painted glow below sink.
 * WebGL only; null for headless or canvas renderers.
 */
export function createColossusEmissionGpuLayer(scene: Phaser.Scene, data: ColossusEmissionBatchData, emissionKey: string,
  zones: number, depth: number, time: () => number, hostile: ColossusEmissionPalette, allied: ColossusEmissionPalette): ColossusEmissionGpuLayer | null {
  const renderer = scene.sys?.renderer as Phaser.Renderer.WebGL.WebGLRenderer | undefined;
  if (!renderer?.gl || !scene.textures.exists(emissionKey)) return null;
  const manager = renderer.renderNodes;
  const image = scene.add.image(0, 0, emissionKey);
  image.name = 'colossus-emission';
  image.setBlendMode(Phaser.BlendModes.NORMAL);
  image.setDepth(depth);
  const colours: readonly (readonly [string, number[]])[] = [
    ['uHostileGlow', rgb(hostile.glow)], ['uHostileHot', rgb(hostile.hot)], ['uHostileDeep', rgb(hostile.deep)],
    ['uAlliedGlow', rgb(allied.glow)], ['uAlliedHot', rgb(allied.hot)], ['uAlliedDeep', rgb(allied.deep)],
  ];
  let ready = false;

  class ColossusEmissionBatch extends Phaser.Renderer.WebGL.RenderNodes.BatchHandler {
    private uploadedVersion = -1;
    constructor() {
      super(manager, {
        name: `BatchHandlerColossusEmission:${emissionKey}`, shaderName: 'COLOSSUS_EMISSION',
        instancesPerBatch: COLOSSUS_EMISSION_CAPACITY, verticesPerInstance: VERTICES, indicesPerInstance: VERTICES,
        topology: renderer!.gl.TRIANGLES,
        vertexSource: COLOSSUS_EMISSION_VERTEX_SHADER, fragmentSource: COLOSSUS_EMISSION_FRAGMENT_SHADER,
        vertexBufferLayout: { usage: 'DYNAMIC_DRAW', layout: [
          { name: 'inPosition', size: 2 }, { name: 'inUv', size: 2 }, { name: 'inLocal', size: 4 },
          { name: 'inLevels', size: 4 }, { name: 'inState', size: 4 }, { name: 'inFrame', size: 3 },
        ] },
      });
    }
    // Phaser calls this virtual hook in its constructor (omitted from Phaser's public d.ts).
    _generateElementIndices(instances: number): ArrayBuffer {
      const indices = new Uint16Array(instances * VERTICES);
      for (let i = 0; i < indices.length; i++) indices[i] = i;
      return indices.buffer;
    }
    run(context: Phaser.Renderer.WebGL.DrawingContext): void {
      // Until linked, one all-zero (degenerate) quad compiles the program outside combat.
      if (data.count === 0 && ready) return;
      this.onRunBegin(context);
      const program = this.programManager;
      const suite = program.getCurrentProgramSuite() as {
        program: Phaser.Renderer.WebGL.Wrappers.WebGLProgramWrapper;
        vao: Phaser.Renderer.WebGL.Wrappers.WebGLVAOWrapper;
      } | null;
      if (suite) {
        ready = true;
        if (this.uploadedVersion !== data.version && data.count > 0) {
          const slice = data.data.subarray(0, data.count * VERTICES * FLOATS_PER_VERTEX);
          this.vertexBufferLayout.buffer.viewF32!.set(slice, 0);
          this.vertexBufferLayout.buffer.update(slice.byteLength, 0);
          this.uploadedVersion = data.version;
        }
        const m = context.camera!.getViewMatrix(!context.useCanvas);
        renderer!.setProjectionMatrixFromDrawingContext(context);
        program.setUniform('uProjectionMatrix', renderer!.projectionMatrix.val);
        program.setUniform('uViewMatrix', [m.a, m.b, 0, m.c, m.d, 0, m.tx, m.ty, 1]);
        program.setUniform('uEmission', 0);
        program.setUniform('uZones', zones);
        program.setUniform('uTime', time());
        for (const [name, value] of colours) program.setUniform(name, value);
        program.applyUniforms(suite.program);
        renderer!.drawElements(context, [image.frame.source.glTexture!], suite.program, suite.vao,
          Math.max(1, data.count) * VERTICES, 0, this.topology);
      }
      this.onRunEnd(context);
    }
    dispose(): void {
      // RenderNodeManager mixes in EventEmitter; its d.ts omits that inheritance.
      (manager as unknown as Phaser.Events.EventEmitter).off(
        Phaser.Renderer.Events.SET_PARALLEL_TEXTURE_UNITS, this.updateTextureCount, this);
      for (const suite of Object.values(this.programManager.programs)) {
        Phaser.Utils.Array.Remove(renderer!.glVAOWrappers, suite.vao);
        suite.vao.destroy();
      }
      this.programManager.programs = {};
      renderer!.deleteBuffer(this.indexBuffer);
      renderer!.deleteBuffer(this.vertexBufferLayout.buffer);
    }
  }

  const batch = new ColossusEmissionBatch();
  class ColossusEmissionSubmitter extends Phaser.Renderer.WebGL.RenderNodes.RenderNode {
    constructor() { super(`SubmitterColossusEmission:${emissionKey}`, manager); }
    run(context: Phaser.Renderer.WebGL.DrawingContext): void {
      manager.startStandAloneRender(); this.onRunBegin(context);
      batch.run(context);
      this.onRunEnd(context);
    }
  }
  image.setRenderNodeRole('Submitter', new ColossusEmissionSubmitter());
  image.once(Phaser.GameObjects.Events.DESTROY, () => batch.dispose());
  return { image, isReady: () => ready };
}
