interface FilterTarget { minFilter?: number; magFilter?: number }
interface TextureFilterRenderer {
  gl: { LINEAR: number; NEAREST: number } | null;
  setTextureFilter(texture: FilterTarget | null | undefined, filter: number): unknown;
}
const installed = new WeakSet<object>();

/**
 * Phaser 4.2.1 `setTextureFilter` re-uploads the whole texture (`texImage2D` from `pixels`, for a
 * loaded image its element, decoded again on the main thread) just to set the sampling filter.
 * Most callers request the filter the texture already has, e.g. LINEAR on loaded woodland
 * textures under the default antialias. That request changes no GL state and is skipped. A real
 * filter change keeps Phaser's path unchanged.
 */
export function installPhaserTextureFilter(target: object): void {
  const prototype = target as TextureFilterRenderer;
  if (installed.has(prototype)) return;
  installed.add(prototype);
  const original = prototype.setTextureFilter;
  prototype.setTextureFilter = function (this: TextureFilterRenderer, texture, filter) {
    const gl = this.gl;
    const wanted = gl ? (filter === 0 ? gl.LINEAR : gl.NEAREST) : undefined;
    if (wanted !== undefined && texture && texture.minFilter === wanted && texture.magFilter === wanted) return this;
    return original.call(this, texture, filter);
  };
}
