/**
 * Der world-owned Owner der autoritativen Projectile-Registry.
 *
 * Er entsteht mit der World und nimmt die scene-langlebige Host-Simulation fuer genau diese
 * Lebensdauer in Dienst: Identity, Records und ihr Teardown gehoeren ihm. Er steht vor Player-,
 * Kampf- und Bau-Anteil, weil deren Quellen ueber seine Spawn-Grenze schiessen.
 */
export function composeWorldProjectileRuntime(
  input: ArenaWorldGameplayCompositionInput,
  gameplay: ArenaWorldGameplay,
): void {
  const { ctx, worldRuntime } = input;
  const presentation = new ProjectilePresentationRuntime(input.scene);
  const projectileRuntime = new WorldProjectileRuntime({
    physicsBinding: new ProjectilePhysicsBinding(input.scene),
    presentation,
    identityScope: worldRuntime.projectileIdentityScope,
    hostNowMs: () => bridge.getSynchronizedNow(),
    resolveProvenance: (provenance) => {
      if (!gameplay.combatSystem) throw new Error('[ArenaWorldComposition] Combat source owner is missing');
      return gameplay.combatSystem.captureProjectileProvenance(provenance);
    },
    onDestroy: () => {
      if (gameplay.projectiles === projectileRuntime) gameplay.projectiles = null;
    },
  });
  projectileRuntime.setProjectileReplicationAdapter(new ProjectileReplicationAdapter(projectileRuntime));
  projectileRuntime.getPresentationRuntime().setAudioSystem(ctx.gameAudioSystem);
  wireProjectileRenderers(input.renderers, projectileRuntime, ctx.playerManager, (enemyId) => {
    const enemy = input.flow.getCoopMissionRuntime()?.enemyManager?.getEnemy(enemyId);
    return enemy?.sprite.active ? { x: enemy.sprite.x, y: enemy.sprite.y } : null;
  });
  gameplay.projectiles = projectileRuntime;
  worldRuntime.bind(projectileRuntime);
}

/** Build phase: creates the concrete Combat instance and installs only its World identity. */
export function composeWorldCombatRuntime(
  input: ArenaWorldGameplayCompositionInput,
  gameplay: ArenaWorldGameplay,
): void {
  const generation = input.flow.nextCombatRuntimeGeneration();
  const combatSystem = new WorldCombatCore(input.ctx.playerManager, bridge);
  const combatRuntime = new WorldCombatRuntime(input.worldRuntime.descriptor.worldRevision, generation);
  input.worldRuntime.setCombat(combatRuntime);
  gameplay.combatSystem = combatSystem;
  gameplay.combatRuntime = combatRuntime;
  input.worldRuntime.bind(combatSystem.bindPlayerVitalsScope(combatRuntime.scope));
}

/** Bind/activate phase: closes every required cyclic edge after all World owners exist. */
export function activateWorldCombatRuntime(
  input: ArenaWorldGameplayCompositionInput,
  gameplay: ArenaWorldGameplay,
): void {
  const combat = gameplay.combatSystem;
  const runtime = gameplay.combatRuntime;
  const binding = gameplay.combat;
  if (!combat || !runtime || !binding) {
    throw new Error('[ArenaWorldComposition] Combat graph is incomplete before activation');
  }
  runtime.attachRequiredBindings(binding.getRequiredCombatBindings());
  input.worldRuntime.bind(input.ctx.hostPhysics.bindCombatCore(combat));
  input.worldRuntime.bind(combat.bindHostExecutionSources({
    nowMs: () => bridge.getSynchronizedNow(),
    random: Math.random,
  }));
  runtime.activate();
}

/**
 * Die World-Projektion der scene-langlebigen Kampf-, Physik- und Projektilsysteme.
 *
 * Das Binding erzeugt die world-lokalen Kampf-Runtimes, installiert seine Resolver und loest sie
 * beim World-Teardown selbst wieder. Die laufende Activity liefert nur Reads nach; welche
 * Missionssysteme dahinter stehen, weiss diese Grenze nicht.
 */
export function composeWorldCombatGameplay(
  input: ArenaWorldGameplayCompositionInput,
  gameplay: ArenaWorldGameplay,
): void {
  const {
    ctx, rockVisualHelper, hostUpdate, flow, worldRuntime, world,
    arenaResult, placementSystem, baseManager,
  } = input;
  const projectileRuntime = gameplay.projectiles;
  if (!projectileRuntime) {
    throw new Error('[ArenaWorldComposition] Projectile runtime is missing');
  }
  const combatSystem = gameplay.combatSystem;
  if (!combatSystem) throw new Error('[ArenaWorldComposition] Combat runtime is missing');
  combatSystem.setPlayerMountedResolver(id => bridge.isHost()
    ? gameplay.player?.isControllingTurret(id) ?? false
    : !!bridge.getLatestGameState()?.players[id]?.turretControl);
  worldRuntime.bind({ destroy: () => combatSystem.setPlayerMountedResolver(null) });
  // Eine Basisaenderung trifft alle Felder gemeinsam: Der Coordinator verschickt den Patch
  // prioritaer und sperrt die entfallenen Zielzellen sofort, bis das neue Feld aktiv ist.
  const syncActiveBaseIds = (): void => {
    flow.getCoopMissionRuntime()?.flowFieldCoordinator?.setActiveBaseIds(
      baseManager?.getNavigationBaseIds() ?? new Set<string>(),
    );
  };
  const combatGameplayBinding = new WorldCombatGameplayBinding({
    playerManager: ctx.playerManager,
    projectileSpawn: projectileRuntime,
    projectileUtility: projectileRuntime,
    projectileEvents: projectileRuntime,
    projectileTimeField: projectileRuntime,
    projectileHoming: {
      setLineOfFireReadPort: port => projectileRuntime.setLineOfFireReadPort(port),
      setProjectileTargetQueryPort: port => projectileRuntime.setProjectileTargetQueryPort(
        port ? new CombatProjectileQueryAdapter(combatSystem, port) : null),
    },
    projectileWorldImpact: projectileRuntime,
    projectileSwarm: projectileRuntime,
    projectileInteraction: {
      setTimeBubbleChargePort: port => projectileRuntime.setTimeBubbleChargePort(port),
      setProjectileBarrierPort: port => projectileRuntime.setProjectileBarrierPort(port),
      setProjectileCombatPort: port => projectileRuntime.setProjectileCombatPort(port),
      setProjectileMiniRocketStatePort: port => projectileRuntime.setProjectileMiniRocketStatePort(port),
      readDetonableProjectiles: (...args) => projectileRuntime.readDetonableProjectiles(...args),
      setProjectileTargetabilityPort: port => projectileRuntime.setProjectileTargetabilityPort(port),
      setProjectileWorldBlockerPort: port => projectileRuntime.setProjectileWorldBlockerPort(port),
      setProjectileCollisionTargetQueryPort: port => {
        const parts = new CombatProjectileQueryAdapter(combatSystem);
        projectileRuntime.setProjectileCollisionTargetQueryPort(port ? { ...port,
          getWorldTargetHit: (target, ...args) => {
            const hit = parts.getWorldTargetHit(target, ...args);
            return hit === undefined ? port.getWorldTargetHit?.(target, ...args) : hit;
          },
        } : null);
      },
    },
    combatSystem,
    hostPhysics: ctx.hostPhysics,
    decoySystem: ctx.decoySystem,
    fireSystem: ctx.fireSystem,
    gameAudioSystem: ctx.gameAudioSystem,
    placementSystem,
    baseManager,
    worldMetrics: world.metrics,
    isCoopMission: () => flow.isCoopMissionActivity(),
    isCoopDefense: () => bridge.getGameMode() === 'coop_defense',
    isActivityActive: () => flow.isActivityActive(),
    getRespawnDelayMs: () => {
      const arenaStartTime = bridge.getArenaStartTime();
      if (!flow.isCoopMissionActivity() || arenaStartTime <= 0) return null;
      const mapConfig = resolveCoopDefenseMapConfig(worldRuntime.context.descriptor, bridge.getActivityDescriptor());
      return resolveCoopDefenseRespawnDelayMs(mapConfig?.respawnDelaySchedule, bridge.getSynchronizedNow() - arenaStartTime);
    },
    onVoiceDamage: (id, amount) => ctx.voice?.damage(id, amount),
    getSpawnContext: (playerId) => {
      const latestState = bridge.getLatestGameState();
      const missionState = bridge.getCoopDefenseMissionProgressPresentationState();
      const worldContext = worldRuntime.context;
      const activeMapConfig = resolveCoopDefenseMapConfig(worldContext.descriptor, bridge.getActivityDescriptor());
      const missionConfig = activeMapConfig === null ? null : resolveCoopDefenseMapMissionProgress(activeMapConfig);
      const respawnCheckpoint = missionConfig?.checkpoints.find(
        ({ id }) => id === missionState?.respawnCheckpointId,
      );
      const spawnFocusCell = respawnCheckpoint ?? missionConfig?.startArea;
      const runtimePlaceables = placementSystem.getAllRuntimeRocks();
      const turretRange = (UTILITY_CONFIGS.SPORE_TURRET as PlaceableTurretUtilityConfig).placeable.targetRange;

      return {
        fires: latestState?.fires ?? [],
        burningGroundCells: ctx.fireSystem.getGroundState().cells.map((cell) => ({
          x: (cell.gridX + 0.5) * GROUND_FIRE_CELL_SIZE,
          y: (cell.gridY + 0.5) * GROUND_FIRE_CELL_SIZE,
          radius: GROUND_FIRE_CELL_SIZE * Math.SQRT2 / 2,
        })),
        stinkClouds: latestState?.stinkClouds ?? [],
        teslaDomes: latestState?.teslaDomes ?? [],
        nukes: latestState?.nukes ?? [],
        meteors: latestState?.meteors ?? [],
        occupiedCells: runtimePlaceables.flatMap((placeable) => getConstructionCells(placeable)),
        turrets: runtimePlaceables
          .filter((placeable) => (
            placeable.kind === 'turret'
            && playerId !== null
            && combatSystem.canDamageTarget(placeable.ownerId, playerId)
          ))
          .map((placeable) => ({
            x: ARENA_OFFSET_X + placeable.gridX * CELL_SIZE + CELL_SIZE * 0.5,
            y: ARENA_OFFSET_Y + placeable.gridY * CELL_SIZE + CELL_SIZE * 0.5,
            ownerId: placeable.ownerId,
            range: placeable.targetRange ?? turretRange,
          })),
        projectiles: (latestState?.projectiles ?? [])
          .filter((projectile) => playerId !== null && combatSystem.canDamageTarget(projectile.ownerId, playerId, projectile.allowTeamDamage))
          .map((projectile) => ({
            x: projectile.x,
            y: projectile.y,
            ownerId: projectile.ownerId,
            radius: resolveSpawnProjectileDangerRadius(projectile),
          })),
        enemyThreats: (() => {
          const livingBases = baseManager?.getBasesByFaction('friendly')
            ?.filter((base) => !(base.isInert?.() ?? false) && base.getHp() > 0) ?? [];
          return (flow.getCoopMissionRuntime()?.enemyManager?.getAllEnemies() ?? [])
            .filter((enemy) => enemy.faction === 'hostile' && enemy.sprite.active && combatSystem.isAlive(enemy.id))
            .map((enemy) => {
              let targetBaseId: string | undefined;
              let targetBaseDistance = Number.POSITIVE_INFINITY;
              for (const base of livingBases) {
                const surface = base.getNearestSurfacePoint(enemy.sprite.x, enemy.sprite.y);
                if (surface && surface.distance < targetBaseDistance) {
                  targetBaseId = base.id;
                  targetBaseDistance = surface.distance;
                }
              }
              return {
                x: enemy.sprite.x,
                y: enemy.sprite.y,
                isBoss: enemy.isBoss(),
                collisionRadius: enemy.getCollisionRadius(),
                attackRange: Math.max(
                  0,
                  ...enemy.getAttackWeapons().map((attackWeapon) => (
                    attackWeapon.weapon.config.fire.type === 'tesla_dome'
                      ? attackWeapon.weapon.config.fire.radius
                      : attackWeapon.weapon.config.range
                  )),
                ),
                targetBaseId,
                targetBaseDistance,
              };
            });
        })(),
        livingCoopBaseIds: baseManager?.getActiveMainBaseIds('friendly'),
        preferredSpawnFocus: spawnFocusCell
          ? {
            x: ARENA_OFFSET_X + (spawnFocusCell.gridX + 0.5) * CELL_SIZE,
            y: ARENA_OFFSET_Y + (spawnFocusCell.gridY + 0.5) * CELL_SIZE,
          }
          : undefined,
        isRelevantOpponent: (otherPlayerId) => playerId === null
          ? combatSystem.isAlive(otherPlayerId)
          : combatSystem.isAlive(otherPlayerId) && bridge.isEnemyPair(playerId, otherPlayerId),
        hasLineOfSight: (sx, sy, ex, ey) => combatSystem.hasLineOfSight(sx, sy, ex, ey),
      };
    },
    getWorldParticipation: (playerId) => flow.getWorldParticipation(playerId),
    getPlayerCapabilities: (playerId) => flow.getPlayerCapabilities(playerId),
    getEnemyManager: () => gameplay.shootingRange?.enemies ?? flow.getCoopMissionRuntime()?.enemyManager ?? null,
    isTrainingTarget: id => gameplay.shootingRange?.isTrainingTarget(id) ?? false,
    getPlayerCombatIntegration: () => gameplay.player?.getPlayerCombatIntegrationPort() ?? null,
    readConstructionSlotOrder: ownerId => (bridge.getPlayerCurrentLoadoutSnapshot(ownerId)?.tools ?? [])
      .flatMap(tool => { const id = normalizeConstructionId(tool.id); return id ? [id] : []; }),
    getManualTurretControl: (id, now) => gameplay.player?.getManualTurretControl(id, now) ?? null,
    bindPlayerShieldBuffPort: (port) => gameplay.player?.bindShieldBuffPort(port),
    automatedWeaponExecution: gameplay.automatedWeaponExecution,
    getPowerUpSystem: () => gameplay.powerUp?.system ?? null,
    getTargetStatusSystem: () => gameplay.targeting?.systems.targetStatus ?? null,
    getEnemyMovementStatusSystem: () => gameplay.targeting?.systems.enemyMovementStatus ?? null,
    getEnergyInjectorSystem: () => gameplay.targeting?.systems.energyInjector ?? null,
    getWorldGeometryBinding: () => gameplay.geometry,
    getPersistentBaseId: () => world.persistentBaseSite?.baseId,
    getConstructionMuzzleOffset: (constructionId) => gameplay.construction?.getMuzzleOffset(constructionId),
    getTargetFootprint: (target) => resolveTargetFootprint(
      ctx.playerManager,
      flow.getCoopMissionRuntime(),
      input.worldRuntime,
      rockVisualHelper,
      target,
      gameplay.shootingRange?.enemies,
    ),
    resolveObstacleDamage: (rockId, damage, attackerId) => resolveObstacleDamage(
      combatSystem,
      placementSystem,
      rockId,
      damage,
      attackerId,
    ),
    updateTurretAngle: (rockId, angle) => rockVisualHelper.updateTurretAngle(rockId, angle),
    spawnImpactCloud: (projectile) => spawnImpactCloudFromProjectile(ctx, projectile),
    resetPlayerPosition: (playerId, x, y) => flow.getCoopMissionRuntime()?.coopDefenseMissionProgressSystem?.resetPlayerPosition(playerId, x, y),
    dropBeer: (playerId, x, y) => flow.getCaptureTheBeerSystem()?.dropBeerForPlayer(playerId, x, y),
    dropCarryForPlayer: (playerId, x, y) => flow.getCoopMissionRuntime()?.coopDefenseCarrySystem?.dropForPlayer(playerId, x, y),
    handlePlayerUnavailable: (playerId) => flow.getCoopMissionRuntime()?.coopDefenseObjectivePlacementRewardSystem?.handlePlayerUnavailable(playerId),
    handlePlayerDeath: (playerId) => flow.getPlayerActivityRuntime()?.handlePlayerDeath(playerId),
    getSecondaryObjectiveState: (objectiveId) => {
      const state = bridge.getCoopDefenseSecondaryObjectivePresentationState();
      return state?.find(entry => entry.objectiveId === objectiveId)?.state ?? null;
    },
    reportTargetContribution: (objectiveId, baseId) => {
      const mission = flow.getCoopMissionRuntime();
      mission?.coopDefenseSecondaryObjectiveSystem?.reportTargetContribution(objectiveId, baseId);
      // The same eligible hit wakes a structure's site, e.g. the guard of a portal generator.
      mission?.coopDefenseSiteActivationSystem?.reportStructureDamaged(baseId);
    },
    reportTargetDestroyed: (objectiveId, baseId) => flow.getCoopMissionRuntime()?.coopDefenseSecondaryObjectiveSystem?.reportTargetDestroyed(objectiveId, baseId) ?? 0,
    reconcilePersistentBaseWorld: () => flow.reconcilePersistentBaseWorld(),
    syncActiveBaseIds,
    getMissionBarrierObstacles: () => flow.getCoopMissionRuntime()?.coopDefenseMissionBarrierManager?.getObstacleRectangles() ?? null,
    getRockTargets: () => arenaResult.rockPhysicsProxies.flatMap((rock, index) => (
      rock?.active ? [{ index, active: true, x: rock.x, y: rock.y }] : []
    )),
    getWorldTrain: () => gameplay.train,
    getReactiveProps: () => worldRuntime.materialization?.reactiveProps ?? null,
    getWorldMutation: () => gameplay.worldMutation,
    getFirestarterSystem: () => flow.getCoopMissionRuntime()?.coopDefenseFirestarterSystem ?? null,
    getShieldChargerSystem: () => flow.getCoopMissionRuntime()?.coopDefenseShieldChargerSystem ?? null,
    getEnergyConeSystem: () => flow.getCoopMissionRuntime()?.coopDefenseEnergyConeSystem ?? null,
    getHopSystem: () => flow.getCoopMissionRuntime()?.coopDefenseEnemyHopSystem ?? null,
    getPounceSystem: () => flow.getCoopMissionRuntime()?.coopDefenseEnemyPounceSystem ?? null,
    getHeatBurstSystem: () => flow.getCoopMissionRuntime()?.coopDefenseEnemyHeatBurstSystem ?? null,
    getMortarSystem: () => flow.getCoopMissionRuntime()?.coopDefenseMortarSystem ?? null,
    getKaboomtulaSystem: () => flow.getCoopMissionRuntime()?.coopDefenseKaboomtulaSystem ?? null,
    getTurretWebSystem: () => flow.getCoopMissionRuntime()?.coopDefenseTurretWebSystem ?? null,
    getNecromancySystem: () => gameplay.shootingRange?.necromancy ?? flow.getCoopMissionRuntime()?.necromancySystem ?? null,
    hostUpdate: hostUpdate,
    createEnergyShieldSystem: (resource, shield) => new EnergyShieldSystem(ctx.playerManager, resource, bridge, shield),
    network: {
      authority: {
        isHost: () => bridge.isHost(),
        isEnemyPair: (first, second) => bridge.isEnemyPair(first, second),
        getPlayerProfile: (playerId) => bridge.getPlayerProfile(playerId),
        getConnectedPlayers: () => bridge.getConnectedPlayers(),
      },
      round: {
        canPlayerInitialSpawn: (playerId) => bridge.canPlayerInitialSpawn(playerId),
        canPlayerRespawn: (playerId) => bridge.canPlayerRespawn(playerId),
        canPlayerReceiveRoundRewards: (playerId) => bridge.canPlayerReceiveRoundRewards(playerId),
        addCoopDefenseRoundXp: (amount) => { bridge.addCoopDefenseRoundXp(amount); },
      },
      stats: {
        recordPlayerDamageTaken: (playerId, hpLost, armorLost) => bridge.recordPlayerDamageTaken(playerId, hpLost, armorLost),
        addPlayerRoomDamage: (playerId, amount) => bridge.addPlayerRoomDamage(playerId, amount),
        recordHealingReceived: (playerId, amount) => bridge.recordHealingReceived(playerId, amount),
        recordArmorReceived: (playerId, amount) => bridge.recordArmorReceived(playerId, amount),
        recordPlayerDeath: (playerId) => bridge.recordPlayerDeath(playerId),
        recordPlayerKill: (playerId, kind) => bridge.recordPlayerKill(playerId, kind),
        incrementPlayerFrags: (playerId) => bridge.incrementPlayerFrags(playerId),
        recordRoundAchievementKill: (kill) => bridge.recordRoundAchievementKill(kill),
        recordRoundTrainVictim: (playerId) => bridge.recordRoundTrainVictim(playerId),
      },
      effects: {
        broadcastCoopDefenseXpPopup: (x, y, xp) => bridge.broadcastCoopDefenseXpPopup(x, y, xp),
        broadcastSlimeBloomEffect: (x, y, targets) => bridge.broadcastSlimeBloomEffect(x, y, targets),
        broadcastExplosionEffect: (...args) => bridge.broadcastExplosionEffect(...args),
        broadcastBfgLaserBatch: (lines, color, preset, projectileId) => bridge.broadcastBfgLaserBatch([...lines], color, preset, projectileId),
        broadcastMiniRocketCollectionEffect: (x, y, color) => bridge.broadcastMiniRocketCollectionEffect(x, y, color),
        broadcastMiniRocketDestructionEffect: (x, y, color) => bridge.broadcastMiniRocketDestructionEffect(x, y, color),
        broadcastKillEvent: (event) => {
          bridge.broadcastKillEvent(event);
          if (event.killerId !== event.victimId && bridge.isEnemyPair(event.killerId, event.victimId)) ctx.voice?.kill(event.killerId);
        },
      },
    },
    respawnPlayer: (playerId) => flow.getPlayerActivityRuntime()?.consumeRespawn(playerId, false) ?? true,
    publishRespawn: () => flow.getPlayerActivityRuntime()?.publishRespawnBudget(),
    getTeamHpRegenBonus: (playerId, nowMs) => flow.getCoopMissionRuntime()?.coopDefenseTeamBuffSystem?.getHpRegenBonus(nowMs, bridge.canPlayerReceiveRoundRewards(playerId), combatSystem.isAlive(playerId)) ?? 0,
    getMatrixDamageReduction: (footprint, applies, nowMs) => gameplay.targeting?.systems.reinforcementMatrix.getDamageReductionForFootprint(footprint, nowMs, applies) ?? 0,
    getMatrixDamageMultiplier: (footprint, applies, nowMs) => gameplay.targeting?.systems.reinforcementMatrix.getDamageMultiplierForFootprint(footprint, nowMs, applies) ?? 1,
    isHomingTargetValid: (id, type, ownerId) => {
      void ownerId;
      if (type !== 'players' && type !== 'decoys') return true;
      const catalog = flow.getCoopMissionRuntime()?.enemyAiTargetCatalog;
      if (!catalog) return true;
      return catalog.isTargetValid({ kind: type === 'players' ? 'player' : 'decoy', id });
    },
  });
  gameplay.combat = combatGameplayBinding;
  worldRuntime.bind(combatGameplayBinding);
  // Der Host-Owner speist den Slice `fc`; die Darstellung liest auf Host und Client dieselbe Quelle.
  if (bridge.isHost()) {
    bridge.setFireControlSnapshotProvider(() => combatGameplayBinding.getFireControlSnapshot(bridge.getSynchronizedNow()));
    worldRuntime.bind({ destroy: () => bridge.setFireControlSnapshotProvider(null) });
    bridge.setBomberSquadronSnapshotProvider(() => combatGameplayBinding.getBomberSquadronSnapshot(bridge.getSynchronizedNow()));
    worldRuntime.bind({ destroy: () => bridge.setBomberSquadronSnapshotProvider(null) });
  }
  // Inspector-Ultimates: der Combat-Owner besitzt die Einsätze, die Ultimate-Runtime nur Aktivierung und Rage.
  gameplay.player?.setHoloOffensiveCapability(combatGameplayBinding.getHoloOffensiveCapability());
  gameplay.player?.setBomberSquadronCapability(combatGameplayBinding.getBomberSquadronCapability());
  worldRuntime.bind({ destroy: () => {
    gameplay.player?.setHoloOffensiveCapability(null);
    gameplay.player?.setBomberSquadronCapability(null);
  } });
  worldRuntime.presentationFrame?.bindFireControl(
    () => bridge.getFireControlSnapshot(),
    id => rockVisualHelper.getTurretOriginalVisual(id),
    projectileRuntime.getPresentationRuntime(),
  );
  const reactiveProps = worldRuntime.materialization?.reactiveProps;
  if (reactiveProps) worldRuntime.presentationFrame?.bindReactiveProps(reactiveProps, input.renderers?.entityBurnGpu ?? null,
    (id, attack, now, visible) => ctx.effectSystem.syncEnemyZone(id, attack, now, visible));
  if (reactiveProps) worldRuntime.presentationFrame?.bindBeeSwarms({
    audio: ctx.gameAudioSystem,
    hostSwarms: () => combatGameplayBinding.beeSwarm?.getSnapshot() ?? null,
    enemyPosition: id => {
      const enemy = (gameplay.shootingRange?.enemies ?? flow.getCoopMissionRuntime()?.enemyManager)?.getEnemy(id);
      return enemy?.sprite.active ? { x: enemy.sprite.x, y: enemy.sprite.y } : null;
    },
  });
  worldRuntime.presentationFrame?.bindBomberSquadron(() => bridge.getBomberSquadronSnapshot(), {
    // Same warm carpet burst as the attack-drone bombs; it is derived locally, never broadcast.
    explode: (x, y, radius) => ctx.effectSystem.playExplosionEffect(x, y, radius, 0xffae57, 'rocket'),
    playSound: (key, x, y, volumeScale) => ctx.gameAudioSystem.playSound(key, x, y, undefined, volumeScale),
    cameraFeedback: () => ctx.visualFeedback.camera,
    navLights: () => input.renderers?.droneNavLights ?? null,
  });
}

function resolveSpawnProjectileDangerRadius(projectile: SyncedProjectile): number {
  const baseRadius = Math.max(CELL_SIZE * 2, projectile.size * 4);

  switch (projectile.style) {
    case 'rocket':
    case 'bfg':
      return Math.max(baseRadius, CELL_SIZE * 4);
    case 'grenade':
    case 'holy_grenade':
      return Math.max(baseRadius, CELL_SIZE * 3.5);
    case 'energy_ball':
    case 'hydra':
    case 'spore':
      return Math.max(baseRadius, CELL_SIZE * 3);
    case 'flame':
      return Math.max(baseRadius, CELL_SIZE * 1.5);
    default:
      return baseRadius;
  }
}

/** Item-Affix-Wolke eines eingeschlagenen Projektils; reine Host-Folge des Treffers. */
function spawnImpactCloudFromProjectile(
  ctx: ArenaContext,
  proj: ProjectileImpactSource,
): void {
  if (!proj.impactCloud) return;
  const ownerColor = proj.ownerColor ?? bridge.getPlayerColor(proj.ownerId) ?? proj.color;
  ctx.stinkCloudSystem.hostCreateStationaryCloud(
    proj.ownerId, ownerColor, proj.x, proj.y,
    proj.impactCloud.radius,
    proj.impactCloud.duration,
    proj.impactCloud.damagePerTick,
    proj.impactCloud.tickInterval,
    proj.impactCloud.rockDamageMult ?? 1,
    proj.impactCloud.trainDamageMult ?? 1,
    proj.impactCloud.baseDamageMult ?? 1,
    proj.impactCloud.visualVariant,
    ctx.getWorldCombatCore()!.getHostTime(),
    ctx.getWorldCombatCore()!.captureWorldDamageSource(proj.ownerId, proj.sourceId, 'ground', proj.provenance, proj.projectileId),
  );
}
