import {
  ACHIEVEMENT_COUNTER,
  ACHIEVEMENT_SOURCE_IDS,
  RABID_RABBIT_ENEMY_KIND,
  enemyKillCounter,
  isTrackedAchievementUtilityId,
  utilityUsedCounter,
} from './AchievementCounters';
import { ROUND_ACHIEVEMENT_MAX_COUNTERS, type RoundAchievementSnapshot } from './AchievementLedger';

export interface RoundAchievementKill {
  readonly killerId: string;
  readonly victim: 'enemy' | 'player';
  readonly enemyKind?: string;
  readonly sourceId: string;
  /** Host frame time of the kill; one nuke strike kills everything within the same frame. */
  readonly nowMs?: number;
  /** Player victim on the opposing side (not a suicide, not a teammate). */
  readonly pvp: boolean;
}

interface PlayerRoundEntry {
  readonly counters: Map<string, number>;
  deaths: number;
  readonly nukeKillsByFrame: Map<number, number>;
}

/**
 * Host-only, one round long: what each eligible player did that the client cannot see itself
 * (which enemy kinds they killed, special kills). Published once in the round results.
 */
export class RoundAchievementLedger {
  private readonly players = new Map<string, PlayerRoundEntry>();

  recordKill(kill: RoundAchievementKill): void {
    const entry = this.entry(kill.killerId);
    if (kill.victim === 'enemy') {
      if (!kill.enemyKind) return;
      this.add(entry, enemyKillCounter(kill.enemyKind));
      this.add(entry, ACHIEVEMENT_COUNTER.killsTotal);
      if (kill.enemyKind === RABID_RABBIT_ENEMY_KIND && kill.sourceId === ACHIEVEMENT_SOURCE_IDS.holyHandGrenade) {
        this.add(entry, ACHIEVEMENT_COUNTER.rabbitHolyHandGrenade);
      }
      if (kill.sourceId === ACHIEVEMENT_SOURCE_IDS.nuke && kill.nowMs !== undefined && Number.isFinite(kill.nowMs)) {
        const burst = (entry.nukeKillsByFrame.get(kill.nowMs) ?? 0) + 1;
        entry.nukeKillsByFrame.set(kill.nowMs, burst);
        if (burst > (entry.counters.get(ACHIEVEMENT_COUNTER.nukeBurst) ?? 0)) {
          this.set(entry, ACHIEVEMENT_COUNTER.nukeBurst, burst);
        }
      }
    } else if (kill.pvp) {
      this.add(entry, ACHIEVEMENT_COUNTER.pvpKills);
    }
    if (kill.sourceId === ACHIEVEMENT_SOURCE_IDS.telefrag && (kill.pvp || kill.victim === 'enemy')) {
      this.add(entry, ACHIEVEMENT_COUNTER.telefrag);
    }
  }

  recordDeath(playerId: string): void {
    this.entry(playerId).deaths++;
  }

  recordTrainVictim(playerId: string): void {
    this.add(this.entry(playerId), ACHIEVEMENT_COUNTER.trainVictim);
  }

  recordTrainDestroyed(playerId: string): void {
    this.add(this.entry(playerId), ACHIEVEMENT_COUNTER.trainDestroyed);
  }

  recordUtilityUsed(playerId: string, utilityId: string): void {
    if (isTrackedAchievementUtilityId(utilityId)) this.add(this.entry(playerId), utilityUsedCounter(utilityId));
  }

  /** Every eligible player gets a row, so "no deaths" is an explicit zero, not a missing field. */
  snapshot(playerId: string): RoundAchievementSnapshot {
    const entry = this.players.get(playerId);
    if (!entry) return { counters: {}, deaths: 0 };
    return { counters: Object.fromEntries(entry.counters), deaths: entry.deaths };
  }

  private entry(playerId: string): PlayerRoundEntry {
    let entry = this.players.get(playerId);
    if (!entry) {
      entry = { counters: new Map(), deaths: 0, nukeKillsByFrame: new Map() };
      this.players.set(playerId, entry);
    }
    return entry;
  }

  private add(entry: PlayerRoundEntry, key: string): void {
    this.set(entry, key, (entry.counters.get(key) ?? 0) + 1);
  }

  private set(entry: PlayerRoundEntry, key: string, value: number): void {
    if (!entry.counters.has(key) && entry.counters.size >= ROUND_ACHIEVEMENT_MAX_COUNTERS) return;
    entry.counters.set(key, value);
  }
}
