import * as Phaser from 'phaser';
import { WALKING_IDLE_FRAME } from '../../animations/BadgerAnimations';
import { runWithScopedBlend } from '../../graphics/PhaserScopedBlend';
import { EnemyMeshGpu } from '../EnemyMeshGpu';
import { ownSunShader, sunShaderName } from '../sunlight/SunRenderTarget';

const CAPACITY = 512;
const ATTRIBUTES = [{ name: 'inCentre', size: 4 }, { name: 'inFrame', size: 4 }, { name: 'inOutline', size: 4 }, { name: 'inTurn', size: 2 }, { name: 'inCode', size: 3 }];
const INSTANCE_WORDS = 17;
/** A sprite this faint shows nothing that could stand for its shape; effects draw such figures themselves. */
const MIN_SPRITE_ALPHA = 0.02;
/** Field texels the outline grows by: narrow gaps between body and legs would let a close lamp through as streaks. */
export const FIGURE_OUTLINE_GROWTH_TEXELS = 1.5;

const VERTEX = `
precision highp float;
attribute vec2 inPosition;
attribute vec4 inCentre,inFrame,inOutline;
attribute vec2 inTurn;
attribute vec3 inCode;
uniform mat4 uProjectionMatrix;
uniform mat3 uViewMatrix;
// Scale and offset from field texels to the target's texels.
uniform vec3 uPlace;
varying vec2 uv;
varying vec2 uvOutline;
varying vec2 reach;
varying vec2 maskTexel;
varying vec3 code;
void main() {
 vec2 local=(inPosition-.5)*inCentre.zw;
 vec2 at=inCentre.xy+vec2(local.x*inTurn.x-local.y*inTurn.y,local.x*inTurn.y+local.y*inTurn.x);
 vec3 view=uViewMatrix*vec3(at*uPlace.x+uPlace.yz,1.0);
 gl_Position=uProjectionMatrix*vec4(view.xy,0.0,1.0);
 uv=inFrame.xy+inPosition*inFrame.zw;
 uvOutline=inOutline.xy+inPosition*inOutline.zw;
 reach=inFrame.zw/inCentre.zw*${FIGURE_OUTLINE_GROWTH_TEXELS.toFixed(2)};
 maskTexel=inFrame.zw/(inCentre.zw*uPlace.x);
 code=inCode;
}`;

const FRAGMENT = `
precision highp float;
uniform sampler2D uSheet;
// x: 1 draws the plain picture shown this frame, 0 the grown blocker. y: for the blocker 1 adds the shown picture to its resting
// outline, for the picture 1 averages four samples per texel into the share of it the figure covers.
uniform vec2 uMode;
varying vec2 uv;
varying vec2 uvOutline;
varying vec2 reach;
varying vec2 maskTexel;
varying vec3 code;
float grown(vec2 at){
 float a=texture2D(uSheet,at).a;
 a=max(a,max(max(texture2D(uSheet,at+reach*vec2(1.0,0.0)).a,texture2D(uSheet,at-reach*vec2(1.0,0.0)).a),max(texture2D(uSheet,at+reach*vec2(0.0,1.0)).a,texture2D(uSheet,at-reach*vec2(0.0,1.0)).a)));
 return max(a,max(max(texture2D(uSheet,at+reach*.7).a,texture2D(uSheet,at-reach*.7).a),max(texture2D(uSheet,at+reach*vec2(.7,-.7)).a,texture2D(uSheet,at+reach*vec2(-.7,.7)).a)));
}
void main() {
 if(uMode.x>.5){
  float a=texture2D(uSheet,uv).a,any=a;
  if(uMode.y>.5){
   vec2 o=maskTexel*.25;
   vec4 taps=vec4(texture2D(uSheet,uv+o).a,texture2D(uSheet,uv-o).a,texture2D(uSheet,uv+vec2(o.x,-o.y)).a,texture2D(uSheet,uv+vec2(-o.x,o.y)).a);
   a=dot(taps,vec4(.25));
   any=max(max(taps.x,taps.y),max(taps.z,taps.w));
  }
  // The height stays whole wherever the figure reaches into the texel: a share of it would read as a lower figure.
  gl_FragColor=vec4(a,code.g*smoothstep(.02,.1,any),0.0,a);
  return;
 }
 float a=grown(uvOutline);
 if(uMode.y>.5)a=max(a,grown(uv));
 float solid=smoothstep(.25,.6,a);
 // Only the blocking fades at the rim. Height and kind stay whole there, or the rim would read as another, lower figure.
 gl_FragColor=vec4(code.r*solid,code.gb*smoothstep(.02,.1,a),solid);
}`;

interface Group { source: Phaser.Textures.TextureSource; data: Float32Array; count: number }

/** The picture that stands for a walking figure at rest: a shadow stretches every step of a leg, so the walk alone would flicker along it. */
function restingFrame(sprite: Phaser.GameObjects.Sprite): Phaser.Textures.Frame {
  return sprite.anims?.isPlaying && sprite.texture.has(String(WALKING_IDLE_FRAME)) ? sprite.texture.get(WALKING_IDLE_FRAME) : sprite.frame;
}

function writeFrame(data: Float32Array, at: number, frame: Phaser.Textures.Frame, mirrorX: boolean, mirrorY: boolean): void {
  data[at] = mirrorX ? frame.u1 : frame.u0; data[at + 1] = mirrorY ? frame.v1 : frame.v0;
  data[at + 2] = mirrorX ? frame.u0 - frame.u1 : frame.u1 - frame.u0; data[at + 3] = mirrorY ? frame.v0 - frame.v1 : frame.v1 - frame.v0;
}

/**
 * Figures as two shapes from one set of instances, one instanced draw per sheet each. The blocker in the occluder field is grown
 * and closed, so their shadows start at their contour without gaps. The mask is the plain picture shown this frame: it tells the
 * shadow pass where the visible figure ends and the ground begins.
 */
export class FigureSilhouettes {
  private readonly renderer: Phaser.Renderer.WebGL.WebGLRenderer;
  private readonly gpu: EnemyMeshGpu;
  /** One entry per target: a render texture runs its draws later, so each has to carry its own settings. */
  private readonly fieldEntry: Phaser.GameObjects.Shader;
  private readonly maskEntry: Phaser.GameObjects.Shader;
  private readonly groups = new Map<Phaser.Textures.TextureSource, Group>();
  private readonly fieldPlace = new Float32Array([1, 0, 0]);
  private readonly fieldMode = new Float32Array(2);
  private readonly maskPlace = new Float32Array([1, 0, 0]);
  private readonly maskMode = new Float32Array([1, 0]);
  private ready = false;
  private any = false;

  constructor(scene: Phaser.Scene, private readonly blend: number) {
    const renderer = this.renderer = scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer;
    this.gpu = new EnemyMeshGpu(renderer, sunShaderName('FigureSilhouette'), VERTEX, FRAGMENT, new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]), 2,
      new Uint16Array([0, 1, 2, 0, 2, 3]), ATTRIBUTES, CAPACITY);
    this.fieldEntry = this.createEntry(scene, this.fieldPlace, this.fieldMode);
    this.maskEntry = this.createEntry(scene, this.maskPlace, this.maskMode);
  }

  private createEntry(scene: Phaser.Scene, place: Float32Array, mode: Float32Array): Phaser.GameObjects.Shader {
    const name = sunShaderName('FigureSilhouetteEntry'), owner = this;
    const entry = new Phaser.GameObjects.Shader(scene, { name, shaderName: name, fragmentSource: 'precision mediump float;void main(){gl_FragColor=vec4(0.0);}' }, 0, 0, 1, 1);
    ownSunShader(entry, name);
    entry.renderNode.run = function (context, object, parent): void {
      runWithScopedBlend(this, () => owner.draw(context, place, mode), context, owner.blend, object, parent);
    };
    return entry.setOrigin(0);
  }

  begin(): void {
    for (const group of this.groups.values()) group.count = 0;
    this.ready = this.gpu.prepare();
    this.any = false;
  }

  /** False when this sprite cannot be drawn as a silhouette; the caller then falls back to a disc. */
  add(sprite: Phaser.GameObjects.Sprite | null, originX: number, originY: number, texelsPerPx: number, code: number): boolean {
    if (!this.ready || !sprite || sprite.alpha < MIN_SPRITE_ALPHA) return false;
    const frame = sprite.frame, source = frame.source;
    if (!source.glTexture) return false;
    let group = this.groups.get(source);
    if (!group) { group = { source, data: new Float32Array(CAPACITY * INSTANCE_WORDS), count: 0 }; this.groups.set(source, group); }
    if (group.count >= CAPACITY) return false;
    const width = sprite.displayWidth, height = sprite.displayHeight, c = Math.cos(sprite.rotation), s = Math.sin(sprite.rotation);
    const px = (0.5 - sprite.originX) * width, py = (0.5 - sprite.originY) * height;
    const mirrorX = sprite.flipX !== (sprite.scaleX < 0), mirrorY = sprite.flipY !== (sprite.scaleY < 0);
    const offset = group.count++ * INSTANCE_WORDS, data = group.data;
    data[offset] = (sprite.x + c * px - s * py - originX) * texelsPerPx; data[offset + 1] = (sprite.y + s * px + c * py - originY) * texelsPerPx;
    data[offset + 2] = width * texelsPerPx; data[offset + 3] = height * texelsPerPx;
    writeFrame(data, offset + 4, frame, mirrorX, mirrorY);
    writeFrame(data, offset + 8, restingFrame(sprite), mirrorX, mirrorY);
    data[offset + 12] = c; data[offset + 13] = s;
    data[offset + 14] = ((code >> 16) & 255) / 255; data[offset + 15] = ((code >> 8) & 255) / 255; data[offset + 16] = (code & 255) / 255;
    this.any = true;
    return true;
  }

  /** The grown blockers into the occluder field; `animated` adds the picture shown this frame to the resting outline. */
  drawInto(field: Phaser.GameObjects.RenderTexture, animated: boolean): void {
    if (!this.any) return;
    this.fieldMode[1] = animated ? 1 : 0;
    this.fieldEntry.setPosition(0, 0).setSize(field.width, field.height);
    field.draw(this.fieldEntry);
  }

  /** The plain pictures into a mask; `scale` and the offsets lead from field texels to the mask's. `coverage` averages each texel. */
  drawMask(mask: Phaser.GameObjects.RenderTexture, scale: number, offsetX: number, offsetY: number, coverage: boolean): void {
    if (!this.any) return;
    this.maskPlace[0] = scale; this.maskPlace[1] = offsetX; this.maskPlace[2] = offsetY;
    this.maskMode[1] = coverage ? 1 : 0;
    this.maskEntry.setPosition(0, 0).setSize(mask.width, mask.height);
    mask.draw(this.maskEntry);
  }

  destroy(): void {
    this.fieldEntry.destroy();
    this.maskEntry.destroy();
    this.gpu.destroy();
    this.groups.clear();
  }

  private draw(context: Phaser.Renderer.WebGL.DrawingContext, place: Float32Array, mode: Float32Array): void {
    const camera = context.camera!.getViewMatrix(!context.useCanvas);
    this.renderer.setProjectionMatrixFromDrawingContext(context);
    for (const group of this.groups.values()) {
      const texture = group.source.glTexture;
      if (!group.count || !texture) continue;
      this.gpu.draw(context, group.data.subarray(0, group.count * INSTANCE_WORDS), group.count, [texture], set => {
        set('uProjectionMatrix', this.renderer.projectionMatrix.val);
        set('uViewMatrix', [camera.a, camera.b, 0, camera.c, camera.d, 0, camera.tx, camera.ty, 1]);
        set('uSheet', 0); set('uPlace', place); set('uMode', mode);
      });
    }
  }
}
