import { CLAW_VFX_FAN_RAYS, CLAW_VFX_SLASH_MS, CLAW_VFX_TELEGRAPH_FADE_MS } from './EnemyClawVfxStore';

/** Landing mark tuning: base disk from the lock on, extra fill reached at the landing. */
const MARK_BASE_ALPHA = '0.1';
const MARK_FILL_ALPHA = '0.13';

/**
 * Analytic claw visuals, all passes reading the same instance buffer:
 * 0 ground telegraph below the figures, 1 rakes and contact marks above them (both lit by
 * the lightmap), 2 an additive emissive trace of everything above the lightmap, so the
 * warning stays readable at night; its alpha follows `emissiveAlpha` and fades by day.
 *
 * Attributes per vertex: world position, quad-local px (x = attack direction), timing
 * (start, strike, hit, end), shape (range/length or mark size, half arc/width, kind, seed), color.
 */
export const ENEMY_CLAW_VERTEX_SHADER = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform mat4 uProjectionMatrix;
uniform mat3 uViewMatrix;
uniform float uTime;
uniform float uPass;
attribute vec2 inPosition;
attribute vec2 inLocal;
attribute vec4 inTiming;
attribute vec4 inShape;
attribute vec4 inColor;
varying vec2 vLocal;
varying vec4 vTiming;
varying vec4 vShape;
varying vec4 vColor;
void main() {
  bool contact = inShape.z > 0.5 && inShape.z < 1.5;
  // Cull whole quads outside their pass/phase before any fragment work.
  bool live = uPass > 1.5 ? true : uPass < 0.5
    ? (!contact && uTime < inTiming.z + ${CLAW_VFX_TELEGRAPH_FADE_MS.toFixed(1)})
    : (contact || uTime >= inTiming.z);
  if (!live || uTime > inTiming.w) {
    gl_Position = vec4(0.0, 0.0, -2.0, 1.0);
  } else {
    vec3 view = uViewMatrix * vec3(inPosition, 1.0);
    gl_Position = uProjectionMatrix * vec4(view.xy, 0.0, 1.0);
  }
  vLocal = inLocal; vTiming = inTiming; vShape = inShape; vColor = inColor;
}`;

export const ENEMY_CLAW_FRAGMENT_SHADER = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform float uTime;
uniform float uPass;
uniform float uPixel;
uniform float uAlpha;
varying vec2 vLocal;
varying vec4 vTiming;
varying vec4 vShape;
varying vec4 vColor;

const float SLASH_MS = ${CLAW_VFX_SLASH_MS.toFixed(1)};
const float FADE_MS = ${CLAW_VFX_TELEGRAPH_FADE_MS.toFixed(1)};
const float PI = 3.14159265;
const vec3 HOT = vec3(1.0, 0.95, 0.88);

float line(float d, float halfWidth) {
  return 1.0 - smoothstep(halfWidth - uPixel, halfWidth + uPixel, abs(d));
}

// A soft, edgeless tint: the zone only needs to read roughly, so both flanks and the far
// end dissolve into transparency. A diffuse charge swell carries the timing instead of lines.
// Output is premultiplied.
vec4 telegraph(float gain) {
  float range = vShape.x;
  float halfArc = vShape.y;
  float r = length(vLocal);
  float rn = r / range;
  if (rn >= 1.0) return vec4(0.0);
  // A full circle (round zone) has no flanks: neither a fade nor a seam behind its axis.
  bool full = halfArc >= PI - 0.001;
  float an = abs(atan(vLocal.y, vLocal.x)) / max(halfArc, 0.001);
  if (!full && an >= 1.0) return vec4(0.0);

  float charge = clamp((uTime - vTiming.x) / max(1.0, vTiming.z - vTiming.x), 0.0, 1.0);
  float strike = smoothstep(vTiming.y, vTiming.z, uTime);
  float vis = smoothstep(vTiming.x, vTiming.x + 90.0, uTime)
    * (1.0 - smoothstep(vTiming.z, vTiming.z + FADE_MS, uTime));

  // The attacker's body covers the hub; flanks and far end fall off over a wide band.
  float hub = smoothstep(0.08, 0.4, rn);
  float flank = full ? 1.0 : 1.0 - smoothstep(0.4, 1.0, an);
  float reach = 1.0 - smoothstep(0.55, 1.0, rn);
  float mask = hub * flank * reach;

  // The swell grows outward with the windup and has no visible front edge.
  float swell = 1.0 - smoothstep(charge - 0.35, charge + 0.1, rn);
  float a = mask * (0.1 + 0.2 * swell * charge + 0.1 * strike) * gain * vis;
  vec3 color = mix(vColor.rgb, HOT, 0.35 * strike);
  return vec4(color * a, a);
}

// Large filled fan (energy cone): the same tint and charge swell as the melee sector, but the
// boundary is the gameplay contract here, so both flanks and the clipped reach end in crisp
// edges. One quad per wedge between two cover rays; vShape.w packs both ray reaches
// (q0 * 256 + q1, 0..255), vColor.a carries the wedge index. The wedge is picked from the
// global ray position, so neighbouring quads neither overlap nor leave seams.
vec4 fan(float gain) {
  float range = vShape.x;
  float halfArc = vShape.y;
  float r = length(vLocal);
  float ang = atan(vLocal.y, vLocal.x);
  float rayStep = 2.0 * halfArc / ${(CLAW_VFX_FAN_RAYS - 1).toFixed(1)};
  float g = (ang + halfArc) / rayStep;
  float wedge = vColor.a;
  if (g < -0.02 || clamp(floor(g), 0.0, ${(CLAW_VFX_FAN_RAYS - 2).toFixed(1)}) != wedge) return vec4(0.0);
  float q0 = floor(vShape.w / 256.0), q1 = vShape.w - q0 * 256.0;
  float reach = mix(q0, q1, clamp(g - wedge, 0.0, 1.0)) / 255.0 * range;
  float side = (halfArc - abs(ang)) * r;   // px to the nearer flank
  float inside = (1.0 - smoothstep(reach - 1.5 * uPixel, reach + 0.5 * uPixel, r))
    * smoothstep(-0.5 * uPixel, 1.5 * uPixel, side);
  if (inside <= 0.0) return vec4(0.0);

  float charge = clamp((uTime - vTiming.x) / max(1.0, vTiming.z - vTiming.x), 0.0, 1.0);
  float strike = smoothstep(vTiming.y, vTiming.z, uTime);
  float vis = smoothstep(vTiming.x, vTiming.x + 90.0, uTime)
    * (1.0 - smoothstep(vTiming.z, vTiming.z + FADE_MS, uTime));
  float rn = r / range;
  // The caster covers the hub; the fill brightens slightly toward the rim.
  float hub = smoothstep(10.0, 34.0, r);
  float swell = 1.0 - smoothstep(charge - 0.3, charge + 0.05, rn);
  float fill = hub * mix(0.75, 1.0, rn) * (0.1 + 0.2 * swell * charge + 0.1 * strike);
  // Outline: rim at the (clipped) reach and both flanks, firming up as the impulse nears.
  float edge = max(line(r - reach, 1.1), line(side, 1.0)) * smoothstep(14.0, 30.0, r);
  float a = (fill + edge * (0.22 + 0.28 * charge)) * inside * gain * vis;
  vec3 color = mix(vColor.rgb, HOT, 0.35 * strike + 0.15 * edge * charge);
  return vec4(color * a, a);
}

// Rectangle uses the Bite sector's normalized falloffs and diffuse charge swell.
// Only the geometry changes: no outline or precise advancing front.
vec4 lane(float gain) {
  float rn = vLocal.x / vShape.x;
  float an = abs(vLocal.y) / max(vShape.y, 0.001);
  if (rn <= 0.0 || rn >= 1.0 || an >= 1.0) return vec4(0.0);
  float charge = clamp((uTime - vTiming.x) / max(1.0, vTiming.z - vTiming.x), 0.0, 1.0);
  float strike = smoothstep(vTiming.y, vTiming.z, uTime);
  float vis = smoothstep(vTiming.x, vTiming.x + 90.0, uTime)
    * (1.0 - smoothstep(vTiming.z, vTiming.z + FADE_MS, uTime));
  float hub = smoothstep(0.08, 0.4, rn);
  float flank = 1.0 - smoothstep(0.4, 1.0, an);
  float reach = 1.0 - smoothstep(0.55, 1.0, rn);
  float swell = 1.0 - smoothstep(charge - 0.35, charge + 0.1, rn);
  float a = hub * flank * reach * (0.1 + 0.2 * swell * charge + 0.1 * strike) * gain * vis;
  return vec4(mix(vColor.rgb, HOT, 0.35 * strike) * a, a);
}

// Landing mark of an announced leap (pounce), shown from the lock on: a soft disk fades in and
// fills from its centre, reaching the hit radius exactly at the landing. Nothing is drawn beyond
// the hit radius, and there is no hub cut-out: the attacker is not standing in the zone.
// A half arc in vShape.y cuts it to a frontal sector: its flanks soften like the rim, centred on
// the hit edge so the zone reads exactly as wide as the strike.
vec4 mark(float gain) {
  float radius = vShape.x;
  float halfArc = vShape.y;
  float r = length(vLocal);
  float rn = r / radius;
  if (rn >= 1.05) return vec4(0.0);
  float flank = 1.0, flankRim = 0.0;
  if (halfArc > 0.001) {
    float soft = radius * 0.09;
    float side = (halfArc - abs(atan(vLocal.y, vLocal.x))) * r;   // px inside the nearer flank
    if (side <= -0.4 * soft) return vec4(0.0);
    flank = smoothstep(-0.4 * soft, soft, side);
    float fd = (side - 0.4 * soft) / (0.45 * soft);
    flankRim = exp(-fd * fd) * smoothstep(0.1, 0.3, rn);
  }
  float progress = clamp((uTime - vTiming.x) / max(1.0, vTiming.z - vTiming.x), 0.0, 1.0);
  float vis = smoothstep(vTiming.x, vTiming.x + 140.0, uTime)
    * (1.0 - smoothstep(vTiming.z, vTiming.z + FADE_MS, uTime));
  float edge = 1.0 - smoothstep(0.82, 1.0, rn);
  float disk = edge * flank;
  // The filled share grows with the remaining time and has a soft front.
  float front = radius * progress;
  float fillWidth = radius * 0.14;
  float filled = 1.0 - smoothstep(front - fillWidth, front + fillWidth, r);
  float rimD = (rn - 0.93) / 0.07;
  float rim = max(exp(-rimD * rimD) * flank, flankRim * edge) * (0.08 + 0.08 * progress);
  float a = (disk * (${MARK_BASE_ALPHA} + ${MARK_FILL_ALPHA} * filled) + rim) * gain * vis;
  if (a <= 0.0) return vec4(0.0);
  float warm = 0.25 * smoothstep(vTiming.z - 80.0, vTiming.z, uTime);
  vec3 color = mix(vColor.rgb, HOT, warm);
  return vec4(color * a, a);
}

// Two mirrored paws closing like a pincer: each drags three stacked claw arcs from the
// flank of the sector toward its centre line, reaching slightly further as it closes.
vec4 rake() {
  float t = uTime - vTiming.z;
  if (t < 0.0 || t > SLASH_MS) return vec4(0.0);
  float range = vShape.x;
  float halfArc = min(vShape.y, 1.35);
  vec2 p = vec2(vLocal.x, abs(vLocal.y));
  float r = max(length(p), 0.001);
  float ang = atan(p.y, p.x);
  float thetaStart = halfArc * 0.92;
  float thetaEnd = halfArc * 0.06;
  float q = (thetaStart - ang) / (thetaStart - thetaEnd);
  if (q < -0.02 || q > 1.02) return vec4(0.0);

  float reveal = 1.0 - pow(1.0 - clamp(t / 60.0, 0.0, 1.0), 2.0);
  float life = t / SLASH_MS;
  float fade = 1.0 - smoothstep(0.25, 1.0, life);
  float halfWidth = max(1.0, range * 0.026);
  float gap = max(3.0, range * 0.08);
  // Radius grows along the sweep; its angular rate sets the stroke's slant against the arc.
  float radiusGain = range * 0.26 / (thetaStart - thetaEnd);
  float norm = inversesqrt(1.0 + (radiusGain / r) * (radiusGain / r));

  float body = 0.0; float core = 0.0; float shade = 0.0; float tip = 0.0;
  for (int k = 0; k < 3; k++) {
    float o = float(k) - 1.0;
    float q0 = abs(o) * 0.08;
    float qq = (q - q0) / (1.0 - q0 - abs(o) * 0.1);
    if (qq < 0.0 || qq > 1.0) continue;
    float head = reveal * 1.15 - qq;
    if (head < 0.0) continue;
    float radius = range * (0.6 + 0.26 * q) + o * gap;
    float d = abs((r - radius) * norm);
    float w = halfWidth * pow(max(sin(PI * qq), 0.0), 0.55) * (1.0 - 0.2 * abs(o));
    body = max(body, 1.0 - smoothstep(w - uPixel, w + uPixel, d));
    core = max(core, 1.0 - smoothstep(0.0, max(w * 0.5, uPixel), d));
    shade = max(shade, 1.0 - smoothstep(w, w + 1.5 + uPixel * 2.0, d));
    tip = max(tip, 1.0 - smoothstep(0.0, 0.22, head));
  }
  float a = body * fade;
  vec3 color = mix(vColor.rgb, HOT, clamp(core * (1.0 - 0.7 * life) + tip * 0.5, 0.0, 1.0));
  // A thin dark shoulder separates the rake from bright ground without a hard outline.
  float shadow = max(shade - body, 0.0) * 0.32 * fade;
  return vec4(color * a, a * 0.92 + shadow);
}

// Short three-claw mark across the struck target plus a quick contact ring.
vec4 contact() {
  float size = vShape.x;
  float life = vTiming.w - vTiming.x;
  float t = uTime - vTiming.x;
  if (t < 0.0 || t > life) return vec4(0.0);
  vec2 p = vLocal;
  float fade = 1.0 - smoothstep(0.3, 1.0, t / life);
  float reveal = 1.0 - pow(1.0 - clamp(t / 45.0, 0.0, 1.0), 2.0);
  vec2 axis = normalize(vec2(0.5, 1.0));
  float along = dot(p, axis);
  float across = dot(p, vec2(-axis.y, axis.x));
  float gap = size * 0.26;
  float halfWidth = max(1.0, size * 0.075);

  float body = 0.0; float core = 0.0;
  for (int k = 0; k < 3; k++) {
    float o = float(k) - 1.0;
    float len = size * (0.8 - 0.16 * abs(o));
    float qq = (along + len) / (2.0 * len);
    if (qq < 0.0 || qq > 1.0 || qq > reveal * 1.1) continue;
    float w = halfWidth * pow(max(sin(PI * qq), 0.0), 0.55);
    float d = abs(across - o * gap + 0.12 * size * o * (qq - 0.5));
    body = max(body, 1.0 - smoothstep(w - uPixel, w + uPixel, d));
    core = max(core, 1.0 - smoothstep(0.0, max(w * 0.5, uPixel), d));
  }
  float r = length(p);
  float ringT = clamp(t / 190.0, 0.0, 1.0);
  float ringR = size * (0.3 + 0.6 * (1.0 - (1.0 - ringT) * (1.0 - ringT)));
  float ring = line(r - ringR, 0.9) * 0.5 * (1.0 - ringT);
  // Purely additive: brightens the struck body instead of veiling it.
  float flash = exp(-(r * r) / (size * size * 0.05)) * 0.3 * (1.0 - smoothstep(0.0, 90.0, t));

  float a = body * fade;
  vec3 color = mix(vColor.rgb, HOT, clamp(core * (1.0 - 0.6 * t / life), 0.0, 1.0));
  vec3 rgb = color * a + mix(vColor.rgb, HOT, 0.6) * ring + mix(vColor.rgb, HOT, 0.5) * flash;
  return vec4(rgb, a * 0.92 + ring * 0.45);
}

void main() {
  vec4 color;
  if (vShape.z > 4.5) color = uPass < .5 ? mark(1.0) : uPass > 1.5 ? mark(.55) : vec4(0.0);
  else if (vShape.z > 3.5) color = uPass < .5 ? fan(1.0) : uPass > 1.5 ? fan(.55) : vec4(0.0);
  else if (vShape.z > 2.5) color = uPass < .5 ? telegraph(1.0) : uPass > 1.5 ? telegraph(.55) : vec4(0.0);
  else if (vShape.z > 1.5) color = uPass < 0.5 ? lane(1.0) : uPass > 1.5 ? lane(0.55) : vec4(0.0);
  else if (uPass < 0.5) color = telegraph(1.0);
  else if (uPass < 1.5) color = vShape.z < 0.5 ? rake() : contact();
  // Emissive trace: a fainter copy of the tint keeps the zone readable under the night lightmap.
  else color = vShape.z < 0.5 ? telegraph(0.55) + rake() : contact();
  if (color.a <= 0.003 && max(color.r, max(color.g, color.b)) <= 0.003) discard;
  gl_FragColor = color * uAlpha;
}`;
