/**
 * Drahtformat zwischen Host und Client.
 *
 * Alle Nachrichten sind JSON-Objekte mit dem Diskriminator `t`. Feldnamen sind
 * absichtlich kurz: Der Snapshot-Batch geht mit NET_TICK_RATE_HZ über die Leitung.
 *
 * Zuverlässigkeit wird NICHT im Envelope kodiert, sondern über den Kanal gewählt,
 * auf dem gesendet wird (siehe PeerLink). Der Host relayt eine Client-Nachricht
 * immer über denselben Kanaltyp, über den sie eingetroffen ist.
 */
import { isValidRoomCode } from './roomCode';

/** Wird im Handshake verglichen; unterschiedliche Deploys dürfen sich nicht verbinden. */
// Input stops fence old movement; Tunnel commits require a host-observed first selection.
// Ready is lobby-revision-bound; active rounds use the host-frozen loadout snapshot.
// GameState deltas name the full baseline that must be consumed before them.
// Kraken spine/regrowth baselines and the appended spine action code require matching peers.
// Firestarter: appended `fire-lance-charge` action and `firestarter_orb` projectile style.
// Shield charger: appended enemy snapshot field for the host-fixed charge lane.
// Alien energy cone: appended enemy snapshot field for the host-fixed cone and cover profile.
// Fire control: required fc world slice and optional turretVisualId projectile static bit.
// Dawn: coop program and round scrap keys, plan fields, grouped encounter announcements, commit
// entitlements and the appended elite affix enemy snapshot field.
// Fire control portals: portal deployments in the fc slice, portal throw payload and route.
// Dawn expansion track: area stages end at 6, core HP bonus world parameter, Dawn plasma turret rewards.
// Inspector ultimates: holo deployments (fc kind 2), required bq bomber squadron slice and
// per-frame batched fcfx burst arrays with World revision.
// Bomber flight: seeded curves, replicated aim offsets/angles and extended bq plan parameters.
// Mini-Kraken: appended enemy kind (shifts the kraken boss/egg indices), submerged snapshot field
// and leap style on the shared charge lane; amphibious flow-field profiles.
// Quacksalber toad: appended hop snapshot field (jump timeline and heal links); the healing aura weapon is gone.
// Kabummtula: kind 12 renamed timebomb-badger -> kaboomtula, appended spider snapshot field (phase window,
// target ref, locked leap), required tw slice (turret web shots and webs); timebomb special actions retired.
// Void danger zones: encounter state names World spawn zones (fronts may be empty) and the
// required csz key announces spawn zones about to release enemies.
// Spawn places: the required csp key names spawn zones in use or still to come and lapsed dormant objectives.
// Bridges: required bg game-state slice (charged/collapsed bridges), World layout bridges.
// Portal generators: the cpl key carries the charge/open/collapse lifecycle of generator portal links.
// Reactive props: the required rp key carries explosive-barrel phases (index, phase code, progress byte).
// Recharging reactive props: rp carries recharge phases and progress; required sw slice (bee swarms of
// hives, one entry per swarm); sc carries the puffball dust styles.
// Burning ground: fg carries base64 run-length blobs keyed by style and raster cell (full f, delta d)
// and the warning band as full w or changed cells wd instead of JSON tuples with host ids.
// Lobby structures: host physics and fog follow checked-in building outlines that the layout
// fingerprint does not cover.
// Lobby structures stand per host-unlocked menu: the World descriptor carries lobbyItemsUnlocked and
// lobbyDawnUnlocked, and none stand before the persistent base.
// Spawn structures: csz also announces spawn structures (structure: true, zoneId = base id); spawn
// points are the canonical carcass footprint with the brood pit centre as spawn point.
// Persistent base core: four 3-cell corner bastions and 3-cell entrances (12 base cells instead of
// 20); host and client derive the core collision from code that the layout fingerprint does not cover.
// The core's anchor cell carries a solid hearth (13 base cells), derived from code the same way.
// Lagekarte: the host base document carries the base rotation (pbrs quarterTurns); maps no longer
// author a base orientation, and lsy carries the host-owned deployment seed of the next round.
// Round spawn zones: generator 17; a zone's organic outline (not its box) feeds route sources, and
// several campaign maps moved their zones (and map 2 its lake shore), so layouts differ between builds.
// Rabid Rabbit: the rabid badger's registry slot (wire kind 2) became `rabid-rabbit`, and enemy
// snapshots gained the pounce field (aim target, locked landing, flight timeline).
// Rabid Rabbit tuning: the pounce landing travels as the new explosion style `pounce_impact`.
// Void taint: enemy full states carry the spawn zone the enemy came out of (spawnZoneId).
// Demon Badger heat burst: enemy snapshots gained the heat timeline field, and the burst and the
// fizzle of a killed charged badger travel as the new explosion styles `demon_burst`/`demon_fizzle`.
// Grave Titan: enemy snapshots gained the volley field (gather, first shot, end, recharge, shots).
// Demon Badger V2: the heat field carries the salvo-fed stage and its step time instead of the
// charge timeline (revision, stage, stageAt, telegraphAt, burstAt).
// Corpse remains: an ncfx removal is { i, t: 0 } and names the reviving owner's colour (c) when the
// corpse was raised instead of only cleared.
// Flammenkoloss V2: enemy snapshots gained the boss phase and the colossus action timeline fields,
// mortar strikes a `void-incendiary` variant, explosions the styles `void_incendiary`/`colossus_quake`;
// projectiles carry a fixed homing assignment, and map 10 was rebuilt (128x56, base east, no track).
// Flammenkoloss beetle salvo: the colossus action timeline gained the kind `beetleSalvo` (index 5).
// Steam achievements: round result rows carry the player's achievement facts (`achievements`), and the
// Dawn round state names its night modifier (`dawn.nightModifierId`).
// Room handover: the host names its successor and the successor room code (`succ`, welcome `n`),
// announces its departure (`close`) and may close the room to new players (reject `room-closed`).
export const PEER_PROTOCOL_VERSION = 64;

/** Kanaltyp eines Links. 'rel' = geordnet+zuverlässig, 'fast' = ungeordnet+ohne Retransmit. */
export type PeerChannelKind = 'rel' | 'fast';

/** Client → Host, erste Nachricht nach dem Öffnen des zuverlässigen Kanals. */
export interface HelloMessage {
  t: 'hello';
  /** Protokollversion des Clients. */
  v: number;
  /** Stabiles, raumbezogenes Token fuer die kurze Wiederaufnahme desselben Spielerslots. */
  k: string;
  /** True nur bei einer Wiederverbindung innerhalb einer bereits laufenden Client-Session. */
  r?: boolean;
  /** Optional native lossless compression capability. Raw framing always works. */
  z?: 1;
}

export type RejectReason = 'room-full' | 'protocol-mismatch' | 'resume-expired' | 'room-closed';

const REJECT_REASONS: readonly RejectReason[] = ['room-full', 'protocol-mismatch', 'resume-expired', 'room-closed'];

/**
 * Host-bestimmte Nachfolge: Wer den Raum übernimmt, wenn der Host geht, und unter welchem
 * frischen Raumcode. `p` ist `null`, solange kein Gast verbunden ist.
 */
export interface RoomSuccession {
  p: string | null;
  c: string;
}

/** Host -> Client: Der Handshake kann nicht abgeschlossen werden. */
export interface RejectMessage {
  t: 'reject';
  k: RejectReason;
}

/** Ein Eintrag des Host-autoritativen Rosters. */
export interface RosterEntry {
  /** Spiel-seitige Spieler-ID (kurz, vom Host vergeben). */
  id: string;
}

/** Host → Client, Antwort auf `hello`. Enthält den vollständigen Store-Stand. */
export interface WelcomeMessage {
  t: 'welcome';
  v: number;
  /** Die dem Client zugewiesene Spieler-ID. */
  id: string;
  /** Spieler-ID des Hosts. */
  h: string;
  roster: RosterEntry[];
  /** Vollständiger globaler Store. */
  g: Record<string, unknown>;
  /** Vollständiger Per-Spieler-Store, außen nach Spieler-ID indiziert. */
  p: Record<string, Record<string, unknown>>;
  z?: 1;
  /** Aktuelle Nachfolge des Raums. */
  n?: RoomSuccession;
}

/** Host → Client: Die Nachfolge hat sich geändert. */
export interface SuccessionMessage extends RoomSuccession {
  t: 'succ';
}

/** Host → Client: Der Host verlässt den Raum bewusst; die Nachfolge übernimmt. */
export interface CloseMessage {
  t: 'close';
}

/** Host → Client: ein weiterer Spieler ist beigetreten. */
export interface JoinMessage {
  t: 'join';
  id: string;
  /** Bereits bekannter Zustand des neuen Spielers (kann leer sein). */
  s: Record<string, unknown>;
}

/** Host → Client: ein Spieler hat den Raum verlassen. */
export interface QuitMessage {
  t: 'quit';
  id: string;
}

/** Host → der gekickte Client: zuverlässige Einzelmeldung vor dem Link-Abbruch. */
export interface KickedMessage {
  t: 'kicked';
}

/** Client → Host: Der Client verlässt den Raum bewusst. Die Spieler-ID steht absichtlich nicht im Drahtformat. */
export interface LeaveMessage {
  t: 'leave';
}

/** Direkter Link-Liveness-Probe, wird nicht an andere Teilnehmer weitergereicht. */
export interface HeartbeatMessage {
  t: 'hb';
}

/** Antwort auf eine Link-Liveness-Probe. */
export interface HeartbeatAckMessage {
  t: 'hba';
}

/**
 * Gebündelte Store-Schreibvorgänge.
 * `g` = globale Keys als [key, value], `p` = Per-Spieler-Keys als [playerId, key, value].
 * Innerhalb eines Batches gewinnt der letzte Eintrag pro Key (die Sendeseite dedupliziert bereits).
 */
export interface BatchMessage {
  t: 'b';
  /** Monotone Sequenz auf dem Fast-Kanal; auf dem Reliable-Kanal nicht gesetzt. */
  q?: number;
  g?: Array<[string, unknown]>;
  p?: Array<[string, string, unknown]>;
}

/**
 * RPC-Aufruf. `c` ist die Correlation-ID des Aufrufers (0 = keine Antwort erwartet).
 * `s` trägt die Absender-Spieler-ID und wird ausschließlich vom Host gesetzt,
 * wenn er einen Client-Aufruf an alle weiterreicht – ein Client kann sie nicht fälschen,
 * weil der Host eingehende `s`-Felder verwirft.
 */
export interface RpcMessage {
  t: 'rpc';
  c: number;
  n: string;
  d: unknown;
  s?: string;
}

/** Antwort auf einen RPC-Aufruf mit `c > 0`. */
export interface RpcResultMessage {
  t: 'res';
  c: number;
  d: unknown;
}

export type PeerMessage =
  | HelloMessage
  | RejectMessage
  | WelcomeMessage
  | JoinMessage
  | QuitMessage
  | KickedMessage
  | LeaveMessage
  | SuccessionMessage
  | CloseMessage
  | HeartbeatMessage
  | HeartbeatAckMessage
  | BatchMessage
  | RpcMessage
  | RpcResultMessage;

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return isRecord(value);
}

function parseGlobalEntries(value: unknown): Array<[string, unknown]> | null {
  if (!Array.isArray(value)) return null;
  const entries: Array<[string, unknown]> = [];
  for (const raw of value) {
    if (!Array.isArray(raw) || raw.length !== 2 || typeof raw[0] !== 'string') continue;
    entries.push([raw[0], raw[1]]);
  }
  return entries;
}

function parsePlayerEntries(value: unknown): Array<[string, string, unknown]> | null {
  if (!Array.isArray(value)) return null;
  const entries: Array<[string, string, unknown]> = [];
  for (const raw of value) {
    if (!Array.isArray(raw) || raw.length !== 3 || typeof raw[0] !== 'string' || typeof raw[1] !== 'string') continue;
    entries.push([raw[0], raw[1], raw[2]]);
  }
  return entries;
}

function parseRoster(value: unknown): RosterEntry[] | null {
  if (!Array.isArray(value)) return null;
  const roster: RosterEntry[] = [];
  for (const raw of value) {
    if (!isRecord(raw) || typeof raw.id !== 'string' || raw.id.length === 0) continue;
    roster.push({ id: raw.id });
  }
  return roster;
}

function parseSuccession(value: unknown): RoomSuccession | null {
  if (!isRecord(value) || typeof value.c !== 'string' || !isValidRoomCode(value.c)) return null;
  const playerId = value.p;
  if (playerId !== null && (typeof playerId !== 'string' || playerId.length === 0)) return null;
  return { p: playerId as string | null, c: value.c.toUpperCase() };
}

function parsePlayerStates(value: unknown): Record<string, Record<string, unknown>> {
  if (!isRecord(value)) return {};
  const result: Record<string, Record<string, unknown>> = {};
  for (const [playerId, state] of Object.entries(value)) {
    if (isPlainRecord(state)) result[playerId] = { ...state };
  }
  return result;
}

/**
 * Validiert eine eingehende Nachricht. Gibt `null` zurück, wenn sie unbrauchbar ist –
 * unbekannte oder fehlerhafte Nachrichten werden verworfen, nicht geworfen, damit ein
 * einzelnes kaputtes Paket den Link nicht beendet.
 */
export function parsePeerMessage(raw: unknown): PeerMessage | null {
  if (typeof raw !== 'string') return null;

  let value: unknown;
  try {
    value = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!isRecord(value) || typeof value.t !== 'string') return null;

  switch (value.t) {
    case 'hello': {
      if (!Number.isSafeInteger(value.v) || typeof value.k !== 'string' || value.k.length < 16) return null;
      const message: HelloMessage = { t: 'hello', v: value.v as number, k: value.k };
      if (value.r === true) message.r = true;
      if (value.z === 1) message.z = 1;
      return message;
    }
    case 'reject': {
      const reason = REJECT_REASONS.find(candidate => candidate === value.k);
      if (!reason) return null;
      return { t: 'reject', k: reason };
    }
    case 'welcome': {
      if (!Number.isSafeInteger(value.v)
        || typeof value.id !== 'string' || value.id.length === 0
        || typeof value.h !== 'string' || value.h.length === 0) return null;
      const roster = parseRoster(value.roster);
      if (!roster) return null;
      const succession = value.n === undefined ? null : parseSuccession(value.n);
      return {
        t: 'welcome',
        v: value.v as number,
        id: value.id,
        h: value.h,
        roster,
        g: isPlainRecord(value.g) ? { ...value.g } : {},
        p: parsePlayerStates(value.p),
        ...(value.z === 1 ? { z: 1 as const } : {}),
        ...(succession ? { n: succession } : {}),
      };
    }
    case 'succ': {
      const succession = parseSuccession(value);
      return succession ? { t: 'succ', ...succession } : null;
    }
    case 'close':
      return { t: 'close' };
    case 'join': {
      if (typeof value.id !== 'string' || value.id.length === 0) return null;
      return { t: 'join', id: value.id, s: isPlainRecord(value.s) ? { ...value.s } : {} };
    }
    case 'quit': {
      if (typeof value.id !== 'string' || value.id.length === 0) return null;
      return { t: 'quit', id: value.id };
    }
    case 'kicked':
      return { t: 'kicked' };
    case 'leave':
      return { t: 'leave' };
    case 'hb':
      return { t: 'hb' };
    case 'hba':
      return { t: 'hba' };
    case 'b': {
      const message: BatchMessage = { t: 'b' };
      if (value.q !== undefined) {
        if (!Number.isSafeInteger(value.q) || (value.q as number) <= 0) return null;
        message.q = value.q as number;
      }
      if (value.g !== undefined) {
        const entries = parseGlobalEntries(value.g);
        if (!entries) return null;
        if (entries.length > 0) message.g = entries;
      }
      if (value.p !== undefined) {
        const entries = parsePlayerEntries(value.p);
        if (!entries) return null;
        if (entries.length > 0) message.p = entries;
      }
      if (!message.g && !message.p) return null;
      return message;
    }
    case 'rpc': {
      if (!Number.isSafeInteger(value.c) || (value.c as number) < 0
        || typeof value.n !== 'string' || value.n.length === 0) return null;
      const message: RpcMessage = { t: 'rpc', c: value.c as number, n: value.n, d: value.d };
      if (typeof value.s === 'string' && value.s.length > 0) message.s = value.s;
      return message;
    }
    case 'res': {
      if (!Number.isSafeInteger(value.c) || (value.c as number) <= 0) return null;
      return { t: 'res', c: value.c as number, d: value.d };
    }
    default:
      return null;
  }
}

export function encodePeerMessage(message: PeerMessage): string {
  return JSON.stringify(message);
}
