import * as Phaser from 'phaser';
import { runtimeFrameName, runtimeTextureFrame, runtimeTextureKey } from '../assets/RuntimeAtlases';
import { ownSunShader } from '../effects/sunlight/SunRenderTarget';
import { maxBlendMode } from '../graphics/CustomBlendModes';
import { getGraphicsQualityProfile } from '../graphics/GraphicsQuality';
import type { GroundCoverStampPlacement } from './GroundCoverField';
import { GROUND_HEIGHT_LEVEL_PX, GROUND_HEIGHT_PAGES, GROUND_HEIGHT_RANGE_PX, groundObjectHeightPx } from './GroundHeightConfig';
import { GROUND_MACRO_KEY, GROUND_MACRO_TILE_SCALE } from './GroundMaterialConfig';

export const GROUND_HEIGHT_BASE_SHADER = 'GroundHeightBase';
/** Mean brightness of the macro map, and how many px of ground one unit of it stands for. */
const MACRO_MEAN = 0.857;
const MACRO_WAVE_PX = 25;
/** How far from a texel the taps average the grain of a material away; closer taps let it beat against the normal's taps into a lattice. */
const GRAIN_TEXELS = 3.5;
const SEAM_TEXELS = 3;

export const GROUND_HEIGHT_BASE_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
varying vec2 outTexCoord;
uniform sampler2D uMacro,uSoil,uGravel,uTrack;
// World x, y and side of the region; width of one texel in UV.
uniform vec4 uRegion;
uniform float uMacroSpan;
uniform vec2 uHas;
float luma(vec4 c){return dot(c.rgb/max(c.a,.02),vec3(.3,.6,.1));}
float grain(sampler2D source,vec2 uv){
 vec2 t=vec2(uRegion.w*${GRAIN_TEXELS.toFixed(1)});
 return .25*(luma(texture2D(source,uv+t))+luma(texture2D(source,uv-t))+luma(texture2D(source,uv+vec2(t.x,-t.y)))+luma(texture2D(source,uv-vec2(t.x,-t.y))));
}
// The soil's edge interleaves with single grass blades; as height that would be noise.
float seam(sampler2D source,vec2 uv){
 vec2 t=vec2(uRegion.w*${SEAM_TEXELS.toFixed(1)});
 return .2*(texture2D(source,uv).a+texture2D(source,uv+t).a+texture2D(source,uv-t).a+texture2D(source,uv+vec2(t.x,-t.y)).a+texture2D(source,uv-vec2(t.x,-t.y)).a);
}
void main(){
 vec2 world=uRegion.xy+vec2(outTexCoord.x,1.0-outTexCoord.y)*uRegion.z;
 float macro=dot(texture2D(uMacro,fract(world/uMacroSpan)).rgb,vec3(.3,.6,.1));
 float level=${GROUND_HEIGHT_LEVEL_PX.toFixed(1)};
 float h=level+(macro-${MACRO_MEAN.toFixed(3)})*${MACRO_WAVE_PX.toFixed(1)};
 // Soil lies a little below the grass and shows its own grain.
 float soil=seam(uSoil,outTexCoord);
 if(soil>.01)h=mix(h,level-.8+(grain(uSoil,outTexCoord)-.25)*4.0,soil);
 if(uHas.x>.5){float gravel=seam(uGravel,outTexCoord);if(gravel>.01)h=mix(h,level-.4+(grain(uGravel,outTexCoord)-.46)*3.5,gravel);}
 if(uHas.y>.5){float track=texture2D(uTrack,outTexCoord).a;if(track>.01)h=mix(h,level+.6+(grain(uTrack,outTexCoord)-.46)*3.5,track);}
 gl_FragColor=vec4(vec3(clamp(h/${GROUND_HEIGHT_RANGE_PX.toFixed(1)},0.0,1.0)),1.0);
}`;

export interface GroundHeightSources {
  readonly soil: Phaser.GameObjects.RenderTexture;
  readonly gravel: Phaser.GameObjects.RenderTexture | null;
  readonly track: Phaser.GameObjects.RenderTexture | null;
}

/** Writes one region of the ground's height layer: the materials as a base, every object stamped above them. */
export class GroundHeightBaker {
  private readonly quad: Phaser.GameObjects.Shader;
  private readonly blend: number;
  private readonly region = new Float32Array(4);
  private readonly has = new Float32Array(2);

  /** High and Ultra build the height layer once its source pages are loaded. */
  static create(scene: Phaser.Scene): GroundHeightBaker | null {
    if (getGraphicsQualityProfile(scene).level !== 'high') return null;
    for (const page of Object.values(GROUND_HEIGHT_PAGES)) if (!scene.textures.exists(page.key)) return null;
    return new GroundHeightBaker(scene);
  }

  private constructor(private readonly scene: Phaser.Scene) {
    this.blend = maxBlendMode(scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer);
    const macroSpan = scene.textures.getFrame(GROUND_MACRO_KEY).width * GROUND_MACRO_TILE_SCALE;
    const quad = this.quad = new Phaser.GameObjects.Shader(scene, {
      name: GROUND_HEIGHT_BASE_SHADER, shaderName: GROUND_HEIGHT_BASE_SHADER, fragmentSource: GROUND_HEIGHT_BASE_FRAGMENT,
      setupUniforms: (set: (name: string, value: unknown) => void) => {
        set('uMacro', 0); set('uSoil', 1); set('uGravel', 2); set('uTrack', 3);
        set('uRegion', this.region); set('uMacroSpan', macroSpan); set('uHas', this.has);
      },
    }, 0, 0, 2, 2, [GROUND_MACRO_KEY, '__WHITE', '__WHITE', '__WHITE']);
    ownSunShader(quad, GROUND_HEIGHT_BASE_SHADER, true);
    quad.setOrigin(0);
  }

  begin(target: Phaser.GameObjects.RenderTexture, worldX: number, worldY: number, size: number, sources: GroundHeightSources): void {
    this.region[0] = worldX; this.region[1] = worldY; this.region[2] = size; this.region[3] = 1 / size;
    this.has[0] = sources.gravel ? 1 : 0; this.has[1] = sources.track ? 1 : 0;
    const textures = this.scene.textures, empty = textures.get('__WHITE');
    this.quad.setTextures([textures.get(GROUND_MACRO_KEY), sources.soil.texture, sources.gravel?.texture ?? empty, sources.track?.texture ?? empty]);
    target.clear();
    this.quad.setPosition(0, 0).setSize(size, size);
    target.draw(this.quad);
  }

  stampCover(target: Phaser.GameObjects.RenderTexture, placements: readonly GroundCoverStampPlacement[], offsetX: number, offsetY: number): void {
    for (const p of placements) {
      const frame = runtimeTextureFrame(this.scene.textures, p.textureKey);
      if (!frame) continue;
      const scale = p.sizePx / Math.max(frame.width, frame.height);
      this.stamp(target, p.textureKey, p.sizePx, p.worldX + offsetX, p.worldY + offsetY, p.rotation, p.mirrorX ? -scale : scale, p.mirrorY ? -scale : scale);
    }
  }

  stampDecal(target: Phaser.GameObjects.RenderTexture, id: string, x: number, y: number, size: number, rotation: number): void {
    const frame = runtimeTextureFrame(this.scene.textures, id);
    if (frame) this.stamp(target, id, size, x, y, rotation, size / frame.width, size / frame.height);
  }

  /** An object placed outside the baked layers; `colourKey` is the atlas its picture comes from. */
  stampObject(target: Phaser.GameObjects.RenderTexture, colourKey: string, frameName: string, x: number, y: number, size: number, rotation: number, alpha: number): void {
    const lift = groundObjectHeightPx(frameName, size) * Math.sqrt(alpha);
    const page = GROUND_HEIGHT_PAGES[colourKey];
    if (lift <= 0 || !page) return;
    const colour = this.scene.textures.getFrame(colourKey, frameName);
    const texture = this.scene.textures.get(page.key);
    if (!texture.has(frameName)) texture.add(frameName, 0, colour.cutX, colour.cutY, colour.cutWidth, colour.cutHeight);
    target.stamp(page.key, frameName, x, y, { rotation, scaleX: size / colour.realWidth, scaleY: size / colour.realHeight, tint: this.heightTint(lift), blendMode: this.blend });
  }

  destroy(): void { this.quad.destroy(); }

  private heightTint(lift: number): number {
    const value = Math.round(Math.min(1, (GROUND_HEIGHT_LEVEL_PX + lift) / GROUND_HEIGHT_RANGE_PX) * 255);
    return (value << 16) | (value << 8) | value;
  }

  private stamp(target: Phaser.GameObjects.RenderTexture, id: string, sizePx: number, x: number, y: number, rotation: number, scaleX: number, scaleY: number): void {
    const lift = groundObjectHeightPx(id, sizePx);
    if (lift <= 0) return;
    const frame = this.heightFrame(id);
    if (!frame) return;
    target.stamp(frame.key, frame.name, x, y, { rotation, scaleX, scaleY, tint: this.heightTint(lift), blendMode: this.blend });
  }

  private heightFrame(id: string): { key: string; name: string } | null {
    const page = GROUND_HEIGHT_PAGES[runtimeTextureKey(id)], name = runtimeFrameName(id);
    if (!page || !name) return null;
    const texture = this.scene.textures.get(page.key);
    if (!texture.has(name)) {
      const source = runtimeTextureFrame(this.scene.textures, id);
      texture.add(name, 0, source.cutX, source.cutY, source.cutWidth, source.cutHeight);
    }
    return { key: page.key, name };
  }
}
