import type * as Phaser from 'phaser';

type Renderer = Phaser.Renderer.WebGL.WebGLRenderer;

/**
 * One retained slot per renderer: removeBlendMode splices the array and would shift other users'
 * indices. Phaser 4.2.1 addBlendMode returns (inserted index - 1), but DrawingContext indexes
 * blendModes directly, so the appended slot itself is used. addBlendMode accepts only combined
 * factors; updateBlendMode also takes separate alpha factors.
 */
function retainedMode(cache: WeakMap<Renderer, number>, renderer: Renderer, factors: (gl: WebGLRenderingContext) => number[]): number {
  let mode = cache.get(renderer);
  if (mode === undefined) {
    const gl = renderer.gl, all = factors(gl);
    mode = renderer.blendModes.length;
    renderer.addBlendMode([all[0], all[1]], gl.FUNC_ADD);
    renderer.updateBlendMode(mode, all, gl.FUNC_ADD);
    cache.set(renderer, mode);
  }
  return mode;
}

const modulateModes = new WeakMap<Renderer, number>();
/** result = 2 * src * dst. Keeps destination coverage: later Phaser ADD draws use DST_ALPHA, even for RGB. */
export function modulate2xBlendMode(renderer: Renderer): number {
  return retainedMode(modulateModes, renderer, gl => [gl.DST_COLOR, gl.SRC_COLOR, gl.ZERO, gl.ONE]);
}

const maxModes = new WeakMap<Renderer, number>();
/** Per-channel maximum: the taller or stronger blocker wins in the occluder field. */
export function maxBlendMode(renderer: Renderer): number {
  let mode = maxModes.get(renderer);
  if (mode === undefined) {
    const gl = renderer.gl as WebGL2RenderingContext;
    mode = renderer.blendModes.length;
    renderer.addBlendMode([gl.ONE, gl.ONE], gl.MAX);
    maxModes.set(renderer, mode);
  }
  return mode;
}

const lightAddModes = new WeakMap<Renderer, number>();
/**
 * Adds colour and leaves alpha alone. Phaser's ADD multiplies the destination by DST_ALPHA; in a
 * float target alpha can rise above 1 and the sum would run away.
 */
export function lightAddBlendMode(renderer: Renderer): number {
  return retainedMode(lightAddModes, renderer, gl => [gl.ONE, gl.ONE, gl.ZERO, gl.ONE]);
}
