import type * as Phaser from 'phaser';
import { ALLIED_PALETTE, DEPTH_LIGHTING, VOID_PALETTE } from '../../config';
import { getCoopDefenseEnemyConfig } from '../../config/coopDefenseEnemies';
import { enemyEmissionTextureKey, enemyEmissionZones } from '../../config/enemyEmission';
import { getPipelineAssetForTexture } from '../../config/pipelineAssets';
import type { EnemyVisualSource } from '../../entities/EnemyVisualSource';
import { enemyVolleyChargeAt, enemyVolleyPhaseAt, type EnemyVolleyState } from '../../systems/EnemyVolleyState';
import type { InfernoColossusAction } from '../../systems/InfernoColossusState';
import { emissiveAlpha } from '../EmissiveScale';
import {
  ColossusEmissionBatchData, createColossusEmissionGpuLayer, type ColossusEmissionGpuLayer, type ColossusEmissionPalette,
} from './InfernoColossusEmissionGpuLayer';
import type { InfernoColossusHeatEffects } from './InfernoColossusHeatEffects';

const EMISSION_DEPTH = DEPTH_LIGHTING + 0.08;
/** By day the light keeps most of its strength; ADD over pale ash would otherwise wash it out. */
const DAY_FLOOR = 0.75;
/** Where the light sleeps, the sheet's painted glow sinks by up to this share (with the sprite's alpha). */
const PAINT_SINK = 0.8;
/** The jets' edges cool down this long after a burst. */
const FLAME_COOL_MS = 420;
/** A big release flashes and settles back over this time. */
const FLASH_MS = 420;
const SIEGE_PULSE_MS = 260;
const SALVO_PULSE_MS = 160;

const HOSTILE_PALETTE: ColossusEmissionPalette = { glow: 0x9b3dff, hot: VOID_PALETTE.bright, deep: 0x4a0f9a };
const ALLIED_PALETTE_GLOW: ColossusEmissionPalette = { glow: ALLIED_PALETTE.primary, hot: ALLIED_PALETTE.bright, deep: ALLIED_PALETTE.deep };

/** Light of the colossus's zones in [0, 1], the mandibles' heat and its heartbeat. */
export interface InfernoColossusZoneLevels {
  readonly cracks: number;
  readonly mandibles: number;
  readonly core: number;
  readonly wings: number;
  /** White heat of the mandible edges in [0, 1]: rises through the ignition, full while the jets burn. */
  readonly heat: number;
  /** Heartbeats per second and their strength in [0, 1.5]. */
  readonly beatRate: number;
  readonly beatGain: number;
}

const clamp01 = (value: number): number => Math.max(0, Math.min(1, value));
const mix = (from: number, to: number, t: number): number => from + (to - from) * clamp01(t);
const progress = (now: number, from: number, to: number): number => clamp01((now - from) / Math.max(1, to - from));
/** 1 at `at`, falling to 0 over `ms` afterwards; 0 before it. */
const flash = (now: number, at: number, ms: number): number => now < at ? 0 : clamp01(1 - (now - at) / ms);

/**
 * The colossus's light from the replicated phase, volley and action timeline. The veined chitin
 * smoulders (stronger once the carapace is open; the shader lets regions of it wake and sink), the
 * mandibles heat up through the flame's ignition and stay white-hot while it burns, the lantern's
 * heart beats faster through every big action and pulses with every siege wave, and the burning wings
 * blaze in flight and siege. The phase change breaks the light open up to its shockwave.
 */
export function infernoColossusZoneLevels(phaseTwo: boolean, action: InfernoColossusAction | null,
  volley: EnemyVolleyState | null, now: number, siegeWaveAtMs: readonly number[] = [],
  salvo?: { readonly count: number; readonly intervalMs: number }): InfernoColossusZoneLevels {
  let cracks = phaseTwo ? 0.78 : 0.6;
  let mandibles = 0.35;
  let core = phaseTwo ? 0.8 : 0.45;
  let wings = phaseTwo ? 0.7 : 0;
  let heat = 0;
  let beatRate = phaseTwo ? 0.95 : 0.7;
  let beatGain = phaseTwo ? 0.9 : 0.5;

  if (volley) {
    const phase = enemyVolleyPhaseAt(volley, now);
    if (phase === 'charge') {
      const charge = enemyVolleyChargeAt(volley, now);
      heat = charge * charge;
      mandibles = mix(mandibles, 1, charge);
    } else if (phase === 'fire') {
      heat = 1;
      mandibles = 1;
    } else if (volley.endedAt > 0) {
      const cool = flash(now, volley.endedAt, FLAME_COOL_MS);
      heat = cool * cool;
      mandibles = Math.max(mandibles, cool);
    }
  }

  if (action && now >= action.startedAt && now < action.endsAt) {
    switch (action.kind) {
      case 'transition': {
        const open = progress(now, action.startedAt, action.releaseAt), burst = flash(now, action.releaseAt, action.endsAt - action.releaseAt);
        cracks = Math.max(mix(cracks, 1, open * open), burst);
        core = Math.max(mix(core, 1, open), burst);
        wings = Math.max(wings, burst);
        beatRate = mix(beatRate, 2.4, open);
        beatGain = Math.max(beatGain, 1.2 * open, 1.4 * burst);
        break;
      }
      case 'glutstoss': {
        const charge = progress(now, action.startedAt, action.commitAt), burst = flash(now, action.commitAt, FLASH_MS);
        core = Math.max(mix(core, 1, charge * charge), burst);
        cracks = Math.max(mix(cracks, 1, charge), burst);
        beatRate = mix(beatRate, 2.6, charge);
        beatGain = Math.max(beatGain, 1.3 * charge, 1.5 * burst);
        break;
      }
      case 'incendiary': {
        const windup = progress(now, action.startedAt, action.releaseAt);
        core = Math.max(mix(core, 1, windup), flash(now, action.releaseAt, FLASH_MS));
        beatRate = mix(beatRate, 1.8, windup);
        beatGain = Math.max(beatGain, 1.1 * windup);
        break;
      }
      case 'siege': {
        let pulse = 0;
        for (const at of siegeWaveAtMs) {
          const waveAt = action.startedAt + at;
          pulse = Math.max(pulse, flash(now, waveAt, SIEGE_PULSE_MS), now < waveAt ? progress(now, waveAt - 200, waveAt) * 0.6 : 0);
        }
        core = 1;
        wings = Math.max(wings, 0.85 + 0.15 * pulse);
        cracks = Math.max(cracks, 0.85 + 0.15 * pulse);
        beatRate = 1.7;
        beatGain = Math.max(beatGain, 1 + 0.5 * pulse);
        break;
      }
      case 'beetleSalvo': {
        // The body (veins, heart, burning wings), not the mandibles, lights up through the windup,
        // stays full while the beetles leave and fades after the last one.
        const lit = now < action.releaseAt ? progress(now, action.startedAt, action.releaseAt) ** 2
          : now <= action.commitAt ? 1 : flash(now, action.commitAt, FLASH_MS);
        let pulse = 0;
        for (let shot = 0; shot < (salvo?.count ?? 0); shot++) pulse = Math.max(pulse, flash(now, action.releaseAt + shot * salvo!.intervalMs, SALVO_PULSE_MS));
        cracks = Math.max(cracks, mix(cracks, 1, lit));
        core = Math.max(core, mix(core, 1, lit));
        if (phaseTwo) wings = Math.max(wings, mix(wings, 1, lit));
        beatRate = mix(beatRate, 2.2, lit);
        beatGain = Math.max(beatGain, 1.2 * lit + 0.3 * pulse);
        break;
      }
      case 'flight': {
        const lift = progress(now, action.startedAt, action.releaseAt);
        const airborne = now >= action.releaseAt && now < action.commitAt;
        wings = Math.max(wings, airborne ? 1 : mix(wings, 1, lift), flash(now, action.commitAt, FLASH_MS));
        cracks = Math.max(cracks, flash(now, action.commitAt, FLASH_MS));
        beatRate = airborne ? 2 : beatRate;
        break;
      }
    }
  }
  return { cracks: clamp01(cracks), mandibles: clamp01(mandibles), core: clamp01(core), wings: clamp01(wings), heat: clamp01(heat),
    beatRate, beatGain: Math.max(0, Math.min(1.5, beatGain)) };
}

/**
 * The colossus's living light: one quad per body on the colossus emission layer of the presented sheet
 * (closed carapace in phase 1, open from phase 2) with all four zones at once; the shader lets the light
 * move organically. The heart's phase accumulates per body, so a changing rate never jumps. Heat
 * effects (light map, haze, shimmer) follow the same levels. Emission sheets are rendered at half size;
 * the quad takes the body's display size.
 */
export class InfernoColossusGlowPresentation {
  private readonly emissionData = new Map<string, ColossusEmissionBatchData>();
  private readonly emissionLayers = new Map<string, ColossusEmissionGpuLayer | null>();
  private readonly hearts = new Map<string, { beat: number; at: number }>();
  private heat: InfernoColossusHeatEffects | null = null;

  constructor(private readonly scene: Phaser.Scene) {}

  setHeatEffects(heat: InfernoColossusHeatEffects | null): void { this.heat = heat; }

  render(enemies: readonly EnemyVisualSource[], now: number): void {
    for (const data of this.emissionData.values()) data.begin();
    this.heat?.beginFrame();
    const seen = new Set<string>();
    for (const enemy of enemies) {
      const config = getCoopDefenseEnemyConfig(enemy.kind);
      const state = config.infernoColossus ? enemy.getInfernoColossusState?.() : undefined;
      const sprite = enemy.sprite;
      if (!state || !sprite.active || !sprite.visible || enemy.getHp() <= 0) continue;
      const phaseTwoAsset = config.phaseTwoImageKey ? getPipelineAssetForTexture(config.phaseTwoImageKey) : undefined;
      const phaseTwo = sprite.texture.key === phaseTwoAsset?.sheetTextureKey;
      const asset = phaseTwo ? phaseTwoAsset : getPipelineAssetForTexture(config.imageKey);
      if (!asset || sprite.texture.key !== asset.sheetTextureKey) continue;
      const allied = enemy.faction === 'allied';
      // An allied (raised) colossus keeps no phases or actions: only its smoulder and flame.
      const levels = infernoColossusZoneLevels(phaseTwo, allied ? null : state.action, enemy.getVolleyState?.() ?? null, now,
        config.infernoColossus?.siege.waveAtMs, config.infernoColossus?.beetleSalvo);
      seen.add(enemy.id);
      const heart = this.hearts.get(enemy.id) ?? { beat: Math.random(), at: now };
      heart.beat += levels.beatRate * Math.max(0, Math.min(100, now - heart.at)) / 1000;
      heart.at = now;
      this.hearts.set(enemy.id, heart);
      const strength = Math.max(emissiveAlpha(sprite.alpha), sprite.alpha * DAY_FLOOR);
      this.heat?.body(enemy.id, sprite, asset, levels, heart.beat, phaseTwo, allied, now);
      const key = enemyEmissionTextureKey(sprite.texture.key);
      const data = this.emissionData.get(key) ?? this.createLayer(key, enemyEmissionZones(asset));
      const frame = data && this.scene.textures.getFrame(key, sprite.frame.name);
      if (!data || !frame) continue;
      data.push({ x: sprite.x, y: sprite.y, rotation: sprite.rotation, width: Math.abs(sprite.displayWidth),
        height: Math.abs(sprite.displayHeight), originX: sprite.originX, originY: sprite.originY, flipX: sprite.flipX,
        flipY: sprite.flipY, u0: frame.u0, v0: frame.v0, u1: frame.u1, v1: frame.v1, seed: seedOf(enemy.id), allied,
        veins: levels.cracks, mandibles: levels.mandibles, lantern: levels.core, wings: levels.wings,
        heat: levels.heat, beat: heart.beat, beatGain: levels.beatGain, strength, sink: sprite.alpha * PAINT_SINK });
    }
    for (const id of this.hearts.keys()) if (!seen.has(id)) this.hearts.delete(id);
    this.heat?.endFrame();
  }

  clear(): void {
    for (const layer of this.emissionLayers.values()) layer?.image.destroy();
    this.emissionLayers.clear();
    this.emissionData.clear();
    this.hearts.clear();
    this.heat?.clear();
  }

  /** One GPU layer per emission sheet, created once it is loaded (null without WebGL). */
  private createLayer(key: string, zones: number): ColossusEmissionBatchData | null {
    if (this.emissionLayers.has(key) || !this.scene.textures.exists(key)) return null;
    const data = new ColossusEmissionBatchData();
    const layer = createColossusEmissionGpuLayer(this.scene, data, key, zones, EMISSION_DEPTH, () => this.scene.time.now % 3_600_000,
      HOSTILE_PALETTE, ALLIED_PALETTE_GLOW);
    this.emissionLayers.set(key, layer);
    if (!layer) return null;
    this.emissionData.set(key, data);
    data.begin();
    return data;
  }
}

/** A stable small offset per body, so two colossi never glow in step. */
function seedOf(id: string): number {
  let hash = 0;
  for (let i = 0; i < id.length; i++) hash = (hash * 31 + id.charCodeAt(i)) | 0;
  return (Math.abs(hash) % 1000) / 37;
}
