import * as Phaser from 'phaser';
import { enableFloatColorBuffer } from '../../utils/webglContext';
import { DEPTH_LIGHTING } from '../../config';
import { modulate2xBlendMode } from '../../graphics/CustomBlendModes';
import { runWithScopedBlend } from '../../graphics/PhaserScopedBlend';
import { getClarityCameraRegistry } from '../../scenes/arena/ClarityCameraRegistry';
import { ownSunShader, SunRenderTarget } from '../sunlight/SunRenderTarget';
import { LIGHT_HDR_HEADROOM } from './LightHdrModel';

export const LIGHT_HDR_COMPOSITE_SHADER = 'LightHdrComposite';
export const LIGHT_HDR_SCATTER_SHADER = 'LightHdrScatter';
export const LIGHT_HDR_BRIGHT_SHADER = 'LightHdrBright';
export const LIGHT_HDR_GLOW_SHADER = 'LightHdrGlow';
/** Reach of the soft halo around strong light, in world pixels. */
const GLOW_RADIUS_PX = 72;
const GLOW_STRENGTH = 0.42;
/** Light below this stays out of the halo, at night; by day the bright floor takes over. */
const GLOW_THRESHOLD = 0.75;
/** Halvings of the map before a disc: a beam's bright tip has to be wider than the disc's taps, or each tap draws a copy of it. */
const CHAIN_HALVINGS = 2;
const GLOW_DISC_TAPS = 12;
/** Blur of all light for the fog: what lies around a spot of plain fog, and the longer reach of void haze. */
/** How much deeper coloured light gets: always, and on top where it is strong (from, full, in the map's units). */
const DEEPEN_BASE = 1.3;
const DEEPEN_STRONG = 0.9;
const DEEPEN_FROM = 0.5;
const DEEPEN_FULL = 2.2;
const DEEPEN_FROM_SATURATION = 0.15;
const DEEPEN_FULL_SATURATION = 0.4;
const NO_DEEPEN = [0, 0] as const;
const DEEPEN = [DEEPEN_BASE, DEEPEN_STRONG] as const;
const FOG_WIDE_LIGHT_PX = 26;
const FOG_FAR_LIGHT_PX = 64;

/**
 * Light above the night with its colour deepened, the more the stronger it is. Lights of one colour that come together add
 * up in every channel; scaled back as a whole they would end pale, and a pale strong light bleaches whatever it lies on. So
 * the brightest channel is kept and the others are lowered by the same share: much violet light is deep violet, white stays white.
 */
const DEEPEN_GLSL = `
// Depth of all light above the night; what strong light adds to it.
uniform vec2 uDeepen;
vec3 deepen(vec3 excess) {
  float top = max(excess.r, max(excess.g, excess.b)), low = min(excess.r, min(excess.g, excess.b));
  if (top <= 0.0001 || uDeepen.x <= 0.0 || top - low <= 0.00001) return excess;
  // A graphics driver may divide by multiplying with a reciprocal, which lands a hair above 1 for a pure colour; the root of a
  // negative number below would then be no number at all, and such a pixel is drawn black.
  float saturation = min((top - low) / top, 1.0);
  float depth = uDeepen.x + uDeepen.y * smoothstep(${DEEPEN_FROM.toFixed(2)}, ${DEEPEN_FULL.toFixed(2)}, top);
  // Lamps are nearly white and stay as they are; only light that has a colour is drawn further into it.
  float deepened = mix(saturation, 1.0 - pow(max(1.0 - saturation, 0.0001), depth), smoothstep(${DEEPEN_FROM_SATURATION.toFixed(2)}, ${DEEPEN_FULL_SATURATION.toFixed(2)}, saturation));
  // All channels keep their order and spacing, so the hue stays: orange gets deeper, not red.
  return top - (top - excess) * (deepened / saturation);
}`;

export const LIGHT_HDR_COMPOSITE_FRAGMENT = `
precision highp float;
uniform sampler2D uLightMap;
uniform sampler2D uAmbientLayer;
uniform vec3 uAmbient;
uniform float uAmbientLayerOn;
varying vec2 outTexCoord;
${DEEPEN_GLSL}
void main() {
  vec3 light = texture2D(uLightMap, outTexCoord).rgb;
  vec3 floorLight = uAmbient + (uAmbientLayerOn > 0.5 ? texture2D(uAmbientLayer, outTexCoord).rgb : vec3(0.0));
  floorLight = min(floorLight, light);
  light = floorLight + deepen(light - floorLight);
  float peak = max(light.r, max(light.g, light.b));
  float scale = peak <= 1.0 ? 1.0 : (1.0 + (1.0 - exp(1.0 - peak)) * ${LIGHT_HDR_HEADROOM.toFixed(3)}) / peak;
  gl_FragColor = vec4(light * scale * 0.5, 0.5);
}
`;

export const LIGHT_HDR_SCATTER_FRAGMENT = `
precision highp float;
uniform sampler2D uLightMap;
uniform sampler2D uAmbientLayer;
uniform sampler2D uGlow;
uniform vec3 uAmbient;
uniform float uBleedFactor;
uniform float uAmbientLayerOn;
uniform float uAmbientLayerWeight;
uniform float uHasGlow;
varying vec2 outTexCoord;
${DEEPEN_GLSL}
void main() {
  vec3 floorLight = uAmbient + (uAmbientLayerOn > 0.5 ? texture2D(uAmbientLayer, outTexCoord).rgb * uAmbientLayerWeight : vec3(0.0));
  vec3 excess = deepen(max(texture2D(uLightMap, outTexCoord).rgb - floorLight, vec3(0.0)));
  float peak = max(excess.r, max(excess.g, excess.b));
  // The room above the floor light limits the bleed, as it did in the old 8-bit map; without it a blast at dusk fogs over everything.
  float room = max(1.0 - max(floorLight.r, max(floorLight.g, floorLight.b)), 0.25);
  float shoulder = room * (1.0 - exp(-2.0 * peak / room)) / max(peak, 0.00001);
  vec3 glow = uHasGlow > 0.5 ? texture2D(uGlow, outTexCoord).rgb : vec3(0.0);
  gl_FragColor = vec4(excess * shoulder * uBleedFactor + deepen(glow) * ${GLOW_STRENGTH.toFixed(3)}, 1.0);
}
`;

/** The light above a threshold at half size. */
export const LIGHT_HDR_BRIGHT_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uLightMap;
uniform sampler2D uAmbientLayer;
uniform vec3 uAmbient;
uniform float uAmbientLayerOn;
uniform float uAmbientLayerWeight;
uniform vec2 uTexel;
uniform float uKnee;
vec3 above(vec2 uv, vec3 threshold) { return max(texture2D(uLightMap, uv).rgb - threshold, vec3(0.0)); }
void main() {
  vec2 uv = gl_FragCoord.xy * uTexel, o = uTexel * 0.25;
  vec3 floorLight = uAmbient + (uAmbientLayerOn > 0.5 ? texture2D(uAmbientLayer, uv).rgb * uAmbientLayerWeight : vec3(0.0));
  vec3 threshold = max(floorLight, vec3(uKnee));
  gl_FragColor = vec4((above(uv + o, threshold) + above(uv - o, threshold) + above(uv + vec2(o.x, -o.y), threshold) + above(uv + vec2(-o.x, o.y), threshold)) * 0.25, 1.0);
}
`;

/** One halving of a chain, or with a reach a disc over its smallest level. */
export const LIGHT_HDR_GLOW_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uSource;
uniform vec2 uTexel;
uniform vec2 uReach;
void main() {
  vec2 uv = gl_FragCoord.xy * uTexel;
  if (uReach.x <= 0.0) {
    vec2 o = uTexel * 0.25;
    gl_FragColor = vec4((texture2D(uSource, uv + o).rgb + texture2D(uSource, uv - o).rgb + texture2D(uSource, uv + vec2(o.x, -o.y)).rgb + texture2D(uSource, uv + vec2(-o.x, o.y)).rgb) * 0.25, 1.0);
    return;
  }
  vec3 sum = texture2D(uSource, uv).rgb;
  float total = 1.0;
  for (int i = 0; i < ${GLOW_DISC_TAPS}; i++) {
    float ring = sqrt((float(i) + 0.5) / ${GLOW_DISC_TAPS.toFixed(1)}), angle = float(i) * 2.39996, weight = 1.0 - ring * 0.6;
    sum += texture2D(uSource, uv + vec2(cos(angle), sin(angle)) * ring * uReach).rgb * weight;
    total += weight;
  }
  gl_FragColor = vec4(sum / total, 1.0);
}
`;

/** Makes a private render target float; a light value above 1 must survive in it. */
export function enableHdrShaderTarget(scene: Phaser.Scene, target: SunRenderTarget): boolean {
  const shader = target.shader;
  return enableHdrTarget(scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer, {
    getWebGLTexture: () => shader.glTexture, drawingContext: shader.drawingContext,
  } as unknown as Phaser.Textures.DynamicTexture);
}

interface ChainStep { readonly target: SunRenderTarget; readonly width: number; readonly height: number }
interface LightChain { readonly bright: ChainStep; readonly steps: ChainStep[]; readonly outputs: SunRenderTarget[] }

export interface LightHdrFrame {
  readonly ambient: ArrayLike<number>;
  readonly ambientLayer: Phaser.Textures.Texture | null;
  readonly ambientLayerWeight: number;
  readonly bleedFactor: number;
  readonly scatter: boolean;
  /** Coloured light is deepened where it is strong instead of adding up to white. */
  readonly vivid: boolean;
}

/** Re-specifies a target as RGBA16F; false means this target cannot provide the required storage. */
export function enableHdrTarget(renderer: Phaser.Renderer.WebGL.WebGLRenderer, texture: Phaser.Textures.DynamicTexture): boolean {
  const gl = renderer.gl as WebGL2RenderingContext;
  if (!enableFloatColorBuffer(gl)) return false;
  const wrapper = texture.getWebGLTexture()!, context = texture.drawingContext;
  renderer.renderNodes.finishBatch();
  renderer.glTextureUnits.bind(wrapper, 0);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, wrapper.width, wrapper.height, 0, gl.RGBA, gl.HALF_FLOAT, null);
  const previous = (renderer.glWrapper.state.bindings as { framebuffer: Phaser.Renderer.WebGL.Wrappers.WebGLFramebufferWrapper | null }).framebuffer;
  try {
    renderer.glWrapper.update({ bindings: { framebuffer: context.framebuffer } });
    if (gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE) return true;
  } finally { renderer.glWrapper.update({ bindings: { framebuffer: previous } }); }
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, wrapper.width, wrapper.height, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
  return false;
}

/** Draws a float light map over the World: multiply with headroom, then scattered light and halo. */
export class LightHdrComposite {
  private readonly composite: Phaser.GameObjects.Shader;
  private readonly scatter: Phaser.GameObjects.Shader;
  private readonly ambient = [0, 0, 0];
  private readonly glowReach: [number, number];
  private frame: LightHdrFrame | null = null;
  private layerTexture: Phaser.Textures.Texture | null = null;
  /** Undefined until the first frame that needs it tried to build it; null when that failed. */
  private glow: LightChain | null | undefined = undefined;
  private soft: LightChain | null | undefined = undefined;
  private softScheduled = false;
  private readonly baseX: number;
  private readonly baseY: number;
  private offsetX = 0;
  private offsetY = 0;
  private readonly runChains = (): void => { this.renderChains(); };

  constructor(private readonly scene: Phaser.Scene, private readonly lightMap: Phaser.GameObjects.RenderTexture) {
    const { x, y, displayWidth: width, displayHeight: height } = lightMap;
    this.baseX = x; this.baseY = y;
    this.glowReach = [GLOW_RADIUS_PX / width, GLOW_RADIUS_PX / height];
    this.composite = this.createQuad(LIGHT_HDR_COMPOSITE_SHADER, LIGHT_HDR_COMPOSITE_FRAGMENT, set => {
      set('uLightMap', 0); set('uAmbientLayer', 1); set('uAmbient', this.ambient); set('uAmbientLayerOn', this.layerTexture ? 1 : 0);
      set('uDeepen', this.frame?.vivid ? DEEPEN : NO_DEEPEN);
    }, [lightMap.texture, lightMap.texture], x, y, width, height);
    this.composite.setDepth(DEPTH_LIGHTING + 0.0005).setBlendMode(Phaser.BlendModes.NORMAL);
    const blend = modulate2xBlendMode(scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer);
    const node = this.composite.renderNode, run = node.run;
    node.run = function (context, object, parent): void { runWithScopedBlend(this, run, context, blend, object, parent); };
    this.scatter = this.createQuad(LIGHT_HDR_SCATTER_SHADER, LIGHT_HDR_SCATTER_FRAGMENT, set => {
      const frame = this.frame;
      set('uLightMap', 0); set('uAmbientLayer', 1); set('uGlow', 2);
      set('uHasGlow', this.glow ? 1 : 0);
      set('uAmbientLayerOn', this.layerTexture ? 1 : 0);
      set('uAmbientLayerWeight', frame?.ambientLayerWeight ?? 0);
      set('uAmbient', this.ambient); set('uBleedFactor', frame?.bleedFactor ?? 0);
      set('uDeepen', frame?.vivid ? DEEPEN : NO_DEEPEN);
    }, [lightMap.texture, lightMap.texture, lightMap.texture], x, y, width, height);
    this.scatter.setDepth(DEPTH_LIGHTING + 0.0015).setBlendMode(Phaser.BlendModes.SCREEN);
  }

  sync(frame: LightHdrFrame): void {
    this.frame = frame;
    this.ambient[0] = frame.ambient[0]; this.ambient[1] = frame.ambient[1]; this.ambient[2] = frame.ambient[2];
    if (frame.ambientLayer !== this.layerTexture) {
      this.layerTexture = frame.ambientLayer;
      this.bindScatterTextures();
    }
    this.composite.setVisible(true);
    this.scatter.setVisible(frame.scatter);
  }

  /** Shifts the quads by `x`, `y` display px from where the light map lay when they were built. */
  setOffset(x: number, y: number): void {
    if (this.offsetX === x && this.offsetY === y) return;
    this.offsetX = x; this.offsetY = y;
    this.composite.setPosition(this.baseX + x, this.baseY + y);
    this.scatter.setPosition(this.baseX + x, this.baseY + y);
  }

  setVisible(visible: boolean): void {
    this.composite.setVisible(visible);
    if (!visible) this.scatter.setVisible(false);
  }

  /** Call after the frame's last draw into the light map: the blurred copies are built from the finished map, before anything reads them. */
  scheduleLightChains(softWanted: boolean): void {
    const glow = this.scatter.visible && this.ensureGlow();
    this.softScheduled = softWanted && this.ensureSoft();
    if (glow || this.softScheduled) (this.lightMap.texture as Phaser.Textures.DynamicTexture).callback(this.runChains);
  }

  /** All light above the night, blurred; null while it is not prepared this frame. */
  get softLight(): { readonly wide: Phaser.Textures.Texture; readonly far: Phaser.Textures.Texture } | null {
    if (!this.softScheduled || !this.soft) return null;
    return { wide: this.soft.outputs[0].shader.texture!, far: this.soft.outputs[1].shader.texture! };
  }

  destroy(): void {
    this.composite.destroy();
    this.scatter.destroy();
    for (const chain of [this.glow, this.soft]) this.destroyChain(chain);
    this.glow = undefined; this.soft = undefined;
  }

  private destroyChain(chain: LightChain | null | undefined): void {
    if (!chain) return;
    chain.bright.target.destroy();
    for (const step of chain.steps) step.target.destroy();
  }

  private bindScatterTextures(): void {
    const map = this.lightMap.texture, layer = this.layerTexture ?? map;
    this.composite.setTextures([map, layer]);
    this.scatter.setTextures([map, layer, this.glow ? this.glow.outputs[0].shader.texture! : map]);
    for (const chain of [this.glow, this.soft]) chain?.bright.target.shader.setTextures([map, layer]);
  }

  private ensureGlow(): boolean {
    if (this.glow === undefined) { this.glow = this.buildChain(GLOW_THRESHOLD, [this.glowReach]); this.bindScatterTextures(); }
    return this.glow !== null;
  }

  private ensureSoft(): boolean {
    if (this.soft === undefined) {
      const { displayWidth: width, displayHeight: height } = this.lightMap;
      this.soft = this.buildChain(0, [[FOG_WIDE_LIGHT_PX / width, FOG_WIDE_LIGHT_PX / height], [FOG_FAR_LIGHT_PX / width, FOG_FAR_LIGHT_PX / height]]);
    }
    return this.soft !== null;
  }

  /** The light above `knee` at half size, halved further, then one disc for each reach at the smallest size. */
  private buildChain(knee: number, reaches: readonly (readonly number[])[]): LightChain | null {
    const map = this.lightMap.texture;
    let width = Math.max(2, Math.ceil(this.lightMap.width / 2)), height = Math.max(2, Math.ceil(this.lightMap.height / 2));
    const brightTexel = [1 / width, 1 / height];
    const target = new SunRenderTarget(this.scene, 'LightHdrBright', LIGHT_HDR_BRIGHT_FRAGMENT, set => {
      const frame = this.frame;
      set('uLightMap', 0); set('uAmbientLayer', 1); set('uTexel', brightTexel); set('uAmbient', this.ambient); set('uKnee', knee);
      set('uAmbientLayerOn', this.layerTexture ? 1 : 0); set('uAmbientLayerWeight', frame?.ambientLayerWeight ?? 0);
    }, [map, this.layerTexture ?? map], LIGHT_HDR_BRIGHT_SHADER);
    target.draw(width, height);
    const chain: LightChain = { bright: { target, width, height }, steps: [], outputs: [] };
    let ready = enableHdrShaderTarget(this.scene, target), source = target.shader.texture!;
    const addStep = (reach: readonly number[]): SunRenderTarget => {
      const texel = [1 / width, 1 / height], step = new SunRenderTarget(this.scene, 'LightHdrGlow', LIGHT_HDR_GLOW_FRAGMENT, set => { set('uSource', 0); set('uTexel', texel); set('uReach', reach); }, [source], LIGHT_HDR_GLOW_SHADER);
      step.draw(width, height);
      ready &&= enableHdrShaderTarget(this.scene, step);
      chain.steps.push({ target: step, width, height });
      return step;
    };
    for (let i = 0; ready && i < CHAIN_HALVINGS; i++) {
      width = Math.max(2, Math.ceil(width / 2)); height = Math.max(2, Math.ceil(height / 2));
      source = addStep([0, 0]).shader.texture!;
    }
    for (const reach of reaches) if (ready) chain.outputs.push(addStep(reach));
    if (ready) return chain;
    this.destroyChain(chain);
    return null;
  }

  private renderChains(): void {
    for (const [chain, wanted] of [[this.glow, this.scatter.visible], [this.soft, this.softScheduled]] as const) {
      if (!chain || !wanted) continue;
      chain.bright.target.draw(chain.bright.width, chain.bright.height);
      for (const step of chain.steps) step.target.draw(step.width, step.height);
    }
  }

  private createQuad(name: string, fragmentSource: string, setupUniforms: (set: (name: string, value: unknown) => void) => void,
    textures: Phaser.Textures.Texture[], x: number, y: number, width: number, height: number): Phaser.GameObjects.Shader {
    const quad = new Phaser.GameObjects.Shader(this.scene, { name, shaderName: name, fragmentSource, setupUniforms }, x, y, width, height, textures);
    ownSunShader(quad, name, true);
    quad.setTextureCoordinatesFromFrame(this.lightMap.frame);
    quad.setOrigin(0).setScrollFactor(0);
    this.scene.add.existing(quad);
    getClarityCameraRegistry(this.scene)?.demote(quad);
    return quad;
  }
}
