import { loadingTimeline } from '../diagnostics/LoadingTimeline';
import {TERRAIN_MATERIAL_WORKERS,TerrainSnapshotWorkerClient} from './TerrainSnapshotWorkerClient';
import * as Phaser from 'phaser';
import type { DirtCell, WaterCell } from '../types';
import { DirtSurfaceField } from './DirtSurfaceField';
import type { GroundMaterialSamples } from './GroundMaterialSamples';
import type { ChunkWorldFrame } from './chunks/ArenaChunkGrid';
import type { ChunkBakeRegion } from './chunks/ChunkedRenderSurface';
import type { ArenaTrackColumnSpec } from './ArenaVisualFactory';
import type { TerrainSnapshotMaterialSource } from './TerrainSnapshotMaterial';
import { soilTileKey, type WorldPrebake } from './prebake/WorldPrebake';

let nextId = 0;
/** Tiles one soil worker holds: the next bakes' tiles are computed while the current one uploads. */
const SOIL_TILES_IN_FLIGHT = 4;

/** A soil worker and the keys of its tiles in flight, in request order. */
interface SoilLane { readonly client: TerrainSnapshotWorkerClient; readonly requested: string[] }

/** One reusable soil and riverbank canvas per World, not one texture/object per soil tile. */
export class DirtSurfaceLayer {
  readonly snapshotSource: TerrainSnapshotMaterialSource;
  private readonly field: DirtSurfaceField;
  private readonly surface: Phaser.Textures.CanvasTexture;
  private readonly image: Phaser.GameObjects.Image;
  private readonly pixels: ImageData;
  /** Soil workers, started on demand: the ground chunks of a World start waited on one worker. */
  private readonly lanes:SoilLane[]=[];
  private readonly prepared=new Map<string,Uint8ClampedArray>();

  constructor(private readonly scene: Phaser.Scene, seed: number, dirt: readonly DirtCell[],
    frame: ChunkWorldFrame, size: number, private readonly materials: GroundMaterialSamples,
    water: readonly WaterCell[] = [], tracks: readonly ArenaTrackColumnSpec[] = [],
    private readonly maxWorkers = TERRAIN_MATERIAL_WORKERS,
    /** Tiles the lobby prepared for this World's soil (dirt layer only, never base gravel). */
    private readonly prebake: WorldPrebake | null = null) {
    this.snapshotSource = DirtSurfaceLayer.source(seed, dirt, frame, materials, water, tracks);
    this.field = new DirtSurfaceField(seed, dirt, frame, water, tracks);
    const key = `__dirt_surface_${nextId++}`;
    const surface = scene.textures.createCanvas(key, size, size);
    if (!surface) throw new Error('[DirtSurfaceLayer] Could not allocate soil surface.');
    this.surface = surface;
    this.pixels = surface.context.createImageData(size, size);
    this.image = new Phaser.GameObjects.Image(scene, 0, 0, key).setOrigin(0);
  }

  /** The worker source of a soil field; the lobby prebake builds the same one from the layout. */
  static source(seed: number, dirt: readonly DirtCell[], frame: ChunkWorldFrame, materials: GroundMaterialSamples,
    water: readonly WaterCell[] = [], tracks: readonly ArenaTrackColumnSpec[] = []): TerrainSnapshotMaterialSource {
    return { kind: 'soil', seed, dirt, water, tracks, frame, materials: {
      dirt: materials.dirt, dirtAlt: materials.dirtAlt, bank: materials.bank, bankWet: materials.bankWet,
      grassHeight: materials.grassHeight,
    } };
  }

  /** A few transferred tiles in flight per worker (no worker idles between bakes), bounded native
   * cache, no readback. A new tile goes to the least busy worker; a second one starts only while
   * every running worker already computes. */
  prepare(worldX:number,worldY:number,size:number):boolean {
    if(typeof Worker==='undefined')return true;
    for(const lane of this.lanes)for(let result=lane.client.take();result;result=lane.client.take()){
      if(this.prepared.size>=64)this.prepared.delete(this.prepared.keys().next().value!);
      this.prepared.set(lane.requested.shift()!,new Uint8ClampedArray(result));
    }
    const key=soilTileKey(worldX,worldY,size);
    if(this.prepared.has(key))return true;
    const taken=loadingTimeline.start(),prebaked=this.prebake?.takeSoilTile(key);
    if(prebaked){loadingTimeline.end('prebake/soil-tile',taken);
      if(this.prepared.size>=64)this.prepared.delete(this.prepared.keys().next().value!);
      this.prepared.set(key,prebaked);return true;
    }
    if(this.lanes.some(lane=>lane.requested.includes(key)))return false;
    let lane=this.lanes.reduce<SoilLane|null>((best,next)=>!best||next.requested.length<best.requested.length?next:best,null);
    if((!lane||lane.requested.length>0)&&this.lanes.length<this.maxWorkers){
      lane={client:new TerrainSnapshotWorkerClient(undefined,SOIL_TILES_IN_FLIGHT),requested:[]};this.lanes.push(lane);
    }
    if(lane?.client.canRequest()){lane.requested.push(key);
      lane.client.request(this.snapshotSource,size,worldX,worldY,size,size,new ArrayBuffer(size*size*4),true);
    }
    return false;
  }

  bake(target: Phaser.GameObjects.RenderTexture, region: ChunkBakeRegion): void {
    this.writeRegion(region);
    this.surface.context.putImageData(this.pixels, 0, 0);
    this.surface.refresh();
    target.clear();
    target.draw(this.image);
    // Flush while this canvas still belongs to this region.
    target.render();
  }

  /** Borrowed native pixels, consumed before the next bake. Snapshot staging uses
   * the identical field without uploading/drawing one GPU scratch per small tile. */
  writeRegion(region: ChunkBakeRegion): ImageData {
    const cached=this.prepared.get(soilTileKey(region.worldX,region.worldY,region.size));
    if(cached){this.pixels.data.set(cached);return this.pixels;}
    this.field.writeSurface(this.pixels.data, this.pixels.width, region.worldX, region.worldY, region.size, this.materials);
    return this.pixels;
  }

  destroy(): void {
    for(const lane of this.lanes)lane.client.destroy();
    this.lanes.length=0;this.prepared.clear();
    this.image.destroy();
    this.scene.textures.remove(this.surface.key);
  }
}
