import type * as Phaser from 'phaser';
import { FogGpuTimer } from '../effects/groundFog/FogGpuTimer';

export interface LightingGpuTimingSample {
  readonly supported: boolean;
  readonly updateMs: number | null;
  readonly updateSample: number;
  readonly compositeMs: number | null;
  readonly compositeSample: number;
}

const TIME_ELAPSED_EXT = 0x88bf;

/**
 * Diagnostics: GPU time of the lighting work. `update` covers the passes drawn at once, `composite`
 * the display-list range between two invisible fences around the light map. Timer queries cannot
 * nest, so a frame the profiler is timing as a whole is simply skipped here.
 */
export class LightingGpuTiming {
  private readonly gl: WebGLRenderingContext | WebGL2RenderingContext;
  private readonly update: FogGpuTimer;
  private readonly composite: FogGpuTimer;
  private readonly fences: readonly Phaser.GameObjects.Extern[];

  constructor(scene: Phaser.Scene, beginDepth: number, endDepth: number) {
    this.gl = (scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer).gl;
    const camera = scene.cameras.main;
    this.update = new FogGpuTimer(this.gl);
    this.composite = new FogGpuTimer(this.gl);
    const fence = (depth: number, mark: () => void) => {
      const extern = scene.add.extern().setDepth(depth);
      // The transparent clarity camera walks the same list; only the World camera draws the map.
      extern.render = (_renderer: unknown, context: Phaser.Renderer.WebGL.DrawingContext) => { if (context.camera === camera) mark(); };
      return extern;
    };
    this.fences = [fence(beginDepth, () => this.begin(this.composite)), fence(endDepth, () => this.composite.end())];
  }

  beginUpdate(): void { this.begin(this.update); }
  endUpdate(): void { this.update.end(); }

  read(): LightingGpuTimingSample {
    this.update.poll();
    this.composite.poll();
    return { supported: this.update.supported, updateMs: this.update.ms, updateSample: this.update.sample,
      compositeMs: this.composite.ms, compositeSample: this.composite.sample };
  }

  destroy(): void {
    for (const fence of this.fences) fence.destroy();
    this.update.destroy();
    this.composite.destroy();
  }

  private begin(timer: FogGpuTimer): void {
    const gl = this.gl;
    if ('getQuery' in gl && gl.getQuery(TIME_ELAPSED_EXT, gl.CURRENT_QUERY)) return;
    timer.begin();
  }
}
