import {
  ACHIEVEMENT_COUNTER,
  classWonCounter,
  dawnModifierWonCounter,
  pvpWonCounter,
} from './AchievementCounters';
import {
  roundSnapshotToDelta,
  type AchievementCounterDelta,
  type AchievementLedger,
  type RoundAchievementSnapshot,
} from './AchievementLedger';
import type { AchievementRegistry } from './AchievementRegistry';

export type AchievementRoundMode = 'coop_defense' | 'deathmatch' | 'team_deathmatch' | 'capture_the_beer';
export type AchievementRoundOutcome = 'victory' | 'defeat' | 'draw' | 'aborted';

/** Everything the local player's client knows about one finished round, credited exactly once. */
export interface AchievementRoundCredit {
  readonly mode: AchievementRoundMode;
  readonly outcome: AchievementRoundOutcome;
  /** Campaign map with a boss objective (never set for Dawn). */
  readonly bossMap: boolean;
  readonly dawn: { readonly threat: number; readonly nightModifierId: string | null } | null;
  /** Played class, only once classes are unlocked. */
  readonly classId: string | null;
  readonly playerCount: number;
  /** The local player's host-recorded row; null for hosts/rounds that sent none. */
  readonly round: RoundAchievementSnapshot | null;
}

export interface AchievementSyncState {
  /** Steam API names of all unlocked achievements (full state, idempotent). */
  readonly unlocked: readonly string[];
  /** Steam stat API name → value. */
  readonly stats: Readonly<Record<string, number>>;
}

export function deriveRoundCreditDelta(credit: AchievementRoundCredit): AchievementCounterDelta {
  const fromRound = credit.round ? roundSnapshotToDelta(credit.round) : { add: {}, max: {} };
  const add: Record<string, number> = { ...fromRound.add };
  const max: Record<string, number> = { ...fromRound.max };
  if (credit.outcome === 'victory') {
    if (credit.mode === 'coop_defense') {
      if (credit.classId) add[classWonCounter(credit.classId)] = 1;
      max[ACHIEVEMENT_COUNTER.maxCoopVictoryPlayers] = Math.max(0, Math.floor(credit.playerCount));
      if (credit.bossMap && credit.round && credit.round.deaths === 0) add[ACHIEVEMENT_COUNTER.bossFlawless] = 1;
      if (credit.dawn) {
        max[ACHIEVEMENT_COUNTER.dawnMaxThreatWon] = Math.max(0, Math.floor(credit.dawn.threat));
        if (credit.dawn.nightModifierId) add[dawnModifierWonCounter(credit.dawn.nightModifierId)] = 1;
      }
    } else {
      add[pvpWonCounter(credit.mode)] = 1;
    }
  }
  return { add, max };
}

export function resolveAchievementValues(
  ledger: AchievementLedger,
  stateValues: Readonly<Record<string, number>>,
): Record<string, number> {
  return { ...ledger.counters, ...stateValues };
}

/** Achievements whose requirements currently hold (latched ones stay in the ledger separately). */
export function evaluateAchievements(
  registry: AchievementRegistry,
  values: Readonly<Record<string, number>>,
): string[] {
  return registry.achievements
    .filter(achievement => achievement.requires.every(requirement => (values[requirement.value] ?? 0) >= requirement.min))
    .map(achievement => achievement.apiName);
}

export function buildAchievementSyncState(
  registry: AchievementRegistry,
  ledger: AchievementLedger,
  values: Readonly<Record<string, number>>,
): AchievementSyncState {
  const known = new Set(registry.achievements.map(achievement => achievement.apiName));
  const stats: Record<string, number> = {};
  for (const stat of registry.stats) stats[stat.apiName] = Math.max(0, Math.floor(values[stat.value] ?? 0));
  // Ledger entries outside the current registry (renamed or archived) are not sent to Steam.
  return { unlocked: ledger.unlocked.filter(name => known.has(name)), stats };
}
