import type * as Phaser from 'phaser';
import type { PipelineAsset } from '../../config/pipelineAssets';
import { muzzleFlameStreamKey } from '../../systems/muzzleFlameStream';
import { DISTORTION_PRIORITY } from '../distortion/distortionFramePlanner';
import type { LocalDistortionComposer } from '../distortion/LocalDistortionComposer';
import { GpuVfxFrameId } from '../gpu/GpuVfxAtlas';
import { GpuVfxEase } from '../gpu/GpuVfxEase';
import { GpuVfxEffectId } from '../gpu/GpuVfxEffects';
import type { GpuVfxSpawnSpec } from '../gpu/GpuVfxSpawnSpec';
import type { GpuVfxSystem } from '../gpu/GpuVfxSystem';
import type { FlameStreamHead } from '../FlameRenderer';
import type { LightingSystem } from '../LightingSystem';
import type { InfernoColossusZoneLevels } from './InfernoColossusGlowPresentation';

/** Tuning of the colossus's heat around its body (world px, per second). */
export const COLOSSUS_HEAT_FX = {
  /** Violet haze rising off the burning mandibles: puffs per second at full heat. */
  hazeRate: 26,
  hazeLifeMs: [520, 900] as const,
  hazeSize: [16, 30] as const,
  hazeGrowth: 2.4,
  hazeAlpha: 0.08,
  hazeTint: 0x8f45ff,
  /**
   * Glowing haze at the jet mouths (the mandible tips) that the flames shoot out of: puffs per second
   * and tip at full heat, starting up to `mouthReachPx` ahead of the tip and drifting slowly after the
   * flames. It builds up through the ignition.
   */
  mouthRate: 64,
  mouthLifeMs: [320, 640] as const,
  mouthSize: [30, 58] as const,
  mouthGrowth: 1.8,
  mouthAlpha: 0.36,
  /** Glowing haze, and the hotter core right at the tip. */
  mouthTint: 0xa35cff,
  mouthCoreTint: 0xd6a6ff,
  mouthReachPx: 62,
  /** Heat shimmer over the mandibles: stamp radius and strength at full heat. */
  shimmerRadiusPx: 86,
  shimmerStrength: 0.75,
  /** Light map: the mandibles' halo from rest to white heat, the lantern's pulse. */
  mandibleLight: [0.18, 1.15] as const,
  mandibleColor: [0x7f2cff, 0xa968ff] as const,
  lanternLight: [0.35, 0.95] as const,
} as const;

/** Where the mandible blades start, as shares of the frame (the rest sockets hold their tips). */
const MANDIBLE_BASE = { u: 0.055, v: 0.2 };
/** A jet's newest flame counts for a tip within this distance of it (world px). */
const JET_HEAD_REACH_PX = 160;

/** The newest flame of a flame stream, by its chain key (the flame renderer). */
export interface FlameStreamSource { streamHead(chainKey: string): FlameStreamHead | null }

/** Haze off a blade (from its base `a` to its tip `b`) or, as `mouth`, at the jet mouth `b`. */
interface HazeEmitter { ax: number; ay: number; bx: number; by: number; heat: number; dx: number; dy: number; mouth: boolean }

/** Lub-dub of the lantern's heart (same curve as the emission shader). */
export function colossusHeartbeat(beats: number): number {
  const c = beats - Math.floor(beats);
  return Math.exp(-(((c - 0.06) / 0.045) ** 2)) + 0.55 * Math.exp(-(((c - 0.24) / 0.055) ** 2));
}

/**
 * The colossus's heat around its body, from the same levels as its light: a halo on the light map
 * that swells from the mandibles' smoulder to white heat, the lantern's heartbeat on the ground around
 * the open abdomen, violet haze rising off the burning mandible edges (soft haze, never sparks), a
 * glowing haze at both jet mouths that the flames shoot out of, and a heat shimmer over the mandibles in
 * the local distortion map. Presentation only; every source is resubmitted
 * per frame and released when its body is gone.
 */
export class InfernoColossusHeatEffects {
  private lighting: LightingSystem | null = null;
  private distortion: LocalDistortionComposer | null = null;
  private gpu: GpuVfxSystem | null = null;
  private streams: FlameStreamSource | null = null;
  private hazeSpec: GpuVfxSpawnSpec | null = null;
  private hazeSource = -1;
  private unregister: (() => void) | null = null;
  private readonly lit = new Map<string, readonly string[]>();
  private readonly seen = new Set<string>();
  private readonly emitters: HazeEmitter[] = [];
  private readonly point = { x: 0, y: 0 };
  private hazeBudget = 0;
  private mouthBudget = 0;

  setLightingSystem(lighting: LightingSystem | null): void {
    if (lighting === this.lighting) return;
    this.releaseLights();
    this.lighting = lighting;
  }

  setDistortionComposer(composer: LocalDistortionComposer | null): void { this.distortion = composer; }

  /** The haze follows each jet's newest flame; without it, it drifts along the body's facing. */
  setFlameStreams(streams: FlameStreamSource | null): void { this.streams = streams; }

  setGpuVfx(gpu: GpuVfxSystem | null): void {
    if (gpu === this.gpu) return;
    this.detachGpu();
    this.gpu = gpu;
    if (!gpu) return;
    // The haze shares the Demon Badger's emissive violet haze: same lane, same soft smoke frame.
    this.hazeSpec = gpu.createSpec(GpuVfxEffectId.DemonHeatHaze);
    this.hazeSource = gpu.createSource(GpuVfxEffectId.DemonHeatHaze);
    this.unregister = gpu.registerEmission(deltaMs => this.emit(deltaMs));
  }

  beginFrame(): void {
    this.seen.clear();
    this.emitters.length = 0;
  }

  body(id: string, sprite: Phaser.GameObjects.Sprite, asset: PipelineAsset, levels: InfernoColossusZoneLevels, beat: number,
    phaseTwo: boolean, allied: boolean, now: number): void {
    this.seen.add(id);
    const fx = COLOSSUS_HEAT_FX, sockets = asset.restSockets;
    const left = sockets?.mandible_l_tip, right = sockets?.mandible_r_tip;
    if (!left || !right) return;
    const heat = levels.heat;
    const tipL = this.at(sprite, left[0], left[1], { x: 0, y: 0 }), tipR = this.at(sprite, right[0], right[1], { x: 0, y: 0 });
    const baseL = this.at(sprite, 0.5 - MANDIBLE_BASE.u, MANDIBLE_BASE.v, { x: 0, y: 0 });
    const baseR = this.at(sprite, 0.5 + MANDIBLE_BASE.u, MANDIBLE_BASE.v, { x: 0, y: 0 });
    const head = this.at(sprite, 0.5, 0.17, { x: 0, y: 0 });
    const mx = (tipL.x + tipR.x + head.x * 2) / 4, my = (tipL.y + tipR.y + head.y * 2) / 4;
    const keys: string[] = [];
    if (this.lighting && !allied) {
      const mandibleKey = `colossus:${id}:mandibles`;
      const intensity = fx.mandibleLight[0] + (fx.mandibleLight[1] - fx.mandibleLight[0]) * Math.max(heat, levels.mandibles * 0.25);
      this.lighting.setLight(mandibleKey, 'colossusMandibleGlow', mx, my,
        { intensity: intensity * sprite.alpha, color: heat > 0.5 ? fx.mandibleColor[1] : fx.mandibleColor[0] });
      keys.push(mandibleKey);
      const core = sockets?.core;
      if (phaseTwo && core) {
        const lanternKey = `colossus:${id}:lantern`;
        const p = this.at(sprite, core[0], core[1], this.point);
        const pulse = Math.min(1, colossusHeartbeat(beat) * levels.beatGain);
        this.lighting.setLight(lanternKey, 'colossusLanternGlow', p.x, p.y,
          { intensity: (fx.lanternLight[0] + (fx.lanternLight[1] - fx.lanternLight[0]) * pulse) * levels.core * sprite.alpha });
        keys.push(lanternKey);
      }
    }
    for (const key of this.lit.get(id) ?? []) if (!keys.includes(key)) this.lighting?.releaseLight(key);
    this.lit.set(id, keys);
    if (heat <= 0.05) return;
    // The haze flies where the jets fly: along each tip's newest flame (the jets converge on the target
    // and lead the turning body), before the first flame along the facing. The mouths glow where the
    // jets leave the tips.
    const fwdX = Math.sin(sprite.rotation), fwdY = -Math.cos(sprite.rotation);
    const jetL = this.jetDirection(id, tipL, fwdX, fwdY), jetR = this.jetDirection(id, tipR, fwdX, fwdY);
    this.emitters.push({ ax: baseL.x, ay: baseL.y, bx: tipL.x, by: tipL.y, heat, dx: jetL.x, dy: jetL.y, mouth: false });
    this.emitters.push({ ax: baseR.x, ay: baseR.y, bx: tipR.x, by: tipR.y, heat, dx: jetR.x, dy: jetR.y, mouth: false });
    this.emitters.push({ ax: tipL.x, ay: tipL.y, bx: tipL.x, by: tipL.y, heat, dx: jetL.x, dy: jetL.y, mouth: true });
    this.emitters.push({ ax: tipR.x, ay: tipR.y, bx: tipR.x, by: tipR.y, heat, dx: jetR.x, dy: jetR.y, mouth: true });
    if (this.distortion) {
      // Two stamps turning against each other make the swirl shimmer instead of standing still.
      const strength = fx.shimmerStrength * heat * sprite.alpha, t = now * 0.001;
      for (let k = 0; k < 2; k++) {
        this.distortion.submit({ id: `colossus-heat:${id}:${k}`, profile: 'heat', worldX: mx + fwdX * 12 * k, worldY: my + fwdY * 12 * k,
          radiusPx: fx.shimmerRadiusPx * (k ? 0.8 : 1), strength: strength * (k ? 0.7 : 1), rotation: (k ? -1.3 : 0.9) * t + k,
          priority: DISTORTION_PRIORITY.heat });
      }
    }
  }

  endFrame(): void {
    for (const [id, keys] of this.lit) {
      if (this.seen.has(id)) continue;
      for (const key of keys) this.lighting?.releaseLight(key);
      this.lit.delete(id);
    }
  }

  clear(): void {
    this.releaseLights();
    this.emitters.length = 0;
    if (this.gpu && this.hazeSource >= 0) this.gpu.clearSource(this.hazeSource);
  }

  destroy(): void {
    this.clear();
    this.detachGpu();
  }

  private emit(deltaMs: number): void {
    const gpu = this.gpu, spec = this.hazeSpec, fx = COLOSSUS_HEAT_FX;
    if (!gpu || !spec || gpu.isSuppressed() || !(deltaMs > 0) || !this.emitters.length) return;
    const now = gpu.now(), dt = Math.min(deltaMs, 50) / 1000;
    for (const e of this.emitters) {
      if (e.mouth) {
        this.mouthBudget += fx.mouthRate * e.heat * dt;
        const count = Math.floor(this.mouthBudget);
        this.mouthBudget -= count;
        const scaled = gpu.quality.scaleDiscreteBurst(GpuVfxEffectId.DemonHeatHaze, count);
        for (let i = 0; i < scaled; i++) this.spawnMouth(gpu, spec, e, now);
        continue;
      }
      this.hazeBudget += fx.hazeRate * e.heat * dt;
      let count = Math.floor(this.hazeBudget);
      this.hazeBudget -= count;
      count = gpu.quality.scaleDiscreteBurst(GpuVfxEffectId.DemonHeatHaze, count);
      for (let i = 0; i < count; i++) {
        const t = 0.15 + Math.random() * 0.85;
        const x = e.ax + (e.bx - e.ax) * t, y = e.ay + (e.by - e.ay) * t;
        const lifeMs = fx.hazeLifeMs[0] + Math.random() * (fx.hazeLifeMs[1] - fx.hazeLifeMs[0]);
        const drift = 18 + Math.random() * 26, side = (Math.random() - 0.5) * 0.9;
        const vx = (e.dx * Math.cos(side) - e.dy * Math.sin(side)) * drift, vy = (e.dx * Math.sin(side) + e.dy * Math.cos(side)) * drift;
        const size = fx.hazeSize[0] + Math.random() * (fx.hazeSize[1] - fx.hazeSize[0]);
        spec.frame = GpuVfxFrameId.ExplosionSmoke;
        spec.lifeMs = lifeMs;
        spec.x = x; spec.y = y;
        spec.vx = vx * 1000 / lifeMs; spec.vy = vy * 1000 / lifeMs;
        spec.positionEase = GpuVfxEase.QuadOut;
        spec.rotation = Math.random() * Math.PI * 2; spec.angularVelocity = (Math.random() - 0.5) * 0.8; spec.rotationEase = GpuVfxEase.QuadOut;
        // The smoke frame is 56 px.
        spec.scaleStart = size / 56; spec.scaleEnd = spec.scaleStart * fx.hazeGrowth; spec.scaleEase = GpuVfxEase.QuadOut;
        spec.stretchStart = 1.3; spec.stretchEnd = 1;
        spec.alphaStart = fx.hazeAlpha * (0.6 + 0.4 * e.heat); spec.alphaEnd = 0; spec.alphaEase = GpuVfxEase.CubicIn;
        spec.tint = fx.hazeTint;
        gpu.spawn(spec, this.hazeSource, now);
      }
    }
  }

  /** Flight direction of the jet leaving a tip: its newest flame nearest to the tip, else the facing. */
  private jetDirection(id: string, tip: { x: number; y: number }, fwdX: number, fwdY: number): { x: number; y: number } {
    let best: FlameStreamHead | null = null, bestDistance = JET_HEAD_REACH_PX;
    for (let muzzle = 0; muzzle < 2; muzzle++) {
      const head = this.streams?.streamHead(muzzleFlameStreamKey(id, muzzle));
      const distance = head ? Math.hypot(head.x - tip.x, head.y - tip.y) : Infinity;
      if (head && distance < bestDistance) { best = head; bestDistance = distance; }
    }
    return best ? { x: best.dirX, y: best.dirY } : { x: fwdX, y: fwdY };
  }

  /**
   * One puff of a jet mouth: dense and small at the tip, larger further out along the jet, drifting
   * slowly after the flames so they shoot out of it.
   */
  private spawnMouth(gpu: GpuVfxSystem, spec: GpuVfxSpawnSpec, e: HazeEmitter, now: number): void {
    const fx = COLOSSUS_HEAT_FX;
    const along = Math.random() ** 1.6, ahead = along * fx.mouthReachPx, side = (Math.random() - 0.5) * (10 + 18 * along);
    const lifeMs = fx.mouthLifeMs[0] + Math.random() * (fx.mouthLifeMs[1] - fx.mouthLifeMs[0]);
    const drift = 36 + Math.random() * 48;
    const size = (fx.mouthSize[0] + Math.random() * (fx.mouthSize[1] - fx.mouthSize[0])) * (0.75 + 0.5 * along);
    spec.frame = GpuVfxFrameId.ExplosionSmoke;
    spec.lifeMs = lifeMs;
    spec.x = e.bx + e.dx * ahead - e.dy * side;
    spec.y = e.by + e.dy * ahead + e.dx * side;
    spec.vx = e.dx * drift * 1000 / lifeMs; spec.vy = e.dy * drift * 1000 / lifeMs;
    spec.positionEase = GpuVfxEase.QuadOut;
    spec.rotation = Math.random() * Math.PI * 2; spec.angularVelocity = (Math.random() - 0.5) * 1.2; spec.rotationEase = GpuVfxEase.QuadOut;
    spec.scaleStart = size / 56; spec.scaleEnd = spec.scaleStart * fx.mouthGrowth; spec.scaleEase = GpuVfxEase.QuadOut;
    spec.stretchStart = 1.2; spec.stretchEnd = 1;
    spec.alphaStart = fx.mouthAlpha * (0.45 + 0.55 * e.heat) * (1 - 0.35 * along); spec.alphaEnd = 0; spec.alphaEase = GpuVfxEase.CubicInOut;
    spec.tint = along < 0.22 ? fx.mouthCoreTint : fx.mouthTint;
    gpu.spawn(spec, this.hazeSource, now);
  }

  /** World point of a frame share (u, v) of the sprite (u right, v down; the frame faces north). */
  private at(sprite: Phaser.GameObjects.Sprite, u: number, v: number, out: { x: number; y: number }): { x: number; y: number } {
    const lx = ((sprite.flipX ? 1 - u : u) - sprite.originX) * Math.abs(sprite.displayWidth);
    const ly = ((sprite.flipY ? 1 - v : v) - sprite.originY) * Math.abs(sprite.displayHeight);
    const cos = Math.cos(sprite.rotation), sin = Math.sin(sprite.rotation);
    out.x = sprite.x + lx * cos - ly * sin;
    out.y = sprite.y + lx * sin + ly * cos;
    return out;
  }

  private releaseLights(): void {
    for (const keys of this.lit.values()) for (const key of keys) this.lighting?.releaseLight(key);
    this.lit.clear();
  }

  private detachGpu(): void {
    this.unregister?.();
    this.unregister = null;
    if (this.gpu && this.hazeSource >= 0) this.gpu.releaseSource(this.hazeSource);
    this.hazeSource = -1;
    this.hazeSpec = null;
  }
}
