/**
 * Idle formation workers per Scene: the main one and, on machines with spare cores, helpers for the
 * first fill of a World's start view. Their module start-up (seconds while the boot is busy) then
 * overlaps asset loading, and the next World initialises the same workers again instead of starting
 * others. Scenes without lifecycle events (headless tools, tests) never pool, so they get no helpers.
 */
interface WorkerPoolOwner { readonly events?: { once?(event: string, callback: () => void): unknown } }

/**
 * Helpers build the first chunks of a World in parallel with the main worker (Steam plan L4): every World,
 * Lobby and maps alike, waited last for its rock formation, one chunk after another on a single worker.
 * Counted in physical cores (half the logical ones): two stay with the main thread, the GPU process and
 * the terrain workers: 3 cores get one helper, 4 cores two, 5 and more three.
 */
export const ROCK_FORMATION_HELPERS = Math.max(0, Math.min(3,
  Math.floor((typeof navigator === 'undefined' ? 4 : navigator.hardwareConcurrency || 4) / 2) - 2));

const idle = new WeakMap<object, Worker[]>();
const guarded = new WeakSet<object>();

function spawn(): Worker {
  return new Worker(new URL('./RockFormationWorker.ts', import.meta.url), { type: 'module' });
}

function pooled(owner: WorkerPoolOwner): boolean {
  return typeof owner.events?.once === 'function';
}

function capacity(): number { return 1 + ROCK_FORMATION_HELPERS; }

/** The Scene's idle workers end with the Scene; a restarted Scene pools again. */
function guardTeardown(owner: WorkerPoolOwner): void {
  if (guarded.has(owner)) return;
  guarded.add(owner);
  const end = (): void => {
    guarded.delete(owner);
    for (const worker of idle.get(owner) ?? []) worker.terminate();
    idle.delete(owner);
  };
  owner.events!.once!('shutdown', end);
  owner.events!.once!('destroy', end);
}

export function prewarmRockFormationWorker(owner: WorkerPoolOwner): void {
  if (!pooled(owner) || typeof Worker === 'undefined') return;
  const workers = idle.get(owner) ?? [];
  while (workers.length < capacity()) workers.push(spawn());
  idle.set(owner, workers);
  guardTeardown(owner);
}

/** `reused`: the worker may still deliver results for its previous World before `initialized`. */
export function acquireRockFormationWorker(owner: WorkerPoolOwner): { worker: Worker; reused: boolean } {
  const worker = idle.get(owner)?.shift();
  if (!worker) return { worker: spawn(), reused: false };
  return { worker, reused: true };
}

/** Only already idle (prewarmed) workers: a helper started now would come too late for the first fill. */
export function acquireRockFormationHelpers(owner: WorkerPoolOwner, count: number): Worker[] {
  const workers = idle.get(owner);
  return workers && count > 0 ? workers.splice(0, count) : [];
}

/** A failed worker is never handed to the next World. */
export function releaseRockFormationWorker(owner: WorkerPoolOwner, worker: Worker, reusable: boolean): void {
  worker.onmessage = null;
  worker.onerror = null;
  const workers = idle.get(owner) ?? [];
  if (!reusable || !pooled(owner) || workers.length >= capacity()) { worker.terminate(); return; }
  workers.push(worker);
  idle.set(owner, workers);
  guardTeardown(owner);
}
