/**
 * Spielsuche (Steam): öffentliche Räume mit Host, Modus, Spielerzahl und geschätztem Ping.
 *
 * Nur eine Liste, kein automatischer Beitritt. Ein Beitritt verlässt den eigenen Raum; wer als Host
 * Mitspieler hat, bestätigt das mit einem zweiten Klick – seine Gruppe geht dann per Host-Übergabe
 * an einen der Mitspieler.
 */
import * as Phaser from 'phaser';
import { COLORS, DEPTH, GAME_HEIGHT, GAME_WIDTH } from '../config';
import { t } from '../i18n';
import type { PlatformPublicRoom, PlatformRoomBrowser } from '../platform';
import { promoteToClarityCamera } from '../scenes/arena/ClarityCameraRegistry';
import { toDesignSpace } from '../graphics/RenderResolution';
import { addForestCloseButton, BORDER, ensureModalPanelTexture, mountForestModal, SURFACE, textStyle } from './ForestModal';
import {
  formatPublicRoomActivity,
  formatPublicRoomHost,
  formatPublicRoomPing,
  formatPublicRoomPlayers,
  sortPublicRooms,
} from './PublicRoomsModel';
import { UiButton } from './UiButton';
import { getPingColor } from './uiTheme';

const CX = GAME_WIDTH / 2;
const CY = GAME_HEIGHT / 2;
const PANEL_W = 1240;
const PANEL_H = 860;
const PANEL_TOP = CY - PANEL_H / 2;
const TABLE_W = 1080;
const TABLE_LEFT = CX - TABLE_W / 2;
const HEADER_Y = PANEL_TOP + 170;
const ROWS_TOP = HEADER_Y + 30;
const ROW_H = 60;
const VISIBLE_ROWS = 8;
const REFRESH_Y = PANEL_TOP + PANEL_H - 110;
const JOIN_W = 200;
const CONFIRM_MS = 3_000;
const TEX_PANEL = '_public_rooms_panel';

/** Spaltenanfänge relativ zur Tabelle; die letzte Spalte trägt den Beitreten-Knopf. */
const COLUMNS = { host: 0, activity: 230, players: 730, ping: 810 } as const;
/** Platz je Textspalte bis zur nächsten; längere Texte enden mit „…“. */
const COLUMN_WIDTH = { host: 210, activity: 480 } as const;

/** Kürzt einen Text, bis er in `maxWidth` passt (Angaben fremder Hosts können lang sein). */
function fitText(text: Phaser.GameObjects.Text, maxWidth: number): Phaser.GameObjects.Text {
  if (text.width <= maxWidth) return text;
  let value = text.text;
  while (value.length > 1 && text.width > maxWidth) {
    value = value.slice(0, -1);
    text.setText(`${value.trimEnd()}…`);
  }
  return text;
}

type ListState = 'loading' | 'ready' | 'failed';

export class PublicRoomsOverlay {
  private container: Phaser.GameObjects.Container | null = null;
  private rowsLayer: Phaser.GameObjects.Container | null = null;
  private readonly rowButtons: UiButton[] = [];
  private refreshBtn: UiButton | null = null;
  private visible = false;
  private rooms: PlatformPublicRoom[] = [];
  private state: ListState = 'loading';
  private firstRow = 0;
  /** Raum, dessen Beitritt der Host gerade mit einem zweiten Klick bestätigen soll. */
  private confirmingRoomId: string | null = null;
  private confirmTimer: Phaser.Time.TimerEvent | null = null;
  private requestSequence = 0;

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly browser: PlatformRoomBrowser,
    /** True, wenn ein Wechsel andere Spieler betrifft (Host mit Mitspielern). */
    private readonly switchAffectsOthers: () => boolean,
  ) {}

  show(): void {
    if (!this.container) this.build();
    if (!this.container) return;
    this.visible = true;
    this.container.setVisible(true);
    this.refresh();
  }

  hide(): void {
    this.visible = false;
    this.clearConfirmation();
    this.container?.setVisible(false);
  }

  isVisible(): boolean {
    return this.visible;
  }

  destroy(): void {
    this.hide();
    this.scene.input.off('wheel', this.wheel);
    for (const button of this.rowButtons.splice(0)) button.destroy();
    this.refreshBtn?.destroy();
    this.refreshBtn = null;
    this.container?.destroy(true);
    this.container = null;
    this.rowsLayer = null;
  }

  private build(): void {
    const backdrop = this.scene.add.rectangle(CX, CY, GAME_WIDTH, GAME_HEIGHT, COLORS.GREY_10, 0.58)
      .setScrollFactor(0).setInteractive();
    backdrop.on('pointerdown', () => this.hide());
    const panel = this.scene.add.image(CX, CY, ensureModalPanelTexture(this.scene, TEX_PANEL, PANEL_W, PANEL_H, SURFACE.modal, BORDER.default))
      .setScrollFactor(0).setInteractive();
    panel.on('pointerdown', (_pointer: Phaser.Input.Pointer, _x: number, _y: number, event: Phaser.Types.Input.EventData) => {
      event.stopPropagation();
    });
    const title = this.scene.add.text(CX, PANEL_TOP + 100, t('ui.publicGames.title'), textStyle('title', { color: COLORS.GREY_1 }))
      .setOrigin(0.5).setScrollFactor(0);
    const header = (x: number, key: string) => this.scene.add.text(TABLE_LEFT + x, HEADER_Y, t(key),
      textStyle('caption', { color: COLORS.GREY_3 })).setOrigin(0, 0.5).setScrollFactor(0);
    const divider = this.scene.add.rectangle(CX, HEADER_Y + 18, TABLE_W, 1, BORDER.subtle, 0.75).setScrollFactor(0);
    this.rowsLayer = this.scene.add.container(0, 0).setScrollFactor(0);
    this.refreshBtn = new UiButton(this.scene, { skin: 'forest',
      x: CX, y: REFRESH_Y, w: 280, h: 48,
      label: t('ui.publicGames.refresh'), labelRole: 'labelSm', intent: 'secondary', icon: 'rotate', iconSize: 18,
      onClick: () => this.refresh(),
    });
    this.container = this.scene.add.container(0, 0, [
      backdrop, panel, title,
      header(COLUMNS.host, 'ui.publicGames.columnHost'),
      header(COLUMNS.activity, 'ui.publicGames.columnMode'),
      header(COLUMNS.players, 'ui.publicGames.columnPlayers'),
      header(COLUMNS.ping, 'ui.publicGames.columnPing'),
      divider, this.rowsLayer, this.refreshBtn.getRoot(),
    ]).setDepth(DEPTH.OVERLAY + 5).setVisible(false);
    mountForestModal(this.scene, this.container, PANEL_W, PANEL_H);
    addForestCloseButton(this.scene, this.container, { x: CX, y: CY }, PANEL_W, PANEL_H, () => this.hide());
    promoteToClarityCamera(this.scene, this.container);
    this.scene.input.on('wheel', this.wheel);
  }

  private refresh(): void {
    const sequence = ++this.requestSequence;
    this.state = 'loading';
    this.clearConfirmation();
    this.renderRows();
    this.refreshBtn?.setEnabled(false);
    this.browser.list().then(rooms => {
      if (sequence !== this.requestSequence) return;
      this.rooms = sortPublicRooms(rooms);
      this.state = 'ready';
    }, (error: unknown) => {
      if (sequence !== this.requestSequence) return;
      console.warn('[Spielsuche] Suche fehlgeschlagen:', error);
      this.rooms = [];
      this.state = 'failed';
    }).finally(() => {
      if (sequence !== this.requestSequence || !this.container) return;
      this.firstRow = 0;
      this.refreshBtn?.setEnabled(true);
      this.renderRows();
    });
  }

  private renderRows(): void {
    const layer = this.rowsLayer;
    if (!layer) return;
    for (const button of this.rowButtons.splice(0)) button.destroy();
    layer.removeAll(true);
    if (this.state !== 'ready' || this.rooms.length === 0) {
      const key = this.state === 'loading' ? 'ui.publicGames.searching'
        : this.state === 'failed' ? 'ui.publicGames.failed' : 'ui.publicGames.empty';
      layer.add(this.scene.add.text(CX, ROWS_TOP + ROW_H * 2, t(key), textStyle('body', { color: COLORS.GREY_4 }))
        .setOrigin(0.5).setScrollFactor(0));
      return;
    }
    this.firstRow = Phaser.Math.Clamp(this.firstRow, 0, Math.max(0, this.rooms.length - VISIBLE_ROWS));
    this.rooms.slice(this.firstRow, this.firstRow + VISIBLE_ROWS).forEach((room, index) => this.buildRow(layer, room, index));
  }

  private buildRow(layer: Phaser.GameObjects.Container, room: PlatformPublicRoom, index: number): void {
    const y = ROWS_TOP + index * ROW_H + ROW_H / 2;
    if (index % 2 === 0) layer.add(this.scene.add.rectangle(CX, y, TABLE_W, ROW_H - 4, SURFACE.raised, 0.28).setScrollFactor(0));
    const cell = (x: number, text: string, color: number = COLORS.GREY_1) => this.scene.add.text(TABLE_LEFT + x, y, text,
      textStyle('body', { color })).setOrigin(0, 0.5).setScrollFactor(0);
    const ping = cell(COLUMNS.ping, formatPublicRoomPing(room), COLORS.GREY_4);
    if (room.pingMs !== null) ping.setColor(getPingColor(room.pingMs));
    layer.add([
      fitText(cell(COLUMNS.host, formatPublicRoomHost(room)), COLUMN_WIDTH.host),
      fitText(cell(COLUMNS.activity, formatPublicRoomActivity(room), COLORS.GREY_3), COLUMN_WIDTH.activity),
      cell(COLUMNS.players, formatPublicRoomPlayers(room)),
      ping,
    ]);
    const confirming = this.confirmingRoomId === room.id;
    const join = new UiButton(this.scene, { skin: 'forest',
      x: TABLE_LEFT + TABLE_W - JOIN_W / 2, y, w: JOIN_W, h: 44,
      label: t(confirming ? 'ui.publicGames.switchConfirm' : 'ui.publicGames.join'), labelRole: 'labelSm',
      intent: confirming ? 'primary' : 'secondary',
      onClick: () => this.onJoin(room),
    });
    this.rowButtons.push(join);
    layer.add(join.getRoot());
  }

  private onJoin(room: PlatformPublicRoom): void {
    if (this.switchAffectsOthers() && this.confirmingRoomId !== room.id) {
      this.confirmingRoomId = room.id;
      this.confirmTimer?.remove(false);
      this.confirmTimer = this.scene.time.delayedCall(CONFIRM_MS, () => this.clearConfirmation(true));
      this.renderRows();
      return;
    }
    this.clearConfirmation();
    this.browser.join(room.id);
  }

  private clearConfirmation(render = false): void {
    this.confirmTimer?.remove(false);
    this.confirmTimer = null;
    if (this.confirmingRoomId === null) return;
    this.confirmingRoomId = null;
    if (render) this.renderRows();
  }

  private readonly wheel = (pointer: Phaser.Input.Pointer, _over: unknown, _dx: number, dy: number): void => {
    if (!this.visible || this.rooms.length <= VISIBLE_ROWS) return;
    const x = toDesignSpace(this.scene.scale, pointer.x);
    const y = toDesignSpace(this.scene.scale, pointer.y);
    if (x < TABLE_LEFT || x > TABLE_LEFT + TABLE_W || y < ROWS_TOP || y > ROWS_TOP + ROW_H * VISIBLE_ROWS) return;
    this.firstRow += Math.sign(dy);
    this.renderRows();
  };
}
