import type * as Phaser from 'phaser';
import { GAME_WIDTH, GAME_HEIGHT, COLORS, toCssColor as baseToCssColor } from '../config';
import type { BackdropSurface } from '../effects/postfx/BackdropBlur';
import { FOREST, skinTextColor } from './UiSkin';
import { BORDER as BASE_BORDER, SURFACE as BASE_SURFACE, TEXT as BASE_TEXT, INTENT, textStyle as baseTextStyle } from './uiTheme';
import { ensureRoundedTexture } from './uiTextures';
import { ensureForestButton } from './forestTextures';
import { BUTTON_CURSOR } from './gameCursor';
import { activateUi } from './UiAudio';
import { attachHoverEffect } from './uiHover';
import { t } from '../i18n';

export const MODAL_FRAME_ASSET = { key: 'forest_modal_frame_kit', file: './assets/ui/forest-modals/frame-kit.png' } as const;
/** Rotes Schliessen-X aller Forest-Fenster; sitzt auf dem Astknoten der rechten oberen Rahmenecke. */
export const FOREST_CLOSE_ASSET = { key: 'forest_close_x', file: './assets/ui/forest-modals/close-x.png' } as const;
/** Groesste angezeigte Eckgroesse des Rahmens; ab ihr bleibt das Holz in allen Fenstern gleich dick. */
const MODAL_FRAME_MAX_CAP = 120;
/** Mitte des geschnitzten Astknotens der rechten oberen Ecke, in Bruchteilen der angezeigten Eckgroesse. */
const CLOSE_KNOT = { fromRight: 0.367, fromTop: 0.442 } as const;
/** Anzeigegroesse des X in Phaser-Fenstern (Design-Pixel) und in DOM-Dialogen (CSS-Pixel). */
export const FOREST_CLOSE_SIZE = 60;
const FOREST_DIALOG_CLOSE_SIZE = 46;
export const SURFACE = { ...BASE_SURFACE, modal: FOREST.glass, raised: 0x293027, sunken: FOREST.sunken };
export const BORDER = { ...BASE_BORDER, subtle: 0x575848, default: FOREST.border };
export const TEXT = { ...BASE_TEXT, primary: FOREST.text, secondary: FOREST.text, muted: FOREST.muted };
export function textStyle(...args: Parameters<typeof baseTextStyle>): ReturnType<typeof baseTextStyle> {
  const style = baseTextStyle(...args);
  if (typeof style.color === 'string' && /^#[0-9a-f]{6}$/i.test(style.color)) {
    style.color = '#' + skinTextColor('forest', parseInt(style.color.slice(1), 16)).toString(16).padStart(6, '0');
  }
  return style;
}

export function preloadForestModalAssets(loader: Phaser.Loader.LoaderPlugin): void {
  loader.image(MODAL_FRAME_ASSET.key, MODAL_FRAME_ASSET.file);
  loader.image(FOREST_CLOSE_ASSET.key, FOREST_CLOSE_ASSET.file);
}

/**
 * Uniform source-to-display scale for every corner and every cropped rail repeat.
 * `maxCap` bounds the displayed corner size; a fixed value keeps the wood equally thick
 * across differently sized windows of one family.
 */
export function drawModalFrame(ctx: CanvasRenderingContext2D, image: HTMLImageElement, w: number, h: number,
  maxCap = MODAL_FRAME_MAX_CAP): void {
  const corner = image.width / 5;
  const cap = Math.min(maxCap, w / 3, h / 3), scale = cap / corner;
  const sx = [0, corner, image.width - corner], sy = [0, corner, image.height - corner];
  const sw = [corner, image.width - corner * 2, corner], sh = [corner, image.height - corner * 2, corner];
  const dx = [0, cap, w - cap], dy = [0, cap, h - cap];
  const dw = [cap, w - cap * 2, cap], dh = [cap, h - cap * 2, cap];
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  for (let row = 0; row < 3; row++) for (let col = 0; col < 3; col++) {
    if (row === 1 && col === 1) continue;
    for (let y = 0; y < dh[row]; y += sh[row] * scale) for (let x = 0; x < dw[col]; x += sw[col] * scale) {
      const width = Math.min(sw[col] * scale, dw[col] - x), height = Math.min(sh[row] * scale, dh[row] - y);
      ctx.drawImage(image, sx[col], sy[row], width / scale, height / scale, dx[col] + x, dy[row] + y, width, height);
    }
  }
}

export function ensureModalFrame(scene: Phaser.Scene, w: number, h: number): string {
  const key = `_forest_modal_frame_${MODAL_FRAME_ASSET.key}_${w}x${h}`;
  if (scene.textures.exists(key)) return key;
  const texture = scene.textures.createCanvas(key, w * 2, h * 2)!;
  texture.context.scale(2, 2);
  if (scene.textures.exists(MODAL_FRAME_ASSET.key)) drawModalFrame(texture.context,
    scene.textures.get(MODAL_FRAME_ASSET.key).getSourceImage() as HTMLImageElement, w, h);
  texture.refresh();
  return key;
}

/** Same signature as the old surface helper, but isolated keys and no changes to lobby textures. */
export function ensureModalPanelTexture(scene: Phaser.Scene, _key: string, w: number, h: number,
  _base?: number, _accent?: number): string {
  return ensureRoundedTexture(scene, { key: `_forest_modal_glass_${w}x${h}`, w: w - 80, h: h - 80, radius: 24,
    topColor: FOREST.glass, bottomColor: SURFACE.sunken, fillAlpha: 0.92,
    strokeColor: FOREST.border, strokeAlpha: 0, strokeWidth: 0, highlightAlpha: 0.015 });
}

/** Existing image-button event/animation contracts are retained by using their forest face. */
export function ensureGlossyButtonTexture(scene: Phaser.Scene, _key: string, w: number, h: number,
  base: number, stroke?: number): string {
  const danger = base === INTENT.danger.fill || stroke === INTENT.danger.stroke;
  const attention = base === INTENT.primary.fill || base === INTENT.accent.fill || stroke === COLORS.GOLD_1;
  return ensureForestButton(scene, w, h, danger ? 'danger' : attention ? 'attention' : 'neutral', 'rest');
}

type ModalRecord = {
  root: Phaser.GameObjects.Container; w: number; h: number; backdrop: 'panel' | 'screen'; offsetY: number;
};
const modalSurfaces = new WeakMap<Phaser.Scene, Set<ModalRecord>>();

/**
 * Decoration is a sibling above content. Callers supply transient layers to keep above the frame.
 * `offsetY` moves the frame inside its root, e.g. when a window shrinks but keeps its content top.
 */
export function mountForestModal(scene: Phaser.Scene, root: Phaser.GameObjects.Container, w: number, h: number,
  transient: Phaser.GameObjects.GameObject[] = [], backdrop: 'panel' | 'screen' = 'panel', offsetY = 0): Phaser.GameObjects.Image {
  const frame = scene.add.image(GAME_WIDTH / 2, GAME_HEIGHT / 2 + offsetY, ensureModalFrame(scene, w, h))
    .setDisplaySize(w, h).setScrollFactor(0);
  root.add(frame);
  for (const child of transient) root.bringToTop(child);
  const records = modalSurfaces.get(scene) ?? new Set<ModalRecord>();
  modalSurfaces.set(scene, records);
  const record = { root, w, h, backdrop, offsetY };
  records.add(record);
  root.once('destroy', () => records.delete(record));
  return frame;
}

export function getForestModalSurfaces(scene: Phaser.Scene): BackdropSurface[] {
  return [...(modalSurfaces.get(scene) ?? [])].filter(({ root }) => root.visible && root.alpha > 0)
    .map(({ root, w, h, backdrop, offsetY }) => backdrop === 'screen'
      ? { x: 0, y: 0, width: GAME_WIDTH, height: GAME_HEIGHT, radius: 0, alpha: root.alpha }
      : { x: (GAME_WIDTH - w) / 2 + 40 + root.x, y: (GAME_HEIGHT - h) / 2 + 40 + root.y + offsetY,
        width: w - 80, height: h - 80, radius: 24, alpha: root.alpha });
}

/** Position des X relativ zur Fenstermitte eines w×h-Fensters: die Mitte des Eckknotens. */
export function forestModalCloseOffset(w: number, h: number): { readonly x: number; readonly y: number } {
  const cap = Math.min(MODAL_FRAME_MAX_CAP, w / 3, h / 3);
  return { x: w / 2 - cap * CLOSE_KNOT.fromRight, y: -h / 2 + cap * CLOSE_KNOT.fromTop };
}

/** Ersatz, falls das Bild nicht geladen ist (isolierte Vorschauen, Ladefehler): rotes X auf dunklem Holz. */
function ensureForestCloseTexture(scene: Phaser.Scene): string {
  if (scene.textures.exists(FOREST_CLOSE_ASSET.key)) return FOREST_CLOSE_ASSET.key;
  const key = '_forest_close_x_fallback';
  if (scene.textures.exists(key)) return key;
  const texture = scene.textures.createCanvas(key, 128, 128);
  if (!texture) return key;
  const ctx = texture.context;
  ctx.fillStyle = baseToCssColor(FOREST.wood);
  ctx.beginPath(); ctx.arc(64, 64, 58, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = baseToCssColor(COLORS.RED_2);
  ctx.lineWidth = 18; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(40, 40); ctx.lineTo(88, 88); ctx.moveTo(88, 40); ctx.lineTo(40, 88); ctx.stroke();
  texture.refresh();
  return key;
}

/**
 * Rotes X auf der Rahmenecke eines Forest-Fensters (Phaser). `center` ist die Mitte des Rahmens im
 * Koordinatensystem von `root`; das X liegt ueber dem Rahmen und schliesst per Klick.
 */
export function addForestCloseButton(scene: Phaser.Scene, root: Phaser.GameObjects.Container,
  center: { readonly x: number; readonly y: number }, w: number, h: number, onClose: () => void,
  size = FOREST_CLOSE_SIZE): Phaser.GameObjects.Image {
  const offset = forestModalCloseOffset(w, h);
  const button = scene.add.image(center.x + offset.x, center.y + offset.y, ensureForestCloseTexture(scene))
    .setDisplaySize(size, size).setScrollFactor(0)
    .setInteractive({ cursor: BUTTON_CURSOR });
  button.on('pointerdown', (_pointer: unknown, _x: number, _y: number, event?: { stopPropagation(): void }) => {
    event?.stopPropagation();
    activateUi(scene, onClose);
  });
  attachHoverEffect(scene, button);
  root.add(button);
  root.bringToTop(button);
  return button;
}

/**
 * Dasselbe X fuer native DOM-Dialoge im Forest-Skin (`.player-profile`). Die Lage folgt dem Rahmen,
 * der als Hintergrund mit 100 % Breite und Hoehe gemalt wird, deshalb in Prozent der Dialoggroesse.
 */
export function appendForestDialogClose(scene: Phaser.Scene, dialog: HTMLElement, w: number, h: number,
  onClose: () => void): HTMLButtonElement {
  const cap = Math.min(MODAL_FRAME_MAX_CAP, w / 3, h / 3);
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'forest-dialog-close';
  button.title = t('ui.common.close');
  button.setAttribute('aria-label', t('ui.common.close'));
  button.style.setProperty('--close-size', `${FOREST_DIALOG_CLOSE_SIZE}px`);
  button.style.setProperty('--close-right', `${(cap * CLOSE_KNOT.fromRight / w) * 100}%`);
  button.style.setProperty('--close-top', `${(cap * CLOSE_KNOT.fromTop / h) * 100}%`);
  button.style.backgroundImage = `url("${scene.textures.getBase64(ensureForestCloseTexture(scene))}")`;
  button.onclick = () => activateUi(scene, onClose);
  dialog.append(button);
  return button;
}

export function toCssColor(color: number): string { return baseToCssColor(skinTextColor('forest', color)); }

/**
 * Theme variables for native DOM dialogs in the forest skin (`--profile-*`, see ProfileDialog.css):
 * palette colours plus the wooden frame rendered at the dialog's design size.
 */
export function applyForestDialogTheme(scene: Phaser.Scene, dialog: HTMLElement, w: number, h: number): void {
  for (const [name, color] of Object.entries({ text: FOREST.text, muted: FOREST.muted,
    surface: FOREST.glass, field: FOREST.sunken, border: FOREST.border, button: FOREST.wood })) {
    dialog.style.setProperty('--profile-' + name, baseToCssColor(color));
  }
  dialog.style.setProperty('--profile-frame', 'url("' + scene.textures.getBase64(ensureModalFrame(scene, w, h)) + '")');
}

export function ensureTintedSectionTexture(scene: Phaser.Scene, _key: string, w: number, h: number, accent: number, _base?: number): string {
  return ensureRoundedTexture(scene, { key: `_forest_section_${w}x${h}_${accent}`, w, h, radius: 16,
    topColor: SURFACE.raised, bottomColor: SURFACE.sunken, fillAlpha: .84, strokeColor: accent, strokeAlpha: .45,
    strokeWidth: 1.5, highlightAlpha: .02 });
}
