import {
  ACHIEVEMENT_COUNTER_KEY_PATTERN,
  ACHIEVEMENT_COUNTER_MAX_VALUE,
  ACHIEVEMENT_MAX_COUNTERS,
  sanitizeAchievementCounterValue,
} from './AchievementCounters';

/**
 * Personal achievement record, persisted inside the progress save.
 *
 * The save is the source of truth; Steam is only a sink that is re-synced in full. Unlocks are
 * latched here because some conditions (a fully upgraded weapon) can be undone by a respec.
 */
export interface AchievementLedger {
  readonly counters: Readonly<Record<string, number>>;
  readonly unlocked: readonly string[];
}

/** One player's achievement data for a single round, carried in that player's RoundResult row. */
export interface RoundAchievementSnapshot {
  readonly counters: Readonly<Record<string, number>>;
  readonly deaths: number;
}

export interface AchievementCounterDelta {
  readonly add?: Readonly<Record<string, number>>;
  readonly max?: Readonly<Record<string, number>>;
}

export const ACHIEVEMENT_LEDGER_MAX_COUNTERS = 256;
export const ACHIEVEMENT_LEDGER_MAX_UNLOCKED = 200;
export const ROUND_ACHIEVEMENT_MAX_COUNTERS = 64;
export const ACHIEVEMENT_API_NAME_PATTERN = /^[A-Z][A-Z0-9_]{0,63}$/u;

export const EMPTY_ACHIEVEMENT_LEDGER: AchievementLedger = Object.freeze({
  counters: Object.freeze({}),
  unlocked: Object.freeze([]),
});

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function sanitizeCounters(raw: unknown, limit: number): Record<string, number> {
  const counters: Record<string, number> = {};
  if (!isRecord(raw)) return counters;
  let count = 0;
  for (const [key, value] of Object.entries(raw)) {
    if (count >= limit) break;
    if (!ACHIEVEMENT_COUNTER_KEY_PATTERN.test(key)) continue;
    const safe = sanitizeAchievementCounterValue(value);
    if (safe === null || safe === 0) continue;
    counters[key] = safe;
    count++;
  }
  return counters;
}

export function sanitizeAchievementLedger(raw: unknown): AchievementLedger {
  if (!isRecord(raw)) return EMPTY_ACHIEVEMENT_LEDGER;
  const unlocked = Array.isArray(raw.unlocked)
    ? [...new Set(raw.unlocked.filter((id): id is string => typeof id === 'string' && ACHIEVEMENT_API_NAME_PATTERN.test(id)))]
      .slice(0, ACHIEVEMENT_LEDGER_MAX_UNLOCKED).sort()
    : [];
  return { counters: sanitizeCounters(raw.counters, ACHIEVEMENT_LEDGER_MAX_COUNTERS), unlocked };
}

/** Wire data from the host: never trusted beyond shape and bounds. */
export function sanitizeRoundAchievementSnapshot(raw: unknown): RoundAchievementSnapshot | null {
  if (!isRecord(raw)) return null;
  const deaths = sanitizeAchievementCounterValue(raw.deaths);
  if (deaths === null) return null;
  return { counters: sanitizeCounters(raw.counters, ROUND_ACHIEVEMENT_MAX_COUNTERS), deaths };
}

/** Union of unlocks and the larger value per counter: safe for imports and cloud conflicts. */
export function mergeAchievementLedgers(a: AchievementLedger, b: AchievementLedger): AchievementLedger {
  const counters: Record<string, number> = { ...a.counters };
  for (const [key, value] of Object.entries(b.counters)) counters[key] = Math.max(counters[key] ?? 0, value);
  return sanitizeAchievementLedger({ counters, unlocked: [...a.unlocked, ...b.unlocked] });
}

export function applyAchievementCounterDelta(ledger: AchievementLedger, delta: AchievementCounterDelta): AchievementLedger {
  const counters: Record<string, number> = { ...ledger.counters };
  let changed = false;
  for (const [key, value] of Object.entries(delta.add ?? {})) {
    const amount = sanitizeAchievementCounterValue(value);
    if (!amount || !ACHIEVEMENT_COUNTER_KEY_PATTERN.test(key)) continue;
    counters[key] = Math.min(ACHIEVEMENT_COUNTER_MAX_VALUE, (counters[key] ?? 0) + amount);
    changed = true;
  }
  for (const [key, value] of Object.entries(delta.max ?? {})) {
    const amount = sanitizeAchievementCounterValue(value);
    if (!amount || !ACHIEVEMENT_COUNTER_KEY_PATTERN.test(key) || (counters[key] ?? 0) >= amount) continue;
    counters[key] = amount;
    changed = true;
  }
  if (!changed) return ledger;
  // Bounded like a decoded save, so a hostile host cannot grow the save without limit.
  const keys = Object.keys(counters);
  if (keys.length > ACHIEVEMENT_LEDGER_MAX_COUNTERS) return ledger;
  return { counters, unlocked: ledger.unlocked };
}

export function withAchievementUnlocks(ledger: AchievementLedger, apiNames: readonly string[]): AchievementLedger {
  const missing = apiNames.filter(name => !ledger.unlocked.includes(name));
  if (missing.length === 0) return ledger;
  return sanitizeAchievementLedger({ counters: ledger.counters, unlocked: [...ledger.unlocked, ...missing] });
}

/** Splits a round snapshot into running sums and best-of values. */
export function roundSnapshotToDelta(snapshot: RoundAchievementSnapshot): { add: Record<string, number>; max: Record<string, number> } {
  const add: Record<string, number> = {};
  const max: Record<string, number> = {};
  for (const [key, value] of Object.entries(snapshot.counters)) {
    if (ACHIEVEMENT_MAX_COUNTERS.has(key)) max[key] = value;
    else add[key] = value;
  }
  return { add, max };
}

export function isAchievementLedgerEqual(a: AchievementLedger, b: AchievementLedger): boolean {
  if (a === b) return true;
  if (a.unlocked.length !== b.unlocked.length || a.unlocked.some((id, index) => id !== b.unlocked[index])) return false;
  const aKeys = Object.keys(a.counters);
  if (aKeys.length !== Object.keys(b.counters).length) return false;
  return aKeys.every(key => a.counters[key] === b.counters[key]);
}
