/**
 * Flame chain of one muzzle of a multi-muzzle body (the colossus's two mandible jets). Presentation
 * finds a jet's newest flame under this key, so effects around the muzzle follow where it flies.
 */
export const muzzleFlameStreamKey = (ownerId: string, muzzle: number): string => `${ownerId}:m${muzzle}`;
