import * as Phaser from 'phaser';
import { preloadLobbyStaffAssets } from './LobbyStaffAssets';
import { preloadLobbyStructureAssets } from '../arena/lobbyStructures/LobbyStructureAssets';
import { preloadBaseFortAssets } from '../arena/baseStructures/BaseFortAssets';
import { PIPELINE_ASSETS, pipelineAnimationKey, getPipelineSpriteScale, isPipelineBossTexture } from '../config/pipelineAssets';
import { enemyEmissionLayout, enemyEmissionSheetPath, enemyEmissionTextureKey, type EnemyEmissionLayout } from '../config/enemyEmission';

/**
 * Shared walking-animation contract for every badger-shaped figure.
 *
 * Walking sheets contain north-facing cells with explicit gutters and clip frame lists.
 * A separate rest frame is excluded from the move loop; an authored idle clip is optional.
 * `WALKING_SHEETS` below is the only place a
 * new animated figure is registered; preload, animation registration and the per-sprite sync
 * all derive from it.
 *
 * The sheet resolution never decides how big a figure is drawn. Display size stays the
 * entity's decision (`PLAYER_SIZE`, `ResolvedCoopDefenseEnemyConfig.size`); an authored
 * displayScale adds transparent motion room without changing that body's size. See
 * docs/ai/rendering.md.
 */
export interface WalkingSheet {
  /** Texture key of the loaded spritesheet. */
  readonly textureKey: string;
  /** Global animation key; the AnimationManager is shared by all scenes. */
  readonly animationKey: string;
  readonly assetPath: string;
  readonly frameWidth: number;
  readonly frameHeight: number;
  readonly frameCount: number;
  readonly frames: readonly number[];
  readonly margin: number;
  readonly spacing: number;
  readonly frameRate: number;
  /** Transparent room for authored motion, independent of the figure's collision diameter. */
  readonly displayScale: number;
  readonly idle?: {
    readonly animationKey: string;
    readonly frames: readonly number[];
    readonly frameRate: number;
  };
  /**
   * Key of the static single-frame texture this sheet supersedes. Authored content that only
   * knows its image key – enemy configs – resolves its animated variant through this field.
   */
  readonly staticTextureKey?: string;
  /** Emission sheet in the same grid (heat channels), loaded as `enemyEmissionTextureKey(textureKey)`. */
  readonly emissionPath?: string;
  /** Cells of a scaled emission sheet; absent = the beauty layout. */
  readonly emissionLayout?: EnemyEmissionLayout;
  /** A player character rather than an enemy. */
  readonly character: boolean;
}

/** Frame 0 ist die neutrale Ruhepose für inaktive Figuren und Sheets ohne Idle-Clip. */
export const WALKING_IDLE_FRAME = 0;

const WALKING_SHEETS: readonly WalkingSheet[] = PIPELINE_ASSETS
  .filter((asset) => asset.runtimeContract === 'sheet' && (asset.category === 'character' || asset.category === 'enemy'))
  // Laufende Figuren brauchen einen move-Clip; reine Idle-Figuren (z. B. der Dawn-Haendler) laufen nie.
  .flatMap((asset) => {
    const clip = asset.clips.find((candidate) => candidate.name === 'move');
    if (!clip) return [];
    const idle = asset.clips.find((candidate) => candidate.name === 'idle');
    return [{
      textureKey: asset.sheetTextureKey,
      animationKey: pipelineAnimationKey(asset, clip),
      assetPath: asset.sheetPath,
      frameWidth: asset.layout.frameWidth,
      frameHeight: asset.layout.frameHeight,
      margin: asset.layout.margin,
      spacing: asset.layout.spacing,
      frameCount: asset.layout.frameCount,
      frames: clip.frames,
      frameRate: clip.frameRate,
      displayScale: getPipelineSpriteScale(asset.textureKey),
      idle: idle ? { animationKey: pipelineAnimationKey(asset, idle), frames: idle.frames, frameRate: idle.frameRate } : undefined,
      staticTextureKey: asset.textureKey,
      emissionPath: enemyEmissionSheetPath(asset) ?? undefined,
      emissionLayout: enemyEmissionLayout(asset) ?? undefined,
      character: asset.category === 'character',
    }];
  });

export const BADGER_WALKING_SHEET = WALKING_SHEETS.find((sheet) => sheet.staticTextureKey === 'badger')!;
export const ZOMBIE_BADGER_WALKING_SHEET = WALKING_SHEETS.find((sheet) => sheet.staticTextureKey === 'enemy_zombie_badger')!;

// Kompatible Einzelwerte fuer die Spielerfigur; sie hat als einzige eine feste Grundskalierung.
export const BADGER_WALKING_TEXTURE_KEY = BADGER_WALKING_SHEET.textureKey;
export const BADGER_WALKING_ANIMATION_KEY = BADGER_WALKING_SHEET.animationKey;
export const BADGER_WALKING_FRAME_WIDTH = BADGER_WALKING_SHEET.frameWidth;
export const BADGER_WALKING_FRAME_HEIGHT = BADGER_WALKING_SHEET.frameHeight;
export const BADGER_IDLE_FRAME = WALKING_IDLE_FRAME;

/** Walking-Sheet zur aktuell gesetzten Textur, oder `null` fuer eine statische Figur. */
export function getWalkingSheetByTexture(textureKey: string): WalkingSheet | null {
  return WALKING_SHEETS.find((sheet) => sheet.textureKey === textureKey) ?? null;
}

/** Walking-Sheet, das die genannte statische Textur ersetzt, oder `null`. */
export function getWalkingSheetForStaticTexture(staticTextureKey: string): WalkingSheet | null {
  return WALKING_SHEETS.find((sheet) => sheet.staticTextureKey === staticTextureKey) ?? null;
}

/** Queue the lobby's figures and its idle-only decoration before scene creation. Sheets the
 * lobby never shows (`lobbyStaticTextureKeys` decides) follow with the second loading phase. */
export function preloadBadgerAnimationAssets(loader: Phaser.Loader.LoaderPlugin,
  lobbyStaticTextureKeys?: ReadonlySet<string>): void {
  preloadLobbyStaffAssets(loader);
  preloadLobbyStructureAssets(loader);
  preloadBaseFortAssets(loader);
  preloadWalkingSheets(loader, sheet => !lobbyStaticTextureKeys || isLobbyWalkingSheet(sheet, lobbyStaticTextureKeys));
}

/** Walking sheets of figures that appear only in rounds; boss phase sheets load when their boss appears. */
export function preloadRoundWalkingSheets(loader: Pick<Phaser.Loader.LoaderPlugin, 'spritesheet'>,
  lobbyStaticTextureKeys: ReadonlySet<string>, lazyStaticTextureKeys: ReadonlySet<string> = new Set()): void {
  preloadWalkingSheets(loader, sheet => !isLobbyWalkingSheet(sheet, lobbyStaticTextureKeys)
    && !lazyStaticTextureKeys.has(sheet.staticTextureKey ?? ''));
}

/** Player characters are always shown; enemies only when the lobby itself places them. */
function isLobbyWalkingSheet(sheet: WalkingSheet, lobbyStaticTextureKeys: ReadonlySet<string>): boolean {
  return sheet.character || lobbyStaticTextureKeys.has(sheet.staticTextureKey ?? '');
}

function preloadWalkingSheets(loader: Pick<Phaser.Loader.LoaderPlugin, 'spritesheet'>,
  include: (sheet: WalkingSheet) => boolean): void {
  for (const sheet of WALKING_SHEETS) {
    if (!include(sheet)) continue;
    const layout = {
      frameWidth: sheet.frameWidth,
      frameHeight: sheet.frameHeight,
      margin: sheet.margin,
      spacing: sheet.spacing,
      endFrame: sheet.frameCount - 1,
    };
    loader.spritesheet(sheet.textureKey, sheet.assetPath, layout);
    if (sheet.emissionPath) loader.spritesheet(enemyEmissionTextureKey(sheet.textureKey), sheet.emissionPath,
      { ...layout, ...sheet.emissionLayout });
  }
}

/** Enemy image preload must use this projection too; boss rest poses come from residency. */
export function genericEnemyImageKeys(enemies: readonly { imageKey: string; krakenBoss?: unknown; krakenEgg?: unknown }[]): string[] {
  return [...new Set(enemies.filter(e => !e.krakenBoss && !e.krakenEgg && !isPipelineBossTexture(e.imageKey)).map(e => e.imageKey))];
}

/** Register the global animations once; AnimationManager is shared by all Scenes. Sheets that are
 * not loaded yet (`isLoaded`) are skipped and registered by a later call. */
export function registerBadgerAnimations(anims: Phaser.Animations.AnimationManager,
  isLoaded: (textureKey: string) => boolean = () => true): void {
  for (const sheet of WALKING_SHEETS) {
    if (!isLoaded(sheet.textureKey)) continue;
    for (const clip of sheet.idle ? [sheet, sheet.idle] : [sheet]) {
      if (anims.exists(clip.animationKey)) continue;
      anims.create({
        key: clip.animationKey,
        frames: anims.generateFrameNumbers(sheet.textureKey, { frames: [...clip.frames] }),
        frameRate: clip.frameRate,
        repeat: -1,
      });
    }
  }
}

/** Walk-cycle phase a figure stopped at; walking on continues from it. */
const pausedWalkPhase = new WeakMap<Phaser.GameObjects.Sprite, number>();

/**
 * Apply the requested locomotion state to one figure sprite.
 *
 * The sheet is resolved from the sprite's own texture, so the helper covers players and
 * animated enemies alike and is a no-op for a figure without walking artwork. Standing figures
 * use their authored idle clip when present, otherwise frame 0. Inactive figures hold frame 0. The
 * helper is idempotent and therefore safe to call from host and client sync.
 */
export function syncBadgerWalkingAnimation(
  sprite: Phaser.GameObjects.Sprite,
  walking: boolean,
  active: boolean = true,
): void {
  const sheet = getWalkingSheetByTexture(sprite.texture.key);
  if (!sheet) return;

  const currentKey = sprite.anims.currentAnim?.key;
  const desiredKey = active ? (walking ? sheet.animationKey : sheet.idle?.animationKey) : undefined;
  if (currentKey === sheet.animationKey && currentKey !== desiredKey) pausedWalkPhase.set(sprite, sprite.anims.getProgress());

  if (desiredKey) {
    if (currentKey !== desiredKey || !sprite.anims.isPlaying) {
      sprite.play(desiredKey);
      // Ein Pulk gleichzeitig gestarteter Figuren liefe sonst im Gleichschritt: der erste Start
      // waehlt eine zufaellige Phase. Danach setzt der Gang dort fort, wo die Beine stehen
      // blieben, statt bei jedem Wiederanlaufen zu springen. Die Phase ist rein visuell und muss
      // zwischen Host und Clients nicht uebereinstimmen.
      if (walking) sprite.anims.setProgress(pausedWalkPhase.get(sprite) ?? Math.random());
    }
    return;
  }

  if ((currentKey === sheet.animationKey || currentKey === sheet.idle?.animationKey) && sprite.anims.isPlaying) {
    sprite.anims.stop();
  }
  if (sprite.frame.name !== String(WALKING_IDLE_FRAME)) {
    sprite.setFrame(WALKING_IDLE_FRAME);
  }
}
