/**
 * „Spiel beenden“ aus dem Optionsmenue (nur mit Desktop-Shell).
 *
 * Eine Runde wird ausschliesslich an ihrem Ende gutgeschrieben, und ihr Zustand wandert nicht mit:
 * Geht der Host, uebernimmt ein Gast nur den Raum (Host-Uebergabe), die Runde endet fuer alle. Beendet der Host deshalb mitten in einer Runde, laeuft zuerst der
 * normale Abbruchweg („Zurueck zur Lobby“): Er wertet die bis dahin erspielten Ergebnisse fuer alle.
 * Erst wenn der Host sein Ergebnis verbucht hat und die Gaeste es empfangen konnten, schliesst die
 * Shell. Gaeste und die Lobby beenden sofort; der Hauptprozess leert vorher die Speicher.
 */

export type ArenaQuitMode = 'idle' | 'host-round' | 'guest-round';

export interface ArenaQuitFlowPorts {
  /** Eine Runde laeuft und ist nicht beendet. */
  isRoundRunning(): boolean;
  /** Der lokale Spieler darf die laufende Runde als Host abbrechen. */
  canHostAbortRound(): boolean;
  hostAbortRound(): void;
  /** Zaehlt jedes lokal verarbeitete Rundenergebnis (gewertet oder nicht teilnahmeberechtigt). */
  getResolvedMatchResultsCount(): number;
  showQuitNotice(): void;
  quit(): void;
  now(): number;
}

/** Zeit fuer Rundenende und Ergebnisse, um die Gaeste zu erreichen, bevor der Raum schliesst. */
export const QUIT_AFTER_CREDIT_GRACE_MS = 1500;
/** Spaetestens dann beendet die Shell, auch wenn die Wertung haengt. */
export const QUIT_CREDIT_TIMEOUT_MS = 10_000;

export class ArenaQuitFlow {
  private requestedAt: number | null = null;
  private resolvedCountAtRequest = 0;
  private creditedAt: number | null = null;
  private quitting = false;

  constructor(private readonly ports: ArenaQuitFlowPorts) {}

  mode(): ArenaQuitMode {
    if (!this.ports.isRoundRunning()) return 'idle';
    return this.ports.canHostAbortRound() ? 'host-round' : 'guest-round';
  }

  isPending(): boolean {
    return this.requestedAt !== null || this.quitting;
  }

  request(): void {
    if (this.isPending()) return;
    if (this.mode() !== 'host-round') {
      this.quitNow();
      return;
    }
    this.requestedAt = this.ports.now();
    this.resolvedCountAtRequest = this.ports.getResolvedMatchResultsCount();
    this.ports.hostAbortRound();
    this.ports.showQuitNotice();
  }

  /** Je Frame: wartet auf die eigene Wertung, dann auf die Zustellung an die Gaeste. */
  update(): void {
    if (this.requestedAt === null || this.quitting) return;
    const now = this.ports.now();
    if (now - this.requestedAt >= QUIT_CREDIT_TIMEOUT_MS) {
      this.quitNow();
      return;
    }
    if (this.creditedAt === null) {
      if (this.ports.getResolvedMatchResultsCount() > this.resolvedCountAtRequest) this.creditedAt = now;
      return;
    }
    if (now - this.creditedAt >= QUIT_AFTER_CREDIT_GRACE_MS) this.quitNow();
  }

  private quitNow(): void {
    if (this.quitting) return;
    this.quitting = true;
    this.ports.quit();
  }
}
