import * as Phaser from 'phaser';
import { getVisibleWorldView, createVisibleWorldView } from '../../graphics/CameraWorldView';
import { lightAddBlendMode } from '../../graphics/CustomBlendModes';
import { getIndirectLightGain } from '../../graphics/LightingFeatures';
import { runWithScopedBlend } from '../../graphics/PhaserScopedBlend';
import { ownSunShader, SunRenderTarget } from '../sunlight/SunRenderTarget';
import { enableHdrShaderTarget } from './LightHdrComposite';
import type { LightMapBinding } from './LightMapBinding';

export interface DistanceFieldView {
  readonly texture: Phaser.Textures.Texture;
  /** World x, y of the field; 1 / world width, 1 / world height. */
  readonly frame: Float32Array;
  readonly cellPx: number;
}

export const CASCADE_SHADER = 'IndirectCascade', FLUENCE_SHADER = 'IndirectFluence', INDIRECT_ADD_SHADER = 'IndirectAdd';
const CASCADES = 5;
/** World px between the probes of the finest cascade; the research settled on half resolution, about 4 px. */
const BASE_SPACING_PX = 4;
/** The fields are sized in steps of this: zooming changes the view on every frame and must not rebuild them on every frame. */
const VIEW_SIZE_STEP_PX = 256;
/** Length of the finest cascade's rays, in probe spacings. */
const INTERVAL_FACTOR = 1.2;
/** Probes reach this far outside the view, so light from just off screen counts. */
const MARGIN_PX = 128;
/** Bounce reaches no further than this. */
const RANGE_PX = 900;
/** Rays travel at this height: lower blockers neither stop nor reflect them. */
const RAY_HEIGHT_PX = 24;
/** Muted warm rock: the surfaces only re-emit part of what hits them. */
const BOUNCE_COLOR = [0.6, 0.54, 0.46] as const;
const MAX_MARCH_STEPS = 24;
/** Width over which the bounce fades in beside a wall. */
const EDGE_FADE_PX = 6;
/** How quickly very bright lit surfaces stop adding to the bounce. */
const BOUNCE_SOFT_LIMIT = 1.2;

const glsl = (v: number): string => v.toFixed(4);

export const CASCADE_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uSdf,uLightMap,uUpper,uFluencePrevious,uAmbientLayer;
uniform vec4 uSdfFrame,uLightFrame,uFluenceFrame;
uniform vec3 uAmbient;
uniform float uBounceGain,uAmbientLayerOn;
// Texel world size; surface tolerance.
uniform vec2 uCell;
uniform vec2 uOrigin,uProbes,uUpperOrigin,uUpperProbes,uUpperTexSize;
// Spacing, tiles, interval start, interval end.
uniform vec4 uLevel;
// Upper level spacing, tiles, whether it exists.
uniform vec3 uUpperLevel;
const float TAU=6.28318530718;
vec3 bounceAt(vec2 world,float distanceWalked) {
 vec2 at=(world-uLightFrame.xy)/uLightFrame.zw;
 vec2 uv=vec2(at.x,1.0-at.y);
 // The moon lies over rock and ground alike: it belongs to the night, not to the lit surfaces that bounce.
 vec3 night=uAmbient+(uAmbientLayerOn>.5?texture2D(uAmbientLayer,uv).rgb:vec3(0.0));
 // The map still holds last frame's bounce: taking it out again keeps the light from feeding itself.
 vec3 lit=max(texture2D(uLightMap,uv).rgb-night-texture2D(uFluencePrevious,(world-uFluenceFrame.xy)*uFluenceFrame.zw).rgb,vec3(0.0));
 // A small surface next to a blast would otherwise throw single rays that read as streaks across the ground.
 lit/=1.0+dot(lit,vec3(.2126,.7152,.0722))*${glsl(BOUNCE_SOFT_LIMIT)};
 float fall=clamp(1.0-distanceWalked/${glsl(RANGE_PX)},0.0,1.0);
 return lit*vec3(${BOUNCE_COLOR.map(glsl).join(',')})*uBounceGain*fall*fall;
}
// Radiance along one interval; alpha 1 means the ray ran free and the next cascade continues it.
vec4 march(vec2 from,vec2 d,float len,float walked) {
 float t=0.0;
 for(int i=0;i<${MAX_MARCH_STEPS};i++) {
  vec2 x=from+d*t,uv=(x-uSdfFrame.xy)*uSdfFrame.zw;
  if(uv.x<0.0||uv.y<0.0||uv.x>1.0||uv.y>1.0)return vec4(0.0,0.0,0.0,1.0);
  vec4 s=texture2D(uSdf,uv);
  if(s.r<uCell.y) {
   bool figure=s.a>.25&&s.a<=.75;
   if(!figure&&s.g>=${glsl(RAY_HEIGHT_PX)})return vec4(bounceAt(x-d*uCell.x*2.5,walked+t),0.0);
   t+=uCell.x*1.5;
  } else t+=s.r;
  if(t>=len)return vec4(0.0,0.0,0.0,1.0);
 }
 return vec4(0.0,0.0,0.0,1.0);
}
vec3 upperLight(vec2 p,float dir) {
 vec2 q=clamp((p-uUpperOrigin)/uUpperLevel.x,vec2(.5),uUpperProbes-.5);
 vec3 sum=vec3(0.0);
 for(int k=0;k<4;k++) {
  float u=dir*4.0+float(k);
  vec2 tile=vec2(mod(u,uUpperLevel.y),floor(u/uUpperLevel.y))*uUpperProbes;
  sum+=texture2D(uUpper,(tile+q)/uUpperTexSize).rgb;
 }
 return sum*.25;
}
void main() {
 vec2 tex=floor(gl_FragCoord.xy),probe=mod(tex,uProbes),tile=floor(tex/uProbes);
 float dir=tile.x+tile.y*uLevel.y;
 float angle=(dir+.5)/(uLevel.y*uLevel.y)*TAU;
 vec2 d=vec2(cos(angle),sin(angle));
 vec2 p=uOrigin+(probe+.5)*uLevel.x;
 // A probe inside a rock has no business gathering light: rock tops would pick up the glow of their own edges.
 vec4 here=texture2D(uSdf,(p-uSdfFrame.xy)*uSdfFrame.zw);
 if(here.r<uCell.y&&here.g>=${glsl(RAY_HEIGHT_PX)}&&!(here.a>.25&&here.a<=.75)){gl_FragColor=vec4(0.0,0.0,0.0,1.0);return;}
 vec4 r=march(p+d*uLevel.z,d,uLevel.w-uLevel.z,uLevel.z);
 vec3 c=r.rgb;
 if(uUpperLevel.z>.5&&r.a>.5)c+=upperLight(p,dir);
 gl_FragColor=vec4(c,1.0);
}`;

export const FLUENCE_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uCascade;
uniform vec2 uProbes,uTexSize;
void main() {
 vec3 sum=vec3(0.0);
 for(int y=0;y<2;y++)for(int x=0;x<2;x++)sum+=texture2D(uCascade,(vec2(float(x),float(y))*uProbes+gl_FragCoord.xy)/uTexSize).rgb;
 gl_FragColor=vec4(sum*.25,1.0);
}`;

export const INDIRECT_ADD_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
varying vec2 outTexCoord;
uniform sampler2D uFluence,uSdf;
// World rectangle of the light map, world origin and 1 / size of the fluence field, the same for the distance field.
uniform vec4 uMapWorld,uFluenceFrame,uSdfFrame;
void main() {
 vec2 world=uMapWorld.xy+vec2(outTexCoord.x,1.0-outTexCoord.y)*uMapWorld.zw;
 vec3 bounce=texture2D(uFluence,(world-uFluenceFrame.xy)*uFluenceFrame.zw).rgb;
 // Bounce lights the ground in front of a wall, not its top: the field's coarse probes would smear it across the edge in steps.
 vec4 s=texture2D(uSdf,(world-uSdfFrame.xy)*uSdfFrame.zw);
 if(s.g>=${glsl(RAY_HEIGHT_PX)}&&!(s.a>.25&&s.a<=.75))bounce*=smoothstep(0.0,${glsl(EDGE_FADE_PX)},s.r);
 gl_FragColor=vec4(bounce,0.0);
}`;

interface Level {
  readonly spacing: number; readonly tiles: number; readonly probesX: number; readonly probesY: number; readonly start: number; readonly end: number;
  readonly target: SunRenderTarget; originX: number; originY: number;
}

/** Soft coloured bounce from lit surfaces, gathered with radiance cascades over the distance field. Ultra only. */
export class IndirectLightField {
  private readonly view = createVisibleWorldView();
  private levels: Level[] = [];
  private fluence: SunRenderTarget | null = null;
  /** After a rebuild the bounce of the last frame, still in the light map, is only known to the old field. */
  private retiredFluence: SunRenderTarget | null = null;
  private addQuad: Phaser.GameObjects.Shader | null = null;
  private viewKey = '';
  private current = 0;
  private distance: DistanceFieldView | null = null;
  private binding: LightMapBinding | null = null;
  /** The cascades of this frame are queued; they run before the light map that reads them. */
  private ready = false;
  private readonly fluenceFrame = new Float32Array(4);
  /** Where the field that went into the current light map lay. */
  private readonly previousFluenceFrame = new Float32Array(4);
  private readonly mapWorld = new Float32Array(4);
  private readonly run = (): void => { this.renderCascades(); };

  constructor(private readonly scene: Phaser.Scene) {}

  /** Queues the cascades. The bounce reads the previous frame's light map: it is the only finished one. */
  prepare(distance: DistanceFieldView | null, binding: LightMapBinding | null, schedule: (work: () => void) => void): void {
    this.ready = false;
    this.distance = distance; this.binding = binding;
    if (!distance || !binding) return;
    const view = getVisibleWorldView(this.scene.cameras.main, this.view, 0);
    if (!this.ensureLevels(view.width, view.height)) return;
    const x = view.x - MARGIN_PX, y = view.y - MARGIN_PX;
    for (const level of this.levels) {
      // A probe keeps its world position while it is in view; anything else shimmers under a moving camera.
      level.originX = Math.floor(x / level.spacing) * level.spacing - level.spacing;
      level.originY = Math.floor(y / level.spacing) * level.spacing - level.spacing;
    }
    const c0 = this.levels[0];
    this.previousFluenceFrame.set(this.fluenceFrame);
    this.fluenceFrame[0] = c0.originX; this.fluenceFrame[1] = c0.originY;
    this.fluenceFrame[2] = 1 / (c0.probesX * c0.spacing); this.fluenceFrame[3] = 1 / (c0.probesY * c0.spacing);
    schedule(this.run);
    this.ready = true;
  }

  /** Adds the bounce to the light map; call after the direct lights. */
  draw(target: Phaser.GameObjects.RenderTexture, frame: Float32Array): void {
    if (!this.ready || !this.fluence) return;
    const quad = this.addQuad ??= this.createAddQuad();
    quad.setTextures([this.fluence.shader.texture!, this.distance!.texture]);
    this.mapWorld.set(frame);
    quad.setSize(target.width, target.height);
    target.draw(quad);
  }

  destroy(): void {
    this.destroyLevels();
    this.addQuad?.destroy(); this.addQuad = null;
    this.retiredFluence?.destroy(); this.retiredFluence = null;
  }

  private renderCascades(): void {
    const distance = this.distance, binding = this.binding;
    if (!distance || !binding || !this.fluence) return;
    const previous = (this.retiredFluence ?? this.fluence).shader.texture!, layer = binding.ambientLayer ?? binding.texture;
    let upper: Level | null = null;
    for (let i = this.levels.length - 1; i >= 0; i--) {
      const level = this.levels[i];
      this.current = i;
      level.target.shader.setTextures([distance.texture, binding.texture, upper ? upper.target.shader.texture! : binding.texture, previous, layer]);
      level.target.draw(level.probesX * level.tiles, level.probesY * level.tiles);
      upper = level;
    }
    this.fluence.shader.setTextures([this.levels[0].target.shader.texture!]);
    this.fluence.draw(this.levels[0].probesX, this.levels[0].probesY);
    this.retiredFluence?.destroy(); this.retiredFluence = null;
  }

  private ensureLevels(viewWidth: number, viewHeight: number): boolean {
    const sizedWidth = Math.ceil(viewWidth / VIEW_SIZE_STEP_PX) * VIEW_SIZE_STEP_PX, sizedHeight = Math.ceil(viewHeight / VIEW_SIZE_STEP_PX) * VIEW_SIZE_STEP_PX;
    const key = `${sizedWidth}x${sizedHeight}`;
    if (key === this.viewKey) return this.levels.length > 0;
    this.retiredFluence?.destroy();
    this.retiredFluence = this.fluence; this.fluence = null;
    this.destroyLevels();
    this.viewKey = key;
    const width = sizedWidth + MARGIN_PX * 2, height = sizedHeight + MARGIN_PX * 2, firstInterval = BASE_SPACING_PX * INTERVAL_FACTOR;
    const levels: Level[] = [];
    for (let i = 0; i < CASCADES; i++) {
      const spacing = BASE_SPACING_PX * 2 ** i, tiles = 2 ** (i + 1);
      const probesX = Math.ceil(width / spacing) + 2, probesY = Math.ceil(height / spacing) + 2;
      const index = i;
      const target = new SunRenderTarget(this.scene, 'IndirectCascade', CASCADE_FRAGMENT, set => this.setCascadeUniforms(set, index),
        ['__WHITE', '__WHITE', '__WHITE', '__WHITE', '__WHITE'], CASCADE_SHADER);
      target.draw(probesX * tiles, probesY * tiles);
      if (!enableHdrShaderTarget(this.scene, target)) { target.destroy(); for (const level of levels) level.target.destroy(); return false; }
      levels.push({ spacing, tiles, probesX, probesY, target, originX: 0, originY: 0,
        start: firstInterval * (4 ** i - 1) / 3, end: firstInterval * (4 ** (i + 1) - 1) / 3 });
    }
    const c0 = levels[0], atlas = [c0.probesX * c0.tiles, c0.probesY * c0.tiles], probes = [c0.probesX, c0.probesY];
    const fluence = new SunRenderTarget(this.scene, 'IndirectFluence', FLUENCE_FRAGMENT, set => { set('uCascade', 0); set('uProbes', probes); set('uTexSize', atlas); }, ['__WHITE'], FLUENCE_SHADER);
    fluence.draw(c0.probesX, c0.probesY);
    if (!enableHdrShaderTarget(this.scene, fluence)) { fluence.destroy(); for (const level of levels) level.target.destroy(); return false; }
    this.levels = levels; this.fluence = fluence;
    return true;
  }

  private setCascadeUniforms(set: (name: string, value: unknown) => void, index: number): void {
    const distance = this.distance, binding = this.binding, level = this.levels[index];
    if (!distance || !binding || !level) return;
    const upper = this.levels[index + 1];
    set('uBounceGain', getIndirectLightGain());
    set('uSdf', 0); set('uLightMap', 1); set('uUpper', 2); set('uFluencePrevious', 3); set('uAmbientLayer', 4); set('uAmbientLayerOn', binding.ambientLayer ? 1 : 0);
    set('uFluenceFrame', this.previousFluenceFrame);
    set('uSdfFrame', distance.frame); set('uLightFrame', binding.frame); set('uAmbient', binding.ambient);
    set('uCell', [distance.cellPx, distance.cellPx * 0.5]);
    set('uOrigin', [level.originX, level.originY]); set('uProbes', [level.probesX, level.probesY]);
    set('uLevel', [level.spacing, level.tiles, level.start, level.end]);
    if (upper) {
      set('uUpperOrigin', [upper.originX, upper.originY]); set('uUpperProbes', [upper.probesX, upper.probesY]);
      set('uUpperTexSize', [upper.probesX * upper.tiles, upper.probesY * upper.tiles]);
      set('uUpperLevel', [upper.spacing, upper.tiles, 1]);
    } else set('uUpperLevel', [1, 1, 0]);
  }

  private createAddQuad(): Phaser.GameObjects.Shader {
    const quad = new Phaser.GameObjects.Shader(this.scene, {
      name: INDIRECT_ADD_SHADER, shaderName: INDIRECT_ADD_SHADER, fragmentSource: INDIRECT_ADD_FRAGMENT,
      setupUniforms: (set: (name: string, value: unknown) => void) => {
        set('uFluence', 0); set('uSdf', 1); set('uMapWorld', this.mapWorld); set('uFluenceFrame', this.fluenceFrame);
        if (this.distance) set('uSdfFrame', this.distance.frame);
      },
    }, 0, 0, 2, 2, [this.fluence!.shader.texture!, this.fluence!.shader.texture!]);
    ownSunShader(quad, INDIRECT_ADD_SHADER, true);
    quad.setOrigin(0);
    const blend = lightAddBlendMode(this.scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer), node = quad.renderNode, run = node.run;
    node.run = function (context, object, parent): void { runWithScopedBlend(this, run, context, blend, object, parent); };
    return quad;
  }

  private destroyLevels(): void {
    for (const level of this.levels) level.target.destroy();
    this.levels = [];
    this.fluence?.destroy(); this.fluence = null;
    this.addQuad?.destroy(); this.addQuad = null;
    this.viewKey = ''; this.ready = false;
  }
}
