import type { RoomNotice } from '../network/RoomHandover';
import type { LobbyAlert } from '../ui/LobbyAlertBanner';
import { t } from './index';
import { describePeerFailure } from './networkFailurePresentation';

/**
 * Banner nach einem Raumwechsel: was passiert ist und wo der Spieler jetzt ist. Kein Hinweis auf
 * Neuladen – das Spiel hat bereits selbst gehandelt.
 */
export function describeRoomNotice(notice: RoomNotice): LobbyAlert {
  const host = notice.previousHostName ?? t('ui.lobby.notice.formerHost');
  const reason = notice.failure ? `${describePeerFailure(notice.failure)} ` : '';
  switch (notice.kind) {
    case 'handover':
      return {
        severity: 'info',
        title: t('ui.lobby.notice.handoverTitle'),
        message: notice.successorName
          ? t('ui.lobby.notice.handoverToOther', { host, successor: notice.successorName })
          : t('ui.lobby.notice.handoverToYou', { host }),
      };
    case 'handover-failed':
      return { severity: 'warning', title: t('ui.lobby.notice.handoverTitle'), message: t('ui.lobby.notice.handoverFailed', { host }) };
    case 'join-failed':
      return { severity: 'warning', title: t('ui.lobby.notice.joinFailedTitle'), message: `${reason}${t('ui.lobby.notice.ownRoom')}` };
    case 'kicked':
      return {
        severity: 'warning',
        title: t('ui.lobby.notice.kickedTitle'),
        message: `${t('ui.lobby.kickedFromRoom')} ${t('ui.lobby.notice.ownRoom')}`,
      };
    case 'room-lost':
      return { severity: 'warning', title: t('ui.lobby.notice.roomLostTitle'), message: `${reason}${t('ui.lobby.notice.ownRoom')}` };
  }
}
