import * as Phaser from 'phaser';
import { GAME_HEIGHT, GAME_WIDTH } from '../config';
import { getRenderScale } from '../graphics/RenderResolution';
import { getLocale, t } from '../i18n';
import { getMapName } from '../i18n/contentPresentation';
import type { AfterRoundView } from '../ui/AfterRoundTransition';
import { getOverlayRoot } from '../ui/fullscreen';
import type { LazyOverlayPresentation, LazyOverlayStatus } from '../ui/LazyOverlayGate';
import { addPersistentBaseEditorAction, addPersistentBaseEditorFrame, addPersistentBaseEditorLabel, addPersistentBaseEditorMinimapPanel,
  addPersistentBaseEditorWorldFrame, PERSISTENT_BASE_EDITOR_HEADER_Y, PERSISTENT_BASE_EDITOR_INVENTORY,
  PERSISTENT_BASE_EDITOR_MINIMAP_PANEL, PERSISTENT_BASE_EDITOR_WORLD_PANEL } from '../ui/PersistentBaseEditorFrame';
import { UPGRADE_MENU } from '../ui/UpgradeMenuLayout';

export interface PersistentBaseEditorShellOptions {
  /** The next round's map, for the situation map's title; `null` without one. */
  readonly mapId: string | null;
  /** The shell was the source of an after-round step and is covered now (see `AfterRoundView.retire`). */
  readonly retire: () => void;
}

/** Where a window's spinner turns, in UI px, and how large it is. */
interface Spinner { readonly element: HTMLDivElement; readonly animation: Animation; readonly x: number; readonly y: number; readonly size: number }

const WORLD = PERSISTENT_BASE_EDITOR_WORLD_PANEL;
const MINIMAP = PERSISTENT_BASE_EDITOR_MINIMAP_PANEL;
const INVENTORY = PERSISTENT_BASE_EDITOR_INVENTORY;
const BAR = { width: 260, height: 4 } as const;

/**
 * The Bauhof while its stage prepares: the editor's frame at once, its World view, situation map
 * and inventory still loading. Once the stage is ready it opens beneath at full alpha and the shell
 * fades away over it. Frame and backdrop lie exactly over the stage's, so only the windows fade in;
 * the dim around the menu would add up and goes at once.
 *
 * The spinners are DOM elements: a compositor animation keeps turning while the stage's build
 * blocks the main thread.
 */
export class PersistentBaseEditorShellScene extends Phaser.Scene implements LazyOverlayPresentation {
  /** Fade-in of the shell, as long as the editor's own on a ready stage. */
  static readonly SHOW_MS = 150;
  /** Fade of the loading windows once the stage shows beneath. */
  static readonly REVEAL_MS = 360;
  private static instances = 0;
  private cancel: () => void = () => {};
  private alpha = 0;
  private fade: Phaser.Tweens.Tween | null = null;
  /** A fade-in asked for before `create`; `0` shows at once. */
  private pendingShow: number | null = null;
  private status: LazyOverlayStatus | null = null;
  private failure: string | null = null;
  private inputBlocked = false;
  /** Revealing or dismissing: no input, and the shell goes when the fade ends. */
  private ending = false;
  private shownWaiters: (() => void)[] = [];
  private dim: Phaser.GameObjects.GameObject[] = [];
  private statusLabel: Phaser.GameObjects.Text | null = null;
  private bar: Phaser.GameObjects.Graphics | null = null;
  private shownProgress: number | null = null;
  private spinners: Spinner[] = [];

  /** Every shell has its own key: one may still fade away while the next opens. */
  readonly sceneKey: string;

  constructor(private readonly options: PersistentBaseEditorShellOptions) {
    const key = `PersistentBaseEditorShell-${++PersistentBaseEditorShellScene.instances}`;
    super(key);
    this.sceneKey = key;
  }

  create(): void {
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => this.dispose());
    this.resize();
    this.scale.on(Phaser.Scale.Events.RESIZE, this.resize, this);
    if (this.input.keyboard) this.input.keyboard.enabled = false;
    const root = this.add.container(0, 0);
    this.dim = addPersistentBaseEditorFrame(this, root, WORLD).dim;
    const centerX = WORLD.x + WORLD.width / 2, centerY = WORLD.y + WORLD.height / 2;
    addPersistentBaseEditorWorldFrame(this, root, WORLD, [this.add.rectangle(WORLD.x, WORLD.y, WORLD.width, WORLD.height, 0x0b120d).setOrigin(0)]);
    this.statusLabel = addPersistentBaseEditorLabel(this, centerX, centerY + 50, '', 'body', .5, WORLD.width - 120, root).setColor('#d9cfa8');
    this.bar = this.add.graphics(); root.add(this.bar);
    addPersistentBaseEditorMinimapPanel(this, root);
    const title = this.options.mapId ? `${t('ui.base.situationMap')} · ${getMapName(this.options.mapId, getLocale())}` : t('ui.base.situationMap');
    addPersistentBaseEditorLabel(this, MINIMAP.x + 4, PERSISTENT_BASE_EDITOR_HEADER_Y, title.toLocaleUpperCase(), 'section', 0, undefined, root);
    addPersistentBaseEditorLabel(this, INVENTORY.x + 4, INVENTORY.y - 22, t('ui.base.inventory').toLocaleUpperCase(), 'section', 0, undefined, root);
    root.add(this.add.graphics().fillStyle(0x101b14, .45).fillRoundedRect(INVENTORY.x, INVENTORY.y, INVENTORY.width, INVENTORY.height, 12)
      .lineStyle(1, 0x718160, .3).strokeRoundedRect(INVENTORY.x, INVENTORY.y, INVENTORY.width, INVENTORY.height, 12));
    addPersistentBaseEditorAction(this, root, 'cancel', () => this.cancel(), () => !this.ending);
    // Apply waits for the editor; it shows where it will be, without a press.
    const apply = addPersistentBaseEditorAction(this, root, 'apply', () => {}, () => false);
    apply.image.disableInteractive().setAlpha(.4); apply.label.setAlpha(.4);
    this.spinners = [this.spinner(centerX, centerY - 6, 46), this.spinner(MINIMAP.x + MINIMAP.width / 2, MINIMAP.y + MINIMAP.height / 2, 34),
      this.spinner(INVENTORY.x + INVENTORY.width / 2, INVENTORY.y + INVENTORY.height / 2, 34)];
    this.placeSpinners();
    this.syncStatus();
    this.applyAlpha();
    if (this.pendingShow !== null) { const duration = this.pendingShow; this.pendingShow = null; this.show(duration === 0); }
  }

  setCancel(cancel: () => void): void { this.cancel = cancel; }

  /** Fades the shell in by itself, outside an after-round transition; `instant` where an editor showed until now. */
  show(instant = false): void {
    if (this.ending) return;
    if (!this.statusLabel) { this.pendingShow = instant ? 0 : PersistentBaseEditorShellScene.SHOW_MS; return; }
    if (instant) { this.setShownAlpha(1); return; }
    this.fadeTo(1, PersistentBaseEditorShellScene.SHOW_MS, 'Sine.easeOut');
  }

  /** The shell's alpha, for an after-round transition from the previous menu. */
  getTransitionView(): AfterRoundView {
    return { depth: 0, setDepth: () => {},
      setAlpha: (alpha) => { if (!this.ending) this.setShownAlpha(alpha); },
      retire: () => this.options.retire() };
  }

  /** The shell shows fully; until then no frame may block. */
  isShown(): boolean { return this.alpha >= 1; }

  /** Settles once the shell shows fully (or goes): the stage's blocking work waits for it. */
  whenShown(): Promise<void> {
    if (this.alpha >= 1 || this.ending) return Promise.resolve();
    return new Promise((resolve) => { this.shownWaiters.push(resolve); });
  }

  setStatus(status: LazyOverlayStatus | null): void {
    this.status = status;
    this.syncStatus();
  }

  fail(label: string): void {
    this.failure = label;
    this.syncStatus();
  }

  /** An after-round transition blocks input while it fades between menus. */
  setInputBlocked(blocked: boolean): void {
    this.inputBlocked = blocked;
    this.syncInput();
  }

  /** The stage shows beneath at full alpha: the dim goes at once, the rest fades away. */
  reveal(done: () => void): void {
    this.end(PersistentBaseEditorShellScene.REVEAL_MS, 'Sine.easeInOut', done);
    for (const dim of this.dim) (dim as Phaser.GameObjects.Rectangle).setVisible(false);
  }

  /** The opening ends without an editor. */
  dismiss(done: () => void): void {
    this.end(PersistentBaseEditorShellScene.SHOW_MS, 'Sine.easeIn', done);
  }

  private end(duration: number, ease: string, done: () => void): void {
    if (this.ending) return;
    this.ending = true;
    this.syncInput();
    this.resolveShown();
    if (!this.statusLabel || this.alpha <= 0) { done(); return; }
    this.fadeTo(0, duration * this.alpha, ease, done);
  }

  private fadeTo(to: number, duration: number, ease: string, done?: () => void): void {
    this.fade?.remove();
    const state = { alpha: this.alpha };
    this.fade = this.tweens.add({ targets: state, alpha: to, duration, ease,
      onUpdate: () => this.setShownAlpha(state.alpha),
      onComplete: () => { this.fade = null; this.setShownAlpha(to); done?.(); } });
  }

  private setShownAlpha(alpha: number): void {
    this.alpha = alpha;
    this.applyAlpha();
    if (alpha >= 1) this.resolveShown();
    this.syncInput();
  }

  private applyAlpha(): void {
    if (!this.statusLabel) return;
    this.cameras.main.setAlpha(this.alpha);
    for (const spinner of this.spinners) spinner.element.style.opacity = String(this.alpha);
  }

  private resolveShown(): void {
    for (const resolve of this.shownWaiters.splice(0)) resolve();
  }

  private syncInput(): void {
    if (!this.statusLabel) return;
    this.input.enabled = !this.ending && !this.inputBlocked && this.alpha >= 1;
  }

  /** What is being done now and the share of counted work, below the World view's spinner. */
  private syncStatus(): void {
    const label = this.statusLabel, bar = this.bar;
    if (!label || !bar) return;
    const text = this.failure ?? this.status?.label ?? t('ui.base.loading');
    if (label.text !== text) label.setText(text);
    for (const spinner of this.spinners) spinner.element.style.visibility = this.failure ? 'hidden' : 'visible';
    const progress = this.failure || this.status?.progress === undefined ? null
      : Math.round(Math.max(0, Math.min(1, this.status.progress)) * 100) / 100;
    if (progress === this.shownProgress) return;
    this.shownProgress = progress;
    bar.clear();
    if (progress === null) return;
    const x = WORLD.x + (WORLD.width - BAR.width) / 2, y = label.y + 34;
    bar.fillStyle(0xefe4bd, .16).fillRoundedRect(x, y, BAR.width, BAR.height, 2);
    if (progress > 0) bar.fillStyle(0xd6e9a2, .9).fillRoundedRect(x, y, Math.max(BAR.height, BAR.width * progress), BAR.height, 2);
  }

  private spinner(x: number, y: number, size: number): Spinner {
    const element = document.createElement('div');
    element.setAttribute('aria-hidden', 'true');
    element.style.cssText = 'position:fixed;z-index:1000;pointer-events:none;box-sizing:border-box;border-radius:50%;'
      + 'border-style:solid;border-color:#efe4bd30;border-top-color:#efe4bdd0;opacity:0';
    getOverlayRoot().appendChild(element);
    const animation = element.animate([{ transform: 'rotate(0deg)' }, { transform: 'rotate(360deg)' }],
      { duration: 1100, iterations: Infinity });
    return { element, animation, x, y, size };
  }

  private placeSpinners(): void {
    const bounds = this.game.canvas.getBoundingClientRect();
    const sx = bounds.width / GAME_WIDTH, sy = bounds.height / GAME_HEIGHT;
    for (const { element, x, y, size } of this.spinners) {
      element.style.left = `${bounds.left + (x - size / 2) * sx}px`;
      element.style.top = `${bounds.top + (y - size / 2) * sy}px`;
      element.style.width = `${size * sx}px`;
      element.style.height = `${size * sy}px`;
      element.style.borderWidth = `${Math.max(2, 3 * sx)}px`;
    }
  }

  private resize(): void {
    this.cameras.main.setViewport(0, 0, this.scale.width, this.scale.height).setOrigin(0, 0).setZoom(getRenderScale(this.scale));
    this.placeSpinners();
  }

  private dispose(): void {
    this.ending = true;
    this.fade?.remove(); this.fade = null;
    this.scale.off(Phaser.Scale.Events.RESIZE, this.resize, this);
    for (const { element, animation } of this.spinners.splice(0)) { animation.cancel(); element.remove(); }
    this.resolveShown();
  }
}
