import type { GraphicsPreset } from '../../graphics/GraphicsQuality';
import type { LightPresetKey } from '../LightingConfig';

/** How much a light keeps of its strength in full daylight, by what kind of source it is. */
export type LightDayClass = 'blast' | 'fire' | 'projectile' | 'lamp' | 'glow';

export const LIGHT_DAY_FLOOR: Readonly<Record<LightDayClass, number>> = {
  blast: 0.55, fire: 0.5, projectile: 0.35, lamp: 0.2, glow: 0.15,
};

const DAY_CLASSES: Readonly<Partial<Record<LightPresetKey, LightDayClass>>> = {
  explosion: 'blast', muzzleFlash: 'blast', beamPulse: 'blast', electricArc: 'blast', teleportFlash: 'blast',
  fireChunkImpact: 'blast', voidFireChunkImpact: 'blast',
  groundFire: 'fire', voidGroundFire: 'fire', flameRing: 'fire', fireChunk: 'fire', voidFireChunk: 'fire',
  projectileBurn: 'fire', flameProjectile: 'fire', voidFlameProjectile: 'fire', entityBurn: 'fire',
  energyProjectile: 'projectile', bfgOrb: 'projectile', rocketThruster: 'projectile', holyProjectile: 'projectile',
  sporeProjectile: 'projectile', sporeVoidProjectile: 'projectile',
  flashlight: 'lamp', flashlightSpill: 'lamp', trainHeadlight: 'lamp', trainWindow: 'lamp',
};

const FAST_LIGHTS: ReadonlySet<LightPresetKey> = new Set<LightPresetKey>([
  'energyProjectile', 'holyProjectile', 'sporeProjectile', 'sporeVoidProjectile', 'flameProjectile', 'voidFlameProjectile', 'muzzleFlash',
]);

/** Lights that pass a spot within a few frames: they and their shadows add up over time, or they would strobe with every shot. */
export function isFastLight(preset: LightPresetKey): boolean {
  return FAST_LIGHTS.has(preset);
}

/** Night keeps full strength (`lightFactor` 1); by day each class falls no lower than its floor. */
export function lightDayFactor(preset: LightPresetKey, lightFactor: number): number {
  return Math.max(lightFactor, LIGHT_DAY_FLOOR[DAY_CLASSES[preset] ?? 'glow']);
}

/** Saturation below which a light counts as white and keeps its colour, and from which it is made fully vivid. */
const VIVID_FROM_SATURATION = 0.08;
const VIVID_FULL_SATURATION = 0.25;
/** How far a coloured light's saturation moves towards full: 1 leaves it, larger values deepen it. */
const VIVID_DEPTH = 2.2;
/** Share of the white a projectile's light is mixed with that it keeps: the float map lifts with colour, it needs no white for that. */
export const VIVID_PROJECTILE_WHITE = 0.3;
/**
 * Essence on the ground: authored as a faint pool right under each drop. With colour to carry it, it lights the ground around
 * in its own turquoise, further out and stronger.
 */
export const VIVID_ESSENCE_COLOR = 0x25d6e2;
export const VIVID_ESSENCE_REACH = 2.3;
export const VIVID_ESSENCE_STRENGTH = 1.5;
const vividCache = new Map<number, number>();

/**
 * A light's colour with the grey taken out of it. The old 8-bit map could only brighten with pale light, so every coloured
 * source was authored close to white; summed up, such lights turn a scene white. Lamps and anything already near white stay
 * as they are, the brightest channel is kept, so no light gets darker in its own colour.
 */
export function vividLightColor(preset: LightPresetKey, color: number): number {
  if (DAY_CLASSES[preset] === 'lamp') return color;
  const cached = vividCache.get(color);
  if (cached !== undefined) return cached;
  const r = (color >> 16) & 0xff, g = (color >> 8) & 0xff, b = color & 0xff;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let vivid = color;
  if (max > 0 && max > min) {
    const saturation = (max - min) / max;
    const t = Math.min(1, Math.max(0, (saturation - VIVID_FROM_SATURATION) / (VIVID_FULL_SATURATION - VIVID_FROM_SATURATION)));
    const share = t * t * (3 - 2 * t);
    const deepened = saturation + share * (1 - Math.pow(1 - saturation, VIVID_DEPTH) - saturation);
    const stretch = deepened / saturation;
    const channel = (value: number): number => Math.max(0, Math.round(max - (max - value) * stretch));
    vivid = (channel(r) << 16) | (channel(g) << 8) | channel(b);
  }
  if (vividCache.size > 512) vividCache.clear();
  vividCache.set(color, vivid);
  return vivid;
}

const OWN_GLOW_YIELD = 2.2;
const OWN_GLOW_FLOOR = 0.15;
/** From this much light on the glow stays at its floor, however much more arrives. */
export const OWN_GLOW_SETTLED_LIGHT = (1 - OWN_GLOW_FLOOR) / OWN_GLOW_YIELD;

/**
 * A figure's own glow lifts it out of the dark and has no shadow of its own. Where light from elsewhere
 * reaches the figure the glow gives way, or it would fill the figure's shadow as a round pool at its feet.
 */
export function ownGlowFactor(outsideLight: number): number {
  return Math.max(OWN_GLOW_FLOOR, 1 - outsideLight * OWN_GLOW_YIELD);
}

/** Ultra renders the new light map finer than High; the old light stays as it was. */
export const ULTRA_LIGHT_MAP_SCALE = 1;

export function lightMapScaleV2(preset: GraphicsPreset, scale: number): number {
  return preset === 'ultra' ? ULTRA_LIGHT_MAP_SCALE : scale;
}

/** How far the composite may lift a pixel beyond its unlit colour, on top of the factor 1 of the map. */
export const LIGHT_HDR_HEADROOM = 0.6;

/**
 * CPU twin of the composite's shoulder, as a scale on the light colour. Up to 1 the map passes
 * unchanged, so an unlit night matches the old multiply. Above 1 the peak bends towards
 * 1 + headroom, and one shared scale keeps the hue.
 */
export function lightHdrScale(peak: number): number {
  return peak <= 1 ? 1 : (1 + (1 - Math.exp(1 - peak)) * LIGHT_HDR_HEADROOM) / peak;
}
