/**
 * Hält die Spielschleife im Takt, solange das Desktop-Fenster minimiert ist.
 *
 * Electron liefert einem minimierten Fenster unter Windows trotz `backgroundThrottling: false` nur
 * noch etwa ein Animation-Frame pro Sekunde, während Timer ungebremst laufen und die Seite als
 * sichtbar gilt (Messung in `docs/reports/desktop-shell-s1-2026-11-03.md`). Phasers Schleife hängt
 * aber an `requestAnimationFrame`, und der Host simuliert für alle. Deshalb läuft sie in dieser
 * Zeit über `setTimeout` im normalen Zieltakt und kehrt danach zu rAF zurück.
 */
import * as Phaser from 'phaser';
import type { PlatformShell } from '../platform';

export function installMinimizedGameLoop(game: Phaser.Game, shell: PlatformShell): void {
  const apply = (minimized: boolean): void => {
    const loop = game.loop;
    if (loop.forceSetTimeOut === minimized) return;
    // Phaser wählt rAF oder setTimeout beim (Neu-)Start der Schleife; die Typen führen den Schalter
    // deshalb als readonly. `sleep`/`wake` startet die Schleife mit dem neuen Wert neu.
    const wasRunning = loop.running;
    loop.sleep();
    (loop as { forceSetTimeOut: boolean }).forceSetTimeOut = minimized;
    if (wasRunning) loop.wake(true);
  };
  apply(shell.isMinimized());
  const unsubscribe = shell.onMinimizedChange(apply);
  game.events.once(Phaser.Core.Events.DESTROY, unsubscribe);
}
