import type * as Phaser from 'phaser';
import { ensureCanvasTexture } from '../EffectUtils';

export const TEX_DEMON_HEAT_MOTE = '__demon_heat_mote';
export const DEMON_HEAT_MOTE_SIZE = 32;

/** Falloff of the mote: exp(-FALLOFF · r²) over the unit radius, about a third of the peak at half radius. */
const FALLOFF = 4.5;

/**
 * A soft white glow mote with a gaussian falloff that reaches zero at the frame edge. Unlike a small
 * spark point it has no visible rim at any scale, so a few px ember reads as a glowing dot, not a pixel.
 */
export function ensureDemonHeatMoteTexture(scene: Phaser.Scene): void {
  const size = DEMON_HEAT_MOTE_SIZE, half = size / 2, floor = Math.exp(-FALLOFF);
  ensureCanvasTexture(scene.textures, TEX_DEMON_HEAT_MOTE, size, size, (ctx) => {
    const image = ctx.createImageData(size, size);
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const r = Math.hypot(x + 0.5 - half, y + 0.5 - half) / half;
        const alpha = r >= 1 ? 0 : (Math.exp(-FALLOFF * r * r) - floor) / (1 - floor);
        const i = (y * size + x) * 4;
        image.data[i] = 255; image.data[i + 1] = 255; image.data[i + 2] = 255;
        image.data[i + 3] = Math.round(255 * alpha);
      }
    }
    ctx.putImageData(image, 0, 0);
  });
}
