/** Linear minification at this integer scale samples only the two central native
 * texels on each axis. Keep those exact values, not an average or coarser field.
 * Native tile/batch origins must be multiples of this scale relative to the World. */
export const TERRAIN_SNAPSHOT_SAMPLE_SCALE = 4;
export function terrainSnapshotTexel(index: number): boolean {
  const phase = index & 3;
  return phase === 1 || phase === 2;
}

/**
 * Only the sample texels of a snapshot material tile (`terrainSnapshotTexel` on both axes), a quarter
 * of its bytes: a lobby keeps prepared tiles this way (Steam plan L14). `side` is a multiple of 4.
 */
export function compactSnapshotSamples(full: Uint8Array | Uint8ClampedArray, side: number): Uint8Array {
  const half = side / 2, compact = new Uint8Array(half * half * 4);
  let offset = 0;
  for (let y = 0; y < side; y++) {
    if (!terrainSnapshotTexel(y)) continue;
    const row = y * side * 4;
    for (let x = 1; x < side; x += 4) {
      // Texels x and x + 1 are the two samples of this group of four.
      compact.set(full.subarray(row + x * 4, row + x * 4 + 8), offset);
      offset += 8;
    }
  }
  return compact;
}

/** Restores the full tile of `compactSnapshotSamples`; every other texel is zero, as the worker leaves it. */
export function expandSnapshotSamples(compact: Uint8Array, side: number, target: Uint8ClampedArray): void {
  target.fill(0);
  let offset = 0;
  for (let y = 0; y < side; y++) {
    if (!terrainSnapshotTexel(y)) continue;
    const row = y * side * 4;
    for (let x = 1; x < side; x += 4) {
      target.set(compact.subarray(offset, offset + 8), row + x * 4);
      offset += 8;
    }
  }
}
