import * as Phaser from 'phaser';
import { ENEMY_MESH_MANIFEST } from '../../assets/EnemyMeshAssets';
import turretNormals from '../../assets/manifests/turret-normals.json';
import { runtimeAssetUrl } from '../../assets/RuntimeAssetUrls';
import { DEPTH_LIGHTING } from '../../config';
import { getPipelineAssetForTexture, type PipelineAsset } from '../../config/pipelineAssets';
import { createVisibleWorldView, getVisibleWorldView } from '../../graphics/CameraWorldView';
import { modulate2xBlendMode } from '../../graphics/CustomBlendModes';
import { getGraphicsQualityProfile } from '../../graphics/GraphicsQuality';
import { runWithScopedBlend } from '../../graphics/PhaserScopedBlend';
import { EnemyMeshGpu } from '../EnemyMeshGpu';
import type { MeshShadowCaster } from '../EnemyMeshShadowRenderer';
import { RELIEF_LIGHTS, type LightMapBinding } from './LightMapBinding';
import { ownSunShader, sunShaderName } from '../sunlight/SunRenderTarget';

const CAPACITY = 256;
const ATTRIBUTES = [{ name: 'inCentre', size: 4 }, { name: 'inFrame', size: 4 }, { name: 'inTurn', size: 4 }, { name: 'inSprite', size: 4 }];
const INSTANCE_WORDS = 16;
/** Sheets keep this many transparent texels around every frame. */
const SHEET_MARGIN = 2;
/** Height of the assumed light above the figure, against a unit horizontal direction. */
const LIGHT_LIFT = 0.8;
/** Brightening and darkening per unit a face is turned towards or away from the light, against a flat face. The dark side stays readable. */
const TOWARDS_LIGHT = 1.1;
const AWAY_FROM_LIGHT = 0.34;
/** How much the baked occlusion deepens creases where light falls. */
const OCCLUSION = 0.35;
/** Reach of the taps that merge the model's flat faces into a form, as a share of the frame. */
const NORMAL_SOFTEN = 0.012;
/** A lamp this close to the figure is its own and does not model it. */
const OWN_LIGHT_PX = 26;

const VERTEX = `
precision highp float;
attribute vec2 inPosition;
attribute vec4 inCentre,inFrame,inTurn,inSprite;
uniform mat4 uProjectionMatrix;
uniform mat3 uViewMatrix;
uniform sampler2D uLightMap;
uniform vec4 uLightFrame;
uniform vec3 uAmbient;
// x, y, radius, weight; direction x, y, cosine of the half angle (-2 without a cone), width of its soft edge.
uniform vec4 uLights[${RELIEF_LIGHTS}];
uniform vec4 uCones[${RELIEF_LIGHTS}];
varying vec2 uv,spriteUv,turn,toLight,soften;
varying float amount,mirror;
float lightAt(vec2 world) {
 vec2 at=(world-uLightFrame.xy)/uLightFrame.zw;
 vec3 above=max(texture2D(uLightMap,vec2(at.x,1.0-at.y)).rgb-uAmbient,vec3(0.0));
 return dot(above,vec3(.2126,.7152,.0722));
}
void main() {
 vec2 local=(inPosition-.5)*inCentre.zw;
 vec2 world=inCentre.xy+vec2(local.x*inTurn.x-local.y*inTurn.y,local.x*inTurn.y+local.y*inTurn.x);
 vec3 view=uViewMatrix*vec3(world,1);
 gl_Position=uProjectionMatrix*vec4(view.xy,0,1);
 uv=inFrame.xy+inPosition*inFrame.zw;
 soften=inFrame.zw*${NORMAL_SOFTEN.toFixed(3)};
 spriteUv=inSprite.xy+inPosition*inSprite.zw;
 turn=inTurn.xy;mirror=inTurn.w;
 vec2 sum=vec2(0.0);
 float total=0.0;
 for(int i=0;i<${RELIEF_LIGHTS};i++){
  vec2 to=uLights[i].xy-inCentre.xy;
  float d=length(to);
  if(d>=uLights[i].z||d<${OWN_LIGHT_PX.toFixed(1)})continue;
  float w=1.0-d/uLights[i].z;
  w*=w*uLights[i].w;
  vec2 dir=to/d;
  if(uCones[i].z>-1.5)w*=clamp((dot(-dir,uCones[i].xy)-uCones[i].z)/uCones[i].w,0.0,1.0);
  sum+=dir*w;total+=w;
 }
 float pull=length(sum);
 toLight=pull>.0001?sum/pull:vec2(0.0);
 // The light map says whether light really arrives here; the lights say from where. All around counts as even light.
 amount=inTurn.z*smoothstep(.02,.14,lightAt(inCentre.xy))*smoothstep(.15,.6,pull/max(total,.0001));
}`;

const FRAGMENT = `
precision highp float;
uniform sampler2D uNormal,uSprite;
varying vec2 uv,spriteUv,turn,toLight,soften;
varying float amount,mirror;
void main() {
 // The normal sheets are padded far beyond the figure; only what the sprite covers may change.
 float cover=texture2D(uSprite,spriteUv).a;
 vec4 data=texture2D(uNormal,uv);
 vec3 sum=data.rgb+texture2D(uNormal,uv+soften).rgb+texture2D(uNormal,uv-soften).rgb+texture2D(uNormal,uv+vec2(soften.x,-soften.y)).rgb+texture2D(uNormal,uv-vec2(soften.x,-soften.y)).rgb;
 vec3 n=normalize(sum/5.0*2.0-1.0);
 vec2 side=vec2((toLight.x*turn.x+toLight.y*turn.y)*mirror,-toLight.x*turn.y+toLight.y*turn.x);
 vec3 l=normalize(vec3(side,${LIGHT_LIFT.toFixed(2)}));
 float face=dot(n,l)-l.z;
 float factor=1.0+amount*(face*(face>0.0?${TOWARDS_LIGHT.toFixed(2)}:${AWAY_FROM_LIGHT.toFixed(2)})+(data.a-1.0)*${OCCLUSION.toFixed(2)});
 gl_FragColor=vec4(vec3(mix(1.0,factor,cover)*.5),.5);
}`;

interface NormalSheet { readonly file: string; readonly frames: number }
interface Group { sheet: NormalSheet; cellU: number; cellV: number; inU: number; inV: number; data: Float32Array; count: number; texture: Phaser.Textures.Texture | null; source: Phaser.Textures.TextureSource | null }

/** Normal sheet of a figure or turret, only for the sprite revision it was baked from. */
function normalSheetOf(id: string, revision: string, fine: boolean): NormalSheet | null {
  const enemy = ENEMY_MESH_MANIFEST.assets.find(entry => entry.id === id);
  const images = enemy && enemy.revision === revision ? enemy.images as Record<string, { file: string } | undefined> : undefined;
  const file = (fine ? images?.normal128?.file : undefined) ?? images?.normal64?.file;
  if (enemy && file) return { file, frames: enemy.mesh.poseIndices.length };
  const turret = (turretNormals.assets as Record<string, { sourceRevision: string; frames: number; file: string } | undefined>)[id];
  return turret && turret.sourceRevision === revision ? turret : null;
}

/** Shapes figures and turrets under the new light: their Blender normals against the frame's strongest lights, as far as the light map says light arrives. */
export class MeshSurfaceRelief {
  private readonly renderer: Phaser.Renderer.WebGL.WebGLRenderer;
  private readonly gpu: EnemyMeshGpu;
  private readonly display: Phaser.GameObjects.Shader;
  private readonly blend: number;
  private readonly groups = new Map<string, Group>();
  private readonly view = createVisibleWorldView();
  private binding: LightMapBinding | null = null;
  private syncedFrame = -1;
  private fine = false;
  /** A horde asks once per enemy and frame. */
  private readonly assetsByImage = new Map<string, PipelineAsset | null>();

  constructor(private readonly scene: Phaser.Scene) {
    const renderer = this.renderer = scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer;
    this.blend = modulate2xBlendMode(renderer);
    this.gpu = new EnemyMeshGpu(renderer, sunShaderName('MeshRelief'), VERTEX, FRAGMENT, new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]), 2,
      new Uint16Array([0, 1, 2, 0, 2, 3]), ATTRIBUTES, CAPACITY);
    const name = sunShaderName('MeshReliefEntry'), owner = this;
    const display = new Phaser.GameObjects.Shader(scene, { name, shaderName: name, fragmentSource: 'precision mediump float;void main(){gl_FragColor=vec4(0.0);}' }, 0, 0, 1, 1);
    ownSunShader(display, name);
    display.renderNode.run = function (context, object, parent): void {
      runWithScopedBlend(this, () => owner.draw(context), context, owner.blend, object, parent);
    };
    this.display = scene.add.existing(display).setDepth(DEPTH_LIGHTING + 0.001).setVisible(false).setName('mesh-surface-relief');
  }

  sync(casters: readonly MeshShadowCaster[], binding: LightMapBinding | null): void {
    this.display.setVisible(false);
    this.binding = binding;
    this.syncedFrame = this.scene.game.loop.frame;
    const level = getGraphicsQualityProfile(this.scene).level;
    if (!binding || level === 'low' || !this.gpu.prepare()) return;
    const fine = level === 'high';
    if (fine !== this.fine) { this.fine = fine; this.groups.clear(); }
    for (const group of this.groups.values()) group.count = 0;
    let any = false;
    for (const caster of casters) {
      const sprite = caster.sprite;
      if (!sprite.active || !sprite.visible || sprite.alpha <= 0 || caster.getHp() <= 0 || caster.isBurrowed()) continue;
      const imageKey = caster.getImageKey();
      let asset = this.assetsByImage.get(imageKey);
      if (asset === undefined) { asset = getPipelineAssetForTexture(imageKey) ?? null; this.assetsByImage.set(imageKey, asset); }
      if (!asset) continue;
      const group = this.group(imageKey, asset.id, asset.revision, asset.layout.columns, asset.layout.rows);
      if (!group?.texture || group.count >= CAPACITY) continue;
      const shown = sprite.frame;
      group.source = shown.source;
      const pose = sprite.frame.name === '__BASE' ? 0 : Number(sprite.frame.name);
      if (!Number.isInteger(pose) || pose < 0 || pose >= group.sheet.frames) continue;
      const columns = asset.layout.columns, row = Math.floor(pose / columns), offset = group.count++ * INSTANCE_WORDS, data = group.data;
      data[offset] = sprite.x; data[offset + 1] = sprite.y; data[offset + 2] = sprite.displayWidth; data[offset + 3] = sprite.displayHeight;
      const mirrored = sprite.flipX !== (sprite.scaleX < 0), inWidth = group.cellU - group.inU * 2, left = group.cellU * (pose % columns) + group.inU;
      data[offset + 4] = mirrored ? left + inWidth : left; data[offset + 5] = group.cellV * row + group.inV;
      data[offset + 6] = mirrored ? -inWidth : inWidth; data[offset + 7] = group.cellV - group.inV * 2;
      data[offset + 8] = Math.cos(sprite.rotation); data[offset + 9] = Math.sin(sprite.rotation); data[offset + 10] = sprite.alpha;
      data[offset + 11] = mirrored ? -1 : 1;
      data[offset + 12] = mirrored ? shown.u1 : shown.u0; data[offset + 13] = shown.v0;
      data[offset + 14] = mirrored ? shown.u0 - shown.u1 : shown.u1 - shown.u0; data[offset + 15] = shown.v1 - shown.v0;
      any = true;
    }
    if (!any) return;
    const view = getVisibleWorldView(this.scene.cameras.main, this.view, 0);
    // Phaser culls the entry against the camera; the instances themselves carry world positions.
    this.display.setPosition(view.x + view.width / 2, view.y + view.height / 2).setSize(view.width, view.height).setVisible(true);
  }

  destroy(): void {
    this.display.destroy();
    this.gpu.destroy();
    this.groups.clear();
    this.binding = null;
  }

  private group(imageKey: string, id: string, revision: string, columns: number, rows: number): Group | null {
    let group = this.groups.get(imageKey);
    if (group) return group;
    const sheet = normalSheetOf(id, revision, this.fine);
    if (!sheet) return null;
    group = { sheet, cellU: 1 / columns, cellV: 1 / rows, inU: 0, inV: 0, data: new Float32Array(CAPACITY * INSTANCE_WORDS), count: 0, texture: null, source: null };
    this.groups.set(imageKey, group);
    this.load(group, `mesh-relief-normal:${id}:${revision}:${sheet.file}`, sheet.file);
    return group;
  }

  /** Loads on first sight, outside the scene loader: a pilot sheet must not hold up the World's load. */
  private load(group: Group, key: string, file: string): void {
    const textures = this.scene.textures;
    const accept = (): void => {
      const texture = textures.get(key);
      texture.setFilter(Phaser.Textures.FilterMode.LINEAR);
      const source = texture.source[0];
      group.inU = SHEET_MARGIN / source.width; group.inV = SHEET_MARGIN / source.height;
      group.texture = texture;
    };
    if (textures.exists(key)) { accept(); return; }
    const image = new Image();
    image.onload = () => { if (!this.display.scene) return; if (!textures.exists(key)) textures.addImage(key, image); accept(); };
    image.onerror = () => { console.warn('[Lighting] normal sheet missing:', file); };
    image.src = runtimeAssetUrl(`./${file}`);
  }

  private draw(context: Phaser.Renderer.WebGL.DrawingContext): void {
    const binding = this.binding;
    // Borrowed for one frame: a teardown between two frames can free the map while the entry is still listed.
    if (!binding || this.syncedFrame !== this.scene.game.loop.frame) return;
    const camera = context.camera!.getViewMatrix(!context.useCanvas);
    this.renderer.setProjectionMatrixFromDrawingContext(context);
    const lightMap = binding.texture.get().source.glTexture!;
    for (const group of this.groups.values()) {
      const shown = group.source?.glTexture;
      if (!group.count || !group.texture || !shown) continue;
      this.gpu.draw(context, group.data.subarray(0, group.count * INSTANCE_WORDS), group.count, [group.texture.get().source.glTexture!, lightMap, shown], set => {
        set('uProjectionMatrix', this.renderer.projectionMatrix.val);
        set('uViewMatrix', [camera.a, camera.b, 0, camera.c, camera.d, 0, camera.tx, camera.ty, 1]);
        set('uNormal', 0); set('uLightMap', 1); set('uSprite', 2); set('uLightFrame', binding.frame); set('uAmbient', binding.ambient);
        set('uLights[0]', binding.lights); set('uCones[0]', binding.lightCones);
      });
    }
  }
}
