/** Browser-Demo: PeerJS-Raum über Raumcode, Einladungslink mit `#r=`, lokaler Name und Demo-Umfang. */
import { ROOM_HANDOVER_JOIN_WINDOW_MS } from '../../config';
import { createHostSession, joinHostSession, PeerNetworkError, type PeerFailureKind } from '../../network/peer';
import { retryUntil, takeRoomHandoverTicket } from '../../network/RoomHandover';
import { copyRoomShareUrl, readRoomCodeFromUrl, replaceRoomCodeInUrl } from '../../utils/roomQuality';
import { DEMO_CONTENT_POLICY } from '../../config/distributionContentPolicy';
import type { PlatformServices, PlatformSessionStart } from '../PlatformServices';

/** Der Nachfolger lädt selbst gerade neu: Bis sein Raum steht, sind diese Fehler erwartbar. */
const HANDOVER_RETRYABLE: ReadonlySet<PeerFailureKind> = new Set(['host-not-found', 'connection-failed', 'broker-unreachable']);
const BROKER_RETRYABLE: ReadonlySet<PeerFailureKind> = new Set(['broker-unreachable']);
const CODE_TAKEN: ReadonlySet<PeerFailureKind> = new Set(['room-code-taken']);

function isFailure(error: unknown, kinds: ReadonlySet<PeerFailureKind>): boolean {
  return error instanceof PeerNetworkError && kinds.has(error.kind);
}

/**
 * Ein Ticket gilt nur zusammen mit der Adresszeile, die `prepareHandover` gesetzt hat: Öffnet
 * jemand stattdessen einen anderen Einladungslink, gewinnt der Link.
 */
function pendingStart(): PlatformSessionStart {
  const ticket = takeRoomHandoverTicket();
  const roomCode = readRoomCodeFromUrl();
  if (ticket && (ticket.successor ? roomCode === null : roomCode === ticket.roomCode)) return { kind: 'handover', ticket };
  return roomCode === null ? { kind: 'host' } : { kind: 'join', target: roomCode };
}

export const webPlatformServices: PlatformServices = {
  sessions: {
    pendingStart,
    // Der eigene Raum steht nie in der eigenen Adresszeile (siehe `roomQuality`).
    host: (options, room) => {
      replaceRoomCodeInUrl(null);
      return createHostSession(options, room.roomCode);
    },
    join: (roomCode, options) => joinHostSession(roomCode, options),
    prepareHandover: ({ roomCode, successor }) => {
      replaceRoomCodeInUrl(successor ? null : roomCode);
      return null;
    },
    continueHandover: async (ticket, options) => {
      const deadline = ticket.createdAt + ROOM_HANDOVER_JOIN_WINDOW_MS;
      if (ticket.successor) {
        try {
          return await retryUntil(() => createHostSession(options, ticket.roomCode), {
            deadline,
            isRetryable: error => isFailure(error, BROKER_RETRYABLE),
          });
        } catch (error) {
          // Die Broker-ID ist schon vergeben: Ein anderer Gast hostet bereits – ihm beitreten.
          if (!isFailure(error, CODE_TAKEN)) throw error;
          replaceRoomCodeInUrl(ticket.roomCode);
        }
      }
      return retryUntil(() => joinHostSession(ticket.roomCode, options), {
        deadline,
        isRetryable: error => isFailure(error, HANDOVER_RETRYABLE),
      });
    },
  },
  // Ohne Lobby-Server gibt es keine Spielsuche; die Aufnahme regelt allein der Raum.
  rooms: {
    visibilities: ['closed', 'friends'],
    defaultVisibility: 'friends',
    applyVisibility: () => undefined,
    browser: null,
  },
  invites: {
    invite: roomCode => copyRoomShareUrl(roomCode),
    confirmation: 'link-copied',
    // Ein Einladungslink öffnet ein neues Spiel im Browser; zur Laufzeit kommt nichts an.
    setIncomingJoinHandler: () => undefined,
  },
  identity: {
    // Ohne gespeicherten Namen bleibt der Platzhalter aus der Spieler-ID (NetworkBridge).
    defaultPlayerName: () => null,
  },
  // Die Browser-Demo hat keine Freundesliste, in der ein Raumzustand stehen könnte.
  presence: { update: () => undefined },
  // Die Browser-Demo hat keine Erfolge; der Fortschritt wird trotzdem im Spielstand gezählt.
  achievements: { sync: () => undefined },
  content: DEMO_CONTENT_POLICY,
  shell: null,
  saves: null,
  // Jedes Asset kommt über das Netz: Große, seltene Inhalte laden erst bei Bedarf.
  assets: { local: false },
};
