import * as Phaser from 'phaser';
import { GROUND_HEIGHT_LEVEL_PX, GROUND_HEIGHT_RANGE_PX, MAX_OBJECT_HEIGHT_PX } from '../../arena/GroundHeightConfig';
import { DEPTH } from '../../config';
import { createVisibleWorldView, getVisibleWorldView } from '../../graphics/CameraWorldView';
import { createColorRenderTexture } from '../../graphics/createColorRenderTexture';
import { modulate2xBlendMode } from '../../graphics/CustomBlendModes';
import { getGraphicsQualityProfile } from '../../graphics/GraphicsQuality';
import { getGroundDetail, GROUND_DETAILS, isLightingFeatureOn } from '../../graphics/LightingFeatures';
import { runWithScopedBlend } from '../../graphics/PhaserScopedBlend';
import { CLOUD_SHADOW_GLSL, setCloudUniforms, type SunCloudState } from '../sunlight/cloudShadow';
import { ownSunShader, SunRenderTarget } from '../sunlight/SunRenderTarget';
import { SUN_VISIBILITY_GLSL } from '../sunlight/sunVisibility';
import { RELIEF_LIGHTS, type LightMapBinding } from './LightMapBinding';

export const GROUND_LIGHT_SHADER = 'GroundLightPass';
export const GROUND_SUN_FIELD_SHADER = 'GroundSunField';
/** The height view follows the camera in steps; only a step or newly baked ground redraws it. */
const VIEW_STEP_PX = 128;
/** Taps of a shadow reach beyond the screen. */
const VIEW_MARGIN_PX = 192;
const MAX_VIEW_SIDE_PX = 4096;
const SHADOW_STEPS = 16;
/** Sun shadows of ground objects end here; a low sun would otherwise draw them across the map. */
const SUN_REACH_PX = 56;
/** Plants and stones throw shadows in the same proportion as the World's other casters, whose cast heights are generous. */
const SUN_SHADOW_LENGTH = 2.0;
/** The sun's shadows are prepared in one field at half size; each pass looks three times as far as the one before, so no texel along a ray is skipped. */
const SUN_FIELD_STRIDES = [1, 3, 9] as const;
const SUN_FIELD_TEXEL_PX = 2;
/** The sides of a shadow open with distance: the serrated edge of a leaf would otherwise stretch into the teeth of a comb. */
const SUN_FIELD_SPREAD = 0.45;
/** Redraws the field once the sun has moved this far; on soft shadows that is well under a pixel. */
const SUN_FIELD_TOLERANCE = 0.006;
/** A receiver this far below the shadow is fully in it: the tip of a shadow fades over this height. */
const SUN_SOFT_HEIGHT_PX = 8;
/** Grain of the ground stays out of the field's comparison with it. */
const SUN_BIAS_PX = 1;
const SUN_SHADE_GAIN = 1.2;
const SUN_SHADE_MAX = 0.46;
/** Leaves and stones are lit from above; only part of a neighbour's shadow lies on them. */
const SUN_ON_OBJECTS = 0.5;
/** Blurring takes height from thin fronds, which would cut their shadows short; only what rises above the ground's waves gets it back. */
const WAVE_TOP_PX = GROUND_HEIGHT_LEVEL_PX + 2.4;
const SOFT_HEIGHT_BOOST = 1;
/** Lamps and blasts: short and soft, so a lit floor keeps showing enemies and markings. */
const LAMP_REACH_PX = 14;
const LAMP_FADE_FROM_PX = 3;
const LAMP_SHADOW = 0.55;
/**
 * Under light from close by, such as a projectile flying past, a caster has to rise this far over a ray for a full shadow, and leaves
 * and stones keep part of their light, or the grain of a plant's height shows as blotches. Light from further away than
 * `LAMP_NEAR_UNTIL` heights keeps the crisp shadows of a lamp.
 */
const LAMP_NEAR_SOFT_PX = 1.2;
const LAMP_NEAR_ON_OBJECTS = 0.6;
const LAMP_NEAR_UNTIL = 6;
/** Distance of the light, in heights above the ground, across which cast shadows fade in: light from above throws none. */
const LAMP_OVERHEAD_FROM = 0.7;
const LAMP_OVERHEAD_TO = 2.4;
/** Ground right beside something taller lies in its shade whatever the light does; this also grounds objects under a canopy. */
const CONTACT_REACH_PX = 2.5;
const CONTACT_SHADE = 0.34;
/**
 * The way before the light vector field, kept for the comparison in the review panel: the strongest single light of a spot
 * shapes it alone, at full strength from a low level on, and fades towards its radius and towards a tie with the next one.
 */
const LAMP_EDGE_FADE = 0.3;
const LAMP_LEAD_FADE = 0.4;
const OWN_LIGHT_PX = 6;
const NO_LIGHTS = new Float32Array(RELIEF_LIGHTS * 4);
const NO_HEIGHTS = new Float32Array(RELIEF_LIGHTS);
/** Below this much lamp light, or this little direction in it, the ground keeps its plain look. */
const MIN_LAMP_LEVEL = 0.004;
const MIN_LIGHT_VECTOR = 0.002;
/** The darkest night still counts as this much light, so a faint glow does not model the ground at full strength. */
const MIN_TOTAL_LIGHT = 0.03;
/** A lamp that gives most of a spot's light models it fully, as a flashlight at night does; a weak light by day keeps a weak shadow. */
const LAMP_SHARE_GAIN = 1.5;
const NO_AMBIENT = new Float32Array(3);
/** Colour channel of each entry of GROUND_DETAILS in the height layer. */
const CHANNELS: readonly (readonly [number, number, number])[] = [[1, 0, 0], [0, 1, 0], [0, 0, 1]];
/** From here on a ray reads the blurred heights: a leaf's serration would otherwise stretch into the parallel teeth of a comb. */
const SHARP_UNTIL_PX = 5;
const SOFT_FROM_PX = 12;

/** One step of the sun's field: how high the shadow of what lies towards the sun reaches above each point. */
export const GROUND_SUN_FIELD_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uSource;
uniform vec2 uTexel,uDir;
// Texels per tap; encoded height a shadow loses per texel.
uniform vec2 uStep;
void main(){
 vec2 uv=gl_FragCoord.xy*uTexel,side=vec2(-uDir.y,uDir.x);
 vec3 top=texture2D(uSource,uv).rgb;
 for(int j=1;j<=3;j++){
  float t=float(j)*uStep.x;
  vec2 at=uv+uDir*t*uTexel,wide=side*t*${SUN_FIELD_SPREAD.toFixed(2)}*uTexel;
  top=max(top,(texture2D(uSource,at+wide).rgb+texture2D(uSource,at-wide).rgb)*.5-t*uStep.y);
 }
 gl_FragColor=vec4(top,1.0);
}`;

export const GROUND_LIGHT_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
varying vec2 outTexCoord;
uniform sampler2D uHeight,uSoftHeight,uLightMap,uReceiver,uSunCast,uLightVectors;
uniform vec4 uView,uHeightFrame,uLightFrame,uReceiverWorld,uVectorFrame;
uniform vec3 uAmbient,uChannel,uSun;
// Sun strength, its light and shadow tuning.
uniform vec3 uSunTuning;
uniform float uHasReceiver,uHasVectors;
// x: 1 reads the light vector field, 0 ranks single lights. y: 1 softens the shadows of light close by.
uniform vec2 uLampMode;
uniform vec4 uLights[${RELIEF_LIGHTS}];
uniform vec4 uCones[${RELIEF_LIGHTS}];
uniform float uLightHeights[${RELIEF_LIGHTS}];
${CLOUD_SHADOW_GLSL}
${SUN_VISIBILITY_GLSL}
float heightAt(vec2 p){
 vec2 at=(p-uHeightFrame.xy)/uHeightFrame.zw;
 return dot(texture2D(uHeight,vec2(at.x,1.0-at.y)).rgb,uChannel)*${GROUND_HEIGHT_RANGE_PX.toFixed(1)};
}
float softHeightAt(vec2 p){
 vec2 at=(p-uHeightFrame.xy)/uHeightFrame.zw;
 return dot(texture2D(uSoftHeight,vec2(at.x,1.0-at.y)).rgb,uChannel)*${GROUND_HEIGHT_RANGE_PX.toFixed(1)};
}
float sunCastAt(vec2 p){
 vec2 at=(p-uHeightFrame.xy)/uHeightFrame.zw;
 return dot(texture2D(uSunCast,vec2(at.x,1.0-at.y)).rgb,uChannel)*${GROUND_HEIGHT_RANGE_PX.toFixed(1)};
}
const vec3 LUMA=vec3(.2126,.7152,.0722);
float canopyAt(vec2 world){
 vec2 uv=(world-uCloudWorld.xy)/max(uCloudWorld.zw,vec2(1.0));
 if(uCloudCached>.5&&all(greaterThanEqual(uv,vec2(0)))&&all(lessThanEqual(uv,vec2(1))))return texture2D(uCloudField,vec2(uv.x,1.0-uv.y)).a;
 return sunVisibility(world);
}
float casterAt(vec2 q,float t){
 float blend=smoothstep(${SHARP_UNTIL_PX.toFixed(1)},${SOFT_FROM_PX.toFixed(1)},t);
 if(blend<=0.0)return heightAt(q);
 float s=softHeightAt(q);
 s+=max(s-${WAVE_TOP_PX.toFixed(1)},0.0)*${SOFT_HEIGHT_BOOST.toFixed(1)};
 return blend<1.0?mix(heightAt(q),s,blend):s;
}
// How much of a ray towards the light is cut by the height field; soft with distance, gone at the reach.
float shadowAlong(vec2 p,float h,vec2 dir,float rise,float reach,float fadeFrom,float soft){
 float shade=0.0;
 for(int i=1;i<=${SHADOW_STEPS};i++){
  // Dense beside the object, where a low rounded edge casts over only a few pixels.
  float s=float(i)/${SHADOW_STEPS}.0,t=reach*s*s,ray=h+.35+t*rise;
  if(ray>${(GROUND_HEIGHT_LEVEL_PX + 18).toFixed(1)})break;
  float over=casterAt(p+dir*t,t)-ray;
  if(over>0.0)shade=max(shade,clamp(over/(soft+min(t,22.0)*.25),0.0,1.0)*(1.0-smoothstep(fadeFrom,reach,t)));
 }
 return shade;
}
void main(){
 vec2 p=uView.xy+vec2(outTexCoord.x,1.0-outTexCoord.y)*uView.zw;
 float ground=1.0;
 if(uHasReceiver>.5)ground=smoothstep(.2,.8,texture2D(uReceiver,(p-uReceiverWorld.xy)/uReceiverWorld.zw).r);
 if(ground<.01)discard;
 float h=heightAt(p);
 // Open ground takes its slope from the blurred heights: eight bits over a gentle wave would show as contour lines.
 float soft=softHeightAt(p);
 float object=smoothstep(.2,.9,abs(h-soft));
 vec2 slope=vec2(0.0);
 if(object<1.0){vec2 e=vec2(4.0,0.0);slope+=vec2(softHeightAt(p+e.xy)-softHeightAt(p-e.xy),softHeightAt(p+e.yx)-softHeightAt(p-e.yx))/8.0*(1.0-object);}
 if(object>0.0){vec2 e=vec2(1.5,0.0);slope+=vec2(heightAt(p+e.xy)-heightAt(p-e.xy),heightAt(p+e.yx)-heightAt(p-e.yx))/3.0*object;}
 vec3 n=normalize(vec3(-slope,1.0));
 float factor=1.0-clamp((soft-h)/${CONTACT_REACH_PX.toFixed(1)},0.0,1.0)*${CONTACT_SHADE.toFixed(2)};
 float sun=uSunTuning.x;
 if(sun>.001){
  float face=dot(n,uSun)-uSun.z;
  factor*=1.0+clamp(face*(face>0.0?.9:.5)*uSunTuning.y,-.28,.22)*sun*cloudFormStrength(p);
  if(uSunTuning.z>0.0){
   float low=1.0-smoothstep(.60,.7071,uSun.z);
   float over=sunCastAt(p)-mix(soft,h,object)-${SUN_BIAS_PX.toFixed(1)};
   if(over>0.0)factor*=1.0-smoothstep(0.0,${SUN_SOFT_HEIGHT_PX.toFixed(1)},over)*min(uSunTuning.z*${SUN_SHADE_GAIN.toFixed(2)},${SUN_SHADE_MAX.toFixed(2)})*(.82+.18*low)*min(sun,1.0)*mix(.45,1.0,canopyAt(p))*mix(1.0,${SUN_ON_OBJECTS.toFixed(2)},object);
  }
 }
 vec2 at=(p-uLightFrame.xy)/uLightFrame.zw;
 vec3 lit=texture2D(uLightMap,vec2(at.x,1.0-at.y)).rgb;
 float level=dot(max(lit-uAmbient,vec3(0.0)),LUMA);
 if(uLampMode.x>.5){
  if(uHasVectors>.5&&level>${MIN_LAMP_LEVEL.toFixed(3)}){
   // Strength times direction towards every light, summed: lights from opposite sides cancel, none takes the spot over from another.
   vec2 from=(p-uVectorFrame.xy)/uVectorFrame.zw;
   vec3 v=texture2D(uLightVectors,vec2(from.x,1.0-from.y)).rgb;
   float len=length(v),across=length(v.xy);
   if(len>${MIN_LIGHT_VECTOR.toFixed(3)}){
    // A shadow can only take away the light that casts it: the share of directed lamp light in all light on this spot.
    float amount=min(1.0,${LAMP_SHARE_GAIN.toFixed(1)}*min(len,level)/max(dot(lit,LUMA),${MIN_TOTAL_LIGHT.toFixed(2)}));
    vec3 l=v/len;
    float face=dot(n,l)-l.z;
    factor*=1.0+clamp(face*(face>0.0?.8:.6),-.42,.4)*amount;
    float away=across/max(v.z,.0001),beside=mix(1.0,smoothstep(${LAMP_OVERHEAD_FROM.toFixed(1)},${LAMP_OVERHEAD_TO.toFixed(1)},away),uLampMode.y);
    if(beside>0.0&&across>.0001){
     float far=max(smoothstep(${LAMP_OVERHEAD_TO.toFixed(1)},${LAMP_NEAR_UNTIL.toFixed(1)},away),1.0-uLampMode.y);
     float shade=shadowAlong(p,h,v.xy/across,max(.5,v.z/across),${LAMP_REACH_PX.toFixed(1)},${LAMP_FADE_FROM_PX.toFixed(1)},mix(${LAMP_NEAR_SOFT_PX.toFixed(1)},.5,far));
     factor*=1.0-shade*${LAMP_SHADOW.toFixed(2)}*amount*beside*mix(mix(${LAMP_NEAR_ON_OBJECTS.toFixed(2)},1.0,far),1.0,1.0-object);
    }
   }
  }
 } else if(level>.015){
  vec2 best=vec2(0.0);
  float strongest=0.0,second=0.0,dist=1.0,lift=0.0,edge=0.0;
  for(int i=0;i<${RELIEF_LIGHTS};i++){
   vec2 to=uLights[i].xy-p;
   float d=length(to);
   if(d>=uLights[i].z||d<${OWN_LIGHT_PX.toFixed(1)})continue;
   float inside=1.0-d/uLights[i].z,w=inside*inside*uLights[i].w;
   vec2 dir=to/d;
   if(uCones[i].z>-1.5)w*=clamp((dot(-dir,uCones[i].xy)-uCones[i].z)/uCones[i].w,0.0,1.0);
   if(w>strongest){second=strongest;strongest=w;best=dir;dist=d;lift=uLightHeights[i];edge=inside;}
   else second=max(second,w);
  }
  if(strongest>.0005){
   float amount=smoothstep(.015,.12,min(level,strongest))*smoothstep(0.0,${LAMP_EDGE_FADE.toFixed(2)},edge)*smoothstep(0.0,${LAMP_LEAD_FADE.toFixed(2)},1.0-second/strongest);
   vec3 l=normalize(vec3(best*dist,max(lift-h,2.0)));
   float face=dot(n,l)-l.z;
   factor*=1.0+clamp(face*(face>0.0?.8:.6),-.42,.4)*amount;
   float shade=shadowAlong(p,h,best,max(.5,(lift-h)/dist),${LAMP_REACH_PX.toFixed(1)},${LAMP_FADE_FROM_PX.toFixed(1)},.5);
   factor*=1.0-shade*${LAMP_SHADOW.toFixed(2)}*amount;
  }
 }
 factor=mix(1.0,factor,ground);
 if(abs(factor-1.0)<.004)discard;
 gl_FragColor=vec4(vec3(clamp(factor,.2,1.9)*.5),.5);
}`;

/** What the pass needs from the World's ground. */
export interface GroundLightSurface {
  visitHeightChunks(visitor: (layer: Phaser.GameObjects.RenderTexture) => void): void;
  getHeightRevision(): number;
  getSunState(): SunCloudState | undefined;
  stampObjectHeights(target: Phaser.GameObjects.RenderTexture, originX: number, originY: number): void;
}

export interface GroundLightReceiver { readonly texture: Phaser.Textures.Texture; readonly world: number[] }

/** One pass over the whole ground: relief and short shadows of everything on it, for the sun and the lamps, from a shared height field. */
export class GroundLightPass {
  private readonly quad: Phaser.GameObjects.Shader;
  private readonly view = createVisibleWorldView();
  private readonly viewRect = new Float32Array(4);
  private readonly heightFrame = new Float32Array(4);
  private readonly sun = new Float32Array([0, 0, 1]);
  private readonly sunMarch = new Float32Array(3);
  private readonly sunTuning = new Float32Array(3);
  private readonly lampMode = new Float32Array(2);
  private readonly fieldSun = new Float32Array(3);
  private readonly fieldTexel = new Float32Array(2);
  private readonly fieldDir = new Float32Array(2);
  private readonly fieldStep = new Float32Array(2);
  private fieldTargets: SunRenderTarget[] | null = null;
  private fieldValid = false;
  private height: Phaser.GameObjects.RenderTexture | null = null;
  private half: Phaser.GameObjects.RenderTexture | null = null;
  private soft: Phaser.GameObjects.RenderTexture | null = null;
  private surface: GroundLightSurface | null = null;
  private binding: LightMapBinding | null = null;
  private receiver: GroundLightReceiver | null = null;
  private originX = NaN;
  private originY = NaN;
  private revision = -1;
  private syncedFrame = -1;
  private readonly onContextRestored = (): void => {
    // Phaser restores storage, not the cached height and sun contents.
    this.originX = NaN;
    this.fieldValid = false;
  };

  constructor(private readonly scene: Phaser.Scene) {
    const blend = modulate2xBlendMode(scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer);
    const quad = this.quad = new Phaser.GameObjects.Shader(scene, {
      name: GROUND_LIGHT_SHADER, shaderName: GROUND_LIGHT_SHADER, fragmentSource: GROUND_LIGHT_FRAGMENT,
      setupUniforms: (set: (name: string, value: unknown) => void) => this.uniforms(set),
    }, 0, 0, 2, 2, ['__WHITE', '__WHITE', '__WHITE', '__WHITE', '__WHITE', '__WHITE']);
    ownSunShader(quad, GROUND_LIGHT_SHADER, true);
    const node = quad.renderNode, run = node.run, owner = this;
    // Borrowed for one frame: a teardown between two frames can free the textures while the quad is still listed.
    node.run = function (context, object, parent): void {
      if (owner.syncedFrame === owner.scene.game.loop.frame) runWithScopedBlend(this, run, context, blend, object, parent);
    };
    scene.add.existing(quad);
    quad.setOrigin(0).setDepth(DEPTH.DECALS + 0.01).setVisible(false).setName('ground-light');
    scene.sys.renderer.on(Phaser.Renderer.Events.RESTORE_WEBGL, this.onContextRestored);
  }

  /** True while the pass draws, which replaces the sun's own treatment of ground objects. */
  sync(surface: GroundLightSurface | null, binding: LightMapBinding | null, receiver: GroundLightReceiver | null): boolean {
    this.surface = surface;
    this.binding = binding;
    this.receiver = receiver;
    this.syncedFrame = this.scene.game.loop.frame;
    // Without a lamp in view the light map is absent; the sun still needs the pass.
    if (!surface || getGraphicsQualityProfile(this.scene).level !== 'high') { this.quad.setVisible(false); return false; }
    const view = getVisibleWorldView(this.scene.cameras.main, this.view, 0);
    const heightChanged = this.refreshHeight(surface, view.x, view.y, view.width, view.height);
    this.readSun(surface);
    this.refreshSunField(heightChanged);
    this.viewRect[0] = view.x; this.viewRect[1] = view.y; this.viewRect[2] = view.width; this.viewRect[3] = view.height;
    const white = this.scene.textures.get('__WHITE');
    this.quad.setTextures([this.height!.texture, this.soft!.texture, binding?.texture ?? white, receiver?.texture ?? white, this.fieldTargets?.[0].shader.texture ?? white, binding?.lightVectors?.texture ?? white]);
    this.quad.setPosition(view.x, view.y).setSize(view.width, view.height).setVisible(true);
    return true;
  }

  destroy(): void {
    this.scene.sys.renderer.off(Phaser.Renderer.Events.RESTORE_WEBGL, this.onContextRestored);
    this.quad.destroy();
    this.destroyTargets();
    for (const target of this.fieldTargets ?? []) target.destroy();
    this.fieldTargets = null;
    this.surface = null;
    this.binding = null;
    this.receiver = null;
  }

  private refreshHeight(surface: GroundLightSurface, x: number, y: number, width: number, height: number): boolean {
    const target = this.ensureTarget(width + VIEW_MARGIN_PX * 2 + VIEW_STEP_PX, height + VIEW_MARGIN_PX * 2 + VIEW_STEP_PX);
    const originX = Math.floor((x - VIEW_MARGIN_PX) / VIEW_STEP_PX) * VIEW_STEP_PX, originY = Math.floor((y - VIEW_MARGIN_PX) / VIEW_STEP_PX) * VIEW_STEP_PX;
    const revision = surface.getHeightRevision();
    if (originX === this.originX && originY === this.originY && revision === this.revision) return false;
    this.originX = originX; this.originY = originY; this.revision = revision;
    this.heightFrame[0] = originX; this.heightFrame[1] = originY; this.heightFrame[2] = target.width; this.heightFrame[3] = target.height;
    const level = Math.round(GROUND_HEIGHT_LEVEL_PX / GROUND_HEIGHT_RANGE_PX * 255);
    target.clear().fill((level << 16) | (level << 8) | level, 1);
    surface.visitHeightChunks(layer => {
      const left = layer.x - originX, top = layer.y - originY;
      if (left >= target.width || top >= target.height || left + layer.width <= 0 || top + layer.height <= 0) return;
      target.stamp(layer.texture.key, layer.frame.name, left, top, { originX: 0, originY: 0 });
    });
    surface.stampObjectHeights(target, originX, originY);
    target.render();
    // Two halvings average the texels a single quarter-size draw would skip.
    const half = this.half!, soft = this.soft!;
    half.clear().stamp(target.texture.key, undefined, 0, 0, { originX: 0, originY: 0, scale: 0.5 });
    half.render();
    soft.clear().stamp(half.texture.key, undefined, 0, 0, { originX: 0, originY: 0, scale: 0.5 });
    soft.render();
    return true;
  }

  private readSun(surface: GroundLightSurface): void {
    const state = surface.getSunState(), sun = state?.sunPath?.sun;
    if (sun) {
      this.sun[0] = sun[0]; this.sun[1] = sun[1]; this.sun[2] = sun[2];
      const flat = Math.max(0.001, Math.hypot(sun[0], sun[1]));
      this.sunMarch[0] = sun[0] / flat; this.sunMarch[1] = sun[1] / flat; this.sunMarch[2] = sun[2] / flat / SUN_SHADOW_LENGTH;
    }
    this.sunTuning[0] = sun ? state?.strength ?? 0 : 0;
    this.sunTuning[1] = state?.tuning.vegLight ?? 1;
    this.sunTuning[2] = state?.quality?.vegetationShadows ? state.tuning.vegShadow : 0;
  }

  /** Only a moved sun or new heights cost anything; the frame itself reads the field once per pixel. */
  private refreshSunField(heightChanged: boolean): void {
    if (this.sunTuning[0] <= 0.001 || this.sunTuning[2] <= 0) return;
    const sun = this.sunMarch, last = this.fieldSun;
    if (!heightChanged && this.fieldValid && Math.abs(sun[0] - last[0]) + Math.abs(sun[1] - last[1]) + Math.abs(sun[2] - last[2]) < SUN_FIELD_TOLERANCE) return;
    last.set(sun);
    this.fieldValid = true;
    const targets = this.fieldTargets ??= [this.createFieldTarget(), this.createFieldTarget()];
    const half = this.half!, width = half.width, height = half.height;
    this.fieldTexel[0] = 1 / width; this.fieldTexel[1] = 1 / height;
    // Texture space runs against the World's y.
    this.fieldDir[0] = sun[0]; this.fieldDir[1] = -sun[1];
    // The tallest object still ends at the reach, however low the sun.
    this.fieldStep[1] = Math.max(sun[2], MAX_OBJECT_HEIGHT_PX / SUN_REACH_PX) * SUN_FIELD_TEXEL_PX / GROUND_HEIGHT_RANGE_PX;
    let source: Phaser.Textures.Texture = half.texture;
    SUN_FIELD_STRIDES.forEach((stride, pass) => {
      // Two targets take turns; the last pass lands in the first, which the frame reads.
      const target = targets[pass % 2];
      this.fieldStep[0] = stride;
      target.shader.setTextures([source]);
      target.draw(width, height);
      source = target.shader.texture!;
    });
  }

  private createFieldTarget(): SunRenderTarget {
    return new SunRenderTarget(this.scene, 'GroundSunField', GROUND_SUN_FIELD_FRAGMENT, set => {
      set('uSource', 0); set('uTexel', this.fieldTexel); set('uDir', this.fieldDir); set('uStep', this.fieldStep);
    }, ['__WHITE'], GROUND_SUN_FIELD_SHADER);
  }

  private destroyTargets(): void {
    this.height?.destroy(); this.height = null;
    this.half?.destroy(); this.half = null;
    this.soft?.destroy(); this.soft = null;
  }

  private createTarget(width: number, height: number): Phaser.GameObjects.RenderTexture {
    const target = createColorRenderTexture(this.scene, width, height);
    target.setOrigin(0).setVisible(false);
    target.texture.setFilter(Phaser.Textures.FilterMode.LINEAR);
    return target;
  }

  private ensureTarget(width: number, height: number): Phaser.GameObjects.RenderTexture {
    // Multiples of four keep the half and quarter copies on the same grid as the full one.
    const w = Math.min(MAX_VIEW_SIDE_PX, Math.ceil(width / 4) * 4), h = Math.min(MAX_VIEW_SIDE_PX, Math.ceil(height / 4) * 4);
    if (this.height && this.height.width >= w && this.height.height >= h) return this.height;
    this.destroyTargets();
    const target = this.height = this.createTarget(w, h);
    this.half = this.createTarget(Math.ceil(w / 2), Math.ceil(h / 2));
    this.soft = this.createTarget(Math.ceil(w / 4), Math.ceil(h / 4));
    this.originX = NaN;
    return target;
  }

  private uniforms(set: (name: string, value: unknown) => void): void {
    const binding = this.binding;
    const state = this.surface?.getSunState();
    const vectors = binding?.lightVectors ?? null;
    set('uHeight', 0); set('uSoftHeight', 1); set('uLightMap', 2); set('uReceiver', 3); set('uSunCast', 4); set('uLightVectors', 5);
    set('uVectorFrame', vectors?.frame ?? this.viewRect); set('uHasVectors', vectors ? 1 : 0);
    this.lampMode[0] = isLightingFeatureOn('groundLightVectors') ? 1 : 0; this.lampMode[1] = isLightingFeatureOn('groundNearSoft') ? 1 : 0;
    set('uLampMode', this.lampMode);
    set('uLights[0]', binding?.lights ?? NO_LIGHTS); set('uCones[0]', binding?.lightCones ?? NO_LIGHTS); set('uLightHeights[0]', binding?.lightHeights ?? NO_HEIGHTS);
    set('uView', this.viewRect); set('uHeightFrame', this.heightFrame); set('uLightFrame', binding?.frame ?? this.viewRect); set('uAmbient', binding?.ambient ?? NO_AMBIENT);
    set('uReceiverWorld', this.receiver?.world ?? this.viewRect); set('uHasReceiver', this.receiver ? 1 : 0);
    set('uChannel', CHANNELS[GROUND_DETAILS.indexOf(getGroundDetail())]);
    set('uSun', this.sun); set('uSunTuning', this.sunTuning);
    setCloudUniforms(set, state);
  }
}
