/**
 * The Flammenkoloss's living light, one quad per body on its current sheet frame just above the light
 * map. Premultiplied NORMAL blend: colour adds light, alpha lets the painted glow of the sheet below sink
 * (`result = light + dst * (1 - alpha)`), so a sleeping vein really darkens instead of glowing forever.
 *
 * The emission sheet (encoding `srgb-zone-alpha-coverage`, premultiplied on upload) stores per pixel
 * the zone in red (k / zones), a flow coordinate in green (0..1 along the light's flow: from a groove
 * out over its sclerite, along a leg, from a mandible's base to its tip, from the lantern's front to
 * its nozzle, from a wing's hinge outwards) and the light share in alpha: exactly the glow painted on
 * the body. Nothing lights up everywhere at once:
 * 1. veined chitin: slow regions of light drift, change shape and breathe each in its own rhythm (some
 *    veins wake while others sink to an ember; the zone level decides how many are awake), every
 *    heartbeat runs out from the heart through the veins as a fading wave, and pulses leave the grooves
 *    at unrelated times;
 * 2. mandibles: at rest an ember breathes from the base to the tips; through the flame the heat front
 *    runs out to the tips, the blades burn violet-hot and white-hot spots crawl over them;
 * 3. lantern: the light fills the translucent body; dark pockets and violet haze drift inside it,
 *    glowing threads wind through it towards the nozzle, and the heartbeat travels from the thorax to
 *    the nozzle;
 * 4. wings: a burning flicker that runs out along the veins.
 * A soft halo (two rings of taps around each pixel, widest for the lantern) lets the light bleed past
 * its painted lines. The slow fields are evaluated once per pixel and shared by its halo taps.
 *
 * Attributes per vertex: world position, sheet UV, local (frame-relative x/y in [-0.5, 0.5], y towards
 * the tail, seed, faction 0 hostile / 1 allied), zone levels (veins, mandibles, lantern, wings), state
 * (mandible heat, heartbeat phase in beats, heartbeat gain, overall strength incl. day/night damping)
 * and frame (the frame's UV size for the halo taps, how far the painted glow may sink).
 */
export const COLOSSUS_EMISSION_VERTEX_SHADER = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform mat4 uProjectionMatrix;
uniform mat3 uViewMatrix;
attribute vec2 inPosition;
attribute vec2 inUv;
attribute vec4 inLocal;
attribute vec4 inLevels;
attribute vec4 inState;
attribute vec3 inFrame;
varying vec2 vUv;
varying vec4 vLocal;
varying vec4 vLevels;
varying vec4 vState;
varying vec3 vFrame;
void main() {
  vec3 view = uViewMatrix * vec3(inPosition, 1.0);
  gl_Position = uProjectionMatrix * vec4(view.xy, 0.0, 1.0);
  vUv = inUv; vLocal = inLocal; vLevels = inLevels; vState = inState; vFrame = inFrame;
}`;

export const COLOSSUS_EMISSION_FRAGMENT_SHADER = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uEmission;
uniform float uZones;
uniform float uTime;
uniform vec3 uHostileGlow;
uniform vec3 uHostileHot;
uniform vec3 uHostileDeep;
uniform vec3 uAlliedGlow;
uniform vec3 uAlliedHot;
uniform vec3 uAlliedDeep;
varying vec2 vUv;
varying vec4 vLocal;
varying vec4 vLevels;
varying vec4 vState;
varying vec3 vFrame;

// The heart under the thorax's rear edge (the 'core' socket), from the frame's centre.
const vec2 HEART = vec2(0.0, 0.107);

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 4; i++) { v += a * noise(p); p = p * 2.03 + vec2(1.7, 9.2); a *= 0.5; }
  return v;
}
float fbm2(vec2 p) { return 0.65 * noise(p) + 0.35 * noise(p * 2.03 + vec2(1.7, 9.2)); }
// Lub-dub: a strong beat and a softer echo early in every cycle, then rest.
float heartbeat(float beats) {
  float c = fract(beats);
  return exp(-pow((c - 0.06) / 0.045, 2.0)) + 0.55 * exp(-pow((c - 0.24) / 0.055, 2.0));
}
float zoneOf(vec4 e) { return floor(clamp(e.r / e.a, 0.0, 1.0) * uZones + 0.5); }

// The slow fields of one pixel; its halo taps share them.
struct Fields {
  float awake;   // veined chitin: 0 sunk to an ember .. 1 awake
  float flare;   // the brightest awake patches run hot
  float phase;   // per-region phase of the vein pulses
  float gate;    // where the pulses run at all
  float wave;    // the heartbeat's wave through the veins
  float inner;   // lantern: glowing haze (1) or dark pocket (0)
  float threads; // lantern: drifting glowing threads
};

Fields fieldsAt(vec2 p, float t, float seed, bool lantern) {
  Fields f;
  // Regions change shape (warp) and drift; the zone level shifts how much of the body is awake.
  vec2 warp = vec2(noise(p * 1.8 + vec2(t * 0.11, 3.0 + seed)), noise(p * 1.8 + vec2(7.0 + seed, -t * 0.09))) - 0.5;
  float n = (fbm(p * 3.6 + warp * 1.6 + vec2(t * 0.06, -t * 0.045) + seed) - 0.47) / 0.12 + (vLevels.x - 0.6) * 3.0;
  // Every region also breathes in its own rhythm (about five seconds), so they never swell together.
  n += 0.7 * sin(t * 1.3 + noise(p * 2.2 + seed * 0.7) * 6.2832);
  f.awake = smoothstep(-0.4, 0.5, n);
  f.flare = smoothstep(1.0, 1.9, n);
  f.phase = noise(p * 6.0 + seed * 1.3) * 12.566;
  f.gate = smoothstep(0.42, 0.72, noise(p * 2.6 + vec2(-t * 0.13, t * 0.07) + 11.0 + seed));
  float d = length((p - HEART) * vec2(1.0, 0.85));
  f.wave = heartbeat(vState.y - d * 1.1) * vState.z * exp(-d * 2.4);
  f.inner = 0.0;
  f.threads = 0.0;
  if (lantern) {
    // Haze and threads stretch along the body and drift towards the nozzle.
    vec2 q = vec2(p.x * 8.0, p.y * 3.4 - t * 0.24) + seed;
    vec2 w = vec2(fbm(q + vec2(t * 0.1, 0.0)), fbm(q * 1.3 + vec2(4.0, -t * 0.08)));
    f.inner = smoothstep(0.32, 0.72, fbm(q + w * 1.8));
    f.threads = pow(1.0 - abs(2.0 * fbm(q * 1.25 + w * 2.2 + 9.0) - 1.0), 10.0);
  }
  return f;
}

// Light a pixel of the given zone, light share and flow adds; 'keep' is how much of its painted glow
// stays, 'halo' how strongly it bleeds into its neighbours.
vec3 zoneLight(float zone, float share, float flow, vec2 p, float t, float seed, Fields f, vec3 glow, vec3 hot, vec3 deep,
  out float keep, out float halo) {
  if (zone < 1.5) {
    float pulse = pow(max(0.0, sin((flow * 1.6 - t * 0.5) * 6.2832 + f.phase)), 12.0) * f.gate * smoothstep(0.0, 0.12, flow + 0.02);
    float life = 0.1 + 0.9 * f.awake + 0.6 * f.wave + 1.2 * pulse * (0.35 + 0.65 * f.awake);
    keep = 0.3 + 0.7 * clamp(life, 0.0, 1.0);
    halo = 0.07;
    vec3 c = mix(glow, hot, clamp(0.55 * f.flare + 0.7 * pulse + 0.35 * f.wave, 0.0, 1.0));
    return c * vLevels.x * share * life * 1.15;
  }
  if (zone < 2.5) {
    float heat = vState.x;
    float lit = smoothstep(-0.2, 0.12, heat * 1.35 - flow);
    float ember = 0.5 + 0.5 * sin(t * 1.4 - flow * 3.0 + seed);
    // The blade burns violet-hot; white-hot spots crawl over it towards the tips.
    float crawl = fbm2(vec2(flow * 7.0 - t * 3.1, p.x * 9.0 + p.y * 5.0 + seed));
    float flicker = 0.5 + 0.5 * sin(flow * 31.0 - t * 17.0 + seed) * sin(flow * 11.0 + t * 6.3);
    float spots = smoothstep(0.42, 0.78, crawl + 0.22 * flicker + 0.25 * flow);
    float white = clamp(heat * lit * (0.25 + 0.75 * spots), 0.0, 1.0);
    vec3 c = mix(glow, hot, clamp(heat * lit * 0.35 + white * 0.5, 0.0, 1.0));
    c = mix(c, vec3(1.0, 0.97, 1.0), white * white * 0.6);
    keep = mix(0.45 + 0.4 * ember, 1.0, heat);
    halo = 0.1 + 0.1 * heat;
    return c * vLevels.y * share * ((0.3 + 0.45 * ember) * (1.0 - heat) + heat * (0.45 + 0.25 * lit) * (1.0 + 1.4 * spots));
  }
  if (zone < 3.5) {
    // The light fills the translucent body instead of following its brightest painted line.
    float body = 0.35 * share + 0.65 * smoothstep(0.0, 0.4, share);
    float beat = heartbeat(vState.y - flow * 0.4) * vState.z;
    vec3 c = mix(deep, glow, f.inner);
    c = mix(c, hot, clamp(0.7 * f.threads + 0.5 * beat, 0.0, 1.0));
    keep = 0.2 + 0.8 * clamp(0.1 + 0.9 * f.inner + 0.6 * beat, 0.0, 1.0);
    halo = 0.2;
    return c * vLevels.z * body * (0.1 + 0.65 * f.inner + 0.95 * f.threads * (0.3 + 0.7 * f.inner) + 0.85 * beat);
  }
  float run = fbm2(vec2(flow * 5.0 - t * 1.7, seed + p.x * 3.0));
  float flicker = 0.35 + 0.85 * run * run;
  keep = 0.4 + 0.6 * clamp(flicker, 0.0, 1.0);
  halo = 0.12;
  return mix(glow, hot, 0.3 * run) * vLevels.w * share * flicker;
}

void main() {
  float t = uTime * 0.001;
  vec2 p = vLocal.xy;
  float seed = vLocal.z;
  bool allied = vLocal.w > 0.5;
  vec3 glow = allied ? uAlliedGlow : uHostileGlow;
  vec3 hot = allied ? uAlliedHot : uHostileHot;
  vec3 deep = allied ? uAlliedDeep : uHostileDeep;
  // The pixel and six halo taps on two rings of about one and two percent of the frame (the frame
  // keeps a transparent margin around the body).
  vec4 taps[7];
  vec2 shift[7];
  float any = 0.0;
  bool lantern = false;
  for (int i = 0; i < 7; i++) {
    float a = float(i) * 1.0472 + 0.4;
    vec2 offset = i == 0 ? vec2(0.0) : vec2(cos(a), sin(a)) * vFrame.xy * (mod(float(i), 2.0) > 0.5 ? 0.012 : 0.022);
    vec4 e = texture2D(uEmission, vUv + offset);
    taps[i] = e;
    shift[i] = offset;
    any = max(any, e.a);
    if (e.a > 0.004 && zoneOf(e) > 2.5 && zoneOf(e) < 3.5) lantern = true;
  }
  if (any < 0.004) { gl_FragColor = vec4(0.0); return; }
  Fields f = fieldsAt(p, t, seed, lantern);
  vec3 color = vec3(0.0);
  float sink = 0.0;
  for (int i = 0; i < 7; i++) {
    vec4 e = taps[i];
    if (e.a < 0.004) continue;
    float keep, halo;
    vec3 light = zoneLight(zoneOf(e), e.a, clamp(e.g / e.a, 0.0, 1.0), p + shift[i] / vFrame.xy, t, seed, f, glow, hot, deep, keep, halo);
    if (i == 0) { color += light; sink = e.a * (1.0 - keep); }
    else color += light * halo;
  }
  gl_FragColor = vec4(color * vState.w, clamp(sink * vFrame.z, 0.0, 1.0));
}`;
