import type * as Phaser from 'phaser';
import type { DistanceFieldView } from './IndirectLightField';
import type { OccluderField } from './OccluderField';

/**
 * A way of computing point-light shadows. The chassis in `ShadowedLightPass` draws each light; a
 * provider contributes the fragment function
 * `float shadowVisibility(vec2 world)`, which returns 0 (dark) to 1 (lit) and may use
 * `uLight`, `uCone`, `uReach`, `occluderAt(world)` and its own uniforms and textures.
 * Texture units from 1 up belong to the provider, in the order of `textures()`.
 */
export interface ShadowProvider {
  readonly id: string;
  readonly glsl: string;
  /** Once per frame, with the field's drawing still queued; work that reads the field goes through `field.afterDrawn`. */
  prepare?(field: OccluderField): void;
  textures?(field: OccluderField): readonly Phaser.Textures.Texture[];
  setUniforms?(set: (name: string, value: unknown) => void, field: OccluderField): void;
  /** This frame's distance field, for a provider that builds one; light transport can share it. */
  distanceField?(): DistanceFieldView | null;
  destroy?(): void;
}

export type ShadowProviderFactory = (scene: Phaser.Scene) => ShadowProvider;

/** Winner of the shadow comparison, the default of the new light. */
export const SHADOW_PROVIDER_DISTANCE_FIELD = 'sdf';

const factories = new Map<string, ShadowProviderFactory>();
const listeners = new Set<() => void>();
let selected = SHADOW_PROVIDER_DISTANCE_FIELD;

export function registerShadowProvider(id: string, factory: ShadowProviderFactory): void { factories.set(id, factory); }
export function getShadowProviderId(): string { return selected; }
export function setShadowProviderId(id: string): void {
  if (!factories.has(id)) throw new Error(`Unknown lighting shadow provider: ${id}`);
  if (id === selected) return;
  selected = id;
  for (const listener of listeners) listener();
}
/** Owners rebuild their light targets when the provider changes. */
export function onShadowProviderChange(listener: () => void): () => void {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}
export function createSelectedShadowProvider(scene: Phaser.Scene): ShadowProvider | null { return factories.get(selected)?.(scene) ?? null; }

/** Darkens exactly where the field says something stands: shows at a glance that the field is aligned. */
registerShadowProvider('field-test', () => ({
  id: 'field-test',
  glsl: 'float shadowVisibility(vec2 world) { return 1.0 - occluderAt(world).r; }',
}));
