import type * as Phaser from 'phaser';
import { SunRenderTarget } from '../../../sunlight/SunRenderTarget';
import { enableHdrTarget } from '../../LightHdrComposite';
import type { OccluderField } from '../../OccluderField';

export interface JumpFloodQuality {
  /** World pixels per distance texel; the grid is world-locked, so edges keep still under a moving camera. */
  readonly cellPx: number;
  /** Largest jump in texels. A seed reaches about twice as far, which also caps the field's distance. */
  readonly startJump: number;
  /** One more pass at jump 1, which removes most of the flood's remaining errors. */
  readonly refine: boolean;
}

export const JUMP_FLOOD_SHADER = 'SdfJumpFlood';
const MODE_SEED = 0, MODE_FLOOD = 1, MODE_RESOLVE = 2;
/** Field coverage from which a texel is a blocker. Below the weak horde strength, above soft edge noise. */
const SEED_THRESHOLD = 0.15;
const MAX_HEIGHT_PX = 510;
/** World px per texel of the occluder field. */
const FIELD_TEXEL_PX = 2;

/**
 * Seed texel: x, y (texel index), blocker height in px, strength + kind (rock 2, figure 4, lamp carrier 6, figure as a disc 8, other 0). An empty texel is -1.
 * The final field holds distance in px, height of the nearest blocker in px, its strength and kind (rock 1, lamp carrier 0.6, figure 0.5, figure as a disc 0.3, other 0).
 */
export const JUMP_FLOOD_FRAGMENT = `
#pragma phaserTemplate(shaderName)
precision highp float;
uniform sampler2D uSource;
uniform sampler2D uField;
uniform float uMode;
uniform float uJump;
uniform vec2 uSize;
// World x, y of texel (0, 0), world pixels per texel, largest distance in px.
uniform vec4 uGrid;
uniform vec4 uFieldFrame;
vec2 fieldUv(vec2 world) {
  vec2 uv = (world - uFieldFrame.xy) / uFieldFrame.zw;
  return vec2(uv.x, 1.0 - uv.y);
}
vec4 best;
float bestDistance;
void consider(vec2 offset) {
  vec4 seed = texture2D(uSource, (gl_FragCoord.xy + offset) / uSize);
  if (seed.x < 0.0) return;
  vec2 delta = seed.xy + 0.5 - gl_FragCoord.xy;
  float distance = dot(delta, delta);
  if (distance < bestDistance) { bestDistance = distance; best = seed; }
}
void main() {
  if (uMode < 0.5) {
    vec2 world = uGrid.xy + gl_FragCoord.xy * uGrid.z;
    vec4 here = texture2D(uField, fieldUv(world));
    if (here.r < ${SEED_THRESHOLD.toFixed(2)}) { gl_FragColor = vec4(-1.0); return; }
    // Edge texels hold faded values; the neighbours carry the blocker's true height, strength and kind. A cell of a coarse grid
    // has its centre between four field texels, where a read is their average: the taps go to those texels' own centres,
    // or a figure's rim would lose its kind and a lamp carrier would block its own lamp.
    vec2 tap = vec2(${FIELD_TEXEL_PX * 0.5}, -${FIELD_TEXEL_PX * 0.5});
    vec4 peak = max(here, max(max(texture2D(uField, fieldUv(world + tap.xx)), texture2D(uField, fieldUv(world - tap.xx))),
      max(texture2D(uField, fieldUv(world + tap)), texture2D(uField, fieldUv(world - tap)))));
    gl_FragColor = vec4(floor(gl_FragCoord.xy), peak.g * ${MAX_HEIGHT_PX}.0, peak.r + (peak.b > 0.5 ? 2.0 : peak.b > 0.32 ? 6.0 : peak.b > 0.19 ? 4.0 : peak.b > 0.01 ? 8.0 : 0.0));
    return;
  }
  if (uMode < 1.5) {
    best = vec4(-1.0);
    bestDistance = 1e12;
    consider(vec2(0.0));
    consider(vec2(-uJump, -uJump)); consider(vec2(0.0, -uJump)); consider(vec2(uJump, -uJump));
    consider(vec2(-uJump, 0.0)); consider(vec2(uJump, 0.0));
    consider(vec2(-uJump, uJump)); consider(vec2(0.0, uJump)); consider(vec2(uJump, uJump));
    gl_FragColor = best;
    return;
  }
  vec4 seed = texture2D(uSource, gl_FragCoord.xy / uSize);
  if (seed.x < 0.0) { gl_FragColor = vec4(uGrid.w, 0.0, 0.0, 0.0); return; }
  float kind = floor(seed.w * 0.5) * 2.0;
  float strength = seed.w - kind;
  // A seed that is only partly covered holds the true contour inside its own texel.
  float coverage = clamp(texture2D(uField, fieldUv(uGrid.xy + (seed.xy + 0.5) * uGrid.z)).r / max(strength, 0.01), 0.0, 1.0);
  float distance = length((seed.xy + 0.5 - gl_FragCoord.xy) * uGrid.z);
  distance = distance < 0.001 ? 0.0 : max(0.0, distance + (0.5 - coverage) * uGrid.z);
  gl_FragColor = vec4(min(distance, uGrid.w), seed.z, strength, kind > 7.0 ? 0.3 : kind > 5.0 ? 0.6 : kind > 3.0 ? 0.5 : kind * 0.5);
}`;

/** Unsigned world-space distance to the nearest blocker, rebuilt each frame from the occluder field by jump flooding. */
export class JumpFloodField {
  /** World x, y of the grid origin; 1 / world width, 1 / world height. */
  readonly frame = new Float32Array(4);
  private readonly size = new Float32Array(2);
  private readonly grid = new Float32Array(4);
  private readonly fieldFrame = new Float32Array(4);
  private readonly run = (): void => { this.flood(); };
  private mode = MODE_SEED;
  private jump = 1;
  private width = 0;
  private height = 0;
  private quality: JumpFloodQuality | null = null;
  private source: Phaser.Textures.Texture | null = null;
  private a: SunRenderTarget | null = null;
  private b: SunRenderTarget | null = null;
  private resolved: SunRenderTarget | null = null;

  constructor(private readonly scene: Phaser.Scene) {}

  get texture(): Phaser.Textures.Texture | null { return this.resolved?.shader.texture ?? null; }
  get maxDistancePx(): number { return this.grid[3]; }

  /** Queues the flood right behind the field's own drawing, so it reads this frame's blockers. */
  prepare(field: OccluderField, quality: JumpFloodQuality): void {
    const texture = field.texture as Phaser.Textures.DynamicTexture | null;
    if (!texture) return;
    const cell = quality.cellPx;
    const originX = Math.floor(field.frame[0] / cell) * cell, originY = Math.floor(field.frame[1] / cell) * cell;
    // The field moves in smaller steps than the SDF grid. Its phase within a cell must
    // not change the allocation: otherwise a camera pan rebuilds all three float targets.
    // One cell covers the snapped origin's remainder, another guards the far edge.
    const width = Math.ceil(field.frame[2] / cell) + 2;
    const height = Math.ceil(field.frame[3] / cell) + 2;
    if (!this.ensureTargets(width, height, texture, quality)) return;
    this.frame[0] = originX; this.frame[1] = originY; this.frame[2] = 1 / (width * cell); this.frame[3] = 1 / (height * cell);
    this.grid[0] = originX; this.grid[1] = originY; this.grid[2] = cell; this.grid[3] = (quality.startJump * 2 - 1) * cell;
    this.fieldFrame.set(field.frame);
    field.afterDrawn(this.run);
  }

  destroy(): void { this.destroyTargets(); }

  private flood(): void {
    if (!this.a || !this.b) return;
    const { width, height, quality } = this;
    let current = this.a, next = this.b;
    this.mode = MODE_SEED;
    current.draw(width, height);
    this.mode = MODE_FLOOD;
    const pass = (jump: number): void => {
      this.jump = jump;
      next.draw(width, height);
      const done = next; next = current; current = done;
    };
    for (let jump = quality!.startJump; jump >= 1; jump >>= 1) pass(jump);
    if (quality!.refine) pass(1);
    this.mode = MODE_RESOLVE;
    this.resolved!.draw(width, height);
  }

  private ensureTargets(width: number, height: number, source: Phaser.Textures.Texture, quality: JumpFloodQuality): boolean {
    if (this.a && this.width === width && this.height === height) {
      if (this.quality === quality && this.source === source) return true;
    } else {
      this.destroyTargets();
      this.width = width; this.height = height;
      this.size[0] = width; this.size[1] = height;
      const a = this.createTarget('SdfFloodA'), b = this.createTarget('SdfFloodB'), resolved = this.createTarget('SdfField');
      this.a = a; this.b = b; this.resolved = resolved;
      if (![a, b, resolved].every(target => this.allocate(target))) {
        console.warn('[Lighting] float targets unavailable, distance-field shadows stay off');
        this.destroyTargets();
        return false;
      }
    }
    this.quality = quality; this.source = source;
    const { a, b, resolved } = this as unknown as Record<'a' | 'b' | 'resolved', SunRenderTarget>;
    a.shader.setTextures([b.shader.texture!, source]);
    b.shader.setTextures([a.shader.texture!, source]);
    // Seeds land in A, each pass swaps, so an odd pass count ends in B.
    let passes = quality.refine ? 1 : 0;
    for (let jump = quality.startJump; jump >= 1; jump >>= 1) passes += 1;
    resolved.shader.setTextures([(passes % 2 === 1 ? b : a).shader.texture!, source]);
    return true;
  }

  private createTarget(kind: string): SunRenderTarget {
    return new SunRenderTarget(this.scene, kind, JUMP_FLOOD_FRAGMENT, set => {
      set('uSource', 0); set('uField', 1); set('uMode', this.mode); set('uJump', this.jump);
      set('uSize', this.size); set('uGrid', this.grid); set('uFieldFrame', this.fieldFrame);
    }, ['__WHITE', '__WHITE'], JUMP_FLOOD_SHADER);
  }

  /** Allocates at the final size, then re-specifies as float: Phaser re-creates textures as 8 bit when it resizes them. */
  private allocate(target: SunRenderTarget): boolean {
    const shader = target.shader;
    target.draw(this.width, this.height);
    return enableHdrTarget(this.scene.sys.renderer as Phaser.Renderer.WebGL.WebGLRenderer, {
      getWebGLTexture: () => shader.glTexture, drawingContext: shader.drawingContext,
    } as unknown as Phaser.Textures.DynamicTexture);
  }

  private destroyTargets(): void {
    this.a?.destroy(); this.a = null;
    this.b?.destroy(); this.b = null;
    this.resolved?.destroy(); this.resolved = null;
    this.width = 0; this.height = 0; this.quality = null; this.source = null;
  }
}
