import * as Phaser from 'phaser';
import {
  CONTROL_ACTIONS,
  needsBrowserCapture,
  type ControlActionId,
  type ControlBinding,
  type ControlMouseButton,
} from './controlBindings';
import { getControlBindings, subscribeControlBindings } from './controlBindingStore';

type DownHandler = (key: Phaser.Input.Keyboard.Key, event: KeyboardEvent | MouseEvent) => void;

/** Nicht registrierte Keys tragen keinen echten keyCode; das Keyboard-Plugin treibt sie nie. */
const DETACHED_KEY_CODE = -1;
/** Maustasten, deren Browser-Standardaktion (Autoscroll, Zurueck/Vor) auf dem Canvas unterbleibt. */
const SUPPRESSED_MOUSE_BUTTONS: ReadonlySet<number> = new Set([1, 3, 4]);

/**
 * Szenen-Adapter zwischen Spielerbelegung und Phaser.
 *
 * Jede Aktion besitzt genau ein `Phaser.Input.Keyboard.Key`. Tastaturbelegungen sind die
 * normalen Keys des Keyboard-Plugins; Mausbelegungen sind eigene, nicht registrierte Keys,
 * die ueber DOM-Mausereignisse gedrueckt und geloest werden. `isDown`, `JustDown`, `JustUp`
 * und das `'down'`-Event verhalten sich dadurch fuer beide Geraete gleich.
 *
 * Aendert sich die Belegung, tauscht der Adapter die Keys live, haengt `onDown`-Handler um und
 * meldet den Wechsel an `onRebind`-Abonnenten, die Key-Referenzen halten.
 */
export class PhaserControlKeys {
  private readonly keys = new Map<ControlActionId, Phaser.Input.Keyboard.Key>();
  private readonly mouseKeys = new Map<ControlMouseButton, Phaser.Input.Keyboard.Key>();
  private readonly downHandlers = new Map<ControlActionId, Set<DownHandler>>();
  private readonly rebindListeners = new Set<() => void>();
  private readonly capturedCodes = new Set<number>();
  private readonly unsubscribe: () => void;
  private readonly canvas: HTMLCanvasElement | null;
  private destroyed = false;

  constructor(private readonly scene: Phaser.Scene) {
    this.canvas = scene.game.canvas ?? null;
    this.bindAll();
    this.unsubscribe = subscribeControlBindings(this.onBindingsChanged);
    this.canvas?.addEventListener('mousedown', this.onMouseDown);
    this.canvas?.addEventListener('auxclick', this.suppressMouseDefault);
    if (typeof window !== 'undefined') {
      // Window statt Canvas: Ein Loslassen ausserhalb oder hinter einem DOM-Dialog loest den Key trotzdem.
      window.addEventListener('mouseup', this.onMouseUp, true);
      window.addEventListener('blur', this.onWindowBlur);
    }
    scene.game.events.on(Phaser.Core.Events.BLUR, this.reset, this);
    scene.game.events.on(Phaser.Core.Events.HIDDEN, this.reset, this);
  }

  /** Der aktuelle Key einer Aktion; nach einem Rebind ein anderer Key (siehe {@link onRebind}). */
  key(action: ControlActionId): Phaser.Input.Keyboard.Key {
    return this.keys.get(action)!;
  }

  /** Erster Druck (ohne Wiederholung), unabhaengig davon, ob Taste oder Maustaste belegt ist. */
  onDown(action: ControlActionId, handler: DownHandler): () => void {
    let handlers = this.downHandlers.get(action);
    if (!handlers) {
      handlers = new Set();
      this.downHandlers.set(action, handlers);
    }
    handlers.add(handler);
    this.keys.get(action)?.on(Phaser.Input.Keyboard.Events.DOWN, handler);
    return () => {
      handlers!.delete(handler);
      this.keys.get(action)?.off(Phaser.Input.Keyboard.Events.DOWN, handler);
    };
  }

  onRebind(listener: () => void): () => void {
    this.rebindListeners.add(listener);
    return () => { this.rebindListeners.delete(listener); };
  }

  /** Loest gehaltene Maus-Keys; Tastatur-Keys setzt `keyboard.resetKeys()` selbst zurueck. */
  reset(): void {
    for (const key of this.mouseKeys.values()) key.reset();
  }

  destroy(): void {
    if (this.destroyed) return;
    this.destroyed = true;
    this.unsubscribe();
    this.canvas?.removeEventListener('mousedown', this.onMouseDown);
    this.canvas?.removeEventListener('auxclick', this.suppressMouseDefault);
    if (typeof window !== 'undefined') {
      window.removeEventListener('mouseup', this.onMouseUp, true);
      window.removeEventListener('blur', this.onWindowBlur);
    }
    this.scene.game.events.off(Phaser.Core.Events.BLUR, this.reset, this);
    this.scene.game.events.off(Phaser.Core.Events.HIDDEN, this.reset, this);
    this.detachHandlers();
    const keyboard = this.scene.input.keyboard;
    for (const code of this.capturedCodes) keyboard?.removeCapture(code);
    this.capturedCodes.clear();
    for (const key of this.mouseKeys.values()) key.destroy();
    this.mouseKeys.clear();
    this.keys.clear();
    this.downHandlers.clear();
    this.rebindListeners.clear();
  }

  private readonly onBindingsChanged = (): void => {
    if (this.destroyed) return;
    this.detachHandlers();
    this.bindAll();
    for (const listener of [...this.rebindListeners]) listener();
  };

  private bindAll(): void {
    const keyboard = this.scene.input.keyboard;
    const bindings = getControlBindings();
    const wantedCaptures = new Set<number>();
    const previousMouseKeys = new Map(this.mouseKeys);
    this.mouseKeys.clear();

    for (const action of CONTROL_ACTIONS) {
      const binding = bindings[action.id];
      const key = this.createKey(keyboard, binding, previousMouseKeys);
      if (binding?.device === 'key' && needsBrowserCapture(binding.code)) wantedCaptures.add(binding.code);
      this.keys.set(action.id, key);
      for (const handler of this.downHandlers.get(action.id) ?? []) key.on(Phaser.Input.Keyboard.Events.DOWN, handler);
    }
    // Ein Key, der seine Aktion verloren hat, darf nicht als gedrueckt weiterleben.
    for (const stale of previousMouseKeys.values()) stale.destroy();

    for (const code of [...this.capturedCodes]) {
      if (wantedCaptures.has(code)) continue;
      keyboard?.removeCapture(code);
      this.capturedCodes.delete(code);
    }
    for (const code of wantedCaptures) {
      if (this.capturedCodes.has(code)) continue;
      keyboard?.addCapture(code);
      this.capturedCodes.add(code);
    }
  }

  private createKey(
    keyboard: Phaser.Input.Keyboard.KeyboardPlugin | null,
    binding: ControlBinding | null,
    previousMouseKeys: Map<ControlMouseButton, Phaser.Input.Keyboard.Key>,
  ): Phaser.Input.Keyboard.Key {
    if (binding?.device === 'key' && keyboard) return keyboard.addKey(binding.code, false);
    if (binding?.device === 'mouse') {
      const reused = previousMouseKeys.get(binding.button);
      previousMouseKeys.delete(binding.button);
      const key = reused ?? new Phaser.Input.Keyboard.Key(keyboard!, DETACHED_KEY_CODE);
      this.mouseKeys.set(binding.button, key);
      return key;
    }
    // Unbelegt: ein Key, den niemand je drueckt, damit Leser keine Sonderfaelle brauchen.
    return new Phaser.Input.Keyboard.Key(keyboard!, DETACHED_KEY_CODE);
  }

  private detachHandlers(): void {
    for (const [action, handlers] of this.downHandlers) {
      const key = this.keys.get(action);
      if (!key) continue;
      for (const handler of handlers) key.off(Phaser.Input.Keyboard.Events.DOWN, handler);
    }
  }

  private isInputActive(): boolean {
    const keyboard = this.scene.input.keyboard;
    return this.scene.input.enabled && keyboard?.enabled !== false;
  }

  private readonly onMouseDown = (event: MouseEvent): void => {
    if (SUPPRESSED_MOUSE_BUTTONS.has(event.button)) event.preventDefault();
    if (!this.isInputActive()) return;
    this.mouseKeys.get(event.button as ControlMouseButton)?.onDown(event as unknown as KeyboardEvent);
  };

  private readonly onMouseUp = (event: MouseEvent): void => {
    if (SUPPRESSED_MOUSE_BUTTONS.has(event.button) && event.target === this.canvas) event.preventDefault();
    const key = this.mouseKeys.get(event.button as ControlMouseButton);
    if (key?.isDown) key.onUp(event as unknown as KeyboardEvent);
  };

  private readonly suppressMouseDefault = (event: MouseEvent): void => {
    if (SUPPRESSED_MOUSE_BUTTONS.has(event.button)) event.preventDefault();
  };

  private readonly onWindowBlur = (): void => { this.reset(); };
}
