import type { CoopDefenseMapConfig } from '../../config/coopDefenseMaps';
import { isCoopDefenseMode } from '../../gameModes';
import { toWorldDefinitionId } from '../../world/arenaDescriptorAdapter';
import { resolveCoopDefenseMapConfig } from '../../world/WorldDefinitionResolution';
import { DeploymentLayoutCache, type DeploymentLayout } from '../../world/deployment/DeploymentLayoutCache';
import { createDeploymentLayoutGenerator } from '../../world/deployment/DeploymentLayoutGeneratorFactory';
import { deploymentLayoutId } from '../../world/deployment/DeploymentLayoutGenerator';
import type { GameMode, GamePhase } from '../../types';
import type { WorldPrebake } from '../../arena/prebake/WorldPrebake';
import type { DeploymentPrebaker } from './DeploymentPrebaker';

/** What the lobby currently announces for the next round. */
export interface DeploymentTerrainSource {
  getGamePhase(): GamePhase;
  getGameMode(): GameMode;
  getCoopProgram(): { readonly kind: string };
  getCoopDefenseMapId(): string;
  getDeploymentSeed(): number | null;
}

/** The next round's campaign map and seed, when its terrain can be previewed. */
export interface Deployment {
  readonly mapConfig: CoopDefenseMapConfig;
  readonly seed: number;
}

/** Any next round the lobby can generate ahead: a campaign map, or a PvP mode (no map config). */
interface AnnouncedDeployment {
  readonly id: string;
  readonly gameMode: GameMode;
  readonly mapConfig: CoopDefenseMapConfig | null;
  readonly seed: number;
}

/**
 * Terrain of the next round, generated in the lobby before the round starts.
 *
 * Every peer generates it from the host's lobby snapshot (map and deployment seed) in the
 * background: the round start reuses it, and the base editor shows the real terrain around the
 * base. Every campaign map and PvP round is generated ahead; only maps with a persistent base have
 * a preview. Dawn plans depend on the host's progress and are never generated ahead.
 */
export class ArenaDeploymentTerrain {
  private cache: DeploymentLayoutCache | null = null;
  private prefetchedKey: string | null = null;
  private prebaker: DeploymentPrebaker | null = null;
  /** The lobby's CPU results for exactly one announced layout (Steam plan L14). */
  private prebaked: { key: string; fingerprint: string; prebake: WorldPrebake } | null = null;

  /** `createPrebaker`: the Scene's prebaker, created on the first prebake (it reads the loaded materials). */
  constructor(private readonly source: DeploymentTerrainSource,
    private readonly createPrebaker: (() => DeploymentPrebaker) | null = null) {}

  /** The deployment the lobby announces, or `null` when there is no previewable terrain. */
  current(): Deployment | null {
    const deployment = this.announced();
    return deployment?.mapConfig?.persistentBase ? { mapConfig: deployment.mapConfig, seed: deployment.seed } : null;
  }

  /** The campaign map or PvP mode and the seed the lobby announces, previewable or not. */
  private announced(): AnnouncedDeployment | null {
    const seed = this.source.getDeploymentSeed(), gameMode = this.source.getGameMode();
    if (seed === null) return null;
    // PvP rounds generate from mode and seed alone (Steam plan L14).
    if (!isCoopDefenseMode(gameMode)) return { id: deploymentLayoutId(gameMode, null), gameMode, mapConfig: null, seed };
    if (this.source.getCoopProgram().kind !== 'campaign') return null;
    const mapConfig = resolveCoopDefenseMapConfig({ definitionId: toWorldDefinitionId(this.source.getCoopDefenseMapId()) }, null);
    return mapConfig ? { id: deploymentLayoutId(gameMode, mapConfig), gameMode, mapConfig, seed } : null;
  }

  /**
   * Generates the announced terrain once per map and seed while the room is in the lobby. With
   * `prebake`, the finished layout's World-build CPU work follows (Steam plan L14); a newly
   * announced deployment frees the previous one's results.
   */
  prefetch(prebake = false): void {
    if (this.source.getGamePhase() !== 'LOBBY') return;
    const deployment = this.announced();
    const key = deployment ? DeploymentLayoutCache.key(deployment.id, deployment.seed) : null;
    if (this.prebaked && this.prebaked.key !== key) this.releasePrebake();
    this.prebaked?.prebake.pump();
    if (deployment && key !== null && prebake && this.createPrebaker && !this.prebaked) {
      const ready = this.cache?.peek(deployment.id, deployment.seed);
      if (ready) this.prebaked = { key, fingerprint: ready.fingerprint, prebake: (this.prebaker ??= this.createPrebaker()).start({
        gameMode: deployment.gameMode, mapConfig: deployment.mapConfig, layout: ready.layout }) };
    }
    if (!deployment || key === this.prefetchedKey) return;
    this.prefetchedKey = key;
    // A failed generation is reported to whoever asks for this terrain; the prefetch stays quiet.
    this.layouts().request(deployment.mapConfig, deployment.seed, deployment.gameMode).catch(() => { this.prefetchedKey = null; });
  }

  /** The lobby finished preparing the announced deployment's World build (load probe, diagnostics). */
  isPrebakeComplete(): boolean {
    const deployment = this.announced(), prebaked = this.prebaked;
    return !!deployment && !!prebaked && !prebaked.prebake.disposed && prebaked.prebake.complete
      && prebaked.key === DeploymentLayoutCache.key(deployment.id, deployment.seed);
  }

  /** The finished terrain of the announced deployment, if it is ready. */
  /** The finished layout's fingerprint: cheap enough for every lobby frame, unlike `peek`. */
  fingerprint(deployment: Deployment): string | null {
    return this.cache?.fingerprint(deployment.mapConfig.mapId, deployment.seed) ?? null;
  }

  peek(deployment: Deployment): DeploymentLayout | null {
    return this.cache?.peek(deployment.mapConfig.mapId, deployment.seed) ?? null;
  }

  /** A finished lobby layout for a round about to start (`id`: `deploymentLayoutId`); a clone, the
   * round may change it. Its prebake is shared: the World built from it takes the results it needs. */
  peekLayout(mapId: string, seed: number): DeploymentLayout | null {
    const layout = this.cache?.peek(mapId, seed) ?? null;
    if (!layout) return null;
    const prebaked = this.prebaked;
    return prebaked && prebaked.key === DeploymentLayoutCache.key(mapId, seed) && prebaked.fingerprint === layout.fingerprint
      && !prebaked.prebake.disposed ? { ...layout, prebake: prebaked.prebake } : layout;
  }

  request(deployment: Deployment): Promise<DeploymentLayout> {
    return this.layouts().request(deployment.mapConfig, deployment.seed);
  }

  destroy(): void {
    this.releasePrebake();
    this.cache?.destroy();
    this.cache = null;
  }

  private releasePrebake(): void {
    this.prebaked?.prebake.dispose();
    this.prebaked = null;
  }

  private layouts(): DeploymentLayoutCache {
    this.cache ??= new DeploymentLayoutCache(createDeploymentLayoutGenerator());
    return this.cache;
  }
}
