import type { LightPresetKey } from '../LightingConfig';

/**
 * Heights for point-light shadows, in world pixels. They are separate from the sun's `castHeightPx`,
 * which is tuned for shadow length. Whatever blocks shots also blocks lamps, so every World obstacle
 * stands taller than the lowest lamp.
 */
export const OCCLUDER_HEIGHT_PX = { rock: 47, trunk: 180, base: 64, barrier: 40, train: 64 } as const;

const DEFAULT_LIGHT_HEIGHT_PX = 24;
const LIGHT_HEIGHT_PX: Readonly<Partial<Record<LightPresetKey, number>>> = {
  flashlight: 16, flashlightSpill: 16, muzzleFlash: 16, trainHeadlight: 30,
  explosion: 60, bfgOrb: 40, groundFire: 20, voidGroundFire: 20,
};

export function lightHeightPx(preset: LightPresetKey): number {
  return LIGHT_HEIGHT_PX[preset] ?? DEFAULT_LIGHT_HEIGHT_PX;
}

/** Share of the light's radius covered by its own glowing body. */
const LIGHT_BODY_SHARE: Readonly<Partial<Record<LightPresetKey, number>>> = { explosion: 0.28, bfgOrb: 0.2 };

/** A figure inside a fireball stands in front of the fire, not between it and the ground around it. */
export function lightBodyPx(preset: LightPresetKey, radiusPx: number): number {
  return (LIGHT_BODY_SHARE[preset] ?? 0) * radiusPx;
}

const SHADOW_LIGHTS: ReadonlySet<LightPresetKey> = new Set<LightPresetKey>([
  'flashlight', 'trainHeadlight', 'explosion', 'muzzleFlash', 'bfgOrb', 'rocketThruster', 'projectileBurn',
  'groundFire', 'voidGroundFire', 'entityBurn',
]);
const ULTRA_SHADOW_LIGHTS: ReadonlySet<LightPresetKey> = new Set<LightPresetKey>([
  'energyProjectile', 'holyProjectile', 'sporeProjectile', 'sporeVoidProjectile', 'flameProjectile', 'voidFlameProjectile',
]);

/** Which lights ask for a shadow from a provider; large projectiles from High on, all glowing ones on Ultra. */
export function lightCastsProviderShadow(preset: LightPresetKey, ultra: boolean): boolean {
  return SHADOW_LIGHTS.has(preset) || (ultra && ULTRA_SHADOW_LIGHTS.has(preset));
}

const FIGURE_HEIGHT_PER_RADIUS = 2.4;
export function figureHeightPx(radiusPx: number): number {
  return radiusPx * FIGURE_HEIGHT_PER_RADIUS;
}

const HORDE_FIGURES = 60;
const SMALL_FIGURE_RADIUS_PX = 16;
const HORDE_SMALL_FIGURE_STRENGTH = 0.45;

/** Small figures in a crowd cast weaker shadows, so a horde does not turn into dark spokes. */
export function figureShadowStrength(radiusPx: number, figureCount: number): number {
  return figureCount > HORDE_FIGURES && radiusPx < SMALL_FIGURE_RADIUS_PX ? HORDE_SMALL_FIGURE_STRENGTH : 1;
}

/** Blue channel of the field: a lamp lights the front of the first rock it meets. */
export const OCCLUDER_KIND_ROCK = 255;
export const OCCLUDER_KIND_OTHER = 0;
/** Figures: no lit rim, and a figure does not shade its own body. Kept below 0.5 so rock tests stay `b > 0.5`. */
export const OCCLUDER_KIND_FIGURE = 64;
/** A figure drawn as a plain disc, because its picture cannot stand for its shape: the shadow pass has no mask of what it shows. */
export const OCCLUDER_KIND_FIGURE_DISC = 32;
/** A figure that can carry a lamp. Told apart from others so that its own body never blocks its lamp while one standing in front of it does. */
export const OCCLUDER_KIND_LAMP_CARRIER = 102;
const MAX_ENCODED_HEIGHT_PX = 510;

/** Field colour as a Phaser tint: R blocks light (0..1), G is height / 510 px, B the surface kind. */
export function encodeOccluder(heightPx: number, kind: number, strength = 1): number {
  const height = Math.round(Math.min(1, heightPx / MAX_ENCODED_HEIGHT_PX) * 255);
  return (Math.round(Math.min(1, Math.max(0, strength)) * 255) << 16) | (height << 8) | kind;
}
