/**
 * Darstellungslogik der Spielsuche, ohne Phaser: Reihenfolge und Texte je Raum.
 *
 * Die Angaben kommen aus Lobby-Daten fremder Hosts und sind unbestätigt; was nicht zu einem
 * bekannten Modus passt, wird neutral dargestellt statt übernommen.
 */
import { isCoopDefenseMode } from '../gameModes';
import { getLocale, t } from '../i18n';
import { getMapName } from '../i18n/contentPresentation';
import { getLocalizedGameModeLabel } from '../i18n/gameModePresentation';
import type { PlatformPublicRoom } from '../platform';
import type { GameMode } from '../types';
import { PLAYER_NAME_MAX_LENGTH } from '../utils/playerName';

const GAME_MODES: readonly GameMode[] = ['deathmatch', 'team_deathmatch', 'capture_the_beer', 'coop_defense'];

/** Niedrigster Ping zuerst, ohne Schätzung ans Ende; bei Gleichstand die vollere Runde. */
export function sortPublicRooms(rooms: readonly PlatformPublicRoom[]): PlatformPublicRoom[] {
  return [...rooms].sort((a, b) => {
    const pingA = a.pingMs ?? Number.POSITIVE_INFINITY;
    const pingB = b.pingMs ?? Number.POSITIVE_INFINITY;
    if (pingA !== pingB) return pingA - pingB;
    return b.players - a.players;
  });
}

export function formatPublicRoomHost(room: PlatformPublicRoom): string {
  return room.hostName?.slice(0, PLAYER_NAME_MAX_LENGTH) || t('ui.publicGames.unknownHost');
}

/** „Koop · Map 3 · in einer Runde“ bzw. „Deathmatch · in der Lobby“. */
export function formatPublicRoomActivity(room: PlatformPublicRoom): string {
  const mode = GAME_MODES.find(candidate => candidate === room.mode);
  const parts: string[] = [];
  if (mode) {
    parts.push(getLocalizedGameModeLabel(mode));
    if (isCoopDefenseMode(mode) && room.coopMapId) parts.push(getMapName(room.coopMapId.slice(0, 16), getLocale()));
  }
  if (room.phase === 'LOBBY') parts.push(t('ui.publicGames.phaseLobby'));
  else if (room.phase === 'ARENA') parts.push(t('ui.publicGames.phaseArena'));
  return parts.join(' · ') || '–';
}

export function formatPublicRoomPlayers(room: PlatformPublicRoom): string {
  return room.maxPlayers === null ? String(room.players) : `${room.players}/${room.maxPlayers}`;
}

export function formatPublicRoomPing(room: PlatformPublicRoom): string {
  return room.pingMs === null ? '–' : `~${room.pingMs} ms`;
}
