import type { CombatDamageKind } from '../../types';

/** Impact feedback only; periodic damage and generic reactions never hold an enemy in place. */
export function resolveEnemyHitStaggerDuration(
  damageKind: CombatDamageKind,
  knockbackFactor: number,
  baseDurationMs: number,
): number {
  if (damageKind !== 'direct' && damageKind !== 'explosion' && damageKind !== 'chain' && damageKind !== 'reflect') return 0;
  if (!Number.isFinite(baseDurationMs) || baseDurationMs <= 0
    || !Number.isFinite(knockbackFactor) || knockbackFactor <= 0) return 0;
  return baseDurationMs * Math.max(1 / 3, Math.min(2, knockbackFactor));
}

export interface EnemyStaggerPoiseTuning {
  readonly fullStaggersToResist: number;
  readonly recoveryMs: number;
  readonly minEffectiveShare: number;
}

export interface EnemyStaggerPoiseState {
  /** 0 = fully staggerable, 1 = resists every further stagger until it decays. */
  readonly poise: number;
  readonly updatedAt: number;
}

/**
 * Diminishing returns under sustained fire. Poise counts recent stagger in units of full staggers
 * and decays linearly, so the held share of any span stays below fullStaggersToResist x raw / recoveryMs
 * regardless of fire rate or number of shooters. A remainder too short to read as a stumble is skipped.
 */
export function resolveEnemyStaggerPoise(
  state: EnemyStaggerPoiseState | undefined,
  rawDurationMs: number,
  nowMs: number,
  tuning: EnemyStaggerPoiseTuning,
): { readonly effectiveMs: number; readonly state: EnemyStaggerPoiseState } {
  const decayed = state && tuning.recoveryMs > 0
    ? Math.max(0, state.poise - Math.max(0, nowMs - state.updatedAt) / tuning.recoveryMs)
    : 0;
  const share = 1 - decayed;
  if (tuning.fullStaggersToResist <= 0) return { effectiveMs: rawDurationMs, state: { poise: 0, updatedAt: nowMs } };
  if (share < tuning.minEffectiveShare) return { effectiveMs: 0, state: { poise: decayed, updatedAt: nowMs } };
  return {
    effectiveMs: rawDurationMs * share,
    state: { poise: Math.min(1, decayed + share / tuning.fullStaggersToResist), updatedAt: nowMs },
  };
}
