/**
 * Laufzeit-Owner der Spielersteuerung.
 *
 * Haelt die aktuelle Belegung, schreibt jede Aenderung sofort in die Geraeteeinstellungen und
 * benachrichtigt Abonnenten (Phaser-Tasten, Texte mit Tastennamen). Texte nennen Tasten nie
 * woertlich, sondern ueber den Platzhalter `{key_<actionId>}`, den dieses Modul bei i18n
 * registriert.
 */
import { getLocale, setTranslationPlaceholderResolver, type Locale } from '../i18n';
import { getStoredControlBindings, setStoredControlBindings } from '../utils/localPreferences';
import {
  assignControlBinding,
  findControlActionForBinding,
  isControlActionId,
  isControlBindingAllowed,
  resolveControlBindings,
  type ControlActionId,
  type ControlBinding,
  type ControlBindingOverrides,
  type ResolvedControlBindings,
} from './controlBindings';
import { formatControlBindingLabel } from './controlKeyLabels';

interface ControlBindingState {
  readonly overrides: ControlBindingOverrides;
  readonly resolved: ResolvedControlBindings;
}

let state: ControlBindingState | null = null;
let revision = 0;
const listeners = new Set<() => void>();

function load(): ControlBindingState {
  const overrides = getStoredControlBindings();
  return { overrides, resolved: resolveControlBindings(overrides) };
}

function current(): ControlBindingState {
  state ??= load();
  return state;
}

function commit(overrides: ControlBindingOverrides): void {
  setStoredControlBindings(overrides);
  // Read back through the persistence boundary so runtime and storage cannot drift apart.
  state = load();
  revision++;
  for (const listener of [...listeners]) {
    try { listener(); } catch (error) { console.warn('[controls] binding listener failed', error); }
  }
}

export function getControlBindings(): ResolvedControlBindings {
  return current().resolved;
}

export function getControlBinding(action: ControlActionId): ControlBinding | null {
  return current().resolved[action];
}

export function getControlBindingOverrides(): ControlBindingOverrides {
  return current().overrides;
}

export function getControlKeyLabel(action: ControlActionId, locale: Locale = getLocale()): string {
  return formatControlBindingLabel(getControlBinding(action), locale);
}

export function findControlActionUsing(binding: ControlBinding): ControlActionId | null {
  return findControlActionForBinding(current().resolved, binding);
}

/** Taste, die einer Spieleraktion gehoert; Entwickler-Hotkeys weichen ihr. */
export function isKeyCodeBoundToAction(code: number): boolean {
  return findControlActionUsing({ device: 'key', code }) !== null;
}

export type ControlBindingChange =
  | { readonly ok: true; readonly swappedWith: ControlActionId | null }
  | { readonly ok: false; readonly reason: 'reserved' };

export function setControlBinding(action: ControlActionId, binding: ControlBinding): ControlBindingChange {
  if (!isControlBindingAllowed(binding)) return { ok: false, reason: 'reserved' };
  const assignment = assignControlBinding(current().overrides, action, binding);
  commit(assignment.overrides);
  return { ok: true, swappedWith: assignment.swappedWith };
}

export function resetControlBindings(): void {
  commit({});
}

/** Monoton steigend; Darstellungen mit zwischengespeicherten Tastennamen bauen bei Aenderung neu. */
export function getControlBindingsRevision(): number {
  return revision;
}

export function subscribeControlBindings(listener: () => void): () => void {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}

/** Fuer Tests und neue Speicher-Lifetimes: verwirft den Zwischenstand und liest neu. */
export function reloadControlBindings(): void {
  state = null;
  revision++;
  for (const listener of [...listeners]) {
    try { listener(); } catch (error) { console.warn('[controls] binding listener failed', error); }
  }
}

const KEY_PLACEHOLDER_PREFIX = 'key_';

// Live values for `{key_<action>}`; without this registration i18n falls back to the defaults.
setTranslationPlaceholderResolver((name, locale) => {
  if (!name.startsWith(KEY_PLACEHOLDER_PREFIX)) return undefined;
  const action = name.slice(KEY_PLACEHOLDER_PREFIX.length);
  return isControlActionId(action) ? getControlKeyLabel(action, locale) : undefined;
});
