import { loadingTimeline } from '../diagnostics/LoadingTimeline';
import type { WaterMaskJob, WaterMaskJobResult } from './WaterMaskJob';

/** Creates the client of one World's mask job, or null where the runtime has no module workers
 * (headless tests): the owner then bakes on the main thread. */
export type WaterMaskWorkerFactory = (job: WaterMaskJob) => WaterMaskWorkerClient | null;

export const createWaterMaskWorker: WaterMaskWorkerFactory = job => typeof Worker === 'function'
  ? new WaterMaskWorkerClient(job, () => new Worker(new URL('./WaterMaskWorker.ts', import.meta.url), { type: 'module' }))
  : null;

/** One World, one worker, one job. Results arrive in request order and wait for `take`; destroy never
 * publishes a late result into the next World. No pool and no retained World data. */
export class WaterMaskWorkerClient {
  private readonly worker: Worker;
  private readonly results: WaterMaskJobResult[] = [];
  private error: Error | null = null;
  private disposed = false;
  constructor(job: WaterMaskJob, create: () => Worker) {
    const measurement = loadingTimeline.capture();
    this.worker = create();
    this.worker.onmessage = (event: MessageEvent<WaterMaskJobResult>) => {
      if (this.disposed) return;
      this.results.push(event.data);
      measurement?.add('water/mask-worker', event.data.cpuMs, 'worker');
    };
    this.worker.onerror = event => { if (!this.disposed) this.error = new Error(event.message || '[WaterSurface] Mask worker failed.'); };
    this.worker.onmessageerror = () => { if (!this.disposed) this.error = new Error('[WaterSurface] Mask worker decode failed.'); };
    // The cells are cloned; the renderer keeps its own layout.
    this.worker.postMessage(job);
  }
  /** Every result that arrived since the last call, in request order; throws the worker's failure. */
  take(): WaterMaskJobResult[] {
    if (this.error) throw this.error;
    return this.results.splice(0);
  }
  destroy(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.worker.onmessage = null; this.worker.onerror = null; this.worker.onmessageerror = null;
    this.worker.terminate(); this.results.length = 0;
  }
}
