/**
 * Counter vocabulary shared by the host round ledger, the persisted achievement ledger and the
 * authored registry. Keys are plain strings so the registry stays data; these helpers are the
 * only place that spells them.
 */

/** Pickup-only special weapons whose use counts toward an achievement. */
export const ACHIEVEMENT_TRACKED_UTILITY_IDS = ['BFG', 'NUKE', 'HOLY_HAND_GRENADE'] as const;
export type AchievementTrackedUtilityId = typeof ACHIEVEMENT_TRACKED_UTILITY_IDS[number];

export const ACHIEVEMENT_COUNTER = Object.freeze({
  killsTotal: 'kills.total',
  pvpKills: 'pvp.kills',
  trainDestroyed: 'train.destroyed',
  trainVictim: 'train.victim',
  nukeBurst: 'feat.nukeBurst',
  rabbitHolyHandGrenade: 'feat.rabbitHolyHandGrenade',
  telefrag: 'feat.telefrag',
  bossFlawless: 'won.bossFlawless',
  maxCoopVictoryPlayers: 'won.maxPlayers',
  dawnMaxThreatWon: 'dawn.maxThreatWon',
});

/** Kill sources the host recognises for feats; pinned by tests against the combat code. */
export const ACHIEVEMENT_SOURCE_IDS = Object.freeze({
  nuke: 'powerup.NUKE',
  holyHandGrenade: 'HOLY_HAND_GRENADE',
  telefrag: 'environment.telefrag',
});

export const RABID_RABBIT_ENEMY_KIND = 'rabid-rabbit';

/** Counters that keep the best single value instead of a running sum. */
export const ACHIEVEMENT_MAX_COUNTERS: ReadonlySet<string> = new Set([
  ACHIEVEMENT_COUNTER.nukeBurst,
  ACHIEVEMENT_COUNTER.maxCoopVictoryPlayers,
  ACHIEVEMENT_COUNTER.dawnMaxThreatWon,
]);

export const ACHIEVEMENT_COUNTER_KEY_PATTERN = /^[a-z][A-Za-z0-9_.-]{0,63}$/u;
/** Steam stats are int32; counters stay well inside that range. */
export const ACHIEVEMENT_COUNTER_MAX_VALUE = 2_000_000_000;

export function enemyKillCounter(enemyKind: string): string {
  return `kills.${enemyKind}`;
}

export function utilityUsedCounter(utilityId: string): string {
  return `used.${utilityId}`;
}

export function pvpWonCounter(mode: string): string {
  return `pvp.won.${mode}`;
}

export function classWonCounter(classId: string): string {
  return `won.class.${classId}`;
}

export function dawnModifierWonCounter(modifierId: string): string {
  return `dawn.won.modifier.${modifierId}`;
}

export function achievementEventCounter(eventId: string): string {
  return `event.${eventId}`;
}

export function isTrackedAchievementUtilityId(value: string): value is AchievementTrackedUtilityId {
  return (ACHIEVEMENT_TRACKED_UTILITY_IDS as readonly string[]).includes(value);
}

export function sanitizeAchievementCounterValue(value: unknown): number | null {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) return null;
  return Math.min(ACHIEVEMENT_COUNTER_MAX_VALUE, Math.floor(value));
}
